// ── Global resize guard: prevents canvas resize storms on mobile zoom ──
// Each caller gets its own debounce timer keyed by function reference.
var _resizeGuardTimers=new Map();
function guardedResize(fn,delay){
  if(_resizeGuardTimers.has(fn))clearTimeout(_resizeGuardTimers.get(fn));
  _resizeGuardTimers.set(fn,setTimeout(function(){
    fn();
    _resizeGuardTimers.delete(fn);
  },delay||150));
}

