//  STARFIELD
// ═══════════════════════════════
(function(){
  const c=document.getElementById('bgc'),ctx=c.getContext('2d');
  let W,H;
  const stars=Array.from({length:280},()=>({x:Math.random(),y:Math.random(),r:Math.random()*.7+.15,a:Math.random(),tw:Math.random()*Math.PI*2,sp:Math.random()*.0003+.0001}));
  const tris=Array.from({length:8},(_,i)=>({x:Math.random(),y:Math.random(),s:Math.random()*50+20,rot:Math.random()*Math.PI*2,rs:(Math.random()-.5)*.0013,dx:(Math.random()-.5)*.00005,dy:(Math.random()-.5)*.00005,al:Math.random()*.02+.006,inv:i%2===0}));
  function resize(){W=c.width=innerWidth;H=c.height=innerHeight;}
  window.addEventListener('resize',function(){guardedResize(resize,200);});resize();
  function draw(){
    ctx.clearRect(0,0,W,H);
    const g=ctx.createRadialGradient(W/2,H*.35,0,W/2,H*.6,Math.max(W,H)*.9);
    g.addColorStop(0,'rgba(20,14,5,1)');g.addColorStop(.5,'rgba(8,5,2,1)');g.addColorStop(1,'rgba(3,2,1,1)');
    ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    for(const s of stars){s.tw+=s.sp*8;ctx.beginPath();ctx.arc(s.x*W,s.y*H,s.r,0,Math.PI*2);ctx.fillStyle=`rgba(232,212,160,${s.a*(.4+.6*Math.sin(s.tw))})`;ctx.fill();}
    for(const t of tris){t.rot+=t.rs;t.x=(t.x+t.dx+1)%1;t.y=(t.y+t.dy+1)%1;ctx.save();ctx.translate(t.x*W,t.y*H);ctx.rotate(t.rot+(t.inv?Math.PI:0));ctx.beginPath();ctx.moveTo(0,-t.s);ctx.lineTo(t.s*.866,t.s*.5);ctx.lineTo(-t.s*.866,t.s*.5);ctx.closePath();ctx.strokeStyle=`rgba(201,168,76,${t.al})`;ctx.lineWidth=.5;ctx.stroke();ctx.restore();}
    requestAnimationFrame(draw);
  }
  draw();
})();

