const erac=document.getElementById('erac'),ectx=erac.getContext('2d');
let eW,eH;
function resizeErac(){eW=erac.width=innerWidth;eH=erac.height=innerHeight;}
window.addEventListener('resize',function(){guardedResize(resizeErac,200);});resizeErac();

const ERA_GLYPHS={brahman:'ॐ',spanda:'∿',nada:'☉',shivashakti:'⚯',hiranyagarbha:'○',virat:'⊙',matsya:'〜',kurma:'◎',varaha:'◈',narasimha:'⊗',vamana:'△',parashurama:'⚒',rama:'◇',krishna:'✦',sindhu:'⌖',kalpa:'∞',svayambhuva:'✶',vaivasvata:'✷',buddha:'☸',darshanas:'⍜',bhakti:'❧',vivekananda:'⊹',now:'◉',kalki:'⟳'};
const ERA_COLORS={brahman:'rgba(201,168,76,',spanda:'rgba(180,160,90,',nada:'rgba(220,200,120,',shivashakti:'rgba(160,120,200,',hiranyagarbha:'rgba(220,190,100,',virat:'rgba(200,180,110,',matsya:'rgba(80,160,200,',kurma:'rgba(140,180,140,',varaha:'rgba(160,120,80,',narasimha:'rgba(200,100,60,',vamana:'rgba(200,200,110,',parashurama:'rgba(140,190,100,',rama:'rgba(120,170,210,',krishna:'rgba(90,110,200,',sindhu:'rgba(180,140,80,',kalpa:'rgba(160,140,200,',svayambhuva:'rgba(200,170,90,',vaivasvata:'rgba(190,170,100,',buddha:'rgba(160,190,170,',darshanas:'rgba(150,180,160,',bhakti:'rgba(200,120,120,',vivekananda:'rgba(170,150,200,',now:'rgba(201,168,76,',kalki:'rgba(210,175,75,'};
let eParts=[],curEraId='brahman';

function mkP(eid,rand){
  return{x:rand?Math.random()*eW:Math.random()*eW,y:rand?Math.random()*eH:eH+50,
    vx:(Math.random()-.5)*.2,vy:-(Math.random()*.15+.04),
    alpha:rand?Math.random()*.07+.02:0,size:Math.random()*18+9,
    rot:Math.random()*Math.PI*2,rs:(Math.random()-.5)*.008,
    life:rand?Math.random():0,eid};
}
function initEraP(eid){curEraId=eid;const cnt=(eid==='now'||eid==='kalki')?18:12;eParts=Array.from({length:cnt},()=>mkP(eid,true));}
function drawEraP(){
  ectx.clearRect(0,0,eW,eH);
  for(const p of eParts){
    p.x+=p.vx;p.y+=p.vy;p.rot+=p.rs;p.life+=.003;
    if(p.life>1||p.y<-60){Object.assign(p,mkP(curEraId,false));p.x=Math.random()*eW;continue;}
    const a=p.alpha*Math.sin(p.life*Math.PI);if(a<=0)continue;
    ectx.save();ectx.translate(p.x,p.y);ectx.rotate(p.rot);ectx.globalAlpha=a;
    ectx.fillStyle=(ERA_COLORS[p.eid]||'rgba(201,168,76,')+'1)';
    ectx.font=p.size+'px serif';ectx.textAlign='center';ectx.textBaseline='middle';
    ectx.fillText(ERA_GLYPHS[p.eid]||'ॐ',0,0);
    ectx.restore();
  }
  requestAnimationFrame(drawEraP);
}

