// ═══════════════════════════════
//  OPEN / CLOSE MAHĀVĀKYA
// ═══════════════════════════════
function openMVK(){
  // Build cards if needed
  const grid=document.getElementById('mv-grid');
  if(!grid.children.length){
    MAHAVAKYAS.forEach((m,i)=>{
      const c=document.createElement('div');c.className='mv-card';
      c.style.setProperty('--card-col',m.col);
      c.innerHTML=`<div class="mv-card-n">Mahāvākya ${['I','II','III','IV'][i]} · ${['Aitareya','Brihadaranyaka','Chandogya','Mandukya'][i]} Upanishad</div>
        <span class="mv-card-skt">${m.skt}</span>
        <span class="mv-card-trans">${m.trans}</span>
        <div class="mv-card-src">${m.src}</div>
        <div class="mv-card-hint">Explore →</div>`;
      c.onclick=()=>openMVKDeep(m);
      grid.appendChild(c);
    });
  }
  document.getElementById('mv-ov').classList.add('on');
}
function closeMVK(){document.getElementById('mv-ov').classList.remove('on');}
function openMVKDeep(m){
  document.getElementById('mvd-skt').textContent=m.skt;
  document.getElementById('mvd-trans').textContent=m.trans;
  document.getElementById('mvd-src').textContent=m.src;
  document.getElementById('mvd-meaning').textContent=m.meaning;
  document.getElementById('mvd-cols').innerHTML=
    `<div class="mvd-col"><div class="mvd-col-lbl">Scripture & Tradition</div>${m.scripture}</div>
     <div class="mvd-col"><div class="mvd-col-lbl">Science & Philosophy</div>${m.science}</div>
     <div class="mvd-col"><div class="mvd-col-lbl">Inner Practice</div>${m.inner}</div>`;
  document.getElementById('mv-deep').classList.add('on');
}
function closeMVKDeep(){document.getElementById('mv-deep').classList.remove('on');}

// ═══════════════════════════════
//  RISHI LINEAGE MAP
// ═══════════════════════════════
let rishiAnimFrame=null;
let rishiCanvas=null,rishiCtx=null,rishiW=0,rishiH=0,selectedRishi=null,rishiNodes=[];
let rishiEraFilter=null; // null = show all
let rishiPulseRings=[]; // [{x,y,r,alpha,color}]

function openRishi(){
  document.getElementById('rl-ov').classList.add('on');
  buildRishiFilters();
  setTimeout(initRishiMap,100);
}
function closeRishi(){
  document.getElementById('rl-ov').classList.remove('on');
  if(rishiAnimFrame){cancelAnimationFrame(rishiAnimFrame);rishiAnimFrame=null;}
}

function buildRishiFilters(){
  const wrap=document.getElementById('rl-era-filters');
  if(wrap.children.length)return;
  // Collect unique era ids from RISHIS
  const eraSet=new Set();
  RISHIS.filter(r=>!r.isEra).forEach(r=>r.eras.forEach(e=>eraSet.add(e)));
  const eraList=[...eraSet].sort();
  wrap.innerHTML=`<button class="rl-ef active" onclick="setRishiFilter(null,this)">All Eras</button>`+
    eraList.map(e=>`<button class="rl-ef" onclick="setRishiFilter('${e}',this)">${e.replace(/-/g,' ')}</button>`).join('');
}

function setRishiFilter(era,btn){
  rishiEraFilter=era;
  document.querySelectorAll('.rl-ef').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  // If a Rishi is selected but doesn't match, deselect
  if(selectedRishi&&!selectedRishi.isEra&&era&&!selectedRishi.eras.includes(era)){
    selectedRishi=null;
    document.getElementById('rl-info').classList.remove('on');
  }
}

function initRishiMap(){
  const wrap=document.getElementById('rl-canvas-wrap');
  rishiCanvas=document.getElementById('rl-canvas');
  rishiCtx=rishiCanvas.getContext('2d');
  const dpr=window.devicePixelRatio||1;
  const dW=wrap.clientWidth, dH=wrap.clientHeight;
  rishiCanvas.width=dW*dpr; rishiCanvas.height=dH*dpr;
  rishiCanvas.style.width=dW+'px'; rishiCanvas.style.height=dH+'px';
  rishiCtx.scale(dpr,dpr);
  rishiW=dW; rishiH=dH;
  rishiNodes=RISHIS.map(r=>({...r,px:r.x*rishiW,py:r.y*rishiH,hov:false}));
  rishiCanvas.onclick=rishiClick;
  rishiCanvas.onmousemove=rishiHover;
  if(rishiAnimFrame)cancelAnimationFrame(rishiAnimFrame);
  drawRishi();
}

function drawRishi(){
  if(!rishiCtx)return;
  rishiCtx.clearRect(0,0,rishiW,rishiH);

  // Determine which nodes are "active" under current era filter
  const activeIds=new Set();
  rishiNodes.forEach(n=>{
    if(!rishiEraFilter||n.isEra||(n.eras&&n.eras.includes(rishiEraFilter)))activeIds.add(n.id);
  });

  // Pulse rings (selection burst)
  rishiPulseRings=rishiPulseRings.filter(p=>{
    p.r+=1.8; p.alpha-=0.022;
    if(p.alpha<=0)return false;
    rishiCtx.beginPath();rishiCtx.arc(p.x,p.y,p.r,0,Math.PI*2);
    rishiCtx.strokeStyle=p.color.replace('1)',p.alpha+')');
    rishiCtx.lineWidth=1;rishiCtx.stroke();
    return true;
  });

  // Connections
  RISHI_CONNECTIONS.forEach(([a,b])=>{
    const na=rishiNodes.find(n=>n.id===a),nb=rishiNodes.find(n=>n.id===b);
    if(!na||!nb)return;
    const bothActive=activeIds.has(a)&&activeIds.has(b);
    const sel=selectedRishi&&(selectedRishi.id===a||selectedRishi.id===b);
    if(!bothActive&&!sel){
      rishiCtx.beginPath();rishiCtx.moveTo(na.px,na.py);rishiCtx.lineTo(nb.px,nb.py);
      rishiCtx.strokeStyle='rgba(107,90,62,.04)';rishiCtx.lineWidth=.4;rishiCtx.stroke();
      return;
    }
    rishiCtx.beginPath();rishiCtx.moveTo(na.px,na.py);rishiCtx.lineTo(nb.px,nb.py);
    rishiCtx.strokeStyle=sel?'rgba(201,168,76,.55)':'rgba(201,168,76,.14)';
    rishiCtx.lineWidth=sel?1.8:.7;rishiCtx.stroke();
  });

  // Nodes
  rishiNodes.forEach(n=>{
    const active=activeIds.has(n.id);
    const r=n.isEra?20:13;
    const sel=selectedRishi&&selectedRishi.id===n.id;
    const hov=n.hov;
    const alpha=active?1:(rishiEraFilter?.18:1);

    if((sel||hov)&&active){
      const g=rishiCtx.createRadialGradient(n.px,n.py,0,n.px,n.py,r*3.5);
      g.addColorStop(0,'rgba(201,168,76,.18)');g.addColorStop(1,'transparent');
      rishiCtx.fillStyle=g;rishiCtx.beginPath();rishiCtx.arc(n.px,n.py,r*3.5,0,Math.PI*2);rishiCtx.fill();
    }
    rishiCtx.globalAlpha=alpha;
    rishiCtx.beginPath();rishiCtx.arc(n.px,n.py,r,0,Math.PI*2);
    rishiCtx.fillStyle=n.isEra?'rgba(201,168,76,.06)':'rgba(5,4,2,.85)';rishiCtx.fill();
    rishiCtx.strokeStyle=sel?n.color:('rgba(201,168,76,'+(hov?.5:.22)+')');
    rishiCtx.lineWidth=sel?2:1;rishiCtx.stroke();
    if(!n.isEra){
      rishiCtx.beginPath();rishiCtx.arc(n.px,n.py,sel?5:3.5,0,Math.PI*2);
      rishiCtx.fillStyle=n.color;rishiCtx.fill();
    }
    rishiCtx.fillStyle=sel?'rgba(240,220,180,.95)':hov?'rgba(201,168,76,.9)':'rgba(107,90,62,.7)';
    rishiCtx.font=(n.isEra?'8':'9.5')+'px "IBM Plex Mono"';
    rishiCtx.textAlign='center';rishiCtx.textBaseline='middle';
    rishiCtx.fillText(n.isEra?n.name.split(' ')[0]:n.name,n.px,n.py+(n.isEra?0:r+11));
    rishiCtx.globalAlpha=1;
  });

  rishiAnimFrame=requestAnimationFrame(drawRishi);
}

function rishiClick(e){
  const rect=rishiCanvas.getBoundingClientRect();
  const mx=e.clientX-rect.left,my=e.clientY-rect.top;
  let hit=null;
  rishiNodes.forEach(n=>{const d=Math.hypot(mx-n.px,my-n.py);if(d<(n.isEra?24:17))hit=n;});
  selectedRishi=hit;
  // Spawn pulse rings on click
  if(hit){
    for(let i=0;i<3;i++){
      rishiPulseRings.push({x:hit.px,y:hit.py,r:hit.isEra?20:13,alpha:.55-i*.12,color:hit.color.includes('rgba')?hit.color:'rgba(201,168,76,1)'});
    }
  }
  const info=document.getElementById('rl-info');
  if(hit&&!hit.isEra){
    document.getElementById('rli-name').textContent=hit.name;
    document.getElementById('rli-manv').textContent=hit.manvantara;
    document.getElementById('rli-desc').textContent=hit.desc;
    // Works composed
    const worksEl=document.getElementById('rli-works');
    if(hit.works&&hit.works.length){
      worksEl.innerHTML=`<div class="rli-works-lbl">Composed / Transmitted</div>`+
        hit.works.map(w=>`<div class="rli-work-item">${w}</div>`).join('');
    }else{worksEl.innerHTML='';}
    // Shakha / tradition
    const shakhaEl=document.getElementById('rli-shakha');
    shakhaEl.innerHTML=hit.shakha?`<div class="rli-shakha-txt">${hit.shakha}</div>`:'';
    // Era tags — clickable to filter
    document.getElementById('rli-eras').innerHTML=hit.eras.map(er=>
      `<span class="rli-tag" onclick="setRishiFilter('${er}',document.querySelector('.rl-ef[onclick*=\\'${er}\']'))">${er}</span>`
    ).join('');
    info.classList.add('on');
  }else if(hit&&hit.isEra){
    document.getElementById('rli-name').textContent=hit.name;
    document.getElementById('rli-manv').textContent=hit.manvantara;
    document.getElementById('rli-desc').textContent=hit.desc;
    document.getElementById('rli-works').innerHTML='';
    document.getElementById('rli-shakha').innerHTML='';
    document.getElementById('rli-eras').innerHTML='';
    info.classList.add('on');
  }else{info.classList.remove('on');}
}

function rishiHover(e){
  const rect=rishiCanvas.getBoundingClientRect();
  const mx=e.clientX-rect.left,my=e.clientY-rect.top;
  rishiNodes.forEach(n=>{n.hov=Math.hypot(mx-n.px,my-n.py)<(n.isEra?24:17);});
  rishiCanvas.style.cursor=rishiNodes.some(n=>n.hov)?'pointer':'default';
}

