// ═══════════════════════════════
//  ESCAPE KEY for new modals
// ═══════════════════════════════
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'){
    // Deep views first
    if(document.getElementById('mv-deep').classList.contains('on')){closeMVKDeep();return;}
    if(document.getElementById('kosha-deep').classList.contains('on')){closeKoshaDeep();return;}
    // Sky sub-tools — close sub then sky
    const skyOv=document.getElementById('sky-ov');
    if(skyOv&&skyOv.classList.contains('on')){
      const anySub=document.querySelector('.sky-sub-ov.on');
      if(anySub){skyShowSub('nakshatras',document.querySelector('.sky-stbtn'));return;}
      closeSky();return;
    }
    // All other modals — in reverse depth order
    const modals=[
      ['mv-ov',closeMVK],['rl-ov',closeRishi],['kosha-ov',closeKosha],
      ['polarity-ov',closePolarity],['cweb-ov',closeConceptWeb],
      ['kmap-ov',closeKnowledgeMap],['fractal-ov',closeFractalMirror],
      ['subtle-ov',closeSubtleBody],['upanishad-ov',closeUpanishad],
      ['cosmic-ov',closeCosmicCycles],['mantra-ov',closeMantraMap],
      ['macro-ov',closeMacroMicro],['dharma-ov',closeDharmaCompass],
      ['about-ov',closeAbout],['cons-ov',closeConsciousness],
      ['livemap-ov',closeLivingMap],['elements-ov',closeElements],
      ['lineage-ov',closeLineage],['erachars-ov',closeEraChars],
      ['mirror-ov',closeMirror],['tattva-ov',closeTattva],
      ['sthula-ov',closeSthula],['karan-ov',closeKaran],
      ['antah-ov',closeAntah],['tanm-ov',closeTanm],
      ['magnet-ov',closeMagnet],['karma-loop-ov',closeKarmaLoopPage],
      ['yugaclock-ov',closeYugaClock],['om-guide',closeOmGuide],['whofor-ov',closeWhoFor],['turiya-ov',closeTuriya],
      ['forgotten-ov',closeForgotten],['oracle-ov',closeOracle],
      ['ov',closePanel],
    ];
    for(const [id,fn] of modals){
      const el=document.getElementById(id);
      if(el&&el.classList.contains('on')){try{fn();}catch(e){} return;}
    }
    if(started){/* do nothing more */}
  }
  if(!started)return;
  if(e.key==='ArrowDown'||e.key==='ArrowRight')navigate(1);
  if(e.key==='ArrowUp'||e.key==='ArrowLeft')navigate(-1);
});

