function openPolarity(){
  document.getElementById('polarity-ov').classList.add('on');
  buildPolarityMap();
}
function closePolarity(){document.getElementById('polarity-ov').classList.remove('on');}

function buildPolarityMap(){
  const body=document.getElementById('polarity-body');
  if(body.dataset.built)return;
  body.dataset.built='1';

  const sections=[
    {label:'Pre-Cosmic — Beyond Polarity',ids:['brahman','spanda','nada','shivashakti','hiranyagarbha','virat']},
    {label:'Dashavatara — The Descents',ids:['matsya','kurma','varaha','narasimha','vamana','parashurama','rama','krishna']},
    {label:'Civilizational Eras',ids:['sindhu','kalpa','svayambhuva','vaivasvata']},
    {label:'Philosophical & Spiritual Peaks',ids:['buddha','darshanas','bhakti','vivekananda']},
    {label:'Present & Future',ids:['now','kalki']},
  ];

  const gunaColors={
    Sattva:'rgba(140,200,140,.7)',
    Rajas:'rgba(200,140,70,.7)',
    Tamas:'rgba(180,80,80,.7)',
    Turiya:'rgba(180,160,230,.7)',
  };

  let html=`
    <div class="pm-legend">
      <div class="pm-leg-item"><div class="pm-leg-dot" style="background:rgba(76,143,201,.7)"></div>Dharmic / Sattva dominant</div>
      <div class="pm-leg-item"><div class="pm-leg-dot" style="background:rgba(201,76,76,.7)"></div>Adharmic / Tamas dominant</div>
      <div class="pm-leg-item"><div class="pm-leg-dot" style="background:rgba(201,168,76,.5)"></div>Rajas / Transitional</div>
      <div class="pm-leg-item"><div class="pm-leg-dot" style="background:rgba(180,160,230,.6)"></div>Transcendent / Beyond Polarity</div>
    </div>
    <div class="pm-chart"><div class="pm-inner">
      <div class="pm-axis-labels">
        <span class="pm-axis-lbl adharma">← Adharma · Tamas</span>
        <span class="pm-axis-lbl" style="color:var(--gdim)">Balanced</span>
        <span class="pm-axis-lbl dharma">Dharma · Sattva →</span>
      </div>
      <div class="pm-rows">`;

  sections.forEach(sec=>{
    html+=`<div class="pm-section-lbl" style="grid-column:1/-1">${sec.label}</div>`;
    sec.ids.forEach(id=>{
      const d=POLARITY_DATA.find(p=>p.id===id);
      const era=ERAS.find(e=>e.id===id);
      if(!d||!era)return;
      const idx=ERAS.findIndex(e=>e.id===id);
      const abs=Math.abs(d.scale);
      const pct=(abs*44).toFixed(1)+'%'; // max 44% per side so bars don't overflow
      const isDharma=d.scale>0.08;
      const isAdharma=d.scale<-0.08;
      const gColor=gunaColors[d.guna]||'rgba(201,168,76,.5)';
      html+=`
        <div class="pm-era-row" onclick="closePolarity();goTo(${idx})">
          <div class="pm-era-name">${d.name}<em>${d.sub}</em></div>
          <div class="pm-bar-track">
            ${isDharma?`<div class="pm-bar-fill dharma" style="width:${pct}"><span class="pm-guna" style="color:${gColor}">${d.guna}</span></div>`:''}
            ${isAdharma?`<div class="pm-bar-fill adharma" style="width:${pct}"><span class="pm-guna" style="color:${gColor}">${d.guna}</span></div>`:''}
            ${!isDharma&&!isAdharma?`<div class="pm-bar-fill neutral" style="width:8px"><span class="pm-guna" style="color:${gColor}">${d.guna}</span></div>`:''}
          </div>
        </div>`;
    });
    html+=`<div class="pm-divider"></div>`;
  });

  html+=`</div></div></div>`;
  body.innerHTML=html;

  // Animate bars in after a tick
  requestAnimationFrame(()=>{
    document.querySelectorAll('.pm-bar-fill').forEach((el,i)=>{
      el.style.width='0';
      setTimeout(()=>{
        const target=el.classList.contains('neutral')?'8px':el.dataset.target||el.style.width;
        el.style.width=el.dataset.w||el.style.width;
      },50+i*30);
    });
  });
}

