// ═══════════════════════════════════════════════════════
//  CONCEPT WEB — clean rewrite, all bugs fixed
// ═══════════════════════════════════════════════════════
let cwebAnimFrame=null;
let cwebCanvas=null,cwebCtx=null,cwebW=0,cwebH=0;
// cwebNodes stores stable positions — never randomised mid-draw
let cwebNodes=[];
let cwebSelectedId=null; // store id, not node object ref
let cwebActiveCat='all';
let cwebInitted=false;

// Pre-compute stable era satellite positions per concept (fixed offsets, no Math.random in draw loop)
const CW_ERA_OFFSETS={};
function buildEraOffsets(){
  CONCEPTS.forEach(c=>{
    const n=c.eras.length;
    CW_ERA_OFFSETS[c.id]=c.eras.map((_,i)=>{
      const angle=(i/n)*Math.PI*2-Math.PI/2;
      const dist=90+(i%3)*18; // deterministic distance based on position
      return{dx:Math.cos(angle)*dist, dy:Math.sin(angle)*dist};
    });
  });
}
buildEraOffsets();

// Safe color helper — works with any CSS color string, falls back gracefully
function cwebColAlpha(col,a){
  // If it's a hex color, parse it
  if(/^#[0-9a-fA-F]{6}$/.test(col)){
    const r=parseInt(col.slice(1,3),16);
    const g=parseInt(col.slice(3,5),16);
    const b=parseInt(col.slice(5,7),16);
    return "rgba("+r+","+g+","+b+","+a+")";
  }
  // If it's already rgba/rgb, inject alpha by rebuilding
  if(col.startsWith('rgba')){
    return col.replace(/[\d.]+\)$/,a+')');
  }
  if(col.startsWith('rgb(')){
    return col.replace('rgb(','rgba(').replace(')',`,${a})`);
  }
  return`rgba(201,168,76,${a})`; // safe fallback
}

function openConceptWeb(){
  document.getElementById('cweb-ov').classList.add('on');
  buildCwebFilters();
  // Always reinit canvas — overlay may have been closed/reopened
  setTimeout(()=>{
    initConceptWeb();
  },120);
}
function closeConceptWeb(){
  document.getElementById('cweb-ov').classList.remove('on');
  if(cwebAnimFrame){cancelAnimationFrame(cwebAnimFrame);cwebAnimFrame=null;}
}

function buildCwebFilters(){
  const wrap=document.getElementById('cweb-filters');
  if(wrap.dataset.built)return;
  wrap.dataset.built='1';
  wrap.innerHTML=`<button class="cw-cat-btn active" onclick="setCwebCat('all',this)">All (${CONCEPTS.length})</button>`+
    CW_CATS.map(c=>`<button class="cw-cat-btn" onclick="setCwebCat('${c.id}',this)" style="--ccat:${c.color}">${c.label}</button>`).join('');
}

function setCwebCat(cat,btn){
  cwebActiveCat=cat;
  document.querySelectorAll('.cw-cat-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  // If selected concept not in new cat, deselect
  if(cwebSelectedId){
    const sel=CONCEPTS.find(c=>c.id===cwebSelectedId);
    if(sel&&cat!=='all'&&sel.cat!==cat){
      cwebSelectedId=null;
      renderCwebInfo(null);
    }
  }
  layoutCwebNodes();
}

function initConceptWeb(){
  const wrap=document.getElementById('cweb-canvas-wrap');
  cwebCanvas=document.getElementById('cweb-canvas');
  cwebCtx=cwebCanvas.getContext('2d');
  // devicePixelRatio fix — crisp on retina/HiDPI
  const dpr=window.devicePixelRatio||1;
  const displayW=wrap.clientWidth;
  const displayH=wrap.clientHeight;
  // Canvas pixel buffer = display size × dpr
  cwebCanvas.width=displayW*dpr;
  cwebCanvas.height=displayH*dpr;
  // CSS display size = wrap size (no stretching)
  cwebCanvas.style.width=displayW+'px';
  cwebCanvas.style.height=displayH+'px';
  // Scale ctx so all drawing coords are in CSS pixels
  cwebCtx.scale(dpr,dpr);
  // Store CSS-pixel dimensions for layout maths
  cwebW=displayW;
  cwebH=displayH;
  layoutCwebNodes();
  cwebCanvas.onclick=cwebClick;
  cwebCanvas.onmousemove=cwebHoverMove;
  cwebCanvas.onmouseleave=()=>cwebNodes.forEach(n=>n.hov=false);
  if(cwebAnimFrame)cancelAnimationFrame(cwebAnimFrame);
  cwebAnimFrame=requestAnimationFrame(drawCweb);
  renderCwebInfo(null);
}

function layoutCwebNodes(){
  if(!cwebW||!cwebH)return;
  const visible=CONCEPTS.filter(c=>cwebActiveCat==='all'||c.cat===cwebActiveCat);
  const cx=cwebW/2, cy=cwebH/2;
  const n=visible.length;
  // Use multi-ring layout for many nodes, single ring for few
  const rings=n<=8?1:n<=20?2:3;
  const perRing=Math.ceil(n/rings);

  // Preserve hover state on relayout
  const prevHov={};
  cwebNodes.forEach(nd=>prevHov[nd.id]=nd.hov);

  cwebNodes=visible.map((c,i)=>{
    const ring=Math.floor(i/perRing);
    const posInRing=i%perRing;
    const countInRing=Math.min(perRing,n-ring*perRing);
    const baseR=Math.min(cwebW,cwebH)*(rings===1?0.38:ring===0?0.22:ring===1?0.38:0.46);
    const angle=(posInRing/countInRing)*Math.PI*2-Math.PI/2+(ring*0.3);
    return{
      ...c,
      px:cx+Math.cos(angle)*baseR,
      py:cy+Math.sin(angle)*baseR,
      hov:prevHov[c.id]||false,
    };
  });
}

function drawCweb(){
  if(!cwebCtx){cwebAnimFrame=null;return;}
  cwebCtx.clearRect(0,0,cwebW,cwebH);

  // Connection lines between all nodes (dim web)
  if(cwebActiveCat==='all'&&cwebNodes.length<=20){
    for(let i=0;i<cwebNodes.length;i++){
      for(let j=i+1;j<cwebNodes.length;j++){
        const a=cwebNodes[i],b=cwebNodes[j];
        // Only draw line if they share at least one era
        const sharedEra=a.eras.some(ea=>b.eras.some(eb=>eb.id===ea.id));
        if(!sharedEra)continue;
        cwebCtx.beginPath();
        cwebCtx.moveTo(a.px,a.py);
        cwebCtx.lineTo(b.px,b.py);
        cwebCtx.strokeStyle='rgba(201,168,76,.04)';
        cwebCtx.lineWidth=0.5;
        cwebCtx.stroke();
      }
    }
  }

  // If a concept is selected, draw era satellite dots around it
  const selNode=cwebSelectedId?cwebNodes.find(n=>n.id===cwebSelectedId):null;
  if(selNode){
    const offsets=CW_ERA_OFFSETS[selNode.id]||[];
    selNode.eras.forEach((e,i)=>{
      const off=offsets[i]||{dx:0,dy:0};
      const tx=selNode.px+off.dx;
      const ty=selNode.py+off.dy;
      // Clamp to canvas
      const ctx=cwebCtx;
      ctx.beginPath();ctx.moveTo(selNode.px,selNode.py);ctx.lineTo(tx,ty);
      ctx.strokeStyle='rgba(201,168,76,.15)';ctx.lineWidth=0.7;ctx.stroke();
      const era=ERAS.find(er=>er.id===e.id);
      if(!era)return;
      ctx.beginPath();ctx.arc(tx,ty,6,0,Math.PI*2);
      ctx.fillStyle='rgba(5,4,2,.9)';ctx.fill();
      ctx.strokeStyle='rgba(201,168,76,.4)';ctx.lineWidth=1;ctx.stroke();
      // Era number
      ctx.fillStyle='rgba(201,168,76,.7)';
      ctx.font='bold 7px "IBM Plex Mono"';
      ctx.textAlign='center';ctx.textBaseline='middle';
      const idx=ERAS.findIndex(er=>er.id===e.id);
      ctx.fillText(String(idx+1).padStart(2,'0'),tx,ty);
      // Era name below dot
      ctx.fillStyle='rgba(201,168,76,.45)';
      ctx.font='6.5px "IBM Plex Mono"';
      ctx.textBaseline='top';
      const label=era.avatarName.replace(/<[^>]+>/g,'').replace(/—.*/,'').trim().substring(0,10);
      ctx.fillText(label,tx,ty+9);
    });
  }

  // Draw concept nodes
  cwebNodes.forEach(n=>{
    const sel=n.id===cwebSelectedId;
    const hov=n.hov;
    const rad=sel?22:hov?17:12;
    const cat=CW_CATS.find(c=>c.id===n.cat);
    const col=cat?cat.color:'#c9a84c';

    // Glow ring
    if(sel||hov){
      cwebCtx.beginPath();
      cwebCtx.arc(n.px,n.py,rad*2.8,0,Math.PI*2);
      cwebCtx.fillStyle=cwebColAlpha(col,sel?0.14:0.07);
      cwebCtx.fill();
    }

    // Node body
    cwebCtx.beginPath();cwebCtx.arc(n.px,n.py,rad,0,Math.PI*2);
    cwebCtx.fillStyle=sel?'rgba(8,6,3,.95)':'rgba(5,4,2,.88)';
    cwebCtx.fill();
    cwebCtx.strokeStyle=sel?col:hov?cwebColAlpha(col,0.75):cwebColAlpha(col,0.3);
    cwebCtx.lineWidth=sel?2:1;
    cwebCtx.stroke();

    // Inner dot
    cwebCtx.beginPath();cwebCtx.arc(n.px,n.py,sel?7:4,0,Math.PI*2);
    cwebCtx.fillStyle=col;cwebCtx.fill();

    // Label
    cwebCtx.textAlign='center';cwebCtx.textBaseline='top';
    cwebCtx.fillStyle=sel?'rgba(240,220,180,.95)':hov?cwebColAlpha(col,0.9):'rgba(130,110,75,.75)';
    cwebCtx.font=(sel?'bold 10':'9')+'px "IBM Plex Mono"';
    cwebCtx.fillText(n.name,n.px,n.py+rad+4);
    if(sel){
      cwebCtx.font='6.5px "IBM Plex Mono"';
      cwebCtx.fillStyle='rgba(201,168,76,.5)';
      cwebCtx.fillText(n.eras.length+' eras',n.px,n.py+rad+16);
    }
  });

  cwebAnimFrame=requestAnimationFrame(drawCweb);
}

function cwebClick(e){
  const rect=cwebCanvas.getBoundingClientRect();
  const scaleX=cwebW/rect.width, scaleY=cwebH/rect.height;
  const mx=(e.clientX-rect.left)*scaleX;
  const my=(e.clientY-rect.top)*scaleY;
  let hit=null;
  cwebNodes.forEach(n=>{
    const rad=n.id===cwebSelectedId?22:12;
    if(Math.hypot(mx-n.px,my-n.py)<rad+4)hit=n;
  });
  if(hit){
    cwebSelectedId=hit.id;
    renderCwebInfo(hit);
  } else {
    cwebSelectedId=null;
    renderCwebInfo(null);
  }
}

function cwebHoverMove(e){
  const rect=cwebCanvas.getBoundingClientRect();
  const scaleX=cwebW/rect.width, scaleY=cwebH/rect.height;
  const mx=(e.clientX-rect.left)*scaleX;
  const my=(e.clientY-rect.top)*scaleY;
  let anyHov=false;
  cwebNodes.forEach(n=>{
    n.hov=Math.hypot(mx-n.px,my-n.py)<(n.id===cwebSelectedId?22:12)+4;
    if(n.hov)anyHov=true;
  });
  cwebCanvas.style.cursor=anyHov?'pointer':'crosshair';
}

function renderCwebInfo(concept){
  const el=document.getElementById('cweb-info');
  if(!concept){
    el.innerHTML=`<div class="cwi-empty">Click any node to trace how that concept threads through all 24 eras of the timeline.</div>`;
    return;
  }
  const cat=CW_CATS.find(c=>c.id===concept.cat);
  const validEras=concept.eras.filter(e=>ERAS.some(er=>er.id===e.id));
  el.innerHTML=`<div class="cwi-concept">
    <span class="cwi-skt" style="color:${cat?cat.color:'#c9a84c'}">${concept.name}</span>
    <span class="cwi-cat">${cat?cat.label:concept.cat} · ${validEras.length} era${validEras.length!==1?'s':''}</span>
    <div class="cwi-def">${concept.def}</div>
    <div class="cwi-eras-lbl">Threads through these eras — click to travel</div>
    ${validEras.map(e=>{
      const era=ERAS.find(er=>er.id===e.id);
      const idx=ERAS.findIndex(er=>er.id===e.id);
      if(!era)return'';
      return`<div class="cwi-era-item" onclick="closeConceptWeb();setTimeout(()=>goTo(${idx}),80)">
        <div class="cwi-era-num">${String(idx+1).padStart(2,'0')}</div>
        <div>
          <div class="cwi-era-name">${era.avatarName.replace(/<[^>]+>/g,'').replace(/—.*/,'').trim()}</div>
          <div class="cwi-era-note">${e.note}</div>
        </div>
      </div>`;
    }).join('')}
  </div>`;
}

