// Tag → color palette for the little chips
var UPDATES_TAG_COLOR={
  'Build':'rgba(255,220,140,',
  'Fix':'rgba(255,170,120,',
  'Page':'rgba(200,180,240,',
  'Experience':'rgba(140,200,220,',
  'Foundations':'rgba(180,220,160,',
  'Reference':'rgba(201,168,76,',
  'Hint':'rgba(240,140,200,',
  'Note':'rgba(200,200,200,'
};

function renderUpdatesTab(){
  var itemsHtml=UPDATES_LOG.map(function(entry,i){
    var col=UPDATES_TAG_COLOR[entry.tag]||'rgba(201,168,76,';
    return ''+
      '<div class="ab-up-item" style="--up-delay:'+(i*60)+'ms" data-tag="'+entry.tag+'">'+
        '<div class="ab-up-rail"><div class="ab-up-dot" style="background:'+col+'.85);box-shadow:0 0 12px '+col+'.6);"></div></div>'+
        '<div class="ab-up-body">'+
          '<div class="ab-up-meta">'+
            '<span class="ab-up-date">'+entry.date+'</span>'+
            '<span class="ab-up-chip" style="color:'+col+'.85);border-color:'+col+'.25);">'+entry.tag+'</span>'+
          '</div>'+
          '<div class="ab-up-title">'+entry.title+'</div>'+
          '<div class="ab-up-text">'+entry.body+'</div>'+
        '</div>'+
      '</div>';
  }).join('');

  return ''+
    '<div class="ab-updates">'+
      '<div class="ab-up-header">'+
        '<div class="ab-up-eyebrow">∴ Build Log</div>'+
        '<div class="ab-up-head">What'+"'"+'s New · What'+"'"+'s Next</div>'+
        '<div class="ab-up-lede">What I shipped, what I broke, what I'+"'"+'m thinking about. Entries signed <strong>-RR</strong> are me in my own voice. The rest is the project talking.</div>'+
        '<div class="ab-up-stats">'+
          '<div class="ab-up-stat"><div class="ab-up-stat-n">9</div><div class="ab-up-stat-l">Era Experiences</div></div>'+
          '<div class="ab-up-stat-sep">·</div>'+
          '<div class="ab-up-stat"><div class="ab-up-stat-n">24</div><div class="ab-up-stat-l">Eras Mapped</div></div>'+
          '<div class="ab-up-stat-sep">·</div>'+
          '<div class="ab-up-stat"><div class="ab-up-stat-n">50+</div><div class="ab-up-stat-l">Marga Pages</div></div>'+
          '<div class="ab-up-stat-sep">·</div>'+
          '<div class="ab-up-stat"><div class="ab-up-stat-n">138</div><div class="ab-up-stat-l">Kośa Terms</div></div>'+
        '</div>'+
      '</div>'+
      '<div class="ab-up-timeline">'+itemsHtml+'</div>'+
      '<div class="ab-up-footer">'+
        '<div class="ab-up-foot-line">— End of log —</div>'+
        '<div class="ab-up-foot-sig">If you want to tell me something you noticed, broken or otherwise: <a href="mailto:dharma@livingsanatan.com">dharma@livingsanatan.com</a></div>'+
        '<div class="ab-up-foot-rr">-RR</div>'+
      '</div>'+
    '</div>';
}

function initUpdatesAnimations(){
  // Stagger-fade each entry in on render
  var items=document.querySelectorAll('.ab-up-item');
  items.forEach(function(el){
    setTimeout(function(){ el.classList.add('visible'); }, parseInt(el.style.getPropertyValue('--up-delay'))||0);
  });
}

// Background particle field for About page
function initAbCanvas(){
  const ov=document.getElementById('about-ov');
  abCanvas=document.getElementById('ab-canvas');
  if(!abCanvas){
    abCanvas=document.createElement('canvas');
    abCanvas.id='ab-canvas';
    abCanvas.style.cssText='position:absolute;inset:0;width:100%;height:100%;pointer-events:none;opacity:.35;';
    ov.insertBefore(abCanvas,ov.firstChild);
  }
  const dpr=window.devicePixelRatio||1;
  abCanvas.width=ov.clientWidth*dpr;
  abCanvas.height=ov.clientHeight*dpr;
  abCanvas.style.width=ov.clientWidth+'px';
  abCanvas.style.height=ov.clientHeight+'px';
  abCtx=abCanvas.getContext('2d');
  abCtx.scale(dpr,dpr);
  if(abAnimFrame)cancelAnimationFrame(abAnimFrame);
  abAnimFrame=requestAnimationFrame(drawAbBg);
}
let abParticles=null, abT=0;
function drawAbBg(){
  if(!abCtx){abAnimFrame=null;return;}
  const W=abCanvas.clientWidth,H=abCanvas.clientHeight;
  if(!abParticles){
    abParticles=[];
    for(let i=0;i<80;i++) abParticles.push({
      x:Math.random()*W,y:Math.random()*H,
      vx:(Math.random()-.5)*.25,vy:(Math.random()-.5)*.25,
      r:Math.random()*1.2+.3,a:Math.random()*.3+.05
    });
  }
  abCtx.clearRect(0,0,W,H);
  abT+=0.003;
  // Holographic grid
  const gridSpacing=60;
  abCtx.strokeStyle='rgba(201,168,76,.018)';abCtx.lineWidth=.5;
  for(let x=0;x<W;x+=gridSpacing){
    const drift=Math.sin(abT+x*0.005)*3;
    abCtx.beginPath();abCtx.moveTo(x+drift,0);abCtx.lineTo(x+drift,H);abCtx.stroke();
  }
  for(let y=0;y<H;y+=gridSpacing){
    const drift=Math.cos(abT+y*0.005)*3;
    abCtx.beginPath();abCtx.moveTo(0,y+drift);abCtx.lineTo(W,y+drift);abCtx.stroke();
  }
  // Scanning line
  const scanY=(abT*80)%H;
  const scanG=abCtx.createLinearGradient(0,scanY-2,0,scanY+2);
  scanG.addColorStop(0,'transparent');scanG.addColorStop(0.5,'rgba(201,168,76,.06)');scanG.addColorStop(1,'transparent');
  abCtx.fillStyle=scanG;abCtx.fillRect(0,scanY-2,W,4);
  // Particles
  abParticles.forEach(p=>{
    p.x=(p.x+p.vx+W)%W; p.y=(p.y+p.vy+H)%H;
    const pulse=p.a*(0.4+0.6*Math.sin(abT*2+p.x*.01));
    abCtx.beginPath();abCtx.arc(p.x,p.y,p.r,0,Math.PI*2);
    abCtx.fillStyle=`rgba(201,168,76,${pulse})`;abCtx.fill();
  });
  // Connect nearby particles
  for(let i=0;i<abParticles.length;i++){
    for(let j=i+1;j<abParticles.length;j++){
      const a=abParticles[i],b=abParticles[j];
      const d=Math.hypot(a.x-b.x,a.y-b.y);
      if(d<100){
        abCtx.beginPath();abCtx.moveTo(a.x,a.y);abCtx.lineTo(b.x,b.y);
        abCtx.strokeStyle=`rgba(201,168,76,${(1-d/100)*0.04})`;abCtx.lineWidth=.4;abCtx.stroke();
      }
    }
  }
  // Rotating triangles — Shri Yantra-ish
  const cx=W/2,cy=H/2,R=Math.min(W,H)*.3;
  for(let t=0;t<3;t++){
    const a=abT*0.25+t*(Math.PI*2/3);
    abCtx.beginPath();
    for(let v=0;v<3;v++){
      const va=a+v*(Math.PI*2/3);
      const x=cx+Math.cos(va)*R,y=cy+Math.sin(va)*R;
      v===0?abCtx.moveTo(x,y):abCtx.lineTo(x,y);
    }
    abCtx.closePath();
    abCtx.strokeStyle=`rgba(201,168,76,${0.02+t*0.008})`;abCtx.lineWidth=.5;abCtx.stroke();
  }
  // Corner brackets (HUD frame)
  const bk=30,bkO=8;
  abCtx.strokeStyle='rgba(201,168,76,.04)';abCtx.lineWidth=1;
  [[bkO,bkO,bk,0,0,bk],[W-bkO,bkO,-bk,0,0,bk],[bkO,H-bkO,bk,0,0,-bk],[W-bkO,H-bkO,-bk,0,0,-bk]].forEach(([x,y,dx1,dy1,dx2,dy2])=>{
    abCtx.beginPath();abCtx.moveTo(x+dx1,y+dy1);abCtx.lineTo(x,y);abCtx.lineTo(x+dx2,y+dy2);abCtx.stroke();
  });
  abAnimFrame=requestAnimationFrame(drawAbBg);
}

