// ═══ Fix 3: Tab scroll hint init ═══════════════════════
function initScrollHints(){
  // Wrap all horizontal scroll tab bars
  const selectors=['.kmap-s-tabs','.mr-tabs','.cons-nav','#dc-tabs','#kmap-filter','.cons-nav'];
  selectors.forEach(sel=>{
    document.querySelectorAll(sel).forEach(el=>{
      if(el.parentElement.classList.contains('tab-scroll-wrap'))return;
      const wrap=document.createElement('div');
      wrap.className='tab-scroll-wrap';
      el.parentNode.insertBefore(wrap,el);
      wrap.appendChild(el);
      el.addEventListener('scroll',()=>{
        const atEnd=el.scrollLeft+el.clientWidth>=el.scrollWidth-4;
        wrap.classList.toggle('at-end',atEnd);
      },{passive:true});
    });
  });
}
// Call after any overlay opens
['openKnowledgeMap','openMantraMap','openConsciousness','openDharmaCompass'].forEach(fn=>{
  const orig=window[fn];
  if(orig) window[fn]=function(...a){orig(...a);setTimeout(initScrollHints,200);};
});


