// Method canvas — flowing particle lines connecting dots
let abMethodFrame=null;
function initAbMethodCanvas(){
  const canvas=document.getElementById('ab-method-canvas');
  if(!canvas)return;
  const wrap=canvas.parentElement;
  const dpr=window.devicePixelRatio||1;
  canvas.width=wrap.clientWidth*dpr;
  canvas.height=wrap.clientHeight*dpr;
  canvas.style.width=wrap.clientWidth+'px';
  canvas.style.height=wrap.clientHeight+'px';
  const ctx=canvas.getContext('2d');
  ctx.scale(dpr,dpr);
  const W=wrap.clientWidth,H=wrap.clientHeight;
  if(abMethodFrame)cancelAnimationFrame(abMethodFrame);
  let t=0;
  const dots=document.querySelectorAll('.ab-mi-dot');
  function draw(){
    if(!document.getElementById('ab-method-canvas')){abMethodFrame=null;return;}
    t+=0.006;
    ctx.clearRect(0,0,W,H);
    // Get dot positions relative to canvas
    const rects=[...dots].map(d=>{
      const r=d.getBoundingClientRect();
      const cr=canvas.getBoundingClientRect();
      return{x:r.left-cr.left+r.width/2,y:r.top-cr.top+r.height/2};
    });
    // Draw flowing curves between dots
    for(let i=0;i<rects.length-1;i++){
      const a=rects[i],b=rects[i+1];
      const mx=(a.x+b.x)/2+Math.sin(t+i)*20;
      const my=(a.y+b.y)/2;
      ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.quadraticCurveTo(mx,my,b.x,b.y);
      ctx.strokeStyle=`rgba(201,168,76,${0.06+0.04*Math.sin(t+i)})`;
      ctx.lineWidth=1;ctx.stroke();
    }
    // Pulse ripple at each dot
    rects.forEach((r,i)=>{
      const p=(t*0.8+i*1.5)%1;
      const radius=p*30;
      ctx.beginPath();ctx.arc(r.x,r.y,radius,0,Math.PI*2);
      ctx.strokeStyle=`rgba(201,168,76,${(1-p)*0.12})`;
      ctx.lineWidth=1;ctx.stroke();
    });
    abMethodFrame=requestAnimationFrame(draw);
  }
  draw();
}

// Field canvas — fluid particle field that responds to mouse/touch
let abFieldFrame=null, abFieldMx=0.5, abFieldMy=0.5, abFieldParticles=null;
function initAbField(){
  const canvas=document.getElementById('ab-field-canvas');
  if(!canvas)return;
  const dpr=window.devicePixelRatio||1;
  const W=canvas.clientWidth,H=canvas.clientHeight;
  canvas.width=W*dpr;canvas.height=H*dpr;
  const ctx=canvas.getContext('2d');
  ctx.scale(dpr,dpr);
  abFieldParticles=[];
  for(let i=0;i<120;i++) abFieldParticles.push({
    x:Math.random()*W,y:Math.random()*H,
    vx:0,vy:0,hue:Math.random()*60+140,life:Math.random()
  });
  function getPos(e){
    const r=canvas.getBoundingClientRect();
    if(e.touches&&e.touches.length>0){
      return{x:(e.touches[0].clientX-r.left),y:(e.touches[0].clientY-r.top)};
    }
    return{x:e.clientX-r.left,y:e.clientY-r.top};
  }
  function onMove(e){e.preventDefault();const p=getPos(e);abFieldMx=p.x/W;abFieldMy=p.y/H;}
  canvas.addEventListener('mousemove',onMove,{passive:false});
  canvas.addEventListener('touchmove',onMove,{passive:false});
  if(abFieldFrame)cancelAnimationFrame(abFieldFrame);
  let t=0;
  function draw(){
    if(!document.getElementById('ab-field-canvas')){abFieldFrame=null;return;}
    t+=0.01;
    ctx.fillStyle='rgba(2,5,4,.12)';ctx.fillRect(0,0,W,H);
    const mx=abFieldMx*W,my=abFieldMy*H;
    abFieldParticles.forEach(p=>{
      const dx=p.x-mx,dy=p.y-my;
      const dist=Math.sqrt(dx*dx+dy*dy)||1;
      const angle=Math.atan2(dy,dx)+Math.sin(t+p.x*0.008)*1.5+Math.cos(t+p.y*0.008)*1.5;
      const force=Math.min(60/dist,2);
      p.vx+=(Math.cos(angle)*force-p.vx)*0.08;
      p.vy+=(Math.sin(angle)*force-p.vy)*0.08;
      p.x=(p.x+p.vx+W)%W;p.y=(p.y+p.vy+H)%H;
      const speed=Math.sqrt(p.vx*p.vx+p.vy*p.vy);
      ctx.beginPath();ctx.arc(p.x,p.y,1+speed*.3,0,Math.PI*2);
      ctx.fillStyle=`hsla(${p.hue+speed*10},70%,70%,${0.3+speed*0.1})`;
      ctx.fill();
    });
    abFieldFrame=requestAnimationFrame(draw);
  }
  draw();
}

