// vars declared globally

function openMirror(){
  document.getElementById('mirror-ov').classList.add('on');
  dmAnswers={};dmCurrentQ=0;
  renderDmQuestion();
}
function closeMirror(){document.getElementById('mirror-ov').classList.remove('on');}

function renderDmQuestion(){
  const container=document.getElementById('dm-container');
  const q=DM_QUESTIONS[dmCurrentQ];
  const progressHtml=DM_QUESTIONS.map((_,i)=>`<div class="dm-prog-dot ${i<dmCurrentQ?'done':i===dmCurrentQ?'current':''}"></div>`).join('');

  container.innerHTML=`
    <div class="dm-intro" id="dm-intro-wrap">
      <span class="dm-intro-om">ॐ</span>
      <div class="dm-intro-h">The Dharmic Mirror</div>
      <div class="dm-intro-s">Seven questions. Your path revealed.</div>
    </div>
    <div class="dm-progress">${progressHtml}</div>
    <div class="dm-q-wrap">
      <div class="dm-q-num">Question ${dmCurrentQ+1} of ${DM_QUESTIONS.length}</div>
      <div class="dm-q-text">${q.q}</div>
      <div class="dm-options">
        ${q.opts.map((o,i)=>`
          <div class="dm-opt ${dmAnswers[dmCurrentQ]===i?'selected':''}" onclick="dmSelect(${i})">
            <div class="dm-opt-text">${o.text}</div>
          </div>`).join('')}
      </div>
    </div>
    <div style="display:flex;gap:10px;justify-content:center;margin-top:8px;">
      ${dmCurrentQ>0?`<button class="dm-submit" style="max-width:140px" onclick="dmBack()">← Back</button>`:''}
      <button class="dm-submit" onclick="dmNext()" ${dmAnswers[dmCurrentQ]===undefined?'disabled style="opacity:.3"':''}>
        ${dmCurrentQ<DM_QUESTIONS.length-1?'Next →':'Reveal My Path →'}
      </button>
    </div>
  `;
}

function dmSelect(i){
  dmAnswers[dmCurrentQ]=i;
  renderDmQuestion();
}
function dmBack(){if(dmCurrentQ>0){dmCurrentQ--;renderDmQuestion();}}
function dmNext(){
  if(dmAnswers[dmCurrentQ]===undefined)return;
  if(dmCurrentQ<DM_QUESTIONS.length-1){dmCurrentQ++;renderDmQuestion();}
  else showDmResult();
}

function showDmResult(){
  // Tally tags
  const counts={jnana:0,karma:0,bhakti:0,raja:0};
  Object.entries(dmAnswers).forEach(([qi,ai])=>{
    const tag=DM_QUESTIONS[qi].opts[ai].tag;
    counts[tag]=(counts[tag]||0)+1;
  });
  const top=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0][0];
  const res=DM_RESULTS[top];

  const container=document.getElementById('dm-container');
  container.innerHTML=`
    <div style="text-align:center;padding:30px 0 16px">
      <div style="font-family:'IBM Plex Mono',monospace;font-size:6.5px;letter-spacing:5px;text-transform:uppercase;color:rgba(100,160,240,.3);margin-bottom:8px">Your Path</div>
      <div style="font-family:'Cormorant Garamond',serif;font-size:clamp(22px,3vw,36px);font-style:italic;color:${res.color};margin-bottom:4px">${res.skt}</div>
      <div class="dm-result-h" style="color:${res.color}">${res.name}</div>
    </div>
    <div class="dm-result-canvas-wrap"><canvas id="dm-result-canvas"></canvas></div>
    <div style="font-family:'Cormorant Garamond',serif;font-size:clamp(15px,1.8vw,19px);font-style:italic;color:${res.color.replace('1)','0.7)')};text-align:center;margin-bottom:20px;padding:0 10px">"${res.headline}"</div>
    <div class="dm-result-grid">
      <div class="dm-result-card"><div class="dm-result-card-lbl">Avatar Lineage</div><div class="dm-result-card-val">${res.avatar}</div></div>
      <div class="dm-result-card"><div class="dm-result-card-lbl">Era</div><div class="dm-result-card-val">${res.era}</div></div>
      <div class="dm-result-card"><div class="dm-result-card-lbl">Mahāvākya</div><div class="dm-result-card-val" style="font-size:13px">${res.mahavakya}</div></div>
      <div class="dm-result-card"><div class="dm-result-card-lbl">Yuga Type</div><div class="dm-result-card-val" style="font-size:13px">${res.yuga}</div></div>
    </div>
    <div class="dm-result-body">${res.body}</div>
    <div style="background:rgba(100,160,240,.04);border:1px solid rgba(100,160,240,.1);padding:14px 16px;margin-bottom:20px;">
      <div style="font-family:'IBM Plex Mono',monospace;font-size:6.5px;letter-spacing:3px;text-transform:uppercase;color:rgba(100,160,240,.3);margin-bottom:8px">Practice for You</div>
      <div style="font-size:13.5px;line-height:1.85;color:rgba(180,210,255,.55);font-style:italic">${res.practice}</div>
    </div>
    <button class="dm-restart" onclick="dmRestart()">Take Again</button>
  `;
  setTimeout(()=>initDmResultCanvas(counts,res.color),80);
}

function dmRestart(){dmAnswers={};dmCurrentQ=0;renderDmQuestion();}

function initDmResultCanvas(counts,col){
  const c=document.getElementById('dm-result-canvas');
  if(!c)return;
  const dpr=window.devicePixelRatio||1;
  const size=c.clientWidth||300;
  c.width=size*dpr;c.height=size*dpr;
  c.style.width=size+'px';c.style.height=size+'px';
  const ctx=c.getContext('2d');ctx.scale(dpr,dpr);
  const cx=size/2,cy=size/2,R=size*0.38;
  const paths=['jnana','karma','bhakti','raja'];
  const cols=['rgba(200,180,100,1)','rgba(100,200,140,1)','rgba(220,100,130,1)','rgba(100,160,240,1)'];
  const labels=['Jñāna','Karma','Bhakti','Rāja'];
  const total=Object.values(counts).reduce((a,b)=>a+b,0)||1;
  let t=0;
  function draw(){
    ctx.clearRect(0,0,size,size);
    // Background
    ctx.beginPath();ctx.arc(cx,cy,R,0,Math.PI*2);
    ctx.fillStyle='rgba(2,4,2,.8)';ctx.fill();
    // Segments
    let startA=-Math.PI/2;
    paths.forEach((p,i)=>{
      const frac=(counts[p]||0)/total;
      const endA=startA+frac*Math.PI*2;
      ctx.beginPath();ctx.moveTo(cx,cy);
      ctx.arc(cx,cy,R,startA,endA);ctx.closePath();
      ctx.fillStyle=cols[i].replace('1)',`${0.3+frac*0.5})`);ctx.fill();
      // Label
      const midA=(startA+endA)/2;
      const lx=cx+Math.cos(midA)*R*0.65,ly=cy+Math.sin(midA)*R*0.65;
      if(frac>0.05){
        ctx.font=`8px 'IBM Plex Mono',monospace`;
        ctx.fillStyle=cols[i];ctx.textAlign='center';ctx.textBaseline='middle';
        ctx.fillText(labels[i],lx,ly);
      }
      startA=endA;
    });
    // Center ring
    ctx.beginPath();ctx.arc(cx,cy,R*0.25,0,Math.PI*2);
    ctx.fillStyle='rgba(2,4,2,.95)';ctx.fill();
    ctx.strokeStyle=col.replace('1)','0.4)');ctx.lineWidth=1.5;ctx.stroke();
    ctx.font=`italic 13px 'Cormorant Garamond',serif`;
    ctx.fillStyle=col.replace('1)','0.8)');ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.fillText('ॐ',cx,cy);
  }
  draw();
}

