// --- STATE ---
let lm2MapCanvas=null,lm2MapCtx=null,lm2MapFrame=null,lm2T=0;
let lm2ActiveTab='map';
let lm2SelectedYuga='all';
let lm2SelectedSite=null,lm2HoveredSite=null;
let lm2BargadCanvas=null,lm2BargadCtx=null,lm2BargadFrame=null;
let lm2NadaCanvas=null,lm2NadaCtx=null,lm2NadaFrame=null;
let lm2AudioCtx=null,lm2ActiveNodes=[],lm2ActiveSiteSound=null;
let lm2WaveCanvas=null,lm2WaveCtx=null,lm2NadaT=0,lm2NadaFreq=0,lm2NadaActive=false;
let lm2BargadT=0,lm2BargadHover=null;
let lm2Particles=[];

// --- OPEN / CLOSE ---
function openLivingMap(){
  document.getElementById('livemap-ov').classList.add('on');
  setTimeout(lm2Start,120);
}
function closeLivingMap(){
  document.getElementById('livemap-ov').classList.remove('on');
  lm2StopAll();
}
function lm2StopAll(){
  if(lm2MapFrame){cancelAnimationFrame(lm2MapFrame);lm2MapFrame=null;}
  if(lm2BargadFrame){cancelAnimationFrame(lm2BargadFrame);lm2BargadFrame=null;}
  if(lm2NadaFrame){cancelAnimationFrame(lm2NadaFrame);lm2NadaFrame=null;}
  lm2StopSound();
}
function lm2Start(){
  lm2T=0; lm2BargadT=0; lm2NadaT=0;
  lm2Particles=[];
  lm2ActiveTab='map';
  lm2SelectedSite=null; lm2HoveredSite=null;
  lm2SelectedYuga='all';
  const ov=document.getElementById('livemap-ov');
  if(!ov)return;
  // Reset tabs
  ov.querySelectorAll('.lm2-tab-btn').forEach((b,i)=>b.classList.toggle('active',i===0));
  ov.querySelectorAll('.lm2-panel').forEach((p,i)=>p.classList.toggle('active',i===0));
  ov.querySelectorAll('.lm2-era-btn').forEach((b,i)=>b.classList.toggle('active',i===0));
  // Close site card
  const card=document.getElementById('lm2-site-card');
  if(card)card.classList.remove('open');
  lm2InitMap();
}

// --- TABS ---
function lm2Tab(which,btn){
  lm2ActiveTab=which;
  document.querySelectorAll('.lm2-tab-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  document.querySelectorAll('.lm2-panel').forEach(p=>p.classList.remove('active'));
  document.getElementById('lm2-'+which+'-panel').classList.add('active');
  lm2StopAll();
  if(which==='map') setTimeout(lm2InitMap,60);
  else if(which==='bargad') setTimeout(lm2InitBargad,60);
  else if(which==='nada') setTimeout(lm2InitNada,60);
}

// --- ERA FILTER ---
function lm2EraFilter(yuga,btn){
  lm2SelectedYuga=yuga;
  document.querySelectorAll('.lm2-era-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  lm2CloseCard();
  lm2HoveredSite=null;
  lm2SelectedSite=null;
}
function lm2CloseCard(){
  const card=document.getElementById('lm2-site-card');
  if(card)card.classList.remove('open');
  lm2SelectedSite=null;
  const hint=document.getElementById('lm2-map-hint');
  if(hint)hint.classList.remove('hidden');
}

// --- GEO TO CANVAS ---
function lm2Geo(lon,lat,W,H){
  const lonMin=25,lonMax=142,latMin=4,latMax=60;
  const pad=Math.min(W,H)*0.03;
  const gW=lonMax-lonMin,gH=latMax-latMin;
  const scX=(W-pad*2)/gW,scY=(H-pad*2)/gH;
  const sc=Math.min(scX,scY);
  const mW=gW*sc,mH=gH*sc;
  const ox=(W-mW)/2,oy=(H-mH)/2;
  return{x:ox+(lon-lonMin)*sc,y:oy+(latMax-lat)*sc,sc};
}

// ═══════════════════════════════
//  MAP PANEL
// ═══════════════════════════════
function lm2InitMap(){
  const panel=document.getElementById('lm2-map-panel');
  lm2MapCanvas=document.getElementById('lm2-map-canvas');
  if(!lm2MapCanvas||!panel)return;
  const dpr=window.devicePixelRatio||1;
  const W=panel.clientWidth||window.innerWidth;
  const H=panel.clientHeight||(window.innerHeight-80);
  lm2MapCanvas.width=W*dpr; lm2MapCanvas.height=H*dpr;
  lm2MapCanvas.style.width=W+'px'; lm2MapCanvas.style.height=H+'px';
  lm2MapCtx=lm2MapCanvas.getContext('2d');
  lm2MapCtx.scale(dpr,dpr);
  lm2MapCanvas.onclick=lm2MapClick;
  lm2MapCanvas.onmousemove=lm2MapHover;
  lm2MapCanvas.ontouchstart=function(e){e.preventDefault();const t=e.touches[0];lm2MapClick({clientX:t.clientX,clientY:t.clientY});};
  // Init particles
  lm2Particles=Array.from({length:40},()=>({
    x:Math.random()*W,y:Math.random()*H,
    vx:(Math.random()-.5)*0.3,vy:(Math.random()-.5)*0.2,
    r:Math.random()*1.5+0.5,
    a:Math.random(),life:Math.random()*200
  }));
  if(lm2MapFrame)cancelAnimationFrame(lm2MapFrame);
  lm2MapFrame=requestAnimationFrame(lm2DrawMap);
}

function lm2DrawMap(){
  if(!lm2MapCtx){lm2MapFrame=null;return;}
  lm2T+=0.012;
  const ctx=lm2MapCtx;
  const W=lm2MapCanvas.clientWidth,H=lm2MapCanvas.clientHeight;
  ctx.clearRect(0,0,W,H);

  // Sky background gradient
  const sky=ctx.createRadialGradient(W*.5,H*.3,0,W*.5,H*.5,Math.max(W,H)*.7);
  sky.addColorStop(0,'rgba(8,5,18,.98)');
  sky.addColorStop(.4,'rgba(5,3,12,.99)');
  sky.addColorStop(1,'rgba(2,1,5,1)');
  ctx.fillStyle=sky; ctx.fillRect(0,0,W,H);

  // Particles (stars)
  lm2Particles.forEach(p=>{
    p.x+=p.vx; p.y+=p.vy; p.life++;
    if(p.x<0||p.x>W)p.vx*=-1;
    if(p.y<0||p.y>H)p.vy*=-1;
    const pulse=0.4+0.3*Math.sin(lm2T*1.5+p.life*0.05);
    ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
    ctx.fillStyle=`rgba(200,180,255,${pulse*0.35})`; ctx.fill();
  });

  // Draw India
  lm2DrawIndia(ctx,W,H);
  // Draw rivers
  lm2DrawRivers(ctx,W,H);
  // Draw sites
  lm2DrawSites(ctx,W,H);

  lm2MapFrame=requestAnimationFrame(lm2DrawMap);
}

function lm2DrawIndia(ctx,W,H){
  if(!LM2_INDIA_POLY.length)return;

  // ── LAYER 1: JAMBUDWEEPA — the full Asian continent (dim) ──
  ctx.save();
  ctx.beginPath();
  LM2_INDIA_POLY.forEach((pt,i)=>{
    const {x,y}=lm2Geo(pt[0],pt[1],W,H);
    if(i===0)ctx.moveTo(x,y); else ctx.lineTo(x,y);
  });
  ctx.closePath();
  // Deep fill — darker for the outer continent
  const fill=ctx.createLinearGradient(0,0,W,H);
  fill.addColorStop(0,'rgba(10,7,22,.55)');
  fill.addColorStop(.5,'rgba(8,5,18,.6)');
  fill.addColorStop(1,'rgba(6,4,14,.55)');
  ctx.fillStyle=fill; ctx.fill();
  // Faint outer border
  ctx.strokeStyle='rgba(100,70,160,.25)'; ctx.lineWidth=1;
  ctx.shadowColor='rgba(120,80,200,.2)'; ctx.shadowBlur=6;
  ctx.stroke(); ctx.shadowBlur=0;
  ctx.restore();

  // Subtle latitude grid inside continent
  ctx.save();
  ctx.globalAlpha=0.025;
  ctx.beginPath();
  LM2_INDIA_POLY.forEach((pt,i)=>{
    const {x,y}=lm2Geo(pt[0],pt[1],W,H);
    if(i===0)ctx.moveTo(x,y); else ctx.lineTo(x,y);
  });
  ctx.closePath(); ctx.clip();
  for(let lat=10;lat<60;lat+=10){
    const a=lm2Geo(25,lat,W,H),b=lm2Geo(142,lat,W,H);
    ctx.beginPath(); ctx.moveTo(a.x,a.y); ctx.lineTo(b.x,b.y);
    ctx.strokeStyle='rgba(180,160,255,.6)'; ctx.lineWidth=.4; ctx.stroke();
  }
  for(let lon=40;lon<142;lon+=15){
    const a=lm2Geo(lon,60,W,H),b=lm2Geo(lon,4,W,H);
    ctx.beginPath(); ctx.moveTo(a.x,a.y); ctx.lineTo(b.x,b.y);
    ctx.strokeStyle='rgba(180,160,255,.6)'; ctx.lineWidth=.4; ctx.stroke();
  }
  ctx.restore();

  // ── LAYER 2: BHĀRAT — the sacred inner geography glowing on top ──
  if(LM2_BHARAT_POLY&&LM2_BHARAT_POLY.length){
    ctx.save();
    // Radial glow behind Bharat
    const bc=lm2Geo(80,22,W,H);
    const bg=ctx.createRadialGradient(bc.x,bc.y,0,bc.x,bc.y,Math.min(W,H)*.28);
    bg.addColorStop(0,'rgba(160,120,255,.12)');
    bg.addColorStop(.5,'rgba(100,70,200,.06)');
    bg.addColorStop(1,'rgba(80,50,150,0)');
    ctx.fillStyle=bg; ctx.fillRect(0,0,W,H);

    ctx.beginPath();
    LM2_BHARAT_POLY.forEach((pt,i)=>{
      const {x,y}=lm2Geo(pt[0],pt[1],W,H);
      if(i===0)ctx.moveTo(x,y); else ctx.lineTo(x,y);
    });
    ctx.closePath();
    // Brighter fill for Bharat
    const bf=ctx.createLinearGradient(0,0,W,H);
    bf.addColorStop(0,'rgba(20,14,40,.7)');
    bf.addColorStop(.5,'rgba(16,10,35,.75)');
    bf.addColorStop(1,'rgba(12,8,28,.7)');
    ctx.fillStyle=bf; ctx.fill();
    // Glowing border for Bharat
    ctx.strokeStyle='rgba(180,130,255,.55)'; ctx.lineWidth=1.5;
    ctx.shadowColor='rgba(200,150,255,.5)'; ctx.shadowBlur=14;
    ctx.stroke(); ctx.shadowBlur=0;
    ctx.restore();
  }

  // ── LAYER 3: SRI LANKA — Laṅkā ──
  if(LM2_SRILANKA_POLY&&LM2_SRILANKA_POLY.length){
    ctx.save();
    ctx.beginPath();
    LM2_SRILANKA_POLY.forEach((pt,i)=>{
      const {x,y}=lm2Geo(pt[0],pt[1],W,H);
      if(i===0)ctx.moveTo(x,y); else ctx.lineTo(x,y);
    });
    ctx.closePath();
    ctx.fillStyle='rgba(22,12,38,.8)'; ctx.fill();
    ctx.strokeStyle='rgba(220,110,70,.45)'; ctx.lineWidth=1.2;
    ctx.shadowColor='rgba(220,110,70,.5)'; ctx.shadowBlur=8; ctx.stroke();
    ctx.shadowBlur=0; ctx.restore();
    const lk=lm2Geo(80.7,7.5,W,H);
    ctx.save(); ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.font=`6px 'IBM Plex Mono',monospace`;
    ctx.fillStyle='rgba(220,110,70,.4)';
    ctx.fillText('LAṄKĀ',lk.x,lk.y); ctx.restore();
  }

  // ── HIMALAYAN ARC — the spine of the continent ──
  const himPts=[[61,37],[65,34],[69,34],[74,37],[78,35],[80,31],[84,28],[87,27],[94,27],[97,28]];
  ctx.save();
  ctx.beginPath();
  himPts.forEach((pt,i)=>{
    const {x,y}=lm2Geo(pt[0],pt[1],W,H);
    if(i===0)ctx.moveTo(x,y); else ctx.lineTo(x,y);
  });
  ctx.strokeStyle='rgba(220,235,255,.18)'; ctx.lineWidth=4;
  ctx.shadowColor='rgba(210,230,255,.3)'; ctx.shadowBlur=10; ctx.stroke();
  ctx.shadowBlur=0; ctx.restore();

  // ── REGION LABELS on the full continent ──
  const labels=[
    {txt:'JAMBUDWEEPA',lon:83,lat:52,size:7,col:'rgba(160,120,255,.16)'},
    {txt:'BHĀRAT',lon:80,lat:23,size:8,col:'rgba(200,160,255,.22)'},
    {txt:'CĪNA',lon:108,lat:36,size:7,col:'rgba(140,100,200,.14)'},
    {txt:'GANDHĀRA',lon:68,lat:33,size:6,col:'rgba(180,140,220,.12)'},
    {txt:'KAMBOJA',lon:104,lat:14,size:6,col:'rgba(140,100,200,.12)'},
    {txt:'PERSIA',lon:56,lat:32,size:6,col:'rgba(140,100,200,.10)'},
    {txt:'LAṄKĀ',lon:80.7,lat:7.5,size:6,col:'rgba(220,110,70,.35)'},
  ];
  labels.forEach(lb=>{
    const {x,y}=lm2Geo(lb.lon,lb.lat,W,H);
    ctx.save(); ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.font=`${lb.size}px 'IBM Plex Mono',monospace`;
    ctx.fillStyle=lb.col; ctx.fillText(lb.txt,x,y); ctx.restore();
  });
}

function lm2DrawRivers(ctx,W,H){
  LM2_RIVERS.forEach(river=>{
    if(!river.pts.length)return;
    ctx.save();
    ctx.beginPath();
    river.pts.forEach((pt,i)=>{
      const {x,y}=lm2Geo(pt[0],pt[1],W,H);
      if(i===0)ctx.moveTo(x,y);
      else{
        const prev=lm2Geo(river.pts[i-1][0],river.pts[i-1][1],W,H);
        const cx=(prev.x+x)/2,cy=(prev.y+y)/2;
        ctx.quadraticCurveTo(prev.x+(Math.random()-.5)*2,prev.y+(Math.random()-.5)*2,x,y);
      }
    });
    if(river.dashed)ctx.setLineDash([4,6]);
    ctx.strokeStyle=river.col+'0.2)'; ctx.lineWidth=river.dashed?1:1.5;
    ctx.shadowColor=river.col+'0.3)'; ctx.shadowBlur=4;
    ctx.stroke(); ctx.setLineDash([]); ctx.shadowBlur=0;
    ctx.restore();
  });
}

function lm2DrawSites(ctx,W,H){
  const active=LM2_SITES.filter(s=>lm2SelectedYuga==='all'||s.yuga===lm2SelectedYuga);
  const inactive=LM2_SITES.filter(s=>lm2SelectedYuga!=='all'&&s.yuga!==lm2SelectedYuga);

  // Draw inactive (faint)
  inactive.forEach(s=>{
    const {x,y}=lm2Geo(s.lon,s.lat,W,H);
    ctx.beginPath(); ctx.arc(x,y,3,0,Math.PI*2);
    ctx.fillStyle='rgba(100,80,140,.2)'; ctx.fill();
  });

  // Draw active
  active.forEach(s=>{
    const {x,y}=lm2Geo(s.lon,s.lat,W,H);
    const isSel=lm2SelectedSite&&lm2SelectedSite.id===s.id;
    const isHov=lm2HoveredSite&&lm2HoveredSite.id===s.id;
    const pulse=1+0.15*Math.sin(lm2T*2.5+s.lon*0.3);

    // Outer glow ring
    const glow=ctx.createRadialGradient(x,y,0,x,y,isSel?28:18);
    glow.addColorStop(0,s.col+(isSel?'0.5)':isHov?'0.35)':'0.18)'));
    glow.addColorStop(1,s.col+'0)');
    ctx.beginPath(); ctx.arc(x,y,(isSel?28:18)*pulse,0,Math.PI*2);
    ctx.fillStyle=glow; ctx.fill();

    // Connection lines from selected to nearby
    if(isSel){
      active.forEach(other=>{
        if(other.id===s.id)return;
        const ot=lm2Geo(other.lon,other.lat,W,H);
        const dist=Math.hypot(x-ot.x,y-ot.y);
        if(dist<180){
          ctx.save();
          ctx.beginPath(); ctx.moveTo(x,y); ctx.lineTo(ot.x,ot.y);
          ctx.strokeStyle=s.col+'0.12)'; ctx.lineWidth=.8;
          ctx.setLineDash([3,6]); ctx.stroke(); ctx.setLineDash([]); ctx.restore();
        }
      });
    }

    // Core dot
    const r=isSel?7:isHov?6:4.5;
    ctx.beginPath(); ctx.arc(x,y,r*pulse,0,Math.PI*2);
    const dotFill=ctx.createRadialGradient(x-r*.3,y-r*.3,0,x,y,r*pulse);
    dotFill.addColorStop(0,'rgba(255,255,255,.9)');
    dotFill.addColorStop(.4,s.col+'0.9)');
    dotFill.addColorStop(1,s.col+'0.5)');
    ctx.fillStyle=dotFill;
    ctx.shadowColor=s.col+'0.8)'; ctx.shadowBlur=isSel?16:8;
    ctx.fill(); ctx.shadowBlur=0;

    // Label
    if(isHov||isSel){
      ctx.save();
      ctx.textAlign='center'; ctx.textBaseline='top';
      const label=s.name;
      ctx.font=`bold 8px 'IBM Plex Mono',monospace`;
      const tw=ctx.measureText(label).width;
      const lx=x,ly=y+(r*pulse)+6;
      ctx.fillStyle='rgba(4,2,10,.8)';
      ctx.fillRect(lx-tw/2-5,ly-2,tw+10,14);
      ctx.fillStyle=s.col+'0.95)';
      ctx.fillText(label,lx,ly);
      ctx.restore();
    }
  });
}

function lm2MapClick(e){
  const rect=lm2MapCanvas.getBoundingClientRect();
  const mx=e.clientX-rect.left,my=e.clientY-rect.top;
  const W=lm2MapCanvas.clientWidth,H=lm2MapCanvas.clientHeight;
  let hit=null,minD=Infinity;
  const visible=LM2_SITES.filter(s=>lm2SelectedYuga==='all'||s.yuga===lm2SelectedYuga);
  visible.forEach(s=>{
    const {x,y}=lm2Geo(s.lon,s.lat,W,H);
    const d=Math.hypot(mx-x,my-y);
    if(d<22&&d<minD){minD=d;hit=s;}
  });
  if(hit){
    lm2SelectedSite=hit;
    lm2ShowCard(hit);
  }
}
function lm2MapHover(e){
  const rect=lm2MapCanvas.getBoundingClientRect();
  const mx=e.clientX-rect.left,my=e.clientY-rect.top;
  const W=lm2MapCanvas.clientWidth,H=lm2MapCanvas.clientHeight;
  let hit=null,minD=Infinity;
  const visible=LM2_SITES.filter(s=>lm2SelectedYuga==='all'||s.yuga===lm2SelectedYuga);
  visible.forEach(s=>{
    const {x,y}=lm2Geo(s.lon,s.lat,W,H);
    const d=Math.hypot(mx-x,my-y);
    if(d<18&&d<minD){minD=d;hit=s;}
  });
  lm2HoveredSite=hit;
  lm2MapCanvas.style.cursor=hit?'pointer':'crosshair';
}
function lm2ShowCard(site){
  const card=document.getElementById('lm2-site-card');
  if(!card)return;
  const yugaNames={satya:'Satya Yuga · Golden Age',treta:'Tretā Yuga · Silver Age',dvapara:'Dvāpara Yuga · Bronze Age',kali:'Kali Yuga · Iron Age'};
  const yugaCols={satya:'rgba(201,168,76,.8)',treta:'rgba(220,110,70,.8)',dvapara:'rgba(60,130,220,.8)',kali:'rgba(140,80,210,.8)'};
  document.getElementById('lm2-sc-yuga-tag').textContent=yugaNames[site.yuga]||'';
  document.getElementById('lm2-sc-yuga-tag').style.color=yugaCols[site.yuga]||'rgba(180,140,220,.6)';
  document.getElementById('lm2-sc-name').textContent=site.name;
  document.getElementById('lm2-sc-era-label').textContent='Era · '+site.era.charAt(0).toUpperCase()+site.era.slice(1);
  document.getElementById('lm2-sc-desc').textContent=site.desc;
  document.getElementById('lm2-sc-mantra').textContent=site.mantra||'';
  const enterBtn=document.getElementById('lm2-sc-enter');
  if(site.fn){
    enterBtn.classList.remove('no-era');
    enterBtn.textContent='Enter '+site.era.charAt(0).toUpperCase()+site.era.slice(1)+' Era →';
  } else {
    enterBtn.classList.add('no-era');
    enterBtn.textContent='Era page coming soon';
  }
  card.classList.add('open');
  const hint=document.getElementById('lm2-map-hint');
  if(hint)hint.classList.add('hidden');
}
function lm2EnterEra(){
  if(!lm2SelectedSite||!lm2SelectedSite.fn)return;
  closeLivingMap();
  setTimeout(()=>{
    if(typeof window[lm2SelectedSite.fn]==='function')window[lm2SelectedSite.fn]();
  },400);
}

// ═══════════════════════════════
//  BARGAD PANEL
// ═══════════════════════════════

// Bargad tree data
const LM2_BARGAD={
  roots:[
    {id:'rg',label:'Ṛg Veda',sublabel:'cognized sound',x:.35,depth:.92,col:'rgba(180,140,60,'},
    {id:'sama',label:'Sāma Veda',sublabel:'melody of cosmos',x:.42,depth:.95,col:'rgba(160,120,50,'},
    {id:'yajur',label:'Yajur Veda',sublabel:'sacrificial knowing',x:.5,depth:.93,col:'rgba(200,160,70,'},
    {id:'atharva',label:'Atharva Veda',sublabel:'protection & healing',x:.58,depth:.92,col:'rgba(180,140,60,'},
    {id:'upanishads',label:'108 Upaniṣads',sublabel:'direct inquiry',x:.65,depth:.9,col:'rgba(220,180,80,'},
    {id:'puranas',label:'18 Purāṇas',sublabel:'mythic memory',x:.28,depth:.9,col:'rgba(200,160,60,'},
  ],
  branches:[
    {id:'satya',label:'Satya Yuga',sublabel:'Śiva · Kailāsa · Meru',angle:-55,r:.3,col:'rgba(201,168,76,',sites:['kailash','kedarnath','saraswati']},
    {id:'treta',label:'Tretā Yuga',sublabel:'Rāma · Ayodhyā · Lanka',angle:-25,r:.32,col:'rgba(220,110,70,',sites:['ayodhya','rameswaram','kishkindha']},
    {id:'dvapara',label:'Dvāpara Yuga',sublabel:'Kṛṣṇa · Kurukṣetra · Dvārakā',angle:20,r:.32,col:'rgba(60,130,220,',sites:['mathura','kurukshetra','dwaraka']},
    {id:'kali',label:'Kali Yuga',sublabel:'Buddha · Ramana · Mahākāla',angle:55,r:.3,col:'rgba(140,80,210,',sites:['bodhgaya','varanasi','tiruvannamalai']},
  ],
  aerials:[
    {fromBranch:'satya',toLoc:'Kedārnāth'},
    {fromBranch:'satya',toLoc:'Kailāsa'},
    {fromBranch:'treta',toLoc:'Ayodhyā'},
    {fromBranch:'treta',toLoc:'Rāmeśvaram'},
    {fromBranch:'dvapara',toLoc:'Mathurā'},
    {fromBranch:'dvapara',toLoc:'Kurukṣetra'},
    {fromBranch:'kali',toLoc:'Vārāṇasī'},
    {fromBranch:'kali',toLoc:'Bodh Gayā'},
  ]
};

function lm2InitBargad(){
  const panel=document.getElementById('lm2-bargad-panel');
  lm2BargadCanvas=document.getElementById('lm2-bargad-canvas');
  if(!lm2BargadCanvas||!panel)return;
  const dpr=window.devicePixelRatio||1;
  const W=panel.clientWidth||window.innerWidth;
  const H=panel.clientHeight||(window.innerHeight-80);
  lm2BargadCanvas.width=W*dpr; lm2BargadCanvas.height=H*dpr;
  lm2BargadCanvas.style.width=W+'px'; lm2BargadCanvas.style.height=H+'px';
  lm2BargadCtx=lm2BargadCanvas.getContext('2d');
  lm2BargadCtx.scale(dpr,dpr);
  lm2BargadCanvas.onclick=lm2BargadClick;
  lm2BargadCanvas.onmousemove=lm2BargadHoverFn;
  lm2BargadHover=null;
  if(lm2BargadFrame)cancelAnimationFrame(lm2BargadFrame);
  lm2BargadFrame=requestAnimationFrame(lm2DrawBargad);
}

function lm2DrawBargad(){
  if(!lm2BargadCtx){lm2BargadFrame=null;return;}
  lm2BargadT+=0.008;
  const ctx=lm2BargadCtx;
  const W=lm2BargadCanvas.clientWidth,H=lm2BargadCanvas.clientHeight;
  ctx.clearRect(0,0,W,H);

  // Background
  const bg=ctx.createRadialGradient(W*.5,H*.8,0,W*.5,H*.5,Math.max(W,H)*.8);
  bg.addColorStop(0,'rgba(12,8,3,.98)');
  bg.addColorStop(.5,'rgba(8,5,2,.99)');
  bg.addColorStop(1,'rgba(3,2,1,1)');
  ctx.fillStyle=bg; ctx.fillRect(0,0,W,H);

  // Ground
  const gnd=ctx.createLinearGradient(0,H*.82,0,H);
  gnd.addColorStop(0,'rgba(60,40,15,.0)');
  gnd.addColorStop(.4,'rgba(40,25,8,.25)');
  gnd.addColorStop(1,'rgba(25,15,5,.5)');
  ctx.fillStyle=gnd; ctx.fillRect(0,H*.82,W,H*.18);

  const cx=W/2,trunkBase=H*.85,trunkTop=H*.25;
  const breathe=Math.sin(lm2BargadT)*3;

  // --- ROOTS ---
  LM2_BARGAD.roots.forEach((root,i)=>{
    const rx=W*root.x,ry=H*root.depth+breathe*.3;
    const midX=cx+(rx-cx)*.5,midY=trunkBase+(ry-trunkBase)*.6;
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(cx,trunkBase);
    ctx.bezierCurveTo(midX,trunkBase+20,midX,midY,rx,ry);
    const isHov=lm2BargadHover&&lm2BargadHover.id===root.id;
    ctx.strokeStyle=root.col+(isHov?'0.7)':'0.35)');
    ctx.lineWidth=isHov?2.5:1.5;
    ctx.shadowColor=root.col+'0.5)'; ctx.shadowBlur=isHov?10:4;
    ctx.stroke(); ctx.shadowBlur=0;
    // Root label
    ctx.font=`${isHov?'bold ':' '}7px 'IBM Plex Mono',monospace`;
    ctx.fillStyle=root.col+(isHov?'0.9)':'0.5)');
    ctx.textAlign='center'; ctx.textBaseline='top';
    ctx.fillText(root.label,rx,ry+5);
    if(isHov){
      ctx.font=`6px 'IBM Plex Mono',monospace`;
      ctx.fillStyle=root.col+'0.4)';
      ctx.fillText(root.sublabel,rx,ry+16);
    }
    ctx.restore();
  });

  // --- TRUNK ---
  ctx.save();
  const trunkW=W*.028;
  // Trunk glow
  const tg=ctx.createLinearGradient(cx-trunkW*2,0,cx+trunkW*2,0);
  tg.addColorStop(0,'rgba(120,80,30,0)');
  tg.addColorStop(.3,'rgba(160,110,50,.15)');
  tg.addColorStop(.5,'rgba(200,160,80,.2)');
  tg.addColorStop(.7,'rgba(160,110,50,.15)');
  tg.addColorStop(1,'rgba(120,80,30,0)');
  ctx.fillStyle=tg;
  ctx.fillRect(cx-trunkW*2,trunkTop-20,trunkW*4,trunkBase-trunkTop+20);

  // Main trunk body
  ctx.beginPath();
  ctx.moveTo(cx-trunkW,trunkBase);
  ctx.bezierCurveTo(cx-trunkW*.8,trunkBase*.5+trunkTop*.5,cx-trunkW*.4,trunkTop+40,cx,trunkTop+breathe);
  ctx.bezierCurveTo(cx+trunkW*.4,trunkTop+40,cx+trunkW*.8,trunkBase*.5+trunkTop*.5,cx+trunkW,trunkBase);
  ctx.closePath();
  const tf=ctx.createLinearGradient(cx-trunkW,0,cx+trunkW,0);
  tf.addColorStop(0,'rgba(80,50,20,.6)');
  tf.addColorStop(.3,'rgba(120,80,35,.8)');
  tf.addColorStop(.5,'rgba(160,110,50,.9)');
  tf.addColorStop(.7,'rgba(120,80,35,.8)');
  tf.addColorStop(1,'rgba(80,50,20,.6)');
  ctx.fillStyle=tf; ctx.fill();
  ctx.strokeStyle='rgba(200,160,80,.25)'; ctx.lineWidth=1; ctx.stroke();
  ctx.restore();

  // --- BRANCHES ---
  LM2_BARGAD.branches.forEach(branch=>{
    const isHov=lm2BargadHover&&lm2BargadHover.id===branch.id;
    const rad=branch.angle*(Math.PI/180);
    const br=H*branch.r;
    const bx=cx+Math.sin(rad)*br;
    const by=trunkTop+breathe-Math.cos(Math.abs(rad)*.5)*H*.08+Math.cos(rad)*br*.5;
    const cp1x=cx+Math.sin(rad)*.3*br;
    const cp1y=trunkTop+breathe+Math.cos(rad)*.1*br;

    ctx.save();
    ctx.beginPath();
    ctx.moveTo(cx,trunkTop+breathe);
    ctx.bezierCurveTo(cp1x,cp1y,bx*.5+cx*.5,by*.5+(trunkTop+breathe)*.5,bx,by);
    ctx.strokeStyle=branch.col+(isHov?'0.8)':'0.45)');
    ctx.lineWidth=isHov?4:2.5;
    ctx.shadowColor=branch.col+'0.6)'; ctx.shadowBlur=isHov?18:8;
    ctx.stroke(); ctx.shadowBlur=0;

    // Branch leaf cluster
    const leafR=isHov?35:25;
    const lg=ctx.createRadialGradient(bx,by,0,bx,by,leafR);
    lg.addColorStop(0,branch.col+(isHov?'0.5)':'0.25)'));
    lg.addColorStop(1,branch.col+'0)');
    ctx.beginPath(); ctx.arc(bx,by,leafR,0,Math.PI*2);
    ctx.fillStyle=lg; ctx.fill();

    // Branch label
    const lx=bx+(branch.angle<0?-8:8),ly=by-32;
    ctx.font=`${isHov?'bold ':' '}8px 'IBM Plex Mono',monospace`;
    ctx.fillStyle=branch.col+(isHov?'0.95)':'0.6)');
    ctx.textAlign=branch.angle<0?'right':'left'; ctx.textBaseline='bottom';
    ctx.fillText(branch.label,lx,ly);
    ctx.font=`6px 'IBM Plex Mono',monospace`;
    ctx.fillStyle=branch.col+(isHov?'0.6)':'0.3)');
    ctx.fillText(branch.sublabel,lx,ly+12);

    // Aerial roots descending from branch
    branch.sites.forEach((siteId,si)=>{
      const site=LM2_SITES.find(s=>s.id===siteId);
      if(!site)return;
      const sx=bx+(si-1)*30+(Math.sin(lm2BargadT+si)*2);
      const sy=by;
      const ex=sx+(Math.sin(lm2BargadT*.7+si)*5);
      const ey=H*.8+(Math.sin(lm2BargadT+si+2)*3);
      const progress=Math.min(1,(Math.sin(lm2BargadT*.5+si*1.2)*.5+.5));
      const endY=sy+(ey-sy)*(.4+progress*.5);
      ctx.save();
      ctx.setLineDash([3,5]);
      ctx.beginPath(); ctx.moveTo(sx,sy); ctx.quadraticCurveTo(ex,sy+(endY-sy)*.5,ex,endY);
      ctx.strokeStyle=branch.col+'0.25)'; ctx.lineWidth=1; ctx.stroke();
      ctx.setLineDash([]);
      // Site name at root end
      if(endY>H*.65){
        ctx.font=`6px 'IBM Plex Mono',monospace`;
        ctx.fillStyle=branch.col+'0.5)';
        ctx.textAlign='center'; ctx.textBaseline='top';
        ctx.fillText(site.name.split('·')[0].trim(),ex,endY+4);
        ctx.beginPath(); ctx.arc(ex,endY,2.5,0,Math.PI*2);
        ctx.fillStyle=branch.col+'0.7)'; ctx.fill();
      }
      ctx.restore();
    });
    ctx.restore();
  });

  // Floating leaves
  for(let i=0;i<12;i++){
    const t=lm2BargadT+i*0.8;
    const lx=cx+Math.sin(t*.7+i)*W*.25;
    const ly=trunkTop+breathe-H*.05+Math.sin(t*.4)*H*.08+i*H*.01;
    if(ly<0||ly>trunkBase)continue;
    const branch=LM2_BARGAD.branches[i%LM2_BARGAD.branches.length];
    ctx.save();
    ctx.translate(lx,ly);
    ctx.rotate(t*.5);
    ctx.beginPath();
    ctx.ellipse(0,0,4,2,0,0,Math.PI*2);
    ctx.fillStyle=branch.col+'0.3)'; ctx.fill();
    ctx.restore();
  }

  // Dharma label on trunk
  ctx.save();
  ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.font=`italic 10px 'Cormorant Garamond',serif`;
  ctx.fillStyle='rgba(200,160,80,.22)';
  ctx.save();
  ctx.translate(cx,trunkTop+(trunkBase-trunkTop)*.5+breathe);
  ctx.rotate(-Math.PI/2);
  ctx.fillText('DHARMA',0,0);
  ctx.restore();
  ctx.restore();

  lm2BargadFrame=requestAnimationFrame(lm2DrawBargad);
}

function lm2BargadClick(e){
  const rect=lm2BargadCanvas.getBoundingClientRect();
  const mx=e.clientX-rect.left,my=e.clientY-rect.top;
  const W=lm2BargadCanvas.clientWidth,H=lm2BargadCanvas.clientHeight;
  const cx=W/2,trunkTop=H*.25,trunkBase=H*.85;
  const breathe=Math.sin(lm2BargadT)*3;
  let hit=null;
  LM2_BARGAD.branches.forEach(branch=>{
    const rad=branch.angle*(Math.PI/180);
    const br=H*branch.r;
    const bx=cx+Math.sin(rad)*br;
    const by=trunkTop+breathe-Math.cos(Math.abs(rad)*.5)*H*.08+Math.cos(rad)*br*.5;
    if(Math.hypot(mx-bx,my-by)<40)hit={...branch,type:'branch'};
  });
  LM2_BARGAD.roots.forEach(root=>{
    const rx=W*root.x,ry=H*root.depth;
    if(Math.hypot(mx-rx,my-ry)<30)hit={...root,type:'root'};
  });
  if(hit){
    const title=document.getElementById('lm2-bargad-card-title');
    const body=document.getElementById('lm2-bargad-card-body');
    if(hit.type==='branch'){
      const sitesStr=LM2_SITES.filter(s=>hit.sites.includes(s.id)).map(s=>s.name).join(', ');
      if(title)title.textContent=hit.label+' · '+hit.sublabel;
      if(body)body.textContent='Sacred sites: '+sitesStr+'. The '+hit.label+' branch reaches its aerial roots into the ground of real geography — these places exist, have always existed, are pilgrimage destinations today.';
    } else {
      if(title)title.textContent=hit.label+' · '+hit.sublabel;
      if(body)body.textContent='Root source of the tradition. The '+hit.label+' flows upward through the trunk of Dharma into the branches of every era. Not metaphor — actual texts, actual knowledge, still studied today.';
    }
    lm2BargadHover=hit;
  } else {
    lm2BargadHover=null;
  }
}
function lm2BargadHoverFn(e){
  const rect=lm2BargadCanvas.getBoundingClientRect();
  const mx=e.clientX-rect.left,my=e.clientY-rect.top;
  const W=lm2BargadCanvas.clientWidth,H=lm2BargadCanvas.clientHeight;
  const cx=W/2,trunkTop=H*.25,trunkBase=H*.85;
  const breathe=Math.sin(lm2BargadT)*3;
  let hit=null;
  LM2_BARGAD.branches.forEach(branch=>{
    const rad=branch.angle*(Math.PI/180);
    const br=H*branch.r;
    const bx=cx+Math.sin(rad)*br;
    const by=trunkTop+breathe-Math.cos(Math.abs(rad)*.5)*H*.08+Math.cos(rad)*br*.5;
    if(Math.hypot(mx-bx,my-by)<40)hit=branch;
  });
  LM2_BARGAD.roots.forEach(root=>{
    const rx=W*root.x,ry=H*root.depth;
    if(Math.hypot(mx-rx,my-ry)<30)hit=root;
  });
  lm2BargadCanvas.style.cursor=hit?'pointer':'default';
}

// ═══════════════════════════════
//  NĀDA PANEL — SACRED SOUND
// ═══════════════════════════════
function lm2InitNada(){
  const panel=document.getElementById('lm2-nada-panel');
  lm2NadaCanvas=document.getElementById('lm2-nada-canvas');
  lm2WaveCanvas=document.getElementById('lm2-wave-canvas');
  if(!lm2NadaCanvas||!panel)return;
  const dpr=window.devicePixelRatio||1;
  const W=panel.clientWidth||window.innerWidth;
  const H=panel.clientHeight||(window.innerHeight-80);
  lm2NadaCanvas.width=W*dpr; lm2NadaCanvas.height=H*dpr;
  lm2NadaCanvas.style.width=W+'px'; lm2NadaCanvas.style.height=H+'px';
  lm2NadaCtx=lm2NadaCanvas.getContext('2d');
  lm2NadaCtx.scale(dpr,dpr);
  if(lm2WaveCanvas){
    const wr=lm2WaveCanvas.parentElement;
    lm2WaveCanvas.width=(wr?wr.clientWidth:400)*dpr;
    lm2WaveCanvas.height=(wr?wr.clientHeight:50)*dpr;
    lm2WaveCtx=lm2WaveCanvas.getContext('2d');
    lm2WaveCtx.scale(dpr,dpr);
  }
  lm2NadaCanvas.onclick=lm2NadaClick;
  lm2NadaCanvas.ontouchstart=function(e){e.preventDefault();const t=e.touches[0];lm2NadaClick({clientX:t.clientX,clientY:t.clientY});};
  lm2NadaCanvas.onmousemove=lm2NadaHover;
  lm2NadaActive=false; lm2NadaFreq=0;
  lm2ActiveSiteSound=null;
  if(lm2NadaFrame)cancelAnimationFrame(lm2NadaFrame);
  lm2NadaFrame=requestAnimationFrame(lm2DrawNada);
}

function lm2DrawNada(){
  if(!lm2NadaCtx){lm2NadaFrame=null;return;}
  lm2NadaT+=0.015;
  const ctx=lm2NadaCtx;
  const W=lm2NadaCanvas.clientWidth,H=lm2NadaCanvas.clientHeight;
  ctx.clearRect(0,0,W,H);

  // Background — darker, more mystical
  const bg=ctx.createRadialGradient(W*.5,H*.4,0,W*.5,H*.5,Math.max(W,H)*.75);
  bg.addColorStop(0,'rgba(10,6,20,.98)');
  bg.addColorStop(.5,'rgba(6,3,14,.99)');
  bg.addColorStop(1,'rgba(2,1,6,1)');
  ctx.fillStyle=bg; ctx.fillRect(0,0,W,H);

  // Sound ripples from active site
  if(lm2NadaActive&&lm2ActiveSiteSound){
    const {x,y}=lm2Geo(lm2ActiveSiteSound.lon,lm2ActiveSiteSound.lat,W,H);
    const site=lm2ActiveSiteSound;
    for(let i=0;i<5;i++){
      const phase=lm2NadaT*2+i*1.2;
      const r=(phase%6.28)*60;
      const alpha=Math.max(0,0.25-r/380);
      ctx.beginPath(); ctx.arc(x,y,r,0,Math.PI*2);
      ctx.strokeStyle=site.col+alpha+')'; ctx.lineWidth=1.5;
      ctx.stroke();
    }
    // Mantra glow at site
    const g=ctx.createRadialGradient(x,y,0,x,y,40);
    g.addColorStop(0,site.col+'0.55)');
    g.addColorStop(1,site.col+'0)');
    ctx.beginPath(); ctx.arc(x,y,40,0,Math.PI*2);
    ctx.fillStyle=g; ctx.fill();
  }

  // Draw India outline (same as map but more ethereal)
  ctx.save();
  ctx.globalAlpha=0.7;
  lm2DrawIndia(ctx,W,H);
  ctx.globalAlpha=1;
  ctx.restore();

  // Draw sites — all visible, tappable
  LM2_SITES.forEach(s=>{
    const {x,y}=lm2Geo(s.lon,s.lat,W,H);
    const isActive=lm2ActiveSiteSound&&lm2ActiveSiteSound.id===s.id;
    const isHov=lm2HoveredSite&&lm2HoveredSite.id===s.id;
    const pulse=1+0.2*Math.sin(lm2NadaT*3+s.lon*0.2);
    const glow=ctx.createRadialGradient(x,y,0,x,y,isActive?25:14);
    glow.addColorStop(0,s.col+(isActive?'0.6)':isHov?'0.3)':'0.15)'));
    glow.addColorStop(1,s.col+'0)');
    ctx.beginPath(); ctx.arc(x,y,(isActive?25:14)*pulse,0,Math.PI*2);
    ctx.fillStyle=glow; ctx.fill();
    ctx.beginPath(); ctx.arc(x,y,(isActive?7:4.5)*pulse,0,Math.PI*2);
    ctx.fillStyle=s.col+(isActive?'0.95)':'0.5)');
    ctx.shadowColor=s.col+'0.8)'; ctx.shadowBlur=isActive?20:6; ctx.fill(); ctx.shadowBlur=0;
    if(isActive){
      ctx.textAlign='center'; ctx.textBaseline='top';
      ctx.font=`bold 8px 'IBM Plex Mono',monospace`;
      ctx.fillStyle=s.col+'0.9)';
      ctx.fillText(s.name.split('·')[0].trim(),x,y+10);
    }
  });

  // Draw waveform if active
  if(lm2NadaActive&&lm2WaveCtx&&lm2WaveCanvas){
    const wctx=lm2WaveCtx;
    const wW=lm2WaveCanvas.clientWidth,wH=lm2WaveCanvas.clientHeight;
    wctx.clearRect(0,0,wW,wH);
    const site=lm2ActiveSiteSound;
    if(site){
      wctx.beginPath();
      for(let px=0;px<wW;px++){
        const t=px/wW*Math.PI*8;
        const y=wH*.5+Math.sin(t+lm2NadaT*4)*wH*.22
                       +Math.sin(t*2.1+lm2NadaT*2.5)*wH*.1
                       +Math.sin(t*3.2+lm2NadaT*1.8)*wH*.05;
        if(px===0)wctx.moveTo(px,y); else wctx.lineTo(px,y);
      }
      wctx.strokeStyle=site.col+'0.7)';
      wctx.lineWidth=1.5;
      wctx.shadowColor=site.col+'0.5)'; wctx.shadowBlur=8;
      wctx.stroke(); wctx.shadowBlur=0;
    }
  }

  lm2NadaFrame=requestAnimationFrame(lm2DrawNada);
}

function lm2NadaClick(e){
  const rect=lm2NadaCanvas.getBoundingClientRect();
  const mx=e.clientX-rect.left,my=e.clientY-rect.top;
  const W=lm2NadaCanvas.clientWidth,H=lm2NadaCanvas.clientHeight;
  let hit=null,minD=Infinity;
  LM2_SITES.forEach(s=>{
    const {x,y}=lm2Geo(s.lon,s.lat,W,H);
    const d=Math.hypot(mx-x,my-y);
    if(d<24&&d<minD){minD=d;hit=s;}
  });
  if(hit){
    lm2ActiveSiteSound=hit;
    lm2PlayNada(hit);
    lm2ShowNadaDisplay(hit);
  }
}
function lm2NadaHover(e){
  const rect=lm2NadaCanvas.getBoundingClientRect();
  const mx=e.clientX-rect.left,my=e.clientY-rect.top;
  const W=lm2NadaCanvas.clientWidth,H=lm2NadaCanvas.clientHeight;
  let hit=null,minD=Infinity;
  LM2_SITES.forEach(s=>{
    const {x,y}=lm2Geo(s.lon,s.lat,W,H);
    const d=Math.hypot(mx-x,my-y);
    if(d<20&&d<minD){minD=d;hit=s;}
  });
  lm2HoveredSite=hit;
  lm2NadaCanvas.style.cursor=hit?'pointer':'crosshair';
}

function lm2ShowNadaDisplay(site){
  const instr=document.getElementById('lm2-nada-instruction');
  const disp=document.getElementById('lm2-nada-display');
  const wave=document.getElementById('lm2-nada-wave');
  if(instr)instr.classList.add('hidden');
  if(disp){
    disp.classList.add('visible');
    document.getElementById('lm2-nd-site').textContent=site.name;
    document.getElementById('lm2-nd-mantra').textContent=site.mantra||'ॐ';
    var yugaN=site.yuga==='satya'?'Satya':site.yuga==='treta'?'Tretā':site.yuga==='dvapara'?'Dvāpara':'Kali';
    document.getElementById('lm2-nd-freq').textContent='Frequency · '+(site.freq||136.1).toFixed(1)+' Hz · '+yugaN+' Yuga';
  }
  if(wave)wave.classList.add('active');
  lm2NadaActive=true;
}

function lm2PlayNada(site){
  lm2StopSound();
  try{
    if(!lm2AudioCtx)lm2AudioCtx=new(window.AudioContext||window.webkitAudioContext)();
    if(lm2AudioCtx.state==='suspended')lm2AudioCtx.resume();
    const freq=site.freq||136.1;
    const now=lm2AudioCtx.currentTime;
    const master=lm2AudioCtx.createGain();
    master.gain.setValueAtTime(0,now);
    master.gain.linearRampToValueAtTime(0.35,now+0.3);
    master.gain.setValueAtTime(0.35,now+2.5);
    master.gain.exponentialRampToValueAtTime(0.001,now+8);
    master.connect(lm2AudioCtx.destination);
    // Fundamental
    const osc1=lm2AudioCtx.createOscillator();
    osc1.type='sine'; osc1.frequency.setValueAtTime(freq,now);
    const g1=lm2AudioCtx.createGain(); g1.gain.value=0.6;
    osc1.connect(g1); g1.connect(master); osc1.start(now); osc1.stop(now+8);
    // 2nd harmonic (octave above — softer)
    const osc2=lm2AudioCtx.createOscillator();
    osc2.type='sine'; osc2.frequency.setValueAtTime(freq*2,now);
    const g2=lm2AudioCtx.createGain(); g2.gain.value=0.2;
    osc2.connect(g2); g2.connect(master); osc2.start(now); osc2.stop(now+8);
    // 5th (perfect fifth — 3/2)
    const osc3=lm2AudioCtx.createOscillator();
    osc3.type='sine'; osc3.frequency.setValueAtTime(freq*1.5,now);
    const g3=lm2AudioCtx.createGain(); g3.gain.value=0.15;
    osc3.connect(g3); g3.connect(master); osc3.start(now+0.05); osc3.stop(now+7);
    // Bell attack transient
    const bell=lm2AudioCtx.createOscillator();
    bell.type='sine'; bell.frequency.setValueAtTime(freq*4,now);
    const bg=lm2AudioCtx.createGain(); bg.gain.setValueAtTime(0.3,now); bg.gain.exponentialRampToValueAtTime(0.001,now+0.8);
    bell.connect(bg); bg.connect(master); bell.start(now); bell.stop(now+0.8);
    lm2ActiveNodes=[master,g1,g2,g3,bg];
    lm2NadaFreq=freq;
  }catch(err){}
}
function lm2StopSound(){
  try{
    lm2ActiveNodes.forEach(n=>{try{n.disconnect();}catch(e){}});
    lm2ActiveNodes=[];
  }catch(e){}
}

