//  SURPRISE PAGE — VEDIC NIGHT SKY / NAKSHATRA MANDALA
// ═══════════════════════════════════════════════════


function openSky(){
  const ov=document.getElementById('sky-ov');
  // Cancel any lingering sub-tool frames from previous session
  Object.keys(skySubFrames).forEach(k=>{if(skySubFrames[k]){cancelAnimationFrame(skySubFrames[k]);skySubFrames[k]=null;}});
  ov.style.opacity='0';ov.style.pointerEvents='all';ov.style.display='block';
  requestAnimationFrame(()=>{
    ov.classList.add('on');ov.style.opacity='';ov.style.pointerEvents='';ov.style.display='';
    requestAnimationFrame(()=>setTimeout(initSky,50));
  });
}
function closeSky(){
  const skyOv=document.getElementById('sky-ov');
  skyOv.classList.remove('on');
  // Clear inline styles left by openSky() — critical to prevent click blocking
  skyOv.style.pointerEvents='';
  skyOv.style.opacity='';
  skyOv.style.display='';
  if(skyFrame){cancelAnimationFrame(skyFrame);skyFrame=null;}
  Object.keys(skySubFrames).forEach(k=>{
    if(skySubFrames[k]){cancelAnimationFrame(skySubFrames[k]);skySubFrames[k]=null;}
  });
  document.querySelectorAll('.sky-sub-ov').forEach(el=>{
    el.classList.remove('on');
    // Reset mobile positioning
    el.style.position='';el.style.top='';el.style.left='';
    el.style.right='';el.style.bottom='';el.style.zIndex='';
  });
  skyActiveSub='nakshatras';
  document.querySelectorAll('.sky-stbtn').forEach((b,i)=>b.classList.toggle('active',i===0));
  const skyC=document.getElementById('sky-canvas');
  if(skyC){skyC.style.visibility='visible';skyC.style.opacity='1';skyC.style.display='';}
}

function initSky(){
  skyCanvas=document.getElementById('sky-canvas');
  if(!skyCanvas)return;
  const dpr=window.devicePixelRatio||1;
  // Always use window dimensions — most reliable across browsers/mobile
  const W=window.innerWidth;
  const H=window.innerHeight;
  skyCanvas.style.position='fixed';
  skyCanvas.style.top='0';
  skyCanvas.style.left='0';
  skyCanvas.style.width=W+'px';
  skyCanvas.style.height=H+'px';
  skyCanvas.width=W*dpr;
  skyCanvas.height=H*dpr;
  skyCtx=skyCanvas.getContext('2d');
  skyCtx.scale(dpr,dpr);
  // Generate star field
  skyStarField=[];
  for(let i=0;i<800;i++) skyStarField.push({
    x:Math.random()*W,y:Math.random()*H,
    r:Math.random()*1.5+.2,
    a:Math.random()*.7+.1,
    tw:Math.random()*Math.PI*2,sp:Math.random()*.002+.0005
  });
  skyCanvas.onclick=skyClick;
  skyCanvas.onmousemove=skyHover;
  skyCanvas.ontouchend=e=>{
    e.preventDefault();
    const t=e.changedTouches[0];
    const r=skyCanvas.getBoundingClientRect();
    skyClick({clientX:t.clientX,clientY:t.clientY,preventDefault:()=>{}});
  };
  if(skyFrame)cancelAnimationFrame(skyFrame);
  skyFrame=requestAnimationFrame(drawSky);
}

function getSkyNakshatraPos(n,W,H){
  const cx=W/2,cy=H/2;
  const R=Math.min(W,H)*0.38;
  const a=nakshatraAngle(n)+(skyT*0.03);
  return{x:cx+Math.cos(a)*R,y:cy+Math.sin(a)*R};
}

function drawSky(){
  if(!skyCtx){skyFrame=null;return;}
  skyT+=0.018;
  const W=skyCanvas.clientWidth,H=skyCanvas.clientHeight;
  const ctx=skyCtx;
  ctx.clearRect(0,0,W,H);

  // Deep space gradient
  const bg=ctx.createRadialGradient(W/2,H*0.4,0,W/2,H/2,Math.max(W,H));
  bg.addColorStop(0,'rgba(6,3,14,.99)');bg.addColorStop(.6,'rgba(2,1,8,1)');bg.addColorStop(1,'rgba(0,0,3,1)');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);

  // Star field
  skyStarField.forEach(s=>{
    s.tw+=s.sp*5;
    const a=s.a*(0.5+0.5*Math.sin(s.tw));
    ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);
    ctx.fillStyle=`rgba(220,210,255,${a})`;ctx.fill();
  });

  const cx=W/2,cy=H/2;
  const outerR=Math.min(W,H)*0.42;
  const innerR=Math.min(W,H)*0.06;
  // Faster rotation of entire sky
  const skyRot=skyT*0.045;

  // ── Zodiac rashi ring ──
  const rashis=['Meṣa','Vṛṣabha','Mithuna','Karkaṭa','Siṃha','Kanyā','Tulā','Vṛścika','Dhanu','Makara','Kumbha','Mīna'];
  ctx.font="5.5px 'IBM Plex Mono',monospace";
  ctx.fillStyle='rgba(140,120,200,.2)';
  ctx.textAlign='center';ctx.textBaseline='middle';
  for(let r=0;r<12;r++){
    const a=skyRot+(r/12)*Math.PI*2-Math.PI/2;
    const rx=cx+Math.cos(a)*(outerR+20),ry=cy+Math.sin(a)*(outerR+20);
    ctx.fillText(rashis[r],rx,ry);
  }

  // ── Outer circle ──
  ctx.beginPath();ctx.arc(cx,cy,outerR,0,Math.PI*2);
  ctx.strokeStyle='rgba(140,100,200,.12)';ctx.lineWidth=1;ctx.stroke();

  // ── Nakshatra division lines (every 13.33°) ──
  for(let n=0;n<27;n++){
    const a=skyRot+(n/27)*Math.PI*2-Math.PI/2;
    ctx.beginPath();
    ctx.moveTo(cx+Math.cos(a)*innerR,cy+Math.sin(a)*innerR);
    ctx.lineTo(cx+Math.cos(a)*outerR,cy+Math.sin(a)*outerR);
    ctx.strokeStyle='rgba(140,100,200,.06)';ctx.lineWidth=0.4;ctx.stroke();
  }

  // ── Draw each Nakshatra ──
  // Calculate current nakshatra based on moon position (simplified: day of year)
  const now=new Date();
  const dayOfYear=Math.floor((now-new Date(now.getFullYear(),0,0))/86400000);
  const currentNakshatraIdx=Math.floor((dayOfYear*27/365.25))%27;
  
  NAKSHATRAS.forEach((n,ni)=>{
    const midAngle=skyRot+(n.deg/360)*Math.PI*2-Math.PI/2+(6.667/360)*Math.PI*2;
    const starR=outerR*0.82;
    const px=cx+Math.cos(midAngle)*starR;
    const py=cy+Math.sin(midAngle)*starR;
    const isSel=skySelectedConst&&skySelectedConst.id===n.id;
    const isCurrent=ni===currentNakshatraIdx;
    const baseSize=n.stars>=100?4.5:n.stars>=10?3.8:n.stars>=4?3.2:2.8;
    const pulse=isSel?1+0.2*Math.sin(skyT*5):isCurrent?1+0.15*Math.sin(skyT*3):1;

    // Current nakshatra gets golden glow
    if(isCurrent && !isSel){
      const cg=ctx.createRadialGradient(px,py,0,px,py,baseSize*10*pulse);
      cg.addColorStop(0,'rgba(201,168,76,0.5)');
      cg.addColorStop(0.5,'rgba(201,168,76,0.2)');
      cg.addColorStop(1,'rgba(201,168,76,0)');
      ctx.beginPath();ctx.arc(px,py,baseSize*10*pulse,0,Math.PI*2);
      ctx.fillStyle=cg;ctx.fill();
    }

    // Glow
    const g=ctx.createRadialGradient(px,py,0,px,py,baseSize*6*pulse);
    g.addColorStop(0,n.color.replace(',1)',',0.6)'));
    g.addColorStop(1,n.color.replace(',1)',',0)'));
    ctx.beginPath();ctx.arc(px,py,baseSize*6*pulse,0,Math.PI*2);
    ctx.fillStyle=g;ctx.fill();

    // Star
    ctx.beginPath();ctx.arc(px,py,baseSize*pulse,0,Math.PI*2);
    ctx.fillStyle=isCurrent&&!isSel?'rgba(201,168,76,1)':n.color;ctx.fill();

    // Name label — only show if not too crowded
    const labelR=outerR*0.88;
    const lx=cx+Math.cos(midAngle)*labelR,ly=cy+Math.sin(midAngle)*labelR;
    ctx.save();
    ctx.translate(lx,ly);
    ctx.rotate(midAngle+Math.PI/2);
    ctx.font=`${isSel?'bold ':isCurrent?'bold ':' '}${isSel?7:isCurrent?6.5:5.5}px 'IBM Plex Mono',monospace`;
    ctx.fillStyle=isCurrent&&!isSel?'rgba(201,168,76,0.9)':n.color.replace(',1)',isSel?',0.95)':',0.4)');
    ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.fillText(n.name,0,0);
    ctx.restore();

    // Sanskrit inside for selected
    if(isSel){
      ctx.font="8px 'Cormorant Garamond',serif";
      ctx.fillStyle=n.color.replace(',1)',',0.7)');
      ctx.textAlign='center';ctx.textBaseline='middle';
      ctx.fillText(n.skt,px,py-baseSize*3);
    }
    
    // "Now" indicator for current nakshatra
    if(isCurrent&&!isSel){
      ctx.font="5px 'IBM Plex Mono',monospace";
      ctx.fillStyle='rgba(201,168,76,0.7)';
      ctx.textAlign='center';ctx.textBaseline='middle';
      ctx.fillText('NOW',px,py+baseSize*4);
    }
  });

  // ── Center mandala with planetary system ──
  // Draw orbital rings
  const planets=[
    {r:innerR*1.2,col:'rgba(248,200,64,.3)',size:3,speed:0.8,name:'☿'},
    {r:innerR*1.6,col:'rgba(240,184,208,.3)',size:3.5,speed:0.5,name:'♀'},
    {r:innerR*2.0,col:'rgba(74,144,96,.25)',size:4,speed:0.3,name:'🜃'},
    {r:innerR*2.4,col:'rgba(224,96,64,.25)',size:3,speed:0.2,name:'♂'}
  ];
  
  planets.forEach((p,i)=>{
    // Orbit ring
    ctx.beginPath();ctx.arc(cx,cy,p.r,0,Math.PI*2);
    ctx.strokeStyle=p.col;ctx.lineWidth=0.5;ctx.stroke();
    
    // Planet position
    const angle=skyT*p.speed+(i*Math.PI/2);
    const px=cx+Math.cos(angle)*p.r;
    const py=cy+Math.sin(angle)*p.r;
    
    // Planet glow
    const pg=ctx.createRadialGradient(px,py,0,px,py,p.size*2);
    pg.addColorStop(0,p.col.replace(',.25)',',0.4)').replace(',.3)',',0.5)'));
    pg.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=pg;
    ctx.beginPath();ctx.arc(px,py,p.size*2,0,Math.PI*2);ctx.fill();
    
    // Planet
    ctx.fillStyle=p.col.replace(',.25)',',0.9)').replace(',.3)',',0.9)');
    ctx.beginPath();ctx.arc(px,py,p.size,0,Math.PI*2);ctx.fill();
  });
  
  // Sun at center
  const sunR=innerR*0.8;
  const sg=ctx.createRadialGradient(cx,cy,0,cx,cy,sunR*2);
  sg.addColorStop(0,'rgba(248,200,64,0.6)');
  sg.addColorStop(0.5,'rgba(248,200,64,0.3)');
  sg.addColorStop(1,'rgba(248,200,64,0)');
  ctx.fillStyle=sg;
  ctx.beginPath();ctx.arc(cx,cy,sunR*2,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='rgba(248,200,64,1)';
  ctx.beginPath();ctx.arc(cx,cy,sunR,0,Math.PI*2);ctx.fill();
  
  // Outer pada division ring
  ctx.beginPath();ctx.arc(cx,cy,innerR*2.8,0,Math.PI*2);
  ctx.strokeStyle='rgba(201,168,76,.08)';ctx.lineWidth=0.5;ctx.stroke();

  // OM at center over sun
  ctx.font=`italic ${14+3*Math.sin(skyT*2)}px 'Cormorant Garamond',serif`;
  ctx.fillStyle=`rgba(201,168,76,${0.6+0.2*Math.sin(skyT*2)})`;
  ctx.textAlign='center';ctx.textBaseline='middle';
  ctx.fillText('ॐ',cx,cy);
  ctx.font="5px 'IBM Plex Mono',monospace";
  ctx.fillStyle='rgba(140,120,200,.12)';
  ctx.fillText('NAKSHATRA MANDALA',cx,cy+22);

  // Selected nakshatra info at top
  if(skySelectedConst){
    ctx.font="bold 9px 'Cinzel',serif";
    ctx.fillStyle='rgba(220,210,255,.8)';
    ctx.textAlign='center';ctx.fillText(skySelectedConst.name,cx,28);
    ctx.font="7px 'IBM Plex Mono',monospace";
    ctx.fillStyle='rgba(160,140,220,.4)';
    ctx.fillText(skySelectedConst.planet+' · '+skySelectedConst.quality,cx,42);
  }

  // Date stamp
  ctx.font="5px 'IBM Plex Mono',monospace";
  ctx.fillStyle='rgba(140,100,200,.15)';
  ctx.textAlign='center';
  ctx.fillText('Brihat Samhita · Varahamihira · 6th century CE',cx,H-10);

  skyFrame=requestAnimationFrame(drawSky);
}

function getSkyNakshatraPos(n,W,H){
  const cx=W/2,cy=H/2;
  const R=Math.min(W,H)*0.42*0.82;
  const skyRot=skyT*0.015;
  const a=skyRot+(n.deg/360)*Math.PI*2-Math.PI/2+(6.667/360)*Math.PI*2;
  return{x:cx+Math.cos(a)*R,y:cy+Math.sin(a)*R};
}


function skyClick(e){
  const r=skyCanvas.getBoundingClientRect();
  const mx=e.clientX-r.left,my=e.clientY-r.top;
  const W=skyCanvas.clientWidth,H=skyCanvas.clientHeight;
  let hit=null;
  NAKSHATRAS.forEach(n=>{
    const pos=getSkyNakshatraPos(n,W,H);
    if(Math.hypot(mx-pos.x,my-pos.y)<16)hit=n;
  });
  skySelectedConst=hit;
  const panel=document.getElementById('sky-info-panel');
  if(hit){
    const colDim=hit.color.replace(',1)',',0.25)');
    const colMed=hit.color.replace(',1)',',0.55)');
    panel.innerHTML=`
      <button style="position:absolute;top:10px;right:10px;background:none;border:1px solid rgba(180,160,220,.2);color:rgba(180,160,220,.5);width:24px;height:24px;cursor:pointer;font-size:11px;display:flex;align-items:center;justify-content:center;" onclick="skySelectedConst=null;document.getElementById('sky-info-panel').classList.remove('open')">✕</button>
      <div style="font-family:'IBM Plex Mono',monospace;font-size:5.5px;letter-spacing:3px;color:${colDim};text-transform:uppercase;margin-bottom:5px">${hit.deg.toFixed(2)}° · Nakshatra ${NAKSHATRAS.indexOf(hit)+1} of 27</div>
      <span style="font-family:'Cormorant Garamond',serif;font-size:22px;font-style:italic;color:${hit.color};display:block;margin-bottom:4px;line-height:1">${hit.skt}</span>
      <div style="font-family:'Cinzel',serif;font-size:14px;color:rgba(220,210,255,.85);margin-bottom:10px">${hit.name}</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:12px">
        ${[['Ruling Planet',hit.planet],['Deity',hit.deity],['Symbol',hit.symbol],['Quality',hit.quality],['Nature',hit.nature||'']].filter(x=>x[1]).map(([k,v])=>
          `<div style="padding:6px 8px;border:1px solid ${colDim};background:${colDim.replace('0.25)','0.04)')}">
            <div style="font-family:'IBM Plex Mono',monospace;font-size:5.5px;letter-spacing:2px;text-transform:uppercase;color:${colDim};margin-bottom:3px">${k}</div>
            <div style="font-size:11px;color:${colMed}">${v}</div>
          </div>`).join('')}
      </div>
      <div style="font-size:12.5px;line-height:1.8;color:rgba(180,200,240,.6);margin-bottom:12px">${hit.story}</div>
      <div style="padding:8px 10px;border-left:2px solid ${colDim};margin-bottom:10px">
        <div style="font-family:'IBM Plex Mono',monospace;font-size:5.5px;letter-spacing:2px;text-transform:uppercase;color:${colDim};margin-bottom:4px">Brihat Samhita — Varahamihira</div>
        <div style="font-size:11.5px;color:rgba(200,190,230,.5);font-style:italic">${hit.brihat}</div>
      </div>
      <div style="padding:8px 10px;border:1px solid ${colDim};background:${colDim.replace('0.25)','0.04)')}">
        <div style="font-family:'IBM Plex Mono',monospace;font-size:5.5px;letter-spacing:2px;text-transform:uppercase;color:${colDim};margin-bottom:4px">Muhurta (Auspicious Timing)</div>
        <div style="font-size:11.5px;color:rgba(180,210,200,.5)">${hit.muhurta}</div>
      </div>
    `;
    panel.classList.add('open');
  } else {
    panel.classList.remove('open');
  }
}
function skyHover(e){
  const r=skyCanvas.getBoundingClientRect();
  const mx=e.clientX-r.left,my=e.clientY-r.top;
  const W=skyCanvas.clientWidth,H=skyCanvas.clientHeight;
  let hit=false;
  NAKSHATRAS.forEach(n=>{const pos=getSkyNakshatraPos(n,W,H);if(Math.hypot(mx-pos.x,my-pos.y)<16)hit=true;});
  skyCanvas.style.cursor=hit?'pointer':'crosshair';
}

// ═══ END INJECTED PAGES ═══


// ═══════════════════════════════════════════════════════════════════
//  TATTVA CASCADE — 36 Tattvas of Kashmir Shaivism
// ═══════════════════════════════════════════════════════════════════
const TATTVAS=[
  // Shiva Tattvas (1-5) — Pure Consciousness
  {n:1,skt:'शिव',roman:'Shiva Tattva',group:'shiva',col:'#e8d8ff',
   essence:'Pure Consciousness — the witness that never moves, the ground in which all arises.',
   body:'The first and highest Tattva. Shiva is not a deity here but a <strong>principle</strong> — undivided, unchanging awareness. It is the sky that holds all weather without becoming weather. Nothing can enter or alter it. Kashmir Shaivism calls this <em>Prakasha</em> — pure luminosity without an object to illuminate.'},
  {n:2,skt:'शक्ति',roman:'Shakti Tattva',group:'shiva',col:'#d0b8ff',
   essence:'Dynamic creative power — consciousness becoming aware of its own capacity to create.',
   body:'Shakti is not separate from Shiva — she is Shiva\'s own power of self-recognition. This is <em>Vimarsha</em> — the reflective awareness that says "I Am." The universe does not exist yet, but the <strong>capacity for universe</strong> has been recognized. The first tremor.'},
  {n:3,skt:'सदाशिव',roman:'Sadashiva Tattva',group:'shiva',col:'#c0a0ff',
   essence:'"I Am This" — the first emergence of cosmic will, where consciousness begins identifying with creation.',
   body:'At this level, Shiva says: <em>"I am the universe and the universe is me."</em> But the "me" still dominates — creation is experienced as part of self. The Tantric symbol: a white swan on a silver lake. The lake is creation; the swan is consciousness. They are one, but the swan is sovereign.'},
  {n:4,skt:'ईश्वर',roman:'Ishvara Tattva',group:'shiva',col:'#b090e8',
   essence:'The Lord — cosmic intelligence that knows the universe as its own manifestation.',
   body:'Here awareness shifts: <em>"This is Me, and I am This"</em> — creation becomes slightly foregrounded. Ishvara is the omniscient cosmic mind that contains the complete blueprint (Suddha Vidya) of all that will manifest. This is the cosmic architect who has not yet drawn the first line but knows every line perfectly.'},
  {n:5,skt:'सद्विद्या',roman:'Suddha Vidya Tattva',group:'shiva',col:'#a080d8',
   essence:'Pure Knowledge — the cosmic plan, perfect and complete, held in cosmic mind before manifestation.',
   body:'<em>"I am This and This is Me"</em> — perfect balance between subject and object. The universe and consciousness are known as equal. This is the last purely divine level before the great limiting power (Maya) enters. Below this, the dream of multiplicity begins.'},
  
  // Maya Tattvas (6-11) — The Limiting Principles
  {n:6,skt:'माया',roman:'Maya Tattva',group:'maya',col:'#8060c0',
   essence:'The cosmic veil — the principle that makes the One appear as many, the infinite as finite.',
   body:'Maya is not illusion — it is <strong>creative delimitation</strong>. Without Maya, there is only Shiva knowing himself. Maya introduces the possibility of separate experiencing. It is the cosmic stage on which the play of existence occurs. Every individual being owes its apparent individuality to Maya.'},
  {n:7,skt:'कला',roman:'Kala',group:'maya',col:'#7055b0',
   essence:'The limiting power of action — time and the capacity for limited creative power.',
   body:'One of Maya\'s five <em>Kanchukas</em> (sheaths/cloaks). Kala limits omnipotence — the unlimited creative power of Shiva is restricted to the small creative capacity of an individual. You can build a house. You cannot create a universe. <strong>This limitation is Kala\'s gift</strong> — it makes embodied action possible.'},
  {n:8,skt:'विद्या',roman:'Avidya/Vidya',group:'maya',col:'#6050a0',
   essence:'Limited knowledge — the restriction of omniscience to individual knowing.',
   body:'The Kanchuka that limits all-knowing to partial knowing. Every individual operates with incomplete information — this is Avidya as a cosmic structural feature, not a moral failing. <em>The fish does not know it is in water.</em> Vidya\'s expansion is the path of liberation.'},
  {n:9,skt:'राग',roman:'Raga',group:'maya',col:'#5545a0',
   essence:'Attachment and selective desire — the limitation of universal will to particular preferences.',
   body:'Universal will (Iccha) becomes selective desire. The unlimited Shiva wants nothing because he has everything. The individual wants <em>this</em> specifically — coffee, approval, security, love. <strong>Raga is what makes the journey personal.</strong> Without it, there is no particular story.'},
  {n:10,skt:'काल',roman:'Kala (Time)',group:'maya',col:'#4a4090',
   essence:'Temporal limitation — the restriction of timeless eternity to experienced sequence.',
   body:'The Kanchuka that limits Shiva\'s eternal "all-at-once" to human sequential time. Past, present, future arise here. This is the source of impermanence, death, and the entire human relationship with time. <em>Time is consciousness forgetting its own eternity.</em>'},
  {n:11,skt:'नियति',roman:'Niyati',group:'maya',col:'#403880',
   essence:'Causal necessity — the limitation that creates the law of cause and effect (Karma).',
   body:'The final Kanchuka — the restriction of Shiva\'s freedom to the universal law of cause and effect. Every action having a consequence is Niyati in operation. This is <strong>Karma\'s metaphysical home</strong> — not punishment, but the structural guarantee that actions matter.'},
  
  // Purusha-Prakriti (12-13)
  {n:12,skt:'पुरुष',roman:'Purusha',group:'pp',col:'#88aaff',
   essence:'The individual witness — consciousness apparently bound by the Kanchukas, experiencing itself as separate.',
   body:'Having passed through Maya\'s five Kanchukas, universal Shiva-consciousness now experiences itself as an individual soul (Jiva). Purusha is not truly bound — but it <em>experiences</em> boundedness. This is the essential confusion that the entire tradition works to dissolve: <strong>Purusha thinking it is not Shiva.</strong>'},
  {n:13,skt:'प्रकृति',roman:'Prakriti',group:'pp',col:'#70c8a0',
   essence:'Primordial nature — the material ground from which all physical and mental phenomena emerge.',
   body:'The counterpart of Purusha. Where Purusha is pure consciousness, Prakriti is the primal material energy in its most subtle, undifferentiated state. Three qualities (Gunas) exist in perfect equilibrium here: Sattva, Rajas, Tamas. <em>The first movement of Prakriti toward manifestation is evolution itself.</em>'},
  
  // Antahkarana / Inner Instrument (14-16)
  {n:14,skt:'बुद्धि',roman:'Buddhi (Mahat)',group:'antah',col:'#60b8e0',
   essence:'Cosmic and individual intelligence — the discriminating faculty, closest to pure consciousness.',
   body:'The first product of Prakriti\'s evolution — cosmic intelligence (Mahat) at the universal level, individual Buddhi in the personal. This is the faculty of <strong>discrimination, decision, and discernment</strong>. The Gita\'s constant reference to intelligence refers to Buddhi — the capacity to see clearly.'},
  {n:15,skt:'अहंकार',roman:'Ahamkara',group:'antah',col:'#50a8d0',
   essence:'The I-maker — the principle that creates the sense of being a separate, defined individual.',
   body:'From Buddhi\'s universal intelligence, Ahamkara individuates: <em>"I am this particular being."</em> This is necessary — without Ahamkara, no embodied action is possible. But identification with Ahamkara as the ultimate self is the root of all suffering. <strong>Ahamkara is not the enemy — it is the mistaken king.</strong>'},
  {n:16,skt:'मनस्',roman:'Manas',group:'antah',col:'#40a0c0',
   essence:'The thinking mind — sensory processing, imagination, doubt, and the oscillating faculty between yes and no.',
   body:'Manas receives input from the five sense organs and five action organs and presents them to Buddhi for evaluation. It generates options, doubts, images, memories. <em>The mind that cannot stop is Manas unsupported by Buddhi.</em> Yoga\'s first task: restore the proper hierarchy.'},
  
  // Jnanendriyas — 5 Sense Organs (17-21)
  {n:17,skt:'श्रोत्र',roman:'Shrotra (Hearing)',group:'jnana',col:'#80d8c0',
   essence:'The faculty of hearing — the subtlest sense, arising from Akasha (space element).',
   body:'The five Jnanendriyas (knowledge-organs) are subtle faculties — not the physical ear but the <strong>capacity to receive sound vibration</strong> into consciousness. Shrotra corresponds to Akasha, the space element. Meditation on inner sound (Nada Yoga) works at this level.'},
  {n:18,skt:'त्वक्',roman:'Tvak (Touch)',group:'jnana',col:'#70c8b0',
   essence:'The faculty of touch — reception of pressure, temperature, texture; arising from Vayu.',
   body:'Touch is the oldest sense evolutionarily and the most intimate. <em>We can survive without sight; we cannot survive without touch.</em> The felt sense of presence itself — of being embodied in a world — is Tvak\'s deepest function.'},
  {n:19,skt:'चक्षुस्',roman:'Chakshu (Sight)',group:'jnana',col:'#60b8a0',
   essence:'The faculty of sight — the capacity to receive light and form; arising from Agni (fire).',
   body:'More than half of human cortical real estate processes visual information. The tradition knew this: <em>Darshana</em> (to see) is also the word for philosophical viewpoint and for receiving the grace of a deity or teacher. <strong>Seeing is not passive reception — it is participation.</strong>'},
  {n:20,skt:'रसना',roman:'Rasana (Taste)',group:'jnana',col:'#50a890',
   essence:'The faculty of taste — reception of the six tastes; arising from Apas (water element).',
   body:'The six tastes (Shad Rasa) of Ayurveda — sweet, sour, salty, pungent, bitter, astringent — are the Rasana Tanmantra\'s register. <em>Taste is how the body makes decisions about what to absorb into itself.</em> At the subtlest level, what we "taste" as wisdom or folly is the same faculty operating in the mind.'},
  {n:21,skt:'घ्राण',roman:'Ghrana (Smell)',group:'jnana',col:'#409880',
   essence:'The faculty of smell — the most direct sense pathway to the limbic system and memory.',
   body:'Smell bypasses the thalamus and goes directly to the limbic system — the emotional brain. This is why smell triggers memory more powerfully than any other sense. <strong>Gandha (smell) corresponds to Prithvi (earth element)</strong> — the grossest sense for the grossest element.'},
  
  // Karmendriyas — 5 Action Organs (22-26)
  {n:22,skt:'वाक्',roman:'Vak (Speech)',group:'karma',col:'#f0d080',
   essence:'The faculty of speech — creation through sound; the human power most like the divine creative Word.',
   body:'The most powerful of the Karmendriyas. <em>In the beginning was the Word.</em> Every tradition says this because it is structurally true at the Tattva level: Vak is the action-faculty corresponding to Akasha and Nada. The capacity to <strong>name</strong> is the capacity to create — to bring form from potential.'},
  {n:23,skt:'पाणि',roman:'Pani (Grasping)',group:'karma',col:'#e8c870',
   essence:'The faculty of grasping and making — the hands as instruments of creation and relationship.',
   body:'The thumb-forefinger opposition that defines human tool use. Every human achievement — from the first stone tool to the most complex surgery — is Pani in action. <em>The hand that builds and the hand that reaches out to another are both expressions of this Tattva.</em>'},
  {n:24,skt:'पाद',roman:'Pada (Locomotion)',group:'karma',col:'#e0c060',
   essence:'The faculty of movement — the capacity to navigate, approach, and withdraw in the world.',
   body:'Walking is how consciousness moves through space. The tradition notes: <em>the feet that walk toward wisdom and the feet that walk toward distraction are both Pada</em> — the Tattva is neutral, a pure capacity. Direction is provided by Buddhi and Ahamkara above.'},
  {n:25,skt:'पायु',roman:'Payu (Elimination)',group:'karma',col:'#d8b850',
   essence:'The faculty of elimination — release of what has been processed and is no longer needed.',
   body:'Every complete cycle requires release. <em>What cannot be eliminated accumulates as toxicity</em> — at every level. This applies to emotions (suppression), thoughts (rumination), relationships (inability to let go), and culture (inability to release outworn forms). <strong>Payu is the teaching of healthy endings.</strong>'},
  {n:26,skt:'उपस्थ',roman:'Upastha (Procreation)',group:'karma',col:'#d0b040',
   essence:'The faculty of procreation and pleasure — the creative-generative principle in embodied form.',
   body:'Corresponded to Apas (water), this Karmendriya governs not only biological reproduction but the <em>generative impulse itself</em> — creativity, pleasure, the desire to bring something new into being. Tantra\'s deep teaching: this energy, refined, becomes Kundalini Shakti.'},
  
  // Tanmantras — 5 Subtle Elements (27-31)
  {n:27,skt:'शब्द',roman:'Shabda (Sound-essence)',group:'tanm',col:'#80c8ff',
   essence:'The pure quality of sound before physical sound — the subtle vibration from which Akasha emerges.',
   body:'The Tanmantras are <em>qualia</em> — pure experienced qualities that precede physical elements. Shabda is not a sound wave. It is the <strong>pure experience of soundness</strong> — what sound feels like from the inside, the "ring" of awareness itself. From Shabda condenses the element of space (Akasha).'},
  {n:28,skt:'स्पर्श',roman:'Sparsha (Touch-essence)',group:'tanm',col:'#70b8f0',
   essence:'The pure quality of touch — the subtle feeling of contact and boundary from which Vayu emerges.',
   body:'Before there is wind, there is the <em>idea of contact</em>. Sparsha is the subtle experience of boundary — of meeting, of pressure, of warmth and cold as pure qualia. From Sparsha condenses Vayu (air/movement). <strong>Every wind carries this primordial quality of touch into the world.</strong>'},
  {n:29,skt:'रूप',roman:'Rupa (Form-essence)',group:'tanm',col:'#60a8e0',
   essence:'The pure quality of form and light — the subtle luminosity from which Agni (fire) emerges.',
   body:'Rupa is not a shape — it is the pure quality of <em>visibility</em>: the "fireness" of fire as an experience. Light, color, form, beauty — all condense from this Tanmantra. Every flame carries Rupa as its essence. The tradition: <strong>to truly see anything is to perceive its Rupa Tanmantra.</strong>'},
  {n:30,skt:'रस',roman:'Rasa (Taste-essence)',group:'tanm',col:'#5098d0',
   essence:'The pure quality of taste — the subtle essence of liquidity and nourishment from which Apas emerges.',
   body:'Before there is water, there is the quality of <em>tastability</em> — the pure experience of flowing, nourishing, connecting. Rasa also means juice, sap, essence, and emotion in Sanskrit. <strong>Every rasa (feeling/taste) is this primordial Tanmantra expressing through a more refined channel.</strong>'},
  {n:31,skt:'गन्ध',roman:'Gandha (Smell-essence)',group:'tanm',col:'#4088c0',
   essence:'The pure quality of smell — the most primordial quality, from which the earth element condenses.',
   body:'The grossest of the subtle elements, Gandha is the pure quality of <em>earthiness</em> — the felt sense of solidity, stability, groundedness. Every smell carries information about the material world. <strong>Prithvi (earth) condenses from Gandha</strong> — the ground beneath your feet is crystallized smell-quality.'},
  
  // Panchabhutas — 5 Gross Elements (32-36)
  {n:32,skt:'आकाश',roman:'Akasha (Space)',group:'bhuta',col:'#c0e0ff',
   essence:'Space — the first gross element, the container of all other elements and all experience.',
   body:'Akasha is not empty — it is <em>fullness as openness</em>. The Upanishads: "From Akasha arose Vayu." All four other elements arise within Akasha — it is their container. <strong>Consciousness and Akasha share one quality: both contain everything without being defined by anything they contain.</strong>'},
  {n:33,skt:'वायु',roman:'Vayu (Air/Wind)',group:'bhuta',col:'#a0d0f0',
   essence:'Air — movement, breath, the life-giving element; connects all living beings through shared atmosphere.',
   body:'Vayu is the element of <em>contact without permanence</em> — touch that moves. Prana (life-force) rides on Vayu — this is why breath is the most direct access to Prana. <strong>The wind connects every living thing:</strong> the air you breathe has been breathed by every being that has ever lived.'},
  {n:34,skt:'तेजस्',roman:'Tejas (Fire)',group:'bhuta',col:'#ffe0a0',
   essence:'Fire — transformation, light, digestion; the element that converts one form into another.',
   body:'Tejas is the transformer. <em>Nothing changes without fire.</em> Agni (the Vedic fire deity) is the digestive fire in the belly, the metabolic fire in cells, the intellectual fire of Viveka (discrimination), and the transformative fire of Tapas (austerity). <strong>Every transformation you have ever undergone was Tejas at work.</strong>'},
  {n:35,skt:'अपस्',roman:'Apas (Water)',group:'bhuta',col:'#90c8e0',
   essence:'Water — the element of cohesion, nourishment, and the feeling principle; takes every form.',
   body:'Water has no fixed form — it perfectly takes the shape of its container. This is its teaching: <em>total adaptability</em>. In Ayurveda, Apas governs taste and emotional fluidity. The blood that carries life through the body is Apas\'s most intimate expression in living form.'},
  {n:36,skt:'पृथ्वी',roman:'Prithvi (Earth)',group:'bhuta',col:'#d0c8a0',
   essence:'Earth — the densest element, the ground of all form; stability, support, and material manifestation.',
   body:'The final Tattva — the completion of descent from unmanifest Shiva-Shakti to solid matter. <em>Every atom in your body is Prithvi.</em> Every stone, every grain of sand, every bone is the Tattva cascade completed — pure consciousness having descended through 35 levels of increasing density to become this: a world you can touch.'},
];

const TATTVA_GROUPS={
  shiva:{label:'Shiva Tattvas',col:'#c090ff',sub:'1–5 · Pure Consciousness'},
  maya:{label:'Maya Tattvas',col:'#8060c0',sub:'6–11 · The Limiting Sheaths'},
  pp:{label:'Purusha–Prakriti',col:'#80b8ff',sub:'12–13 · Individual Soul & Nature'},
  antah:{label:'Antahkarana',col:'#60b8e0',sub:'14–16 · The Inner Instrument'},
  jnana:{label:'Jnanendriyas',col:'#70d0b0',sub:'17–21 · Five Knowledge Organs'},
  karma:{label:'Karmendriyas',col:'#e8c870',sub:'22–26 · Five Action Organs'},
  tanm:{label:'Tanmantras',col:'#80c8ff',sub:'27–31 · Five Subtle Elements'},
  bhuta:{label:'Panchabhutas',col:'#b0c8e0',sub:'32–36 · Five Gross Elements'},
};

let tattvaCanvas=null,tattvaCtx=null,tattvaFrame=null,tattvaT=0;
let tattvaSelected=null,tattvaHov=null,tattvaNodes=[];

function openTattva(){
  document.getElementById('tattva-ov').classList.add('on');
  const delay=window.innerWidth<=768?200:60;
  setTimeout(initTattva,delay);
}
function closeTattva(){
  document.getElementById('tattva-ov').classList.remove('on');
  if(tattvaFrame){cancelAnimationFrame(tattvaFrame);tattvaFrame=null;}
  document.getElementById('tattva-panel').classList.remove('open');
}

function initTattva(){
  tattvaCanvas=document.getElementById('tattva-canvas');
  if(!tattvaCanvas)return;
  const dpr=window.devicePixelRatio||1;
  const W=window.innerWidth, H=window.innerHeight;
  tattvaCanvas.style.position='fixed';tattvaCanvas.style.top='0';tattvaCanvas.style.left='0';
  tattvaCanvas.style.width=W+'px';tattvaCanvas.style.height=H+'px';
  tattvaCanvas.width=W*dpr;tattvaCanvas.height=H*dpr;
  tattvaCtx=tattvaCanvas.getContext('2d');
  tattvaCtx.scale(dpr,dpr);
  buildTattvaNodes(W,H);
  tattvaCanvas.onclick=tattvaClick;
  tattvaCanvas.onmousemove=tattvaHover;
  tattvaCanvas.ontouchend=e=>{e.preventDefault();const t=e.changedTouches[0];tattvaClick({clientX:t.clientX,clientY:t.clientY});};
  if(tattvaFrame)cancelAnimationFrame(tattvaFrame);
  tattvaFrame=requestAnimationFrame(drawTattva);
}

function buildTattvaNodes(W,H){
  // Waterfall cascade layout — 8 groups flowing top to bottom
  const groups=Object.keys(TATTVA_GROUPS);
  const topY=72, botY=H-30;
  const usable=botY-topY;
  const groupH=usable/groups.length;
  tattvaNodes=[];
  groups.forEach((gk,gi)=>{
    const members=TATTVAS.filter(t=>t.group===gk);
    const y=topY+gi*groupH+groupH*0.5;
    const totalW=W*0.8;
    members.forEach((tv,ti)=>{
      const slots=members.length;
      const x=W*0.1+((ti+0.5)/slots)*totalW;
      tattvaNodes.push({...tv,x,y,px:x,py:y,vx:0,vy:0,
        r:window.innerWidth<=768?11:13,hov:false,sel:false});
    });
  });
}

function drawTattva(){
  if(!tattvaCtx){tattvaFrame=null;return;}
  tattvaT+=0.012;
  const W=tattvaCanvas.clientWidth,H=tattvaCanvas.clientHeight;
  const ctx=tattvaCtx;
  ctx.clearRect(0,0,W,H);

  // Deep space bg
  const bg=ctx.createRadialGradient(W/2,H*0.3,0,W/2,H*0.6,Math.max(W,H));
  bg.addColorStop(0,'rgba(8,3,18,1)');bg.addColorStop(.5,'rgba(4,1,10,1)');bg.addColorStop(1,'rgba(2,0,5,1)');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);

  // Group cascade labels + divider lines
  const groups=Object.keys(TATTVA_GROUPS);
  const topY=72,botY=H-30,usable=botY-topY,groupH=usable/groups.length;
  groups.forEach((gk,gi)=>{
    const g=TATTVA_GROUPS[gk];
    const y=topY+gi*groupH;
    if(gi>0){
      // cascade flow line
      ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);
      ctx.strokeStyle='rgba(120,80,200,.06)';ctx.lineWidth=1;ctx.stroke();
    }
    ctx.fillStyle='rgba(120,80,200,.18)';
    ctx.font='7px "IBM Plex Mono"';ctx.textAlign='left';ctx.textBaseline='middle';
    ctx.fillText((gi+1)+'. '+g.label.toUpperCase(),12,y+groupH*0.15);
  });

  // Flow connections between groups
  const getGroupMid=(gk)=>{
    const ns=tattvaNodes.filter(n=>n.group===gk);
    const x=ns.reduce((a,n)=>a+n.x,0)/ns.length;
    const y=ns[0]?ns[0].y:0;
    return{x,y};
  };
  for(let i=0;i<groups.length-1;i++){
    const a=getGroupMid(groups[i]),b=getGroupMid(groups[i+1]);
    const grd=ctx.createLinearGradient(a.x,a.y,b.x,b.y);
    const ca=TATTVA_GROUPS[groups[i]].col, cb=TATTVA_GROUPS[groups[i+1]].col;
    const hexToRgba2=(h,a)=>{var rv=parseInt(h.slice(1,3),16),gv=parseInt(h.slice(3,5),16),bv=parseInt(h.slice(5,7),16);return "rgba("+rv+","+gv+","+bv+","+a+")";};
    grd.addColorStop(0,hexToRgba2(ca,.12));grd.addColorStop(1,hexToRgba2(cb,.06));
    ctx.beginPath();ctx.moveTo(a.x,a.y+12);ctx.lineTo(b.x,b.y-12);
    ctx.strokeStyle='rgba(120,80,200,.04)';ctx.lineWidth=2;ctx.stroke();
  }

  // Nodes
  tattvaNodes.forEach(n=>{
    const sel=tattvaSelected&&tattvaSelected.n===n.n;
    const hov=tattvaHov&&tattvaHov.n===n.n;
    const r=n.r+(sel?4:hov?2:0);
    const pulse=Math.sin(tattvaT*1.2+n.n*0.4)*0.4+0.6;

    // Glow
    if(sel||hov){
      const g=ctx.createRadialGradient(n.x,n.y,0,n.x,n.y,r*3.5);
      const hex=n.col;
      g.addColorStop(0,hex+'30');g.addColorStop(1,'transparent');
      ctx.fillStyle=g;ctx.beginPath();ctx.arc(n.x,n.y,r*3.5,0,Math.PI*2);ctx.fill();
    }

    // Particle ring for selected
    if(sel){
      for(let p=0;p<6;p++){
        const pa=(p/6)*Math.PI*2+tattvaT*0.5;
        const pr=r*2.2;
        const px=n.x+Math.cos(pa)*pr,py=n.y+Math.sin(pa)*pr;
        ctx.beginPath();ctx.arc(px,py,1.5,0,Math.PI*2);
        ctx.fillStyle=n.col+'aa';ctx.fill();
      }
    }

    // Node body
    ctx.beginPath();ctx.arc(n.x,n.y,r,0,Math.PI*2);
    ctx.fillStyle=sel?'rgba(12,4,24,.95)':'rgba(5,1,12,.88)';ctx.fill();
    ctx.strokeStyle=sel?n.col:hov?n.col+'cc':n.col+'44';
    ctx.lineWidth=sel?2:1;ctx.stroke();

    // Inner dot
    ctx.beginPath();ctx.arc(n.x,n.y,sel?5:3,0,Math.PI*2);
    ctx.fillStyle=n.col+(sel?'ff':'88');ctx.fill();

    // Number
    ctx.fillStyle=sel?'rgba(240,220,255,.9)':hov?n.col:'rgba(120,80,200,.5)';
    ctx.font=(sel?'bold 8':'7')+'px "IBM Plex Mono"';
    ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.fillText(n.n,n.x,n.y);

    // Sanskrit name (abbreviated)
    if(W>600||sel||hov){
      ctx.fillStyle=sel?'rgba(220,200,255,.8)':hov?n.col+'cc':'rgba(120,80,200,.35)';
      ctx.font=(sel?'9':'7.5')+'px "IBM Plex Mono"';
      ctx.textBaseline='top';
      const label=n.roman.split(' ')[0].substring(0,8);
      ctx.fillText(label,n.x,n.y+r+4);
    }
  });

  // Title
  ctx.fillStyle='rgba(200,170,255,.15)';
  ctx.font='bold 10px "IBM Plex Mono"';
  ctx.textAlign='left';ctx.textBaseline='top';
  ctx.fillText('TATTVA CASCADE · 36 PRINCIPLES · KASHMIR SHAIVISM',14,56);

  tattvaFrame=requestAnimationFrame(drawTattva);
}

function tattvaClick(e){
  const r=tattvaCanvas.getBoundingClientRect();
  const mx=e.clientX-r.left,my=e.clientY-r.top;
  let hit=null;
  tattvaNodes.forEach(n=>{if(Math.hypot(mx-n.x,my-n.y)<n.r+8)hit=n;});
  tattvaSelected=hit;
  const panel=document.getElementById('tattva-panel');
  if(hit){
    const g=TATTVA_GROUPS[hit.group];
    panel.innerHTML=`
      <button style="background:none;border:1px solid rgba(120,80,200,.2);color:rgba(120,80,200,.5);padding:5px 10px;font-family:'IBM Plex Mono',monospace;font-size:7px;letter-spacing:2px;cursor:pointer;text-transform:uppercase;margin-bottom:18px;display:block;transition:all .2s;" onmouseover="this.style.color='rgba(200,170,255,.9)'" onmouseout="this.style.color='rgba(120,80,200,.5)'" onclick="document.getElementById('tattva-panel').classList.remove('open');tattvaSelected=null;">✕ close</button>
      <div class="tattva-num">Tattva ${hit.n} of 36 · ${g.label}</div>
      <span class="tattva-skt">${hit.skt}</span>
      <span class="tattva-roman">${hit.roman}</span>
      <div style="display:inline-block;padding:3px 10px;border:1px solid ${hit.col}44;background:${hit.col}11;color:${hit.col};font-family:'IBM Plex Mono',monospace;font-size:6px;letter-spacing:2px;text-transform:uppercase;margin-bottom:14px;">${g.sub}</div>
      <div class="tattva-essence">${hit.essence}</div>
      <div class="tattva-body">${hit.body}</div>
    `;
    panel.classList.add('open');
  }else{
    panel.classList.remove('open');
  }
}

function tattvaHover(e){
  const r=tattvaCanvas.getBoundingClientRect();
  const mx=e.clientX-r.left,my=e.clientY-r.top;
  tattvaHov=null;
  tattvaNodes.forEach(n=>{n.hov=Math.hypot(mx-n.x,my-n.y)<n.r+8;if(n.hov)tattvaHov=n;});
  tattvaCanvas.style.cursor=tattvaHov?'pointer':'default';
}

// ═══════════════════════════════════════════════════════════════════
//  STHULA BODY — The Gross Physical Body
// ═══════════════════════════════════════════════════════════════════
const STHULA_NODES=[
  {id:'annamaya',label:'Annamaya Kosha',skt:'अन्नमय कोश',x:.5,y:.18,r:52,col:'#80c080',
   essence:'The food body — born from food, sustained by food, returned to earth as food.',
   body:'The outermost sheath of the self. Every cell in your body was once food — sunlight converted to plant matter, converted to animal matter, converted to you. <strong>The body is borrowed light.</strong> The Taittiriya Upanishad: "From food, verily, are produced all creatures that dwell on earth." Ayurveda maps this sheath through the three Doshas, seven Dhatus, and three Malas.'},
  {id:'prana',label:'Pranamaya Kosha',skt:'प्राणमय कोश',x:.5,y:.38,r:44,col:'#60d0a0',
   essence:'The vital body — the energy sheath that animates the physical, the breath behind the breath.',
   body:'Subtler than matter but grosser than mind. Five Pranas govern all physiological function: <strong>Prana</strong> (inward breath — reception), <strong>Apana</strong> (downward — elimination), <strong>Samana</strong> (equalizing — digestion), <strong>Udana</strong> (upward — speech, consciousness), <strong>Vyana</strong> (pervading — circulation). When the five Pranas cease their coordination, what we call death occurs.'},
  {id:'panchabhoota',label:'Pancha Mahabhuta',skt:'पञ्च महाभूत',x:.5,y:.58,r:40,col:'#90d080',
   essence:'Five great elements — the building materials of all gross physical matter.',
   body:'Every substance in the physical universe is a specific combination of the five elements. Your bones are Prithvi-dominant. Your blood, Apas. Your metabolic heat, Agni. Your breath, Vayu. The spaces in your cells and body cavities, Akasha. <strong>Ayurveda heals by rebalancing these elements.</strong> Yoga prepares the body by mastering them.'},
  {id:'saptadhatu',label:'Sapta Dhatu',skt:'सप्त धातु',x:.28,y:.72,r:32,col:'#70c878',
   essence:'Seven tissues — the structural layers of the body from gross to subtle.',
   body:'Rasa (plasma/chyle) → Rakta (blood) → Mamsa (muscle) → Meda (fat) → Asthi (bone) → Majja (marrow/nerve) → Shukra (reproductive tissue). Each feeds the next. <strong>Health is the orderly production and nourishment of each Dhatu in sequence.</strong> Ayurvedic diagnosis often traces disease to the point where this chain breaks.'},
  {id:'doshas',label:'Tri-Dosha',skt:'त्रिदोष',x:.72,y:.72,r:32,col:'#a0d870',
   essence:'Three biological intelligences — Vata, Pitta, Kapha — governing all physiological processes.',
   body:'<strong>Vata</strong> (space + air): movement, communication, creativity, nerve impulses. <strong>Pitta</strong> (fire + water): transformation, digestion, intelligence, vision. <strong>Kapha</strong> (earth + water): structure, lubrication, immunity, memory. Every individual is a unique ratio of these three. Disease is their imbalance; health is their harmony.'},
  {id:'agni',label:'Agni — Digestive Fire',skt:'अग्नि',x:.5,y:.88,r:28,col:'#f0c060',
   essence:'The metabolic fire — the transformative principle that converts food to consciousness.',
   body:'Ayurveda identifies 13 Agnis: one central digestive fire (Jatharagni) and twelve subsidiary fires in each Dhatu and five elements. <strong>All disease ultimately traces to impaired Agni.</strong> Yoga practice fans the inner fire through Pranayama, Asana, and Tapas. The Vedic fire altar is the external symbol of this inner transformation.'},
];

let sthCanvas=null,sthCtx=null,sthFrame=null,sthT=0,sthSel=null,sthHov=null,sthNodes=[];

function openSthula(){
  document.getElementById('sthula-ov').classList.add('on');
  setTimeout(initSthula,window.innerWidth<=768?200:60);
}
function closeSthula(){
  document.getElementById('sthula-ov').classList.remove('on');
  if(sthFrame){cancelAnimationFrame(sthFrame);sthFrame=null;}
  document.getElementById('sthula-panel').classList.remove('open');
}

function initSthula(){
  sthCanvas=document.getElementById('sthula-canvas');
  if(!sthCanvas)return;
  const dpr=window.devicePixelRatio||1;
  const W=window.innerWidth,H=window.innerHeight;
  sthCanvas.style.position='fixed';sthCanvas.style.top='0';sthCanvas.style.left='0';
  sthCanvas.style.width=W+'px';sthCanvas.style.height=H+'px';
  sthCanvas.width=W*dpr;sthCanvas.height=H*dpr;
  sthCtx=sthCanvas.getContext('2d');sthCtx.scale(dpr,dpr);
  sthNodes=STHULA_NODES.map(n=>({...n,px:n.x*W,py:n.y*(H-54)+54,r:Math.min(n.r,(W>600?n.r:n.r*.7))}));
  sthCanvas.onclick=sthClick;sthCanvas.onmousemove=sthHover;
  sthCanvas.ontouchend=e=>{e.preventDefault();const t=e.changedTouches[0];sthClick({clientX:t.clientX,clientY:t.clientY});};
  if(sthFrame)cancelAnimationFrame(sthFrame);
  sthFrame=requestAnimationFrame(drawSthula);
}

function drawSthula(){
  if(!sthCtx){sthFrame=null;return;}
  sthT+=0.008;
  const W=sthCanvas.clientWidth,H=sthCanvas.clientHeight;
  const ctx=sthCtx;ctx.clearRect(0,0,W,H);
  // BG
  const bg=ctx.createRadialGradient(W/2,H*0.5,0,W/2,H*0.5,Math.max(W,H));
  bg.addColorStop(0,'rgba(3,8,5,1)');bg.addColorStop(.6,'rgba(1,4,3,1)');bg.addColorStop(1,'rgba(0,2,1,1)');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);

  // Body silhouette (subtle)
  ctx.save();
  const bx=W/2,by=H/2+20,bh=H*0.75;
  const grad=ctx.createLinearGradient(bx,by-bh/2,bx,by+bh/2);
  grad.addColorStop(0,'rgba(80,160,100,.025)');grad.addColorStop(.5,'rgba(80,160,100,.04)');grad.addColorStop(1,'rgba(80,160,100,.01)');
  ctx.beginPath();
  ctx.ellipse(bx,by-bh*0.25,bh*0.15,bh*0.45,0,0,Math.PI*2); // torso
  ctx.fillStyle=grad;ctx.fill();
  ctx.restore();

  // Connection lines between nodes
  const conns=[['annamaya','prana'],['prana','panchabhoota'],['panchabhoota','saptadhatu'],['panchabhoota','doshas'],['saptadhatu','agni'],['doshas','agni']];
  conns.forEach(([a,b])=>{
    const na=sthNodes.find(n=>n.id===a),nb=sthNodes.find(n=>n.id===b);
    if(!na||!nb)return;
    ctx.beginPath();ctx.moveTo(na.px,na.py);ctx.lineTo(nb.px,nb.py);
    ctx.strokeStyle='rgba(80,160,100,.12)';ctx.lineWidth=1;ctx.stroke();
  });

  // Flowing particle effect (prana streams)
  for(let i=0;i<8;i++){
    const t=(sthT*0.4+i/8)%1;
    const path=sthNodes;if(!path.length)return;
    const pi=Math.floor(t*(path.length-1));
    const a=path[pi],b=path[Math.min(pi+1,path.length-1)];
    const lt=t*(path.length-1)-pi;
    const px=a.px+(b.px-a.px)*lt,py=a.py+(b.py-a.py)*lt;
    ctx.beginPath();ctx.arc(px,py,2,0,Math.PI*2);
    ctx.fillStyle=`rgba(100,200,140,${0.4*Math.sin(t*Math.PI)})`;ctx.fill();
  }

  // Nodes
  sthNodes.forEach(n=>{
    const sel=sthSel&&sthSel.id===n.id,hov=sthHov&&sthHov.id===n.id;
    const r=n.r+(sel?6:hov?3:0);
    const pulse=Math.sin(sthT*1.5+n.px*0.01)*0.3+0.7;

    if(sel||hov){
      const g=ctx.createRadialGradient(n.px,n.py,0,n.px,n.py,r*2.5);
      g.addColorStop(0,n.col+'22');g.addColorStop(1,'transparent');
      ctx.fillStyle=g;ctx.beginPath();ctx.arc(n.px,n.py,r*2.5,0,Math.PI*2);ctx.fill();
    }

    // Pulsing ring
    const ringR=r+(Math.sin(sthT*2+n.px*0.005)*6+6);
    ctx.beginPath();ctx.arc(n.px,n.py,ringR,0,Math.PI*2);
    ctx.strokeStyle=n.col+(sel?'44':'18');ctx.lineWidth=1;ctx.stroke();

    ctx.beginPath();ctx.arc(n.px,n.py,r,0,Math.PI*2);
    ctx.fillStyle=sel?'rgba(2,8,5,.95)':'rgba(1,4,3,.88)';ctx.fill();
    ctx.strokeStyle=sel?n.col:hov?n.col+'aa':n.col+'40';ctx.lineWidth=sel?2:1;ctx.stroke();

    ctx.beginPath();ctx.arc(n.px,n.py,sel?6:4,0,Math.PI*2);
    ctx.fillStyle=n.col+(sel?'ff':'88');ctx.fill();

    ctx.fillStyle=sel?'rgba(220,255,230,.9)':hov?n.col:'rgba(80,160,100,.6)';
    ctx.font=(sel?'bold 10':'9')+'px "IBM Plex Mono"';
    ctx.textAlign='center';ctx.textBaseline='top';
    ctx.fillText(n.label.split(' ')[0].toUpperCase(),n.px,n.py+r+5);
  });

  ctx.fillStyle='rgba(100,180,120,.12)';
  ctx.font='bold 9px "IBM Plex Mono"';ctx.textAlign='left';ctx.textBaseline='top';
  ctx.fillText('STHULA SHARIRA · GROSS BODY · ANNAMAYA KOSHA',14,58);

  sthFrame=requestAnimationFrame(drawSthula);
}

function sthClick(e){
  const r=sthCanvas.getBoundingClientRect();
  const mx=e.clientX-r.left,my=e.clientY-r.top;
  let hit=null;
  sthNodes.forEach(n=>{if(Math.hypot(mx-n.px,my-n.py)<n.r+10)hit=n;});
  sthSel=hit;
  const panel=document.getElementById('sthula-panel');
  if(hit){
    panel.innerHTML=`
      <button style="background:none;border:1px solid rgba(80,160,100,.2);color:rgba(80,160,100,.5);padding:5px 10px;font-family:'IBM Plex Mono',monospace;font-size:7px;letter-spacing:2px;cursor:pointer;text-transform:uppercase;margin-bottom:18px;display:block;" onclick="document.getElementById('sthula-panel').classList.remove('open');sthSel=null;">✕ close</button>
      <span class="sthula-skt">${hit.skt}</span>
      <span class="sthula-roman">${hit.label}</span>
      <div style="font-family:'Cormorant Garamond',serif;font-size:15px;font-style:italic;color:rgba(120,200,150,.6);line-height:1.8;margin-bottom:14px;padding-bottom:12px;border-bottom:1px solid rgba(80,160,100,.12);">${hit.essence}</div>
      <div class="sthula-body">${hit.body}</div>
    `;
    panel.classList.add('open');
  }else{panel.classList.remove('open');}
}
function sthHover(e){
  const r=sthCanvas.getBoundingClientRect();
  const mx=e.clientX-r.left,my=e.clientY-r.top;
  sthHov=null;sthNodes.forEach(n=>{n.hov=Math.hypot(mx-n.px,my-n.py)<n.r+10;if(n.hov)sthHov=n;});
  sthCanvas.style.cursor=sthHov?'pointer':'default';
}

// ═══════════════════════════════════════════════════════════════════
//  KARAN BODY — Causal Body / Anandamaya Kosha
// ═══════════════════════════════════════════════════════════════════
const KARAN_NODES=[
  {id:'ananda',label:'Anandamaya Kosha',skt:'आनन्दमय कोश',x:.5,y:.2,r:55,col:'#c090f0',
   essence:'The bliss sheath — the subtlest of the five, closest to the Atman; experienced as deep joy in dreamless sleep.',
   body:'The causal body is the "seed body" (Karana Sharira) — the blueprint from which the subtle and gross bodies grow in each life. It contains the impressions (Samskaras) and desires (Vasanas) that determine the next birth. <strong>It is the Anandamaya because it is closest to Brahman</strong> — and Brahman is Ananda. The bliss experienced in deep sleep is the individual touching this sheath.'},
  {id:'samskara',label:'Samskara',skt:'संस्कार',x:.3,y:.42,r:38,col:'#a070e0',
   essence:'Mental impressions — every experience leaves a groove; the causal body is their repository.',
   body:'Every thought, every action, every sensation leaves an impression in the field of consciousness. These grooves (Samskaras) accumulate over lifetimes, shaping: personality, preferences, fears, talents, and relationships. <strong>The causal body is a library of all Samskaras across all lifetimes.</strong> Liberation dissolves this library by dissolving the librarian.'},
  {id:'vasana',label:'Vasana',skt:'वासना',x:.7,y:.42,r:38,col:'#b080e8',
   essence:'Latent tendencies — clusters of Samskaras that create powerful pull toward certain experiences.',
   body:'When Samskaras of a similar type cluster, they form Vasanas — unconscious drives. The persistent attraction to certain experiences, the recurring life themes, the patterns that repeat across relationships: all are Vasanas at work. <strong>Yoga is the systematic dissolution of Vasanas</strong> — not by fighting them but by tracing them to their root and recognizing it as empty.'},
  {id:'karma_seed',label:'Karma Bija',skt:'कर्म बीज',x:.5,y:.63,r:34,col:'#9060d0',
   essence:'Karmic seeds — the unripened results of past actions held in potential until conditions allow fruition.',
   body:'Not all Karma ripens immediately. Three types: <strong>Sanchita</strong> (accumulated, not yet begun), <strong>Prarabdha</strong> (currently ripening — this life), <strong>Agami</strong> (being created now). The causal body contains Sanchita karma in seed form — the vast potential library of all actions whose results have not yet manifested. Liberation is burning Sanchita in the fire of Jnana.'},
  {id:'turiya',label:'Sushupti / Turiya Gateway',skt:'तुरीय द्वार',x:.5,y:.83,r:30,col:'#d0b0ff',
   essence:'The doorway to the Fourth — the causal body is the antechamber where the individual most nearly touches the Absolute.',
   body:'In deep dreamless sleep, you enter the causal body and dissolve into undifferentiated bliss — but unconsciously. <strong>Yoga Nidra, Samadhi, and the moment of death are three occasions when this doorway opens consciously.</strong> The Mandukya Upanishad: the causal body\'s state is Prajna — knowing-without-object. One step further is Turiya: the witness of all three states.'},
];

let karCanvas=null,karCtx=null,karFrame=null,karT=0,karSel=null,karNodes=[];

function openKaran(){
  document.getElementById('karan-ov').classList.add('on');
  setTimeout(initKaran,window.innerWidth<=768?200:60);
}
function closeKaran(){
  document.getElementById('karan-ov').classList.remove('on');
  if(karFrame){cancelAnimationFrame(karFrame);karFrame=null;}
  document.getElementById('karan-panel').classList.remove('open');
}

function initKaran(){
  karCanvas=document.getElementById('karan-canvas');
  if(!karCanvas)return;
  const dpr=window.devicePixelRatio||1,W=window.innerWidth,H=window.innerHeight;
  karCanvas.style.position='fixed';karCanvas.style.top='0';karCanvas.style.left='0';
  karCanvas.style.width=W+'px';karCanvas.style.height=H+'px';
  karCanvas.width=W*dpr;karCanvas.height=H*dpr;
  karCtx=karCanvas.getContext('2d');karCtx.scale(dpr,dpr);
  karNodes=KARAN_NODES.map(n=>({...n,px:n.x*W,py:n.y*(H-54)+54,r:Math.min(n.r,n.r*(W>600?1:.7))}));
  karCanvas.onclick=karClick;karCanvas.onmousemove=karHover;
  karCanvas.ontouchend=e=>{e.preventDefault();const t=e.changedTouches[0];karClick({clientX:t.clientX,clientY:t.clientY});};
  if(karFrame)cancelAnimationFrame(karFrame);
  karFrame=requestAnimationFrame(drawKaran);
}

function drawKaran(){
  if(!karCtx){karFrame=null;return;}karT+=0.007;
  const W=karCanvas.clientWidth,H=karCanvas.clientHeight;
  const ctx=karCtx;ctx.clearRect(0,0,W,H);
  // Deep violet bg
  const bg=ctx.createRadialGradient(W/2,H*0.35,0,W/2,H*0.6,Math.max(W,H));
  bg.addColorStop(0,'rgba(8,3,16,1)');bg.addColorStop(.5,'rgba(4,1,8,1)');bg.addColorStop(1,'rgba(2,0,4,1)');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  // Nebula clouds
  for(let i=0;i<3;i++){
    const nx=W*(0.2+i*0.3),ny=H*(0.3+i*0.15);
    const g=ctx.createRadialGradient(nx,ny,0,nx,ny,W*0.2);
    g.addColorStop(0,'rgba(150,100,220,.03)');g.addColorStop(1,'transparent');
    ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
  }
  // Orbiting particles around each node
  karNodes.forEach(n=>{
    for(let p=0;p<5;p++){
      const pa=(p/5)*Math.PI*2+karT*(0.3+p*0.05);
      const pr=n.r*2+(Math.sin(karT+p)*8);
      const px=n.px+Math.cos(pa)*pr,py=n.py+Math.sin(pa)*pr;
      const al=0.15+0.1*Math.sin(karT*2+p);
      ctx.beginPath();ctx.arc(px,py,1.5,0,Math.PI*2);
      ctx.fillStyle=n.col+Math.round(al*255).toString(16).padStart(2,'0');ctx.fill();
    }
  });
  // Lines
  const conns=[['ananda','samskara'],['ananda','vasana'],['samskara','karma_seed'],['vasana','karma_seed'],['karma_seed','turiya']];
  conns.forEach(([a,b])=>{
    const na=karNodes.find(n=>n.id===a),nb=karNodes.find(n=>n.id===b);
    if(!na||!nb)return;
    ctx.beginPath();ctx.moveTo(na.px,na.py);ctx.lineTo(nb.px,nb.py);
    ctx.strokeStyle='rgba(150,100,220,.1)';ctx.lineWidth=1;ctx.stroke();
  });
  // Nodes
  karNodes.forEach(n=>{
    const sel=karSel&&karSel.id===n.id;
    const r=n.r+(sel?6:0);
    if(sel){
      const g=ctx.createRadialGradient(n.px,n.py,0,n.px,n.py,r*3);
      g.addColorStop(0,n.col+'22');g.addColorStop(1,'transparent');
      ctx.fillStyle=g;ctx.beginPath();ctx.arc(n.px,n.py,r*3,0,Math.PI*2);ctx.fill();
    }
    ctx.beginPath();ctx.arc(n.px,n.py,r,0,Math.PI*2);
    ctx.fillStyle='rgba(5,1,10,.9)';ctx.fill();
    ctx.strokeStyle=sel?n.col:n.col+'55';ctx.lineWidth=sel?2:1;ctx.stroke();
    ctx.beginPath();ctx.arc(n.px,n.py,sel?6:4,0,Math.PI*2);
    ctx.fillStyle=n.col;ctx.fill();
    ctx.fillStyle=sel?'rgba(230,210,255,.85)':n.col+'99';
    ctx.font=(sel?'bold 9':'8')+'px "IBM Plex Mono"';
    ctx.textAlign='center';ctx.textBaseline='top';
    ctx.fillText(n.label.split(' ').slice(0,2).join(' ').toUpperCase(),n.px,n.py+r+5);
  });
  ctx.fillStyle='rgba(180,140,240,.12)';
  ctx.font='bold 9px "IBM Plex Mono"';ctx.textAlign='left';ctx.textBaseline='top';
  ctx.fillText('KARANA SHARIRA · CAUSAL BODY · ANANDAMAYA KOSHA',14,58);
  karFrame=requestAnimationFrame(drawKaran);
}

function karClick(e){
  const r=karCanvas.getBoundingClientRect();const mx=e.clientX-r.left,my=e.clientY-r.top;
  let hit=null;karNodes.forEach(n=>{if(Math.hypot(mx-n.px,my-n.py)<n.r+10)hit=n;});
  karSel=hit;const panel=document.getElementById('karan-panel');
  if(hit){
    panel.innerHTML=`<button style="background:none;border:1px solid rgba(150,100,220,.2);color:rgba(150,100,220,.5);padding:5px 10px;font-family:'IBM Plex Mono',monospace;font-size:7px;letter-spacing:2px;cursor:pointer;text-transform:uppercase;margin-bottom:18px;display:block;" onclick="document.getElementById('karan-panel').classList.remove('open');karSel=null;">✕ close</button>
      <span class="karan-skt">${hit.skt}</span><span class="karan-roman">${hit.label}</span>
      <div style="font-family:'Cormorant Garamond',serif;font-size:15px;font-style:italic;color:rgba(180,140,230,.6);line-height:1.8;margin-bottom:14px;padding-bottom:12px;border-bottom:1px solid rgba(150,100,220,.12);">${hit.essence}</div>
      <div class="karan-body">${hit.body}</div>`;
    panel.classList.add('open');
  }else panel.classList.remove('open');
}
function karHover(e){const r=karCanvas.getBoundingClientRect();const mx=e.clientX-r.left,my=e.clientY-r.top;karNodes.forEach(n=>{n.hov=Math.hypot(mx-n.px,my-n.py)<n.r+10;});karCanvas.style.cursor=karNodes.some(n=>n.hov)?'pointer':'default';}

// ═══════════════════════════════════════════════════════════════════
//  ANTAHKARANA — The Four-fold Inner Instrument
// ═══════════════════════════════════════════════════════════════════
const ANTAH_DATA=[
  {id:'manas',label:'Manas',skt:'मनस्',col:'#80b0f0',angle:0,
   essence:'The oscillating mind — sensory processor, doubter, imaginer; the faculty that says yes and no simultaneously.',
   body:'Manas receives all sensory data from the five Jnanendriyas and presents it to Buddhi. It generates options, images, memories, doubts. <em>Left alone, Manas is a child in a toy shop — perpetually distracted.</em> Its quality is Rajas — constant movement. <strong>Pratyahara (sense withdrawal) and Dharana (concentration) are specifically Manas-training.</strong> The chattering mind that meditators encounter first is Manas showing its nature.'},
  {id:'buddhi',label:'Buddhi',skt:'बुद्धि',col:'#f0d060',angle:Math.PI/2,
   essence:'Discriminating intelligence — the decisive faculty that can distinguish real from unreal, eternal from temporary.',
   body:'Buddhi is the closest individual instrument to pure consciousness. When Buddhi is pure (Sattva dominant), it reflects the Atman almost without distortion — like a still lake reflecting the moon. <strong>The entire path of Jnana Yoga is Buddhi refinement.</strong> Patanjali: "Yogas chitta vrtti nirodhah" — when mental modifications cease, Purusha rests in its own nature. That resting is Buddhi becoming transparent.'},
  {id:'chitta',label:'Chitta',skt:'चित्त',col:'#c080d0',angle:Math.PI,
   essence:'The mind-field — the storehouse of all impressions, memories, and subconscious patterns.',
   body:'Chitta is the substance of the mind — the material in which Manas, Buddhi, and Ahamkara operate. <em>Every experience leaves a trace in Chitta.</em> Every memory, fear, joy, and habit lives here. The goal of Yoga (Patanjali 1.2): Chitta-vrtti-nirodha — stilling the modifications of Chitta. <strong>Chitta purified becomes Chit — the pure consciousness it has been reflecting all along.</strong>'},
  {id:'ahamkara',label:'Ahamkara',skt:'अहंकार',col:'#f08080',angle:Math.PI*3/2,
   essence:'The I-maker — the function that takes pure awareness and assigns it a name, body, story, and self-concept.',
   body:'Ahamkara is necessary — without it, no individual can function in the world. The problem is <em>identification</em>: mistaking Ahamkara for the Self. <strong>Every spiritual crisis is Ahamkara losing its footing.</strong> Every genuine insight is Ahamkara briefly recognizing it is not the source. The wave discovering it is the ocean — and then, terrified, reasserting "I am a wave."'},
];

let antCanvas=null,antCtx=null,antFrame=null,antT=0,antSel=null,antNodes=[];

function openAntah(){
  document.getElementById('antah-ov').classList.add('on');
  setTimeout(initAntah,window.innerWidth<=768?200:60);
}
function closeAntah(){
  document.getElementById('antah-ov').classList.remove('on');
  if(antFrame){cancelAnimationFrame(antFrame);antFrame=null;}
  document.getElementById('antah-panel').classList.remove('open');
}

function initAntah(){
  antCanvas=document.getElementById('antah-canvas');
  if(!antCanvas)return;
  const dpr=window.devicePixelRatio||1,W=window.innerWidth,H=window.innerHeight;
  antCanvas.style.position='fixed';antCanvas.style.top='0';antCanvas.style.left='0';
  antCanvas.style.width=W+'px';antCanvas.style.height=H+'px';
  antCanvas.width=W*dpr;antCanvas.height=H*dpr;
  antCtx=antCanvas.getContext('2d');antCtx.scale(dpr,dpr);
  const cx=W/2,cy=H/2+20,R=Math.min(W,H)*0.3;
  antNodes=ANTAH_DATA.map(n=>({...n,px:cx+Math.cos(n.angle)*R,py:cy+Math.sin(n.angle)*R,r:Math.min(W,H)*0.09}));
  antCanvas.onclick=antClick;antCanvas.onmousemove=antHover;
  antCanvas.ontouchend=e=>{e.preventDefault();const t=e.changedTouches[0];antClick({clientX:t.clientX,clientY:t.clientY});};
  if(antFrame)cancelAnimationFrame(antFrame);
  antFrame=requestAnimationFrame(drawAntah);
}

function drawAntah(){
  if(!antCtx){antFrame=null;return;}antT+=0.008;
  const W=antCanvas.clientWidth,H=antCanvas.clientHeight;
  const ctx=antCtx;ctx.clearRect(0,0,W,H);
  const bg=ctx.createRadialGradient(W/2,H/2,0,W/2,H/2,Math.max(W,H));
  bg.addColorStop(0,'rgba(4,5,12,1)');bg.addColorStop(1,'rgba(1,2,5,1)');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);

  const cx=W/2,cy=H/2+20,R=Math.min(W,H)*0.3;

  // Rotating mandala rings
  for(let ring=0;ring<3;ring++){
    const rr=R*(0.5+ring*0.22)+Math.sin(antT*(0.3+ring*0.1))*8;
    ctx.beginPath();ctx.arc(cx,cy,rr,0,Math.PI*2);
    ctx.strokeStyle=`rgba(100,130,220,${0.04+ring*0.02})`;ctx.lineWidth=1;ctx.stroke();
  }

  // Cross connections between all 4 faculties
  for(let i=0;i<antNodes.length;i++){
    for(let j=i+1;j<antNodes.length;j++){
      const a=antNodes[i],b=antNodes[j];
      ctx.beginPath();ctx.moveTo(a.px,a.py);ctx.lineTo(b.px,b.py);
      ctx.strokeStyle='rgba(100,130,220,.06)';ctx.lineWidth=1;ctx.stroke();
    }
  }

  // Center Atman symbol
  const centerR=R*0.18;
  const cg=ctx.createRadialGradient(cx,cy,0,cx,cy,centerR);
  cg.addColorStop(0,'rgba(255,240,180,.15)');cg.addColorStop(1,'transparent');
  ctx.fillStyle=cg;ctx.beginPath();ctx.arc(cx,cy,centerR,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='rgba(240,220,160,.35)';
  ctx.font=`${Math.floor(centerR)}px serif`;ctx.textAlign='center';ctx.textBaseline='middle';
  ctx.fillText('ॐ',cx,cy);

  // Orbital particles
  for(let p=0;p<12;p++){
    const pa=(p/12)*Math.PI*2+antT*0.4;
    const pr=R*0.55;
    const px=cx+Math.cos(pa)*pr,py=cy+Math.sin(pa)*pr;
    ctx.beginPath();ctx.arc(px,py,1.5,0,Math.PI*2);
    ctx.fillStyle=`rgba(140,170,240,${0.12+0.08*Math.sin(antT*3+p)})`;ctx.fill();
  }

  // Nodes
  antNodes.forEach(n=>{
    const sel=antSel&&antSel.id===n.id;
    const r=n.r+(sel?8:0);
    if(sel){
      const g=ctx.createRadialGradient(n.px,n.py,0,n.px,n.py,r*2);
      g.addColorStop(0,n.col+'25');g.addColorStop(1,'transparent');
      ctx.fillStyle=g;ctx.beginPath();ctx.arc(n.px,n.py,r*2,0,Math.PI*2);ctx.fill();
    }
    ctx.beginPath();ctx.arc(n.px,n.py,r,0,Math.PI*2);
    ctx.fillStyle='rgba(3,4,10,.92)';ctx.fill();
    ctx.strokeStyle=sel?n.col:n.col+'66';ctx.lineWidth=sel?2.5:1.5;ctx.stroke();
    ctx.beginPath();ctx.arc(n.px,n.py,r*0.3,0,Math.PI*2);
    ctx.fillStyle=n.col+(sel?'ff':'aa');ctx.fill();
    ctx.fillStyle=sel?'rgba(220,230,255,.9)':n.col+'cc';
    ctx.font=`bold ${Math.floor(r*0.38)}px 'Cinzel'`;
    ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.fillText(n.label.toUpperCase(),n.px,n.py);
    ctx.font=`${Math.floor(r*0.28)}px 'IBM Plex Mono'`;
    ctx.fillStyle=n.col+'88';ctx.textBaseline='top';
    ctx.fillText(n.skt,n.px,n.py+r+4);
  });

  ctx.fillStyle='rgba(130,160,240,.12)';
  ctx.font='bold 9px "IBM Plex Mono"';ctx.textAlign='left';ctx.textBaseline='top';
  ctx.fillText('ANTAHKARANA · THE INNER INSTRUMENT · FOUR FACULTIES OF MIND',14,58);
  antFrame=requestAnimationFrame(drawAntah);
}

function antClick(e){
  const r=antCanvas.getBoundingClientRect();const mx=e.clientX-r.left,my=e.clientY-r.top;
  let hit=null;antNodes.forEach(n=>{if(Math.hypot(mx-n.px,my-n.py)<n.r+10)hit=n;});
  antSel=hit;const panel=document.getElementById('antah-panel');
  if(hit){
    panel.innerHTML=`<button style="background:none;border:1px solid rgba(100,140,220,.2);color:rgba(100,140,220,.5);padding:5px 10px;font-family:'IBM Plex Mono',monospace;font-size:7px;letter-spacing:2px;cursor:pointer;text-transform:uppercase;margin-bottom:18px;display:block;" onclick="document.getElementById('antah-panel').classList.remove('open');antSel=null;">✕ close</button>
      <span class="antah-skt">${hit.skt}</span><span style="font-family:'Cinzel',serif;font-size:11px;letter-spacing:3px;color:${hit.col}88;text-transform:uppercase;display:block;margin-bottom:12px;">${hit.label}</span>
      <div style="font-family:'Cormorant Garamond',serif;font-size:15px;font-style:italic;color:${hit.col}99;line-height:1.8;margin-bottom:14px;padding-bottom:12px;border-bottom:1px solid ${hit.col}22;">${hit.essence}</div>
      <div class="antah-body">${hit.body}</div>`;
    panel.classList.add('open');
  }else panel.classList.remove('open');
}
function antHover(e){const r=antCanvas.getBoundingClientRect();const mx=e.clientX-r.left,my=e.clientY-r.top;antNodes.forEach(n=>{n.hov=Math.hypot(mx-n.px,my-n.py)<n.r+10;});antCanvas.style.cursor=antNodes.some(n=>n.hov)?'pointer':'default';}

// ═══════════════════════════════════════════════════════════════════
//  TANMATRAS — Five Subtle Elements
// ═══════════════════════════════════════════════════════════════════
const TANM_DATA=[
  {id:'shabda',label:'Shabda',skt:'शब्द',roman:'Sound-Essence',col:'#80c8ff',element:'Akasha (Space)',freq:1.0,
   essence:'The pure quality of sound — the vibration of awareness itself before any physical wave exists.',
   body:'Shabda is not sound waves in air — it is the <em>pure experiential quality of soundness</em>. The Nada tradition: Para (transcendent sound) → Pashyanti (visionary) → Madhyama (mental) → Vaikhari (spoken). Shabda Tanmantra corresponds to all four levels. <strong>OM is Shabda Tanmantra in its most compressed form</strong> — the universe\'s self-announcement.'},
  {id:'sparsha',label:'Sparsha',skt:'स्पर्श',roman:'Touch-Essence',col:'#a0e0c0',element:'Vayu (Air)',freq:0.8,
   essence:'The pure quality of contact — the felt sense of meeting, boundary, and presence before any physical touch.',
   body:'Before wind exists, there is the <em>quality of touchability</em> — the felt sense of being met, of boundaries, of warmth and cold as pure experience. <strong>Every meditation on the breath is a Sparsha Tanmantra practice</strong> — feeling the subtlest sensations of air meeting the nostril, the subtle boundary between self and world.'},
  {id:'rupa',label:'Rupa',skt:'रूप',roman:'Form-Essence',col:'#ffd080',element:'Agni (Fire)',freq:0.6,
   essence:'The pure quality of form and visibility — luminosity, color, and beauty as fundamental properties of consciousness.',
   body:'Rupa is what makes fire <em>fire</em> — not its chemistry but its luminous quality. The tradition: true beauty (Sundaram) is Rupa Tanmantra perceived without the filter of ego-preference. <strong>The Shaiva teaching</strong>: consciousness is self-luminous (Prakasha) — every light in the world is this self-luminosity appearing through Rupa Tanmantra. Aesthetics is Rupa-perception refined.'},
  {id:'rasa',label:'Rasa',skt:'रस',roman:'Taste-Essence',col:'#c0e870',element:'Apas (Water)',freq:0.4,
   essence:'The pure quality of taste — the felt sense of nourishment, sweetness, and the six flavors as modes of consciousness.',
   body:'Rasa has the richest semantic field in Sanskrit: taste, juice, sap, essence, emotion, aesthetic experience, and the nine Rasas of classical art (Shringara, Vira, Karuna...). <strong>The nine aesthetic Rasas are Rasa Tanmantra operating through human emotion and art</strong> — the same faculty that knows sweetness in honey knows beauty in music.'},
  {id:'gandha',label:'Gandha',skt:'गन्ध',roman:'Smell-Essence',col:'#e0c0a0',element:'Prithvi (Earth)',freq:0.2,
   essence:'The pure quality of earthiness — the most primordial subtle element, from which the gross earth element condenses.',
   body:'Smell connects most directly to memory because Gandha Tanmantra carries the most information about the material substrate of reality. <em>The earth after rain (Petrichor) is Gandha Tanmantra made maximally perceptible.</em> <strong>Prithvi (earth element) is the crystallized form of Gandha</strong> — every grain of sand is concentrated smell-quality that has become fixed. The ground you stand on is solidified Tanmantra.'},
];

let tanmCanvas=null,tanmCtx=null,tanmFrame=null,tanmT=0,tanmSel=null,tanmNodes=[];

function openTanm(){
  document.getElementById('tanm-ov').classList.add('on');
  setTimeout(initTanm,window.innerWidth<=768?200:60);
}
function closeTanm(){
  document.getElementById('tanm-ov').classList.remove('on');
  if(tanmFrame){cancelAnimationFrame(tanmFrame);tanmFrame=null;}
  document.getElementById('tanm-panel').classList.remove('open');
}

function initTanm(){
  tanmCanvas=document.getElementById('tanm-canvas');
  if(!tanmCanvas)return;
  const dpr=window.devicePixelRatio||1,W=window.innerWidth,H=window.innerHeight;
  tanmCanvas.style.position='fixed';tanmCanvas.style.top='0';tanmCanvas.style.left='0';
  tanmCanvas.style.width=W+'px';tanmCanvas.style.height=H+'px';
  tanmCanvas.width=W*dpr;tanmCanvas.height=H*dpr;
  tanmCtx=tanmCanvas.getContext('2d');tanmCtx.scale(dpr,dpr);
  const cx=W/2,cy=H/2+10;
  const R=Math.min(W,H)*0.32;
  tanmNodes=TANM_DATA.map((n,i)=>{
    const a=(i/TANM_DATA.length)*Math.PI*2-Math.PI/2;
    return{...n,px:cx+Math.cos(a)*R,py:cy+Math.sin(a)*R,r:Math.min(W,H)*0.08,angle:a};
  });
  tanmCanvas.onclick=tanmClick;tanmCanvas.onmousemove=tanmHover;
  tanmCanvas.ontouchend=e=>{e.preventDefault();const t=e.changedTouches[0];tanmClick({clientX:t.clientX,clientY:t.clientY});};
  if(tanmFrame)cancelAnimationFrame(tanmFrame);
  tanmFrame=requestAnimationFrame(drawTanm);
}

function drawTanm(){
  if(!tanmCtx){tanmFrame=null;return;}tanmT+=0.007;
  const W=tanmCanvas.clientWidth,H=tanmCanvas.clientHeight;
  const ctx=tanmCtx;ctx.clearRect(0,0,W,H);
  const bg=ctx.createRadialGradient(W/2,H/2,0,W/2,H/2,Math.max(W,H));
  bg.addColorStop(0,'rgba(2,5,10,1)');bg.addColorStop(1,'rgba(0,1,3,1)');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  const cx=W/2,cy=H/2+10;

  // Wave interference pattern — efficient ImageData version
  const step=8; // coarser grid = faster
  const iw=Math.ceil(W/step),ih=Math.ceil((H-54)/step);
  const imgData=ctx.createImageData(W,H);
  const d=imgData.data;
  for(let xi=0;xi<iw;xi++){
    for(let yi=0;yi<ih;yi++){
      const px=xi*step,py=54+yi*step;
      let v=0;
      for(let ni=0;ni<tanmNodes.length;ni++){
        const n=tanmNodes[ni];
        const dx=px-n.px,dy=py-n.py;
        const dist=Math.sqrt(dx*dx+dy*dy);
        v+=Math.sin(dist*0.035-tanmT*(0.8+n.freq)*1.2)*0.5;
      }
      const a=Math.max(0,(v+0.6)*0.018);
      if(a>0.005){
        const alpha=Math.min(255,Math.floor(a*255));
        // Fill a step×step block
        for(let bx=0;bx<step&&px+bx<W;bx++){
          for(let by=0;by<step&&py+by<H;by++){
            const idx=((py+by)*W+(px+bx))*4;
            d[idx]=60;d[idx+1]=180;d[idx+2]=220;
            d[idx+3]=Math.max(d[idx+3],alpha);
          }
        }
      }
    }
  }
  ctx.putImageData(imgData,0,0);

  // Pentagon connecting all 5
  ctx.beginPath();
  tanmNodes.forEach((n,i)=>{i===0?ctx.moveTo(n.px,n.py):ctx.lineTo(n.px,n.py);});
  ctx.closePath();
  ctx.strokeStyle='rgba(100,200,220,.1)';ctx.lineWidth=1;ctx.stroke();

  // Cascade lines from Brahman center downward
  const R=Math.min(W,H)*0.32;
  tanmNodes.forEach(n=>{
    ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(n.px,n.py);
    ctx.strokeStyle=n.col+'18';ctx.lineWidth=1;ctx.stroke();
  });

  // Center — Prakriti
  ctx.beginPath();ctx.arc(cx,cy,R*0.15,0,Math.PI*2);
  ctx.fillStyle='rgba(100,160,200,.06)';ctx.fill();
  ctx.strokeStyle='rgba(100,160,200,.15)';ctx.lineWidth=1;ctx.stroke();
  ctx.fillStyle='rgba(160,210,240,.25)';
  ctx.font='8px "IBM Plex Mono"';ctx.textAlign='center';ctx.textBaseline='middle';
  ctx.fillText('PRAKRITI',cx,cy);

  // Nodes
  tanmNodes.forEach(n=>{
    const sel=tanmSel&&tanmSel.id===n.id;
    const r=n.r+(sel?8:0);
    // Wave rings
    for(let ring=0;ring<3;ring++){
      const rr=(tanmT*60*(1-ring*0.3))%120;
      const ra=Math.max(0,1-rr/120)*(0.25-ring*0.07);
      ctx.beginPath();ctx.arc(n.px,n.py,r+rr*0.5,0,Math.PI*2);
      ctx.strokeStyle=n.col+Math.round(ra*255).toString(16).padStart(2,'0');ctx.lineWidth=1;ctx.stroke();
    }
    if(sel){
      const g=ctx.createRadialGradient(n.px,n.py,0,n.px,n.py,r*2.2);
      g.addColorStop(0,n.col+'22');g.addColorStop(1,'transparent');
      ctx.fillStyle=g;ctx.beginPath();ctx.arc(n.px,n.py,r*2.2,0,Math.PI*2);ctx.fill();
    }
    ctx.beginPath();ctx.arc(n.px,n.py,r,0,Math.PI*2);
    ctx.fillStyle='rgba(1,3,8,.92)';ctx.fill();
    ctx.strokeStyle=sel?n.col:n.col+'77';ctx.lineWidth=sel?2.5:1.5;ctx.stroke();
    ctx.beginPath();ctx.arc(n.px,n.py,r*0.28,0,Math.PI*2);ctx.fillStyle=n.col+(sel?'ff':'aa');ctx.fill();
    ctx.fillStyle=sel?'rgba(220,240,255,.9)':n.col+'cc';
    ctx.font=`bold ${Math.floor(r*0.36)}px 'Cinzel'`;ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.fillText(n.label.toUpperCase(),n.px,n.py);
    ctx.fillStyle=n.col+'88';
    ctx.font=`${Math.floor(r*0.26)}px 'IBM Plex Mono'`;ctx.textBaseline='top';
    ctx.fillText(n.element.toUpperCase(),n.px,n.py+r+4);
  });

  ctx.fillStyle='rgba(100,200,230,.12)';
  ctx.font='bold 9px "IBM Plex Mono"';ctx.textAlign='left';ctx.textBaseline='top';
  ctx.fillText('TANMATRAS · FIVE SUBTLE ELEMENTS · THE SEEDS OF SENSATION',14,58);
  tanmFrame=requestAnimationFrame(drawTanm);
}

function tanmClick(e){
  const r=tanmCanvas.getBoundingClientRect();const mx=e.clientX-r.left,my=e.clientY-r.top;
  let hit=null;tanmNodes.forEach(n=>{if(Math.hypot(mx-n.px,my-n.py)<n.r+10)hit=n;});
  tanmSel=hit;const panel=document.getElementById('tanm-panel');
  if(hit){
    panel.innerHTML=`<button style="background:none;border:1px solid ${hit.col}44;color:${hit.col}88;padding:5px 10px;font-family:'IBM Plex Mono',monospace;font-size:7px;letter-spacing:2px;cursor:pointer;text-transform:uppercase;margin-bottom:18px;display:block;" onclick="document.getElementById('tanm-panel').classList.remove('open');tanmSel=null;">✕ close</button>
      <span class="tanm-skt">${hit.skt}</span>
      <span style="font-family:'Cinzel',serif;font-size:11px;letter-spacing:3px;color:${hit.col}88;text-transform:uppercase;display:block;margin-bottom:4px;">${hit.roman}</span>
      <span style="font-family:'IBM Plex Mono',monospace;font-size:7px;letter-spacing:2px;color:${hit.col}55;text-transform:uppercase;display:block;margin-bottom:14px;">→ ${hit.element}</span>
      <div style="font-family:'Cormorant Garamond',serif;font-size:15px;font-style:italic;color:${hit.col}88;line-height:1.8;margin-bottom:14px;padding-bottom:12px;border-bottom:1px solid ${hit.col}22;">${hit.essence}</div>
      <div class="tanm-body">${hit.body}</div>`;
    panel.classList.add('open');
  }else panel.classList.remove('open');
}
function tanmHover(e){const r=tanmCanvas.getBoundingClientRect();const mx=e.clientX-r.left,my=e.clientY-r.top;tanmNodes.forEach(n=>{n.hov=Math.hypot(mx-n.px,my-n.py)<n.r+10;});tanmCanvas.style.cursor=tanmNodes.some(n=>n.hov)?'pointer':'default';}


