// ── Fix 9: More Tray ─────────────────────────────────
// ══════════════════════════════════════════════
//  MARGA NAV — Four Sacred Paths navigation
// ══════════════════════════════════════════════
const MARGAS=['antaryatra','brahmanda','parampara','sadhana'];
let _activeMarga=null;

function toggleMarga(name){
  if(_activeMarga===name){
    closeMarga();return;
  }
  closeMarga(false);
  _activeMarga=name;
  const drop=document.getElementById('marga-'+name);
  const btn=document.getElementById('marga-'+name+'-btn');
  if(drop)drop.classList.add('open');
  if(btn)btn.classList.add('open');
  // Position dropdown beside its button
  if(drop&&btn){
    const r=btn.getBoundingClientRect();
    const tb=document.getElementById('toolbar');
    if(window.innerWidth<=768){
      // Mobile: open upward, centered
      drop.style.left='50%';
      drop.style.right='auto';
      drop.style.top='auto';
      drop.style.bottom='56px';
      drop.style.transform='translateX(-50%)';
    } else {
      // Desktop: open horizontally toward center
      // Clamp top so dropdown never goes below viewport
      drop.style.visibility='hidden';drop.style.display='block';
      const dh=drop.offsetHeight||360;
      drop.style.display='';drop.style.visibility='';
      const margin=12;
      const maxTop=window.innerHeight - dh - margin;
      const topPos=Math.min(Math.max(margin, r.top), maxTop);
      drop.style.top=topPos+'px';
      drop.style.bottom='auto';
      drop.style.transform='translateX(0)';
      if(tb&&tb.classList.contains('toolbar-right')){
        drop.style.right=(window.innerWidth - r.left + 6)+'px';
        drop.style.left='auto';
      } else {
        drop.style.left=(r.right + 6)+'px';
        drop.style.right='auto';
      }
    }
  }
  // Close when clicking outside
  setTimeout(()=>{
    document.addEventListener('click',_margaOutsideClick,{once:true});
  },10);
}

function _margaOutsideClick(e){
  const openDrop=document.querySelector('.marga-drop.open');
  const openBtn=document.querySelector('.marga-btn.open');
  if(openDrop&&!openDrop.contains(e.target)&&openBtn&&!openBtn.contains(e.target)){
    closeMarga();
  } else if(openDrop&&!openDrop.contains(e.target)&&!e.target.closest('.marga-btn')){
    closeMarga();
  }
}

function closeMarga(resetActive=true){
  MARGAS.forEach(n=>{
    const d=document.getElementById('marga-'+n);
    const b=document.getElementById('marga-'+n+'-btn');
    if(d)d.classList.remove('open');
    if(b)b.classList.remove('open');
  });
  if(resetActive)_activeMarga=null;
}

// Legacy aliases — some old onclick handlers still call these
function closeMoreTray(){closeMarga();}
function toggleMoreTray(){toggleMarga('sadhana');}


function savePosition(idx){
  try{ history.replaceState(null,'','#era-'+idx); }catch(e){}
}
function restorePosition(){
  try{
    const hash=location.hash;
    if(hash&&hash.startsWith('#era-')){
      const idx=parseInt(hash.replace('#era-',''));
      if(!isNaN(idx)&&idx>=0&&idx<ERAS.length) return idx;
    }
  }catch(e){}
  return 0;
}

