// Convert hover-only tooltips to also work on touch
document.addEventListener('touchstart',e=>{
  const tag=e.target.closest('.e-tag');
  if(tag){
    e.preventDefault();
    const evt=new MouseEvent('mouseenter',{bubbles:true});
    tag.dispatchEvent(evt);
    setTimeout(()=>{
      const tevt=new MouseEvent('mouseleave',{bubbles:true});
      tag.dispatchEvent(tevt);
    },2500);
  }
},{passive:false});

