// ═══════════════════════════════════════════════════════════════════
//  HOSTING RESILIENCE — defensive click delegation
// ═══════════════════════════════════════════════════════════════════
(function(){
  document.addEventListener('click', function(ev){
    var target = ev.target;
    var btn = target && target.closest ? target.closest('[onclick]') : null;
    if (!btn) return;
    var oc = btn.getAttribute('onclick') || '';
    var m = oc.match(/\b(open[A-Z]\w*Exp|openAboutToUpdates)\s*\(/);
    if (!m) return;
    var fnName = m[1];
    if (typeof window[fnName] === 'function') return;
    ev.preventDefault();
    ev.stopPropagation();
    console.warn('[LST] '+fnName+' not yet defined \u2014 retrying for 3s\u2026');
    var tries = 0;
    var iv = setInterval(function(){
      tries++;
      if (typeof window[fnName] === 'function') {
        clearInterval(iv);
        try { window[fnName](); } catch(e){ console.error(fnName+' threw:',e); }
        return;
      }
      if (tries > 30) {
        clearInterval(iv);
        console.error('[LST] '+fnName+' never appeared. script.js may be truncated.');
      }
    },100);
  }, true);
})();


