// ── Network ────────────────────────────────────────
function buildKmapNetwork(){
  const nodes=[];const links=[];const nodeMap={};
  KMAP_DOMAINS.forEach(d=>{
    const n={id:'d_'+d.id,type:'domain',label:d.name,color:d.color,desc:d.desc,size:22,px:0,py:0,vx:0,vy:0};
    nodes.push(n);nodeMap[n.id]=n;
  });
  KMAP_SCHOLARS.forEach((s,i)=>{
    const dom=KMAP_DOMAINS.find(d=>d.id===s.domain);
    const n={id:'s_'+i,type:'scholar',label:s.name,color:dom?dom.color:'#c9a84c',desc:s.contrib,size:13,px:0,py:0,vx:0,vy:0};
    nodes.push(n);nodeMap[n.id]=n;
    links.push({src:'s_'+i,dst:'d_'+s.domain,strength:.45});
  });
  KMAP_TEXTS.forEach((t,i)=>{
    const dom=KMAP_DOMAINS.find(d=>d.id===t.domain);
    const n={id:'t_'+i,type:'text',label:t.name,color:dom?dom.color:'#c9a84c',desc:t.desc,size:9,px:0,py:0,vx:0,vy:0};
    nodes.push(n);nodeMap[n.id]=n;
    links.push({src:'t_'+i,dst:'d_'+t.domain,strength:.3});
    KMAP_SCHOLARS.forEach((s,si)=>{
      if(s.texts&&s.texts.some(tx=>t.name.split(' ').some(w=>w.length>3&&tx.includes(w)))){
        links.push({src:'s_'+si,dst:'t_'+i,strength:.55});
      }
    });
  });
  return{nodes,links,nodeMap};
}

// ── Open / Close ──────────────────────────────────
function openKnowledgeMap(){
  document.getElementById('kmap-ov').classList.add('on');
  setTimeout(initKmap,100);
}
function closeKnowledgeMap(){
  document.getElementById('kmap-ov').classList.remove('on');
  if(kmapNetFrame){cancelAnimationFrame(kmapNetFrame);kmapNetFrame=null;}
}

// ── State ─────────────────────────────────────────
let kmapActiveDomain='all';
let kmapNetFrame=null,kmapNetData=null;
let kmapNetCanvas=null,kmapNetCtx=null;
let kmapNetDragNode=null,kmapNetMx=0,kmapNetMy=0;
let kmapNetHov=null,kmapNetFilter='all';
let kmapInitDone=false;

// ── Init ──────────────────────────────────────────
function initKmap(){
  if(kmapInitDone)return;
  kmapInitDone=true;
  renderKmapDomains();
  renderKmapFilter();
  renderKmapScholars('all');
  renderKmapTexts();
  renderKmapTimeline();
  initKmapNetwork();
}

// ── Domains ───────────────────────────────────────
function renderKmapDomains(){
  const el=document.getElementById('kmap-domains');
  if(!el||el.children.length>0)return;
  el.innerHTML=KMAP_DOMAINS.map(d=>{
    const count=KMAP_SCHOLARS.filter(s=>s.domain===d.id).length;
    return `<div class="kmap-domain" style="--dc:${d.color}" onclick="filterKmapDomain('${d.id}',this)" data-domain="${d.id}">
      <span class="kmap-d-icon">${d.icon}</span>
      <div class="kmap-d-name">${d.name}</div>
      <div class="kmap-d-count">${count} scholar${count!==1?'s':''}</div>
    </div>`;
  }).join('');
}
function filterKmapDomain(id,el){
  kmapActiveDomain=kmapActiveDomain===id?'all':id;
  document.querySelectorAll('.kmap-domain').forEach(d=>d.classList.toggle('active',d.dataset.domain===kmapActiveDomain));
  document.querySelectorAll('.kmap-fbtn').forEach(b=>b.classList.toggle('active',b.dataset.domain===kmapActiveDomain||(kmapActiveDomain==='all'&&b.dataset.domain==='all')));
  renderKmapScholars(kmapActiveDomain);
}

// ── Scholar filter ────────────────────────────────
function renderKmapFilter(){
  const el=document.getElementById('kmap-filter');
  if(!el||el.children.length>0)return;
  const all=document.createElement('button');
  all.className='kmap-fbtn active';all.textContent='All Domains';all.dataset.domain='all';
  all.onclick=()=>filterKmapDomain('all',null);
  el.appendChild(all);
  KMAP_DOMAINS.forEach(d=>{
    const btn=document.createElement('button');
    btn.className='kmap-fbtn';btn.textContent=d.name;btn.dataset.domain=d.id;
    btn.onclick=function(){
      filterKmapDomain(d.id,null);
      document.querySelectorAll('.kmap-fbtn').forEach(b=>b.classList.remove('active'));
      this.classList.add('active');
    };
    el.appendChild(btn);
  });
}

// ── Scholars ──────────────────────────────────────
function renderKmapScholars(domain){
  const el=document.getElementById('kmap-scholars');if(!el)return;
  const list=domain==='all'?KMAP_SCHOLARS:KMAP_SCHOLARS.filter(s=>s.domain===domain);
  el.innerHTML=list.map(s=>{
    const i=KMAP_SCHOLARS.indexOf(s);
    const dom=KMAP_DOMAINS.find(d=>d.id===s.domain);
    const col=dom?dom.color:'#c9a84c';
    return `<div class="kmap-scholar" id="kscl-${i}" style="--sc:${col}">
      <div class="kmap-s-head" onclick="toggleKmapScholar(${i})">
        <span class="kmap-s-era">${s.era}</span>
        <div class="kmap-s-info">
          <div class="kmap-s-name">${s.name}</div>
          <span class="kmap-s-badge" style="color:${col};border-color:${col}55">${s.badge}</span>
        </div>
        <span class="kmap-s-toggle" id="kst-${i}">+ expand</span>
      </div>
      <div class="kmap-s-contrib">${s.contrib}</div>
      <div class="kmap-s-body" id="ksb-${i}">
        ${s.quote?`<div class="kmap-s-quote"><div class="kmap-s-quote-text">"${s.quote.text}"</div><div class="kmap-s-quote-src">${s.quote.src}</div></div>`:''}
        <div class="kmap-s-tabs" id="kstabs-${i}">
          <button class="kmap-s-tab active" onclick="switchKmapTab(${i},'disc',this)">Discoveries</button>
          <button class="kmap-s-tab" onclick="switchKmapTab(${i},'inf',this)">Influence</button>
          <button class="kmap-s-tab" onclick="switchKmapTab(${i},'sci',this)">Science Parallel</button>
          <button class="kmap-s-tab" onclick="switchKmapTab(${i},'texts',this)">Texts</button>
        </div>
        <div id="ksp-disc-${i}" class="kmap-s-panel active">
          <div class="kmap-s-discoveries">${(s.discoveries||[]).map(d=>`
            <div class="kmap-s-disc">
              <div class="kmap-s-disc-title">${d.title}</div>
              <div class="kmap-s-disc-desc">${d.desc}</div>
              <div class="kmap-s-disc-ref">📖 ${d.ref}</div>
            </div>`).join('')}</div>
        </div>
        <div id="ksp-inf-${i}" class="kmap-s-panel" style="padding-top:12px;">
          <div class="kmap-s-val">${s.influence||''}</div>
        </div>
        <div id="ksp-sci-${i}" class="kmap-s-panel">
          <div class="kmap-s-science-box"><div class="kmap-s-sci-lbl">Modern Science Parallel</div><div class="kmap-s-sci-text">${s.science||''}</div></div>
        </div>
        <div id="ksp-texts-${i}" class="kmap-s-panel" style="padding-top:12px;">
          <div class="kmap-s-texts">${(s.texts||[]).map(t=>`<span class="kmap-s-tag">${t}</span>`).join('')}</div>
        </div>
      </div>
    </div>`;
  }).join('');
}
function toggleKmapScholar(i){
  const body=document.getElementById('ksb-'+i);
  const tog=document.getElementById('kst-'+i);
  const card=document.getElementById('kscl-'+i);
  if(!body)return;
  const open=body.classList.toggle('open');
  if(card)card.classList.toggle('open-card',open);
  if(tog)tog.textContent=open?'− collapse':'+ expand';
}
function switchKmapTab(i,tab,btn){
  ['disc','inf','sci','texts'].forEach(t=>{
    const p=document.getElementById('ksp-'+t+'-'+i);
    if(p)p.classList.toggle('active',t===tab);
  });
  const tabs=document.getElementById('kstabs-'+i);
  if(tabs)tabs.querySelectorAll('.kmap-s-tab').forEach(b=>b.classList.remove('active'));
  if(btn)btn.classList.add('active');
}

// ── Texts ─────────────────────────────────────────
function renderKmapTexts(){
  const el=document.getElementById('kmap-texts');if(!el||el.children.length>0)return;
  el.innerHTML=KMAP_TEXTS.map((t,i)=>{
    const dom=KMAP_DOMAINS.find(d=>d.id===t.domain);
    const col=dom?dom.color:'#c9a84c';
    return `<div class="kmap-text" onclick="toggleKmapText(${i})" id="ktxt-${i}">
      <div class="kmap-text-head">
        <span class="kmap-text-glyph">${t.glyph}</span>
        <div class="kmap-text-name">${t.name}</div>
        <div class="kmap-text-author">by ${t.author}</div>
        <div class="kmap-text-year">✦ ${t.authorYear}</div>
        <span class="kmap-text-badge" style="color:${col};border-color:${col}44">${dom?dom.name:t.domain}</span>
      </div>
      <div class="kmap-text-desc">${t.desc}</div>
      <div class="kmap-text-expand-hint"><span>Click to dive deeper</span><span>→</span></div>
      <div class="kmap-text-body" id="ktb-${i}">
        ${t.structure?`<div class="kmap-text-section"><div class="kmap-text-sec-lbl">Structure</div><div class="kmap-text-sec-body">${t.structure}</div></div>`:''}
        ${t.keyVerse?`<div class="kmap-text-verse"><div class="kmap-text-verse-skt">${t.keyVerse.skt}</div><div class="kmap-text-verse-trans">${t.keyVerse.trans}</div><div class="kmap-text-verse-ref">📖 ${t.keyVerse.ref}</div></div>`:''}
        ${t.impact?`<div class="kmap-text-section"><div class="kmap-text-sec-lbl">Impact & Transmission</div><div class="kmap-text-sec-body">${t.impact}</div></div>`:''}
        ${t.chapters&&t.chapters.length?`<div class="kmap-text-section"><div class="kmap-text-sec-lbl">Key Sections</div><div class="kmap-text-chapters">${t.chapters.map(c=>`<span class="kmap-text-chapter">${c}</span>`).join('')}</div></div>`:''}
        ${t.translations?`<div class="kmap-text-section"><div class="kmap-text-sec-lbl">Modern Translations</div><div class="kmap-text-sec-body" style="font-size:11.5px;color:var(--tdim)">${t.translations}</div></div>`:''}
      </div>
    </div>`;
  }).join('');
}
function toggleKmapText(i){
  const b=document.getElementById('ktb-'+i);
  const card=document.getElementById('ktxt-'+i);
  if(!b)return;
  const open=b.classList.toggle('open');
  const hint=card&&card.querySelector('.kmap-text-expand-hint span');
  if(hint)hint.textContent=open?'Click to collapse':'Click to dive deeper';
}

// ── Mini Timeline ─────────────────────────────────
function renderKmapTimeline(){
  const inner=document.getElementById('kmap-tl-inner');
  if(!inner||inner.querySelectorAll('.kmap-tl-node').length>0)return;
  const periods=[
    {label:'Vedic Era (~1500–500 BCE)',start:2,end:36,color:'rgba(201,168,76,.08)',bc:'rgba(201,168,76,.2)'},
    {label:'Classical (~500 BCE–600 CE)',start:36,end:72,color:'rgba(80,180,200,.07)',bc:'rgba(80,180,200,.2)'},
    {label:'Medieval (600–1500 CE)',start:72,end:95,color:'rgba(160,130,220,.07)',bc:'rgba(160,130,220,.2)'},
  ];
  const nodes=[
    {label:'Lagadha',pct:3,major:true,color:'#6090c8'},
    {label:'Yajnavalkya',pct:9,major:true,color:'#b080d0'},
    {label:'Baudhayana',pct:12,major:true,color:'#c9a84c'},
    {label:'Kapila',pct:13,major:true,color:'#b080d0'},
    {label:'Kanada',pct:18,major:false,color:'#e08860'},
    {label:'Pāṇini',pct:22,major:true,color:'#c06090'},
    {label:'Pingala',pct:26,major:true,color:'#c9a84c'},
    {label:'Charaka',pct:30,major:true,color:'#70c890'},
    {label:'Sushruta',pct:28,major:true,color:'#70c890'},
    {label:'Patanjali',pct:34,major:true,color:'#80b8c0'},
    {label:'Bharata Muni',pct:42,major:false,color:'#d4a040'},
    {label:'Nagarjuna',pct:50,major:false,color:'#a0a880'},
    {label:'Aryabhata',pct:58,major:true,color:'#6090c8'},
    {label:'Varahamihira',pct:61,major:false,color:'#6090c8'},
    {label:'Brahmagupta',pct:65,major:true,color:'#c9a84c'},
    {label:'Vagbhata',pct:63,major:false,color:'#70c890'},
    {label:'Shankara',pct:72,major:true,color:'#b080d0'},
    {label:'Mahaviracharya',pct:78,major:false,color:'#c9a84c'},
    {label:'Bhaskaracharya',pct:84,major:true,color:'#c9a84c'},
    {label:'Madhava',pct:93,major:true,color:'#c9a84c'},
  ];
  periods.forEach(p=>{
    const band=document.createElement('div');
    band.className='kmap-period';
    band.style.cssText=`left:calc(${p.start}% + 60px);width:calc(${p.end-p.start}%);border-color:${p.bc};background:${p.color};`;
    const lbl=document.createElement('div');
    lbl.style.cssText='position:absolute;bottom:-22px;left:50%;transform:translateX(-50%);font-family:IBM Plex Mono,monospace;font-size:5.5px;letter-spacing:1.5px;color:rgba(201,168,76,.3);text-transform:uppercase;white-space:nowrap;';
    lbl.textContent=p.label;
    band.appendChild(lbl);
    inner.appendChild(band);
  });
  // Stagger nodes vertically to avoid overlap
  const sortedNodes=[...nodes].sort((a,b)=>a.pct-b.pct);
  sortedNodes.forEach((n,i)=>{
    const node=document.createElement('div');
    node.className='kmap-tl-node';
    const offset=i%2===0?0:28;
    node.style.cssText=`left:calc(${n.pct}% + 60px);top:${offset}px;`;
    node.innerHTML=`<div class="kmap-tl-lbl" style="color:${n.color}aa">${n.label}</div>
      <div class="kmap-tl-dot${n.major?' major':''}" style="border-color:${n.color};${n.major?'background:'+n.color+'33':''};${n.major?'box-shadow:0 0 8px '+n.color+'44':''};"></div>`;
    inner.appendChild(node);
  });
}

// ── Network canvas ────────────────────────────────
function initKmapNetwork(){
  kmapNetCanvas=document.getElementById('kmap-net');if(!kmapNetCanvas)return;
  const wrap=document.getElementById('kmap-net-wrap');
  kmapNetCtx=kmapNetCanvas.getContext('2d');
  const dpr=window.devicePixelRatio||1;
  const dW=wrap.clientWidth,dH=wrap.clientHeight;
  kmapNetCanvas.width=dW*dpr;kmapNetCanvas.height=dH*dpr;
  kmapNetCanvas.style.width=dW+'px';kmapNetCanvas.style.height=dH+'px';
  kmapNetCtx.scale(dpr,dpr);
  kmapNetData=buildKmapNetwork();
  const W=dW,H=dH,cx=W/2,cy=H/2;
  kmapNetData.nodes.forEach((n,i)=>{
    if(n.type==='domain'){
      const di=KMAP_DOMAINS.findIndex(d=>'d_'+d.id===n.id);
      const a=(di/KMAP_DOMAINS.length)*Math.PI*2-Math.PI/2;
      n.px=cx+Math.cos(a)*190;n.py=cy+Math.sin(a)*155;
    }else if(n.type==='scholar'){
      const si=parseInt(n.id.split('_')[1]);
      const dom=KMAP_DOMAINS.find(d=>d.id===KMAP_SCHOLARS[si]?.domain);
      const di=KMAP_DOMAINS.indexOf(dom);
      const a=((di/KMAP_DOMAINS.length)*Math.PI*2-Math.PI/2)+(si%8-4)*0.22;
      n.px=cx+Math.cos(a)*(260+Math.random()*60);
      n.py=cy+Math.sin(a)*(210+Math.random()*50);
    }else{
      const ti=parseInt(n.id.split('_')[1]);
      const dom=KMAP_DOMAINS.find(d=>d.id===KMAP_TEXTS[ti]?.domain);
      const di=KMAP_DOMAINS.indexOf(dom);
      const a=((di/KMAP_DOMAINS.length)*Math.PI*2-Math.PI/2)+((ti%6)-3)*0.28;
      n.px=cx+Math.cos(a)*(320+Math.random()*50);
      n.py=cy+Math.sin(a)*(260+Math.random()*40);
    }
  });
  // Stats
  const stats=document.getElementById('kmap-net-stats');
  if(stats)stats.innerHTML=`${KMAP_SCHOLARS.length} Scholars · ${KMAP_TEXTS.length} Texts · ${KMAP_DOMAINS.length} Domains`;
  // Controls
  const ctrl=document.getElementById('kmap-net-controls');
  if(ctrl&&ctrl.children.length===0){
    [{l:'All',v:'all'},{l:'Scholars',v:'scholar'},{l:'Texts',v:'text'},{l:'Domains',v:'domain'}].forEach(item=>{
      const btn=document.createElement('button');
      btn.className='knc-btn'+(item.v==='all'?' active':'');
      btn.textContent=item.l;
      btn.onclick=function(){
        kmapNetFilter=item.v;
        document.querySelectorAll('.knc-btn').forEach(b=>b.classList.remove('active'));
        this.classList.add('active');
      };
      ctrl.appendChild(btn);
    });
  }
  // Legend
  const leg=document.getElementById('kmap-net-legend');
  if(leg&&leg.children.length===0){
    [{l:'Domain',c:'#c9a84c'},{l:'Scholar',c:'rgba(80,185,205,.9)'},{l:'Text',c:'rgba(160,130,220,.8)'}].forEach(item=>{
      const d=document.createElement('div');d.className='knl-item';
      d.innerHTML=`<div class="knl-dot" style="background:${item.c}"></div>${item.l}`;
      leg.appendChild(d);
    });
  }
  kmapNetCanvas.onmousemove=kmapNetMM;
  kmapNetCanvas.onmousedown=e=>{const r=kmapNetCanvas.getBoundingClientRect();kmapNetDragNode=kmapNetHitTest(e.clientX-r.left,e.clientY-r.top);};
  kmapNetCanvas.onmouseup=()=>kmapNetDragNode=null;
  kmapNetCanvas.onmouseleave=()=>{kmapNetHov=null;document.getElementById('kmap-net-tip').style.opacity='0';};
  if(kmapNetFrame)cancelAnimationFrame(kmapNetFrame);
  kmapNetFrame=requestAnimationFrame(tickKmapNet);
}
function kmapNetMM(e){
  const r=kmapNetCanvas.getBoundingClientRect();
  kmapNetMx=e.clientX-r.left;kmapNetMy=e.clientY-r.top;
  if(kmapNetDragNode){kmapNetDragNode.px=kmapNetMx;kmapNetDragNode.py=kmapNetMy;kmapNetDragNode.vx=0;kmapNetDragNode.vy=0;}
  const hit=kmapNetHitTest(kmapNetMx,kmapNetMy);
  const tip=document.getElementById('kmap-net-tip');
  if(hit&&kmapNetNodeVisible(hit)){
    kmapNetHov=hit;
    tip.querySelector('.knt-name').textContent=hit.label;
    tip.querySelector('.knt-type').textContent=hit.type.toUpperCase();
    tip.querySelector('.knt-desc').textContent=(hit.desc||'').slice(0,120)+(hit.desc&&hit.desc.length>120?'...':'');
    const cx=kmapNetCanvas.clientWidth;
    tip.style.left=(kmapNetMx+14>cx-240?kmapNetMx-224:kmapNetMx+14)+'px';
    tip.style.top=Math.max(0,kmapNetMy-20)+'px';
    tip.style.opacity='1';
  }else{kmapNetHov=null;tip.style.opacity='0';}
}
function kmapNetHitTest(mx,my){
  if(!kmapNetData)return null;
  for(const n of kmapNetData.nodes){
    if(!kmapNetNodeVisible(n))continue;
    const dx=n.px-mx,dy=n.py-my;
    if(Math.sqrt(dx*dx+dy*dy)<n.size+5)return n;
  }
  return null;
}
function kmapNetNodeVisible(n){
  if(kmapNetFilter==='all')return true;
  return n.type===kmapNetFilter;
}
function tickKmapNet(){
  if(!kmapNetCtx||!kmapNetData){kmapNetFrame=null;return;}
  const W=kmapNetCanvas.clientWidth,H=kmapNetCanvas.clientHeight;
  const nodes=kmapNetData.nodes,links=kmapNetData.links;
  // Physics
  nodes.forEach(n=>{
    if(n===kmapNetDragNode)return;
    nodes.forEach(m=>{
      if(m===n)return;
      const dx=n.px-m.px,dy=n.py-m.py;
      const d=Math.sqrt(dx*dx+dy*dy)||1;
      if(d<200){const f=140/(d*d);n.vx+=dx*f;n.vy+=dy*f;}
    });
    n.vx+=(W/2-n.px)*0.0015;n.vy+=(H/2-n.py)*0.0015;
  });
  links.forEach(l=>{
    const a=kmapNetData.nodeMap[l.src],b=kmapNetData.nodeMap[l.dst];
    if(!a||!b)return;
    const dx=b.px-a.px,dy=b.py-a.py,d=Math.sqrt(dx*dx+dy*dy)||1;
    const tgt=a.type==='domain'||b.type==='domain'?130:a.type==='scholar'&&b.type==='text'?80:100;
    const f=(d-tgt)*0.035*l.strength;
    const fx=dx/d*f,fy=dy/d*f;
    if(a!==kmapNetDragNode){a.vx+=fx;a.vy+=fy;}
    if(b!==kmapNetDragNode){b.vx-=fx;b.vy-=fy;}
  });
  nodes.forEach(n=>{
    if(n===kmapNetDragNode)return;
    n.vx*=0.72;n.vy*=0.72;
    n.px+=n.vx;n.py+=n.vy;
    n.px=Math.max(n.size+4,Math.min(W-n.size-4,n.px));
    n.py=Math.max(n.size+4,Math.min(H-n.size-4,n.py));
  });
  // Draw
  const ctx=kmapNetCtx;
  ctx.clearRect(0,0,W,H);
  // Background grid
  ctx.strokeStyle='rgba(201,168,76,.03)';ctx.lineWidth=1;
  for(let x=0;x<W;x+=60){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}
  for(let y=0;y<H;y+=60){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}
  // Links
  links.forEach(l=>{
    const a=kmapNetData.nodeMap[l.src],b=kmapNetData.nodeMap[l.dst];
    if(!a||!b||!kmapNetNodeVisible(a)||!kmapNetNodeVisible(b))return;
    const hov=kmapNetHov&&(kmapNetHov===a||kmapNetHov===b);
    ctx.beginPath();ctx.moveTo(a.px,a.py);ctx.lineTo(b.px,b.py);
    ctx.strokeStyle=hov?`${a.color}88`:`rgba(201,168,76,.08)`;
    ctx.lineWidth=hov?1.5:.5;ctx.stroke();
    // Arrow midpoint for hovered
    if(hov){
      const mx=(a.px+b.px)/2,my=(a.py+b.py)/2;
      ctx.beginPath();ctx.arc(mx,my,2.5,0,Math.PI*2);
      ctx.fillStyle=a.color+'88';ctx.fill();
    }
  });
  // Nodes
  nodes.forEach(n=>{
    if(!kmapNetNodeVisible(n))return;
    const hov=kmapNetHov===n;
    const r=hov?n.size*1.35:n.size;
    // Outer glow for hovered
    if(hov){
      ctx.beginPath();ctx.arc(n.px,n.py,r+8,0,Math.PI*2);
      ctx.fillStyle=n.color+'18';ctx.fill();
    }
    ctx.beginPath();ctx.arc(n.px,n.py,r,0,Math.PI*2);
    const alpha=n.type==='domain'?'cc':n.type==='scholar'?'99':'66';
    ctx.fillStyle=n.color+alpha;ctx.fill();
    ctx.strokeStyle=n.color+(hov?'ff':'88');
    ctx.lineWidth=hov?2:n.type==='domain'?1.5:.8;ctx.stroke();
    // Type indicator ring
    if(n.type==='text'){
      ctx.beginPath();ctx.arc(n.px,n.py,r+3,0,Math.PI*2);
      ctx.strokeStyle=n.color+'44';ctx.lineWidth=.5;ctx.stroke();
    }
    // Label
    if(hov||n.type==='domain'){
      ctx.font=n.type==='domain'?`600 9px 'IBM Plex Mono',monospace`:`7.5px 'IBM Plex Mono',monospace`;
      ctx.textAlign='center';
      const words=n.label.split(' ');
      const short=words.length>2?words[0]+' '+words[1]:n.label;
      ctx.fillStyle=hov?'rgba(240,224,176,1)':n.color+'cc';
      ctx.fillText(short,n.px,n.py+r+13);
    }
  });
  kmapNetFrame=requestAnimationFrame(tickKmapNet);
}


