//  FRACTAL MIRROR
// ═══════════════════════════════════════════════════════
let fmCurrentEra = 0;

function openFractalMirror(){
  document.getElementById('fractal-ov').classList.add('on');
  renderFractalMirror(current);
}
function closeFractalMirror(){ document.getElementById('fractal-ov').classList.remove('on'); }

function renderFractalMirror(idx){
  fmCurrentEra = idx;
  const era = ERAS[idx];
  if(!era) return;

  // Era selector dots
  const sel = document.getElementById('fm-era-select');
  if(sel && sel.children.length === 0){
    ERAS.forEach((e,i)=>{
      const d = document.createElement('div');
      d.className='fm-dot';
      d.style.background = e.dotColor;
      d.title = e.avatarName.replace(/<[^>]+>/g,'').replace(/—.*/,'').trim();
      d.onclick = ()=>renderFractalMirror(i);
      sel.appendChild(d);
    });
  }
  // Update active dot
  if(sel){ Array.from(sel.children).forEach((d,i)=>d.classList.toggle('active',i===idx)); }

  const name = era.avatarName.replace(/<[^>]+>/g,'').replace(/—.*/,'').trim();
  const fractal = era.fractal || {};

  function colContent(id, contentHtml){
    const el = document.getElementById(id);
    if(el){ el.innerHTML = `
      <div style="padding:16px 24px 8px">
        <div class="fm-era-glyph">${era.glyph||''}</div>
        <div class="fm-era-num" style="color:${era.dotColor}44">${String(idx+1).padStart(2,'0')}</div>
        <div class="fm-era-name">${name}</div>
      </div>
      <div class="fm-content">${contentHtml}</div>
    `;}
  }

  // Cosmic column — use meta layer
  const cosmicText = fractal.cosmic || era.layers?.meta || '';
  colContent('fm-cosmic-content', `<p>${cosmicText}</p>`);

  // Civilizational column — use history layer
  const civText = fractal.civ || era.layers?.history || '';
  colContent('fm-civ-content', `<p>${civText}</p>`);

  // Inner column — use inner layer
  const innerText = fractal.inner || era.layers?.inner || '';
  colContent('fm-inner-content', `
    <p>${innerText}</p>
    <div class="fm-inner-prompt">
      <div class="fm-inner-prompt-lbl">Resonance Inquiry</div>
      <div class="fm-inner-prompt-text">Where in your own experience is this era alive right now? The ${name} era is not history — it is a state of consciousness. Right now, which layer are you in?</div>
    </div>
  `);

  // Resonance line — era quote as connector
  if(era.quote){
    ['fm-cosmic-content','fm-civ-content','fm-inner-content'].forEach(id=>{
      const el = document.getElementById(id);
      if(el){ el.insertAdjacentHTML('beforeend', `
        <div class="fm-resonance">
          <div class="fm-resonance-lbl">Resonance — The Same Pattern</div>
          <div class="fm-resonance-text">"${era.quote.t}"<br><span style="font-size:11px;color:var(--muted);font-family:'IBM Plex Mono',monospace;letter-spacing:1px;">— ${era.quote.s}</span></div>
        </div>
      `);}
    });
  }
}

