let sbLayer = 'chakra';

function openSubtleBody(){
  document.getElementById('subtle-ov').classList.add('on');
  setTimeout(renderSbFigure, 80);
}
function closeSubtleBody(){
  document.getElementById('subtle-ov').classList.remove('on');
  if(sbAnimFrame){cancelAnimationFrame(sbAnimFrame);sbAnimFrame=null;}
  // Also cancel sb canvas frames
  if(typeof sbCanvasFrame!=='undefined'&&sbCanvasFrame){cancelAnimationFrame(sbCanvasFrame);sbCanvasFrame=null;}
  // Hide canvas panel
  const p=document.getElementById('sb-canvas-panel');if(p)p.style.display='none';
  const si=document.getElementById('sb-info');if(si)si.style.display='';
}
function setSbLayer(layer, btn){
  sbLayer = layer;
  if(sbAnimFrame){cancelAnimationFrame(sbAnimFrame);sbAnimFrame=null;}
  document.querySelectorAll('.sb-lbtn').forEach(b=>b.classList.remove('active'));
  if(btn) btn.classList.add('active');
  renderSbFigure();
  document.getElementById('sb-info').innerHTML = '<div class="sb-placeholder">Click any element on the figure to explore it.</div>';
}

// ── Macrocosm-Microcosm open/close ──
let mmCanvas=null,mmCtx=null,mmMode='all',mmHov=null,mmAnimFrame=null;
