const VEDA_COLORS = { rig:'#c9a84c', yajur_k:'#6090c8', yajur_s:'#70b890', sama:'#b080d0', atharva:'#c06090' };
const VEDA_LABELS = { rig:'Rigveda', yajur_k:'Kṛṣṇa Yajurveda', yajur_s:'Śukla Yajurveda', sama:'Sāmaveda', atharva:'Atharvaveda' };

let upCanvas=null, upCtx=null, upAnimFrame=null, upMode='all', upHov=null, upNodes=[], upSel=null;

function setUpMode(mode, btn){
  upMode=mode;
  document.querySelectorAll('.up-cbtn').forEach(b=>b.classList.remove('active'));
  if(btn) btn.classList.add('active');
}
function initUpanishad(){
  upCanvas=document.getElementById('up-canvas');
  if(!upCanvas) return;
  const wrap=document.getElementById('up-canvas-wrap');
  upCtx=upCanvas.getContext('2d');
  const dpr=window.devicePixelRatio||1;
  const dW=wrap.clientWidth,dH=wrap.clientHeight;
  upCanvas.width=dW*dpr;upCanvas.height=dH*dpr;
  upCanvas.style.width=dW+'px';upCanvas.style.height=dH+'px';
  upCtx.scale(dpr,dpr);
  // Layout nodes
  const W=dW,H=dH,cx=W/2,cy=H/2;
  const vedaOrder=['rig','yajur_k','yajur_s','sama','atharva'];
  upNodes = UPANISHADS.map((u,i)=>{
    const vi = vedaOrder.indexOf(u.veda);
    const sameVeda = UPANISHADS.filter(x=>x.veda===u.veda);
    const vi2 = sameVeda.indexOf(u);
    const baseAngle = (vi/vedaOrder.length)*Math.PI*2 - Math.PI/2;
    const spread = (vi2/Math.max(sameVeda.length-1,1) - 0.5)*0.8;
    const r = u.principal ? 160 : 220 + Math.random()*60;
    const a = baseAngle + spread;
    return {
      ...u, i,
      x: cx + Math.cos(a)*r,
      y: cy + Math.sin(a)*r,
      r: u.principal ? 10 : 4 + u.influence*1.2,
      color: VEDA_COLORS[u.veda]||'#c9a84c',
    };
  });
  upCanvas.onmousemove = e=>{
    const r=upCanvas.getBoundingClientRect();
    const mx=e.clientX-r.left,my=e.clientY-r.top;
    upHov=upNodes.find(n=>Math.hypot(n.x-mx,n.y-my)<n.r+6)||null;
    upCanvas.style.cursor=upHov?'pointer':'crosshair';
  };
  upCanvas.onclick = e=>{
    const r=upCanvas.getBoundingClientRect();
    const mx=e.clientX-r.left,my=e.clientY-r.top;
    const hit=upNodes.find(n=>Math.hypot(n.x-mx,n.y-my)<n.r+6);
    if(hit) showUpanishad(hit);
  };
  upCanvas.onmouseleave=()=>upHov=null;
  // Touch support for mobile swipe/tap
  upCanvas.style.touchAction='none';
  let upTouchStartX=0,upTouchStartY=0,upTouchMoved=false;
  upCanvas.ontouchstart=e=>{
    e.preventDefault();
    const t=e.touches[0];
    upTouchStartX=t.clientX;upTouchStartY=t.clientY;upTouchMoved=false;
  };
  upCanvas.ontouchmove=e=>{
    e.preventDefault();
    const t=e.touches[0];
    const dx=t.clientX-upTouchStartX,dy=t.clientY-upTouchStartY;
    if(Math.hypot(dx,dy)>8)upTouchMoved=true;
    // Pan the canvas on drag
    if(upTouchMoved&&upNodes.length){
      upNodes.forEach(n=>{n.x+=dx*0.5;n.y+=dy*0.5;});
      upTouchStartX=t.clientX;upTouchStartY=t.clientY;
    }
  };
  upCanvas.ontouchend=e=>{
    e.preventDefault();
    if(!upTouchMoved){
      const t=e.changedTouches[0];
      const r=upCanvas.getBoundingClientRect();
      const mx=t.clientX-r.left,my=t.clientY-r.top;
      const hit=upNodes.find(n=>Math.hypot(n.x-mx,n.y-my)<n.r+12);
      if(hit)showUpanishad(hit);
    }
  };
  if(upAnimFrame) cancelAnimationFrame(upAnimFrame);
  upAnimFrame=requestAnimationFrame(tickUpanishad);
}
function tickUpanishad(){
  if(!upCtx){upAnimFrame=null;return;}
  const W=upCanvas.clientWidth,H=upCanvas.clientHeight;
  upCtx.clearRect(0,0,W,H);
  // Background — veda quadrants
  const vedaOrder=['rig','yajur_k','yajur_s','sama','atharva'];
  vedaOrder.forEach((v,i)=>{
    const a=(i/vedaOrder.length)*Math.PI*2-Math.PI/2;
    const a2=((i+1)/vedaOrder.length)*Math.PI*2-Math.PI/2;
    upCtx.beginPath();
    upCtx.moveTo(W/2,H/2);
    upCtx.arc(W/2,H/2,Math.max(W,H),a,a2);
    upCtx.closePath();
    upCtx.fillStyle=(VEDA_COLORS[v]||'#c9a84c').replace(')',',0.02)').replace('rgb','rgba').replace('#','rgba(').replace('rgba(c9a84c',`rgba(201,168,76`)||'rgba(201,168,76,.02)';
    // Simpler approach:
    upCtx.fillStyle=VEDA_COLORS[v]+'0a';
    upCtx.fill();
    // Veda label
    const midA=(a+a2)/2;
    const lx=W/2+Math.cos(midA)*290,ly=H/2+Math.sin(midA)*290;
    upCtx.font="600 7px 'IBM Plex Mono',monospace";
    upCtx.fillStyle=VEDA_COLORS[v]+'44';
    upCtx.textAlign='center';
    upCtx.fillText(VEDA_LABELS[v]||v,lx,ly);
  });
  // Connection lines for teaching threads
  if(upMode!=='all'){
    const filtered=upNodes.filter(n=>n.topic&&n.topic.includes(upMode==='principal'?null:upMode)||upMode==='principal'&&n.principal);
    filtered.forEach((a,i)=>{filtered.forEach((b,j)=>{
      if(j<=i)return;
      upCtx.beginPath();upCtx.moveTo(a.x,a.y);upCtx.lineTo(b.x,b.y);
      upCtx.strokeStyle=a.color+'33';upCtx.lineWidth=.5;upCtx.stroke();
    });});
  }
  // Center pulse
  upCtx.beginPath();upCtx.arc(W/2,H/2,8,0,Math.PI*2);
  upCtx.fillStyle='rgba(201,168,76,.3)';upCtx.fill();
  upCtx.beginPath();upCtx.arc(W/2,H/2,14,0,Math.PI*2);
  upCtx.strokeStyle='rgba(201,168,76,.15)';upCtx.lineWidth=1;upCtx.stroke();
  upCtx.font="8px 'Cormorant Garamond',serif";
  upCtx.fillStyle='rgba(201,168,76,.4)';upCtx.textAlign='center';
  upCtx.fillText('ॐ',W/2,H/2+3);
  // Stars
  upNodes.forEach(n=>{
    const visible = upMode==='all'||(upMode==='principal'&&n.principal)||(n.topic&&n.topic.includes(upMode));
    if(!visible){
      upCtx.beginPath();upCtx.arc(n.x,n.y,n.r*.4,0,Math.PI*2);
      upCtx.fillStyle=n.color+'22';upCtx.fill();
      return;
    }
    const hov=upHov===n;
    if(hov||n.principal){
      upCtx.beginPath();upCtx.arc(n.x,n.y,n.r+8,0,Math.PI*2);
      upCtx.fillStyle=n.color+'15';upCtx.fill();
    }
    upCtx.beginPath();upCtx.arc(n.x,n.y,n.r,0,Math.PI*2);
    upCtx.fillStyle=n.color+(hov?'dd':n.principal?'99':'55');
    upCtx.fill();
    if(n.principal){upCtx.strokeStyle=n.color+'cc';upCtx.lineWidth=1.5;upCtx.stroke();}
    if(hov||n.principal){
      upCtx.font=`${hov?8:7}px 'IBM Plex Mono',monospace`;
      upCtx.fillStyle=hov?'rgba(240,224,176,.9)':n.color+'99';
      upCtx.textAlign='center';
      upCtx.fillText(n.name,n.x,n.y+n.r+12);
    }
  });
  upAnimFrame=requestAnimationFrame(tickUpanishad);
}
function showUpanishad(u){
  const info=document.getElementById('up-info');
  info.innerHTML=`
    <div class="up-item-name">${u.name} Upaniṣad</div>
    <div class="up-item-veda">${VEDA_LABELS[u.veda]||u.veda} · ${u.era<0?Math.abs(u.era)+' BCE':u.era+' CE'} · ${u.rishi}</div>
    ${u.principal?'<div style="font-family:IBM Plex Mono,monospace;font-size:6px;letter-spacing:2px;color:rgba(201,168,76,.5);text-transform:uppercase;margin-bottom:12px;">✦ One of Shankaracharya\'s 10 Principal Upanishads</div>':''}
    <div class="up-item-section"><div class="up-item-sec-lbl">Core Teaching</div><div class="up-item-sec-body">${u.teaching}</div></div>
    ${u.verse?`<div class="up-verse"><div class="up-verse-skt">${u.verse.skt}</div><div class="up-verse-trans">${u.verse.trans}</div></div>`:''}
    <div class="up-item-section"><div class="up-item-sec-lbl">Themes</div><div class="up-item-sec-body">${(u.topic||[]).map(t=>`<span style="font-family:IBM Plex Mono,monospace;font-size:6.5px;letter-spacing:1px;color:${VEDA_COLORS[u.veda]};border:1px solid ${VEDA_COLORS[u.veda]}44;padding:2px 7px;margin-right:4px;">${t}</span>`).join('')}</div></div>
  `;
  info.scrollTop=0;
}

