let kcCanvas=null,kcCtx=null,kcLevel=0,kcAnimFrame=null;
let kcRotation=0,kcHov=null,kcViewMode='cyclical';

function initKalachakra(){
  kcCanvas=document.getElementById('cc-canvas');if(!kcCanvas)return;
  const wrap=document.getElementById('cc-canvas-wrap');
  kcCtx=kcCanvas.getContext('2d');
  const dpr=window.devicePixelRatio||1;
  const dW=wrap.clientWidth,dH=wrap.clientHeight;
  kcCanvas.width=dW*dpr;kcCanvas.height=dH*dpr;
  kcCanvas.style.width=dW+'px';kcCanvas.style.height=dH+'px';
  kcCtx.scale(dpr,dpr);

  kcCanvas.onclick=e=>{
    const r=kcCanvas.getBoundingClientRect();
    const mx=e.clientX-r.left,my=e.clientY-r.top;
    if(kcViewMode==='cyclical'){
      const hit=kcHitRing(mx,my);
      if(hit!==null){kcLevel=hit;showKcDetail(KC_LAYERS[hit]);}
    } else {
      const hit=kcHitBar(mx,my);
      if(hit!==null) showKcDetail(KC_LAYERS[hit]);
    }
  };
  kcCanvas.onmousemove=e=>{
    const r=kcCanvas.getBoundingClientRect();
    const mx=e.clientX-r.left,my=e.clientY-r.top;
    kcHov=kcViewMode==='cyclical'?kcHitRing(mx,my):kcHitBar(mx,my);
  };
  kcCanvas.onmouseleave=()=>kcHov=null;
  kcCanvas.addEventListener('wheel',e=>{
    e.preventDefault();
    if(e.deltaY>0) kcLevel=Math.min(kcLevel+1,KC_LAYERS.length-1);
    else kcLevel=Math.max(kcLevel-1,0);
    showKcDetail(KC_LAYERS[kcLevel]);
  },{passive:false});

  // Set up toggle buttons
  const ctrl=document.getElementById('kc-toggle');
  if(ctrl){
    ctrl.querySelectorAll('.knc-btn').forEach(b=>{
      b.onclick=function(){
        kcViewMode=this.dataset.mode;
        ctrl.querySelectorAll('.knc-btn').forEach(x=>x.classList.remove('active'));
        this.classList.add('active');
      };
    });
  }

  showKcDetail(KC_LAYERS[0]);
  if(kcAnimFrame)cancelAnimationFrame(kcAnimFrame);
  kcAnimFrame=requestAnimationFrame(tickKc);
}

function kcHitRing(mx,my){
  const W=kcCanvas.clientWidth,H=kcCanvas.clientHeight;
  const cx=W/2,cy=H*.45;
  const maxR=Math.min(W,H)*.42;
  const dx=mx-cx,dy=my-cy;
  const dist=Math.sqrt(dx*dx+dy*dy);
  const n=KC_LAYERS.length;
  for(let i=0;i<n;i++){
    const r1=maxR*(i/n);
    const r2=maxR*((i+1)/n);
    if(dist>=r1&&dist<=r2)return i;
  }
  return null;
}

function kcHitBar(mx,my){
  const W=kcCanvas.clientWidth;
  const bw=W/KC_LAYERS.length;
  const i=Math.floor(mx/bw);
  return(i>=0&&i<KC_LAYERS.length)?i:null;
}

function tickKc(){
  if(!kcCtx){kcAnimFrame=null;return;}
  kcRotation+=0.0005;
  if(kcViewMode==='cyclical') drawKcCyclical();
  else drawKcLinear();
  kcAnimFrame=requestAnimationFrame(tickKc);
}

function drawKcCyclical(){
  const ctx=kcCtx;
  const W=kcCanvas.clientWidth,H=kcCanvas.clientHeight;
  ctx.clearRect(0,0,W,H);
  ctx.fillStyle='rgba(3,2,1,.97)';ctx.fillRect(0,0,W,H);

  const cx=W/2,cy=H*.46;
  const maxR=Math.min(W,H)*.40;
  const n=KC_LAYERS.length;

  // ── Starfield ───────────────────────────────────
  if(!kcStars){
    kcStars=[];
    for(let i=0;i<140;i++) kcStars.push({x:Math.random()*W,y:Math.random()*H,r:Math.random()*1.4+.3,a:Math.random()*.5+.1,twinkle:Math.random()*Math.PI*2});
  }
  kcStars.forEach(s=>{
    const a=s.a*(0.5+0.5*Math.sin(kcRotation*8+s.twinkle));
    ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);
    ctx.fillStyle=`rgba(240,224,176,${a})`;ctx.fill();
  });

  // ── COSMOLOGICAL ORIGIN — Shiva→Vishnu→Navel→Hiranyagarbha→Cosmos ──
  // Shiva — the unmanifest ground, far above
  const shivaY=H*.08;
  ctx.save();
  ctx.font="italic 13px 'Cormorant Garamond',serif";
  ctx.fillStyle=`rgba(160,80,220,${0.3+0.15*Math.sin(kcRotation*3)})`;
  ctx.textAlign='center';
  ctx.fillText('𑁍  Śiva — Pure Consciousness (Nirguna Brahman)',cx,shivaY);
  ctx.font="7px 'IBM Plex Mono',monospace";
  ctx.fillStyle='rgba(160,80,220,.2)';
  ctx.fillText('the unmanifest ground — before all cycles',cx,shivaY+14);
  ctx.restore();

  // Dotted descent line from Shiva downward
  ctx.beginPath();
  ctx.setLineDash([3,6]);
  ctx.moveTo(cx,shivaY+18);ctx.lineTo(cx,H*.18);
  ctx.strokeStyle='rgba(160,80,220,.18)';ctx.lineWidth=1;ctx.stroke();
  ctx.setLineDash([]);

  // Vishnu — reclining on Ananta Shesha, above the wheel
  const vishnuY=H*.20;
  const vishnuPulse=0.4+0.15*Math.sin(kcRotation*2.5);
  // Ananta Shesha coil
  ctx.beginPath();
  for(let t=0;t<Math.PI*3;t+=0.05){
    const sr=14+t*5;const sx=cx+Math.cos(t)*sr*.5;const sy=vishnuY+Math.sin(t)*sr*.3;
    t<0.05?ctx.moveTo(sx,sy):ctx.lineTo(sx,sy);
  }
  ctx.strokeStyle=`rgba(80,180,200,${vishnuPulse*.5})`;ctx.lineWidth=1.5;ctx.stroke();

  ctx.font=`italic 14px 'Cormorant Garamond',serif`;
  ctx.fillStyle=`rgba(80,180,200,${vishnuPulse})`;
  ctx.textAlign='center';
  ctx.fillText('Viṣṇu — Reclining on Ananta Śeṣa',cx,vishnuY-8);
  ctx.font="7px 'IBM Plex Mono',monospace";
  ctx.fillStyle=`rgba(80,180,200,${vishnuPulse*.6})`;
  ctx.fillText('Preserver of all cycles — the cosmic dreamer',cx,vishnuY+5);

  // Navel lotus — connecting Vishnu to the wheel
  const navelY=vishnuY+22;
  const lotus_r=8+3*Math.sin(kcRotation*4);
  ctx.beginPath();ctx.arc(cx,navelY,lotus_r,0,Math.PI*2);
  ctx.strokeStyle=`rgba(201,168,76,.5)`;ctx.lineWidth=1.5;ctx.stroke();
  ctx.fillStyle=`rgba(201,168,76,.08)`;ctx.fill();
  ctx.font="10px 'Cormorant Garamond',serif";
  ctx.fillStyle=`rgba(201,168,76,.6)`;ctx.textAlign='center';
  ctx.fillText('🪷',cx,navelY+4);

  // Lotus stem from navel down to Brahma ring
  const stemBot=cy-maxR-8;
  ctx.beginPath();ctx.moveTo(cx,navelY+lotus_r);ctx.lineTo(cx,stemBot);
  const stemGrad=ctx.createLinearGradient(cx,navelY+lotus_r,cx,stemBot);
  stemGrad.addColorStop(0,'rgba(201,168,76,.45)');
  stemGrad.addColorStop(0.5,'rgba(100,200,80,.3)');
  stemGrad.addColorStop(1,'rgba(201,168,76,.15)');
  ctx.strokeStyle=stemGrad;ctx.lineWidth=2;
  ctx.setLineDash([4,4]);ctx.stroke();ctx.setLineDash([]);

  // Brahma — sitting on lotus, at outer ring
  const brahmaLabelY=stemBot-5;
  ctx.font="italic 11px 'Cormorant Garamond',serif";
  ctx.fillStyle=`rgba(201,168,76,${0.5+0.15*Math.sin(kcRotation*1.5)})`;
  ctx.textAlign='center';
  ctx.fillText('Brahmā emerges — begins creation',cx,brahmaLabelY);

  // Hiranyagarbha glow — just inside the outer ring
  const hgR=maxR*.88;
  const hgAlpha=0.06+0.03*Math.sin(kcRotation*2);
  const hgGrad=ctx.createRadialGradient(cx,cy,hgR*.3,cx,cy,hgR);
  hgGrad.addColorStop(0,`rgba(220,180,60,${hgAlpha*2})`);
  hgGrad.addColorStop(0.5,`rgba(201,168,76,${hgAlpha})`);
  hgGrad.addColorStop(1,'rgba(201,168,76,0)');
  ctx.beginPath();ctx.arc(cx,cy,hgR,0,Math.PI*2);
  ctx.fillStyle=hgGrad;ctx.fill();
  // Hiranyagarbha label (inside outer ring, subtle)
  ctx.font="italic 9px 'Cormorant Garamond',serif";
  ctx.fillStyle=`rgba(220,180,60,.3)`;ctx.textAlign='center';
  ctx.fillText('Hiraṇyagarbha',cx,cy-hgR*.5);

  // ── TIME RINGS (outermost = Brahma = slowest = index 0) ──
  for(let i=0;i<n;i++){
    const layer=KC_LAYERS[i];
    const r1=maxR*(i/n)+2;
    const r2=maxR*((i+1)/n)-2;
    const mid=(r1+r2)/2;
    // Outermost ring (i=0, Brahma) rotates slowest. Innermost (i=n-1, Human) rotates fastest.
    const speedMult=(i+1); // i=0 → ×1 (slowest), i=5 → ×6 (fastest)
    const rot=kcRotation*speedMult;
    const hov=kcHov===i,active=kcLevel===i;

    // Ring fill with cosmic gradient
    ctx.beginPath();
    ctx.arc(cx,cy,r2,0,Math.PI*2);
    ctx.arc(cx,cy,r1,0,Math.PI*2,true);
    const grad=ctx.createRadialGradient(cx,cy,r1,cx,cy,r2);
    grad.addColorStop(0,layer.color.replace(/[\d.]+\)$/,active?'0.22)':'0.07)'));
    grad.addColorStop(1,layer.color.replace(/[\d.]+\)$/,active?'0.14)':'0.03)'));
    ctx.fillStyle=grad;ctx.fill('evenodd');

    // Ring border
    ctx.beginPath();ctx.arc(cx,cy,r2,0,Math.PI*2);
    ctx.strokeStyle=layer.color.replace(/[\d.]+\)$/,hov||active?'0.9)':'0.3)');
    ctx.lineWidth=hov||active?2:.8;ctx.stroke();
    ctx.beginPath();ctx.arc(cx,cy,r1,0,Math.PI*2);
    ctx.strokeStyle=layer.color.replace(/[\d.]+\)$/,'0.1)');
    ctx.lineWidth=.4;ctx.stroke();

    // Rotating tick marks — number of ticks matches the cycle's subdivisions
    const ticks=[1,14,71,4,4,1][i]||1;
    for(let t=0;t<ticks;t++){
      const a=(t/ticks)*Math.PI*2+rot;
      const x1=cx+Math.cos(a)*(r1+2);const y1=cy+Math.sin(a)*(r1+2);
      const x2=cx+Math.cos(a)*(r2-2);const y2=cy+Math.sin(a)*(r2-2);
      ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);
      ctx.strokeStyle=layer.color.replace(/[\d.]+\)$/,'0.5)');
      ctx.lineWidth=ticks>4?.5:1;ctx.stroke();
    }

    // Yuga coloring for Maha Yuga ring (i=3)
    if(i===3){
      const yugaColors=['rgba(120,200,160,.25)','rgba(220,200,80,.2)','rgba(200,140,60,.18)','rgba(180,60,60,.22)'];
      const yugaNames=['Satya','Treta','Dvapara','Kali'];
      const yugaRatios=[4/10,3/10,2/10,1/10];
      let angleAcc=rot;
      yugaRatios.forEach((ratio,yi)=>{
        const span=ratio*Math.PI*2;
        ctx.beginPath();
        ctx.arc(cx,cy,r2,angleAcc,angleAcc+span);
        ctx.arc(cx,cy,r1,angleAcc+span,angleAcc,true);
        ctx.closePath();
        ctx.fillStyle=yugaColors[yi];ctx.fill();
        const midA=angleAcc+span/2;
        ctx.font="6px 'IBM Plex Mono',monospace";
        ctx.fillStyle=yugaColors[yi].replace('.25)','.8)').replace('.2)','.8)').replace('.18)','.8)').replace('.22)','.8)');
        ctx.textAlign='center';ctx.textBaseline='middle';
        ctx.fillText(yugaNames[yi],cx+Math.cos(midA)*mid,cy+Math.sin(midA)*mid);
        ctx.textBaseline='alphabetic';
        angleAcc+=span;
      });
    }

    // Label — rotated along the ring arc at top-left position
    const ringH=r2-r1;
    const labelAng=-Math.PI/2+0.12; // slightly offset from top
    const lx=cx+Math.cos(labelAng)*mid;
    const ly=cy+Math.sin(labelAng)*mid;

    ctx.save();
    ctx.translate(lx,ly);
    ctx.rotate(labelAng+Math.PI/2); // align text with ring curve
    ctx.textAlign='center';ctx.textBaseline='middle';

    // Name
    const fs=active?Math.min(ringH*0.38,10):Math.min(ringH*0.32,8.5);
    ctx.font=`${active?'700':'500'} ${fs.toFixed(1)}px 'IBM Plex Mono',monospace`;
    ctx.fillStyle=hov||active?'rgba(240,224,176,.95)':layer.color.replace(/[\d.]+\)$/,'0.75)');
    ctx.fillText(layer.name,0,-ringH*0.12);

    // Short label (duration)
    if(ringH>18){
      const fs2=Math.min(ringH*0.24,6.5);
      ctx.font=`${fs2.toFixed(1)}px 'IBM Plex Mono',monospace`;
      ctx.fillStyle=layer.color.replace(/[\d.]+\)$/,active?'0.7)':'0.42)');
      ctx.fillText(layer.short,0,ringH*0.2);
    }
    ctx.restore();
  }

  // ── Center — Human Life ──
  const innerR=maxR/n;
  ctx.beginPath();ctx.arc(cx,cy,innerR*.85,0,Math.PI*2);
  ctx.fillStyle='rgba(120,200,150,.08)';ctx.fill();
  ctx.strokeStyle='rgba(120,200,150,.4)';ctx.lineWidth=1.2;ctx.stroke();

  // Pulsing human dot
  const pR=4+2*Math.sin(kcRotation*(n)); // fastest pulse
  ctx.beginPath();ctx.arc(cx,cy,pR+6,0,Math.PI*2);
  ctx.fillStyle='rgba(120,200,150,.1)';ctx.fill();
  ctx.beginPath();ctx.arc(cx,cy,pR,0,Math.PI*2);
  ctx.fillStyle='rgba(120,200,150,.9)';ctx.fill();

  ctx.font="700 7px 'IBM Plex Mono',monospace";
  ctx.fillStyle='rgba(120,200,150,.7)';ctx.textAlign='center';
  ctx.fillText('YOU',cx,cy+3);

  // Gita quote
  ctx.font="italic 10px 'Cormorant Garamond',serif";
  ctx.fillStyle='rgba(201,168,76,.28)';ctx.textAlign='center';
  ctx.fillText('"A thousand Yugas are a day of Brahmā." — Bhagavad Gītā 8.17',cx,H-12);
}
let kcStars=null;

function drawKcLinear(){
  const ctx=kcCtx;
  const W=kcCanvas.clientWidth,H=kcCanvas.clientHeight;
  ctx.clearRect(0,0,W,H);
  ctx.fillStyle='rgba(3,2,1,.95)';ctx.fillRect(0,0,W,H);

  const n=KC_LAYERS.length;
  const bw=W/n;
  const maxLog=Math.log10(KC_LAYERS[0].years);

  KC_LAYERS.forEach((layer,i)=>{
    const x=i*bw;
    const logH=(Math.log10(layer.years)/maxLog)*(H*.65);
    const barH=Math.max(25,logH);
    const hov=kcHov===i,active=kcLevel===i;

    const grad=ctx.createLinearGradient(x,H*.85-barH,x,H*.85);
    grad.addColorStop(0,layer.color);
    grad.addColorStop(1,layer.color.replace(/[\d.]+\)$/,'0.1)'));
    ctx.fillStyle=hov||active?layer.color.replace(/[\d.]+\)$/,'0.85)'):grad;
    ctx.fillRect(x+3,H*.85-barH,bw-6,barH);

    ctx.font=`600 ${bw>90?8:6}px 'IBM Plex Mono',monospace`;
    ctx.fillStyle=hov||active?'rgba(240,224,176,.9)':'rgba(201,168,76,.55)';
    ctx.textAlign='center';
    ctx.save();ctx.translate(x+bw/2,H*.85-barH-10);
    if(bw<70)ctx.rotate(-Math.PI/5);
    ctx.fillText(layer.name,0,0);ctx.restore();

    ctx.font='6px IBM Plex Mono,monospace';
    ctx.fillStyle=layer.color.replace(/[\d.]+\)$/,'0.5)');
    ctx.textAlign='center';
    ctx.fillText(layer.short,x+bw/2,H*.85+10+(i%2)*12);

    if(layer.name==='Kali Yuga'){
      const nowX=x+(5126/layer.years)*bw;
      ctx.beginPath();ctx.moveTo(nowX,H*.85-barH-5);ctx.lineTo(nowX,H*.85);
      ctx.strokeStyle='rgba(201,168,76,.7)';ctx.lineWidth=1.5;ctx.stroke();
      ctx.font='5.5px IBM Plex Mono,monospace';ctx.fillStyle='rgba(201,168,76,.7)';
      ctx.textAlign='center';ctx.fillText('NOW',nowX,H*.85-barH-9);
    }
  });

  // Civilizations line
  ctx.font="italic 11px 'Cormorant Garamond',serif";
  ctx.fillStyle='rgba(201,168,76,.35)';ctx.textAlign='center';
  ctx.fillText('"Civilizations rise and fall in the blink of cosmic time."',W/2,H-28);
  ctx.font="italic 10px 'Cormorant Garamond',serif";
  ctx.fillStyle='rgba(201,168,76,.25)';
  ctx.fillText('"A thousand Yugas are a day of Brahma." — Bhagavad Gita 8.17',W/2,H-12);
}

function showKcDetail(layer){
  const lbl=document.getElementById('cc-scale-lbl');
  if(lbl) lbl.textContent = layer.short + ' — ' + layer.name;
  document.getElementById('cc-info-scale').textContent = layer.short;
  document.getElementById('cc-info-title').textContent = layer.name;
  document.getElementById('cc-info-body').innerHTML = layer.detail || layer.desc;
}
// Old zoom functions replaced — just nav
function ccZoomIn(){kcLevel=Math.max(kcLevel-1,0);showKcDetail(KC_LAYERS[kcLevel]);}
function ccZoomOut(){kcLevel=Math.min(kcLevel+1,KC_LAYERS.length-1);showKcDetail(KC_LAYERS[kcLevel]);}
function ccReset(){kcLevel=0;showKcDetail(KC_LAYERS[0]);}


