let daSelected=[], daHoverId=null, daFrame=null, daCanvas=null, daCtx=null, daNodes=[];
let vwCurrentQ=0;

function openDarsana(){
  const ov=document.getElementById('darsana-ov');
  ov.classList.add('on');
  setTimeout(initDarsanaArena,80);
  renderVW();
}
function closeDarsana(){
  document.getElementById('darsana-ov').classList.remove('on');
  if(daFrame){cancelAnimationFrame(daFrame);daFrame=null;}
}

function daSwitchTab(tab,btn){
  document.querySelectorAll('.da-tab').forEach(b=>b.classList.remove('on'));
  btn.classList.add('on');
  document.getElementById('da-arena-section').style.display=tab==='arena'?'':'none';
  document.getElementById('da-vedanta-section').style.display=tab==='vedanta'?'':'none';
  if(tab==='arena')setTimeout(initDarsanaArena,50);
}

function initDarsanaArena(){
  daCanvas=document.getElementById('da-canvas');
  if(!daCanvas)return;
  const wrap=document.getElementById('da-canvas-col');
  const dpr=window.devicePixelRatio||1;
  const W=wrap.clientWidth, H=wrap.clientHeight;
  daCanvas.width=W*dpr; daCanvas.height=H*dpr;
  daCanvas.style.width=W+'px'; daCanvas.style.height=H+'px';
  daCtx=daCanvas.getContext('2d');
  daCtx.scale(dpr,dpr);
  // Arrange schools in hexagon
  const cx=W/2, cy=H/2, r=Math.min(W,H)*0.32;
  daNodes=DA_SCHOOLS.map((s,i)=>{
    const angle=(i/6)*Math.PI*2 - Math.PI/2;
    return {school:s, x:cx+Math.cos(angle)*r, y:cy+Math.sin(angle)*r, vx:0, vy:0, r:32, selected:false};
  });
  if(daFrame)cancelAnimationFrame(daFrame);
  daFrame=requestAnimationFrame(daLoop);
  daCanvas.onclick=daClick;
  daCanvas.onmousemove=daHover;
  daCanvas.onmouseleave=()=>{daHoverId=null;};
}

function daLoop(){
  if(!daCanvas||!daCtx)return;
  const dpr=window.devicePixelRatio||1;
  const W=daCanvas.width/dpr, H=daCanvas.height/dpr;
  daCtx.clearRect(0,0,W,H);
  // Draw connection lines
  for(let i=0;i<daNodes.length;i++){
    for(let j=i+1;j<daNodes.length;j++){
      const a=daNodes[i], b=daNodes[j];
      const key=[a.school.id,b.school.id].sort().join('-');
      const hasdebate=!!DA_DEBATES[key];
      const sel=daSelected.includes(a.school.id)&&daSelected.includes(b.school.id);
      const hov=(daHoverId===a.school.id||daHoverId===b.school.id);
      daCtx.beginPath();
      daCtx.moveTo(a.x,a.y); daCtx.lineTo(b.x,b.y);
      if(sel){daCtx.strokeStyle='rgba(201,168,76,.5)';daCtx.lineWidth=1.5;}
      else if(hov&&hasdebate){daCtx.strokeStyle='rgba(201,168,76,.15)';daCtx.lineWidth=1;}
      else{daCtx.strokeStyle='rgba(201,168,76,.04)';daCtx.lineWidth=.5;}
      daCtx.setLineDash(hasdebate?[]:[4,4]);
      daCtx.stroke();
      daCtx.setLineDash([]);
    }
  }
  // Draw nodes
  daNodes.forEach(n=>{
    const sel=daSelected.includes(n.school.id);
    const hov=daHoverId===n.school.id;
    const c=n.school.color;
    // Glow
    if(sel||hov){
      const g=daCtx.createRadialGradient(n.x,n.y,n.r*.5,n.x,n.y,n.r*2);
      g.addColorStop(0,c.replace(')',',0.18)').replace('rgb','rgba'));
      g.addColorStop(1,'rgba(0,0,0,0)');
      daCtx.beginPath();daCtx.arc(n.x,n.y,n.r*2,0,Math.PI*2);
      daCtx.fillStyle=g;daCtx.fill();
    }
    // Circle
    daCtx.beginPath();daCtx.arc(n.x,n.y,n.r,0,Math.PI*2);
    daCtx.fillStyle=sel?c+'22)':hov?c+'18)':c+'0C)';
    daCtx.fill();
    daCtx.strokeStyle=sel?c:hov?c+'AA':c+'44';
    daCtx.lineWidth=sel?1.5:1;
    daCtx.stroke();
    // Label
    daCtx.fillStyle=sel||hov?'rgba(240,220,180,.9)':'rgba(180,160,120,.6)';
    daCtx.font=`${sel?'600 ':''} 11px Cinzel,serif`;
    daCtx.textAlign='center';daCtx.textBaseline='middle';
    daCtx.fillText(n.school.name,n.x,n.y);
    // Sanskrit below
    daCtx.fillStyle=c+'66';
    daCtx.font='9px IBM Plex Mono,monospace';
    daCtx.fillText(n.school.skt,n.x,n.y+16);
  });
  daFrame=requestAnimationFrame(daLoop);
}

function daClick(e){
  if(!daCanvas)return;
  const rect=daCanvas.getBoundingClientRect();
  const dpr=window.devicePixelRatio||1;
  const mx=(e.clientX-rect.left), my=(e.clientY-rect.top);
  let hit=null;
  daNodes.forEach(n=>{if(Math.hypot(mx-n.x,my-n.y)<n.r+8)hit=n.school.id;});
  if(!hit)return;
  if(daSelected.includes(hit)){
    daSelected=daSelected.filter(x=>x!==hit);
  } else {
    daSelected.push(hit);
    if(daSelected.length>2)daSelected.shift();
  }
  daUpdateInfo();
}
function daHover(e){
  if(!daCanvas)return;
  const rect=daCanvas.getBoundingClientRect();
  const mx=e.clientX-rect.left, my=e.clientY-rect.top;
  let hit=null;
  daNodes.forEach(n=>{if(Math.hypot(mx-n.x,my-n.y)<n.r+8)hit=n.school.id;});
  daHoverId=hit;
  daCanvas.style.cursor=hit?'pointer':'default';
}
function daUpdateInfo(){
  const hint=document.getElementById('da-hint');
  const single=document.getElementById('da-single-block');
  const debate=document.getElementById('da-debate-block');
  if(daSelected.length===0){
    document.getElementById('da-school-title').textContent='';
    document.getElementById('da-school-skt').textContent='';
    document.getElementById('da-school-claim').textContent='';
    single.style.display=''; debate.style.display='none';
    hint.style.opacity='1'; return;
  }
  hint.style.opacity='0';
  if(daSelected.length===1){
    const s=DA_SCHOOLS.find(x=>x.id===daSelected[0]);
    document.getElementById('da-school-title').textContent=s.name;
    document.getElementById('da-school-skt').textContent=s.skt+' · '+s.founder;
    document.getElementById('da-school-claim').textContent=s.claim;
    document.getElementById('da-school-detail').innerHTML=s.detail;
    document.getElementById('da-school-modern').innerHTML=s.modern;
    document.getElementById('da-school-objection').innerHTML=s.objection;
    single.style.display=''; debate.style.display='none';
  } else {
    const key=daSelected.slice().sort().join('-');
    const txt=DA_DEBATES[key]||'Select two schools to see their debate.';
    const a=DA_SCHOOLS.find(x=>x.id===daSelected[0]);
    const b=DA_SCHOOLS.find(x=>x.id===daSelected[1]);
    document.getElementById('da-school-title').textContent=a.name+' vs '+b.name;
    document.getElementById('da-school-skt').textContent=a.skt+' · '+b.skt;
    document.getElementById('da-school-claim').textContent='';
    document.getElementById('da-debate-schools').textContent='The Tension';
    document.getElementById('da-debate-body').textContent=txt;
    single.style.display='none'; debate.style.display='block';
  }
}

// ── Vedanta Wars ──
function renderVW(){
  const grid=document.getElementById('vw-grid');
  if(!grid||grid.children.length>0)return;
  grid.innerHTML=VW_SCHOOLS.map((s,i)=>`
    <div class="vw-school" onclick="vwSelect(${i})">
      <div class="vw-school-dot" style="background:${s.color};"></div>
      <div class="vw-school-name">${s.name}</div>
      <div class="vw-school-founder">${s.founder}</div>
      <div class="vw-answer" id="vwa-${i}"></div>
    </div>
  `).join('');
  vwSetQ(0,document.querySelector('.vw-qtab'));
}
function vwSetQ(qi,btn){
  vwCurrentQ=qi;
  document.querySelectorAll('.vw-qtab').forEach(b=>b.classList.remove('on'));
  if(btn)btn.classList.add('on');
  VW_SCHOOLS.forEach((s,i)=>{
    const el=document.getElementById('vwa-'+i);
    if(el)el.innerHTML=s.answers[qi];
  });
}
function vwSelect(i){
  document.querySelectorAll('.vw-school').forEach((el,j)=>el.classList.toggle('selected',j===i));
}



// ═══════════════════════════════════════════════════════
//  PAÑCA BHEDA
// ═══════════════════════════════════════════════════════
(function(){
const PB_DATA=[
  {id:'jiva-ishvara',name:'Jīva–Īśvara',skt:'जीव–ईश्वर',
   label:'Soul ≠ God',color:'#B48CFF',angle:-90,
   body:'The individual soul (jīva) and God (Īśvara/Viṣṇu) are eternally and absolutely distinct. No amount of spiritual practice dissolves this distinction. The soul can come infinitely close to God, can experience God\'s bliss, can dwell in God\'s presence — but can never become God. This is the most fundamental of the five differences. Madhva\'s critique of Advaita begins here: the claim "I am Brahman" is not liberation — it is the most dangerous of all confusions, a confusion of identity between the finite and the infinite.'},
  {id:'jada-ishvara',name:'Jaḍa–Īśvara',skt:'जड–ईश्वर',
   label:'Matter ≠ God',color:'#5090C8',angle:-18,
   body:'Matter (jaḍa — the inert, the unconscious) and God are eternally distinct. The universe is not made of God. God is not the material cause of the world in the way a spider is the material cause of its web. God is the efficient cause — the intelligence that organises matter — but matter itself is real, eternal, and categorically other than God. This rules out pantheism: the rock is not God, the tree is not God.'},
  {id:'jiva-jada',name:'Jīva–Jaḍa',skt:'जीव–जड',
   label:'Soul ≠ Matter',color:'#8CC8DC',angle:54,
   body:'Consciousness (the soul) and matter are eternally distinct. The soul is not a product of matter, not an emergent property of the brain, not reducible to chemistry. The soul is a real, eternal, conscious entity. Matter is real, eternal, and inert. Their difference is categorical. This is Madhva\'s answer to materialism: consciousness cannot be explained by matter, ever, because they belong to permanently different categories of being.'},
  {id:'jiva-jiva',name:'Jīva–Jīva',skt:'जीव–जीव',
   label:'Soul ≠ Soul',color:'#DCB450',angle:126,
   body:'No two souls are identical. Each jīva is a unique, eternal individual with its own distinct character, its own distinct karma, its own distinct relationship with God. There is no universal soul that all individual souls are "really" identical to. Even in liberation, the distinctness of each soul is preserved. This is Madhva\'s most psychologically radical claim: your individuality is not an illusion to be overcome — it is an eternal feature of reality.'},
  {id:'jada-jada',name:'Jaḍa–Jaḍa',skt:'जड–जड',
   label:'Matter ≠ Matter',color:'#C89040',angle:198,
   body:'No two material objects are identical. Each piece of matter has its own particular qualities, its own particular identity, its own particular relationship to God. The diversity of the material world is real, not apparent. This rules out the idea that "all is one" at the material level. The tree and the stone are both matter, but they are permanently, irreducibly distinct kinds of matter. Reality is irreducibly plural at every level.'}
];

let pbCanvas=null,pbCtx=null,pbFrame=null,pbHover=null,pbActive=null;

function openPancaBheda(){
  document.getElementById('pb-ov').classList.add('on');
  setTimeout(pbInit,80);
}
function closePancaBheda(){
  document.getElementById('pb-ov').classList.remove('on');
  if(pbFrame){cancelAnimationFrame(pbFrame);pbFrame=null;}
}
function pbInit(){
  pbCanvas=document.getElementById('pb-canvas');
  if(!pbCanvas)return;
  const dpr=window.devicePixelRatio||1;
  pbCanvas.width=pbCanvas.offsetWidth*dpr;
  pbCanvas.height=pbCanvas.offsetHeight*dpr;
  pbCtx=pbCanvas.getContext('2d');
  pbCtx.scale(dpr,dpr);
  pbCanvas.onclick=pbClick;
  pbCanvas.onmousemove=pbMouseMove;
  pbCanvas.onmouseleave=()=>{pbHover=null;};
  if(pbFrame)cancelAnimationFrame(pbFrame);
  pbFrame=requestAnimationFrame(pbLoop);
}
let pbT=0;
function pbLoop(){
  if(!pbCanvas||!pbCtx)return;
  pbT+=0.008;
  const dpr=window.devicePixelRatio||1;
  const W=pbCanvas.width/dpr,H=pbCanvas.height/dpr;
  pbCtx.clearRect(0,0,W,H);
  const cx=W/2,cy=H/2-40;
  const r=Math.min(W,H)*0.28;

  // Draw connective lines between all nodes
  PB_DATA.forEach((a,i)=>{
    PB_DATA.forEach((b,j)=>{
      if(j<=i)return;
      const ax=cx+Math.cos(a.angle*Math.PI/180)*r;
      const ay=cy+Math.sin(a.angle*Math.PI/180)*r;
      const bx=cx+Math.cos(b.angle*Math.PI/180)*r;
      const by=cy+Math.sin(b.angle*Math.PI/180)*r;
      pbCtx.beginPath();pbCtx.moveTo(ax,ay);pbCtx.lineTo(bx,by);
      pbCtx.strokeStyle='rgba(180,140,255,0.05)';pbCtx.lineWidth=1;pbCtx.stroke();
    });
  });

  // Central "Madhva" node
  const pulse=0.8+Math.sin(pbT*1.5)*0.2;
  const g=pbCtx.createRadialGradient(cx,cy,0,cx,cy,40*pulse);
  g.addColorStop(0,'rgba(180,140,255,0.12)');g.addColorStop(1,'rgba(0,0,0,0)');
  pbCtx.beginPath();pbCtx.arc(cx,cy,40*pulse,0,Math.PI*2);
  pbCtx.fillStyle=g;pbCtx.fill();
  pbCtx.beginPath();pbCtx.arc(cx,cy,18,0,Math.PI*2);
  pbCtx.strokeStyle='rgba(180,140,255,0.3)';pbCtx.lineWidth=1;pbCtx.stroke();
  pbCtx.fillStyle='rgba(180,140,255,0.6)';pbCtx.font='9px IBM Plex Mono,monospace';
  pbCtx.textAlign='center';pbCtx.textBaseline='middle';
  pbCtx.fillText('MADHVA',cx,cy);

  PB_DATA.forEach(d=>{
    const nx=cx+Math.cos(d.angle*Math.PI/180)*r;
    const ny=cy+Math.sin(d.angle*Math.PI/180)*r;
    const isHov=pbHover===d.id,isAct=pbActive===d.id;
    const nr=isAct?38:isHov?34:28;

    // Orbit trail
    const trailR=r+Math.sin(pbT+d.angle)*6;
    pbCtx.beginPath();pbCtx.arc(cx,cy,trailR,d.angle*Math.PI/180-0.2,d.angle*Math.PI/180+0.2);
    pbCtx.strokeStyle=d.color+'22';pbCtx.lineWidth=1;pbCtx.stroke();

    // Glow
    if(isHov||isAct){
      const gl=pbCtx.createRadialGradient(nx,ny,nr*.4,nx,ny,nr*2.5);
      gl.addColorStop(0,d.color+'30');gl.addColorStop(1,'rgba(0,0,0,0)');
      pbCtx.beginPath();pbCtx.arc(nx,ny,nr*2.5,0,Math.PI*2);
      pbCtx.fillStyle=gl;pbCtx.fill();
    }
    // Node
    pbCtx.beginPath();pbCtx.arc(nx,ny,nr,0,Math.PI*2);
    pbCtx.fillStyle=isAct?d.color+'25':isHov?d.color+'18':'rgba(10,8,20,0.8)';
    pbCtx.fill();
    pbCtx.strokeStyle=isAct?d.color:isHov?d.color+'BB':d.color+'44';
    pbCtx.lineWidth=isAct?2:1;pbCtx.stroke();

    // Label
    pbCtx.fillStyle=isAct||isHov?'rgba(240,220,255,.95)':'rgba(180,160,220,.6)';
    pbCtx.font=`${isAct?'500 ':''}10px Cinzel,serif`;
    pbCtx.textAlign='center';pbCtx.textBaseline='middle';
    pbCtx.fillText(d.label,nx,ny-3);
    pbCtx.font='8px Noto Sans Devanagari,sans-serif';
    pbCtx.fillStyle=d.color+'66';
    pbCtx.fillText(d.skt,nx,ny+10);
  });
  pbFrame=requestAnimationFrame(pbLoop);
}
function pbGetHit(e){
  const rect=pbCanvas.getBoundingClientRect();
  const dpr=window.devicePixelRatio||1;
  const W=pbCanvas.width/dpr,H=pbCanvas.height/dpr;
  const cx=W/2,cy=H/2-40,r=Math.min(W,H)*0.28;
  const mx=e.clientX-rect.left,my=e.clientY-rect.top;
  for(const d of PB_DATA){
    const nx=cx+Math.cos(d.angle*Math.PI/180)*r;
    const ny=cy+Math.sin(d.angle*Math.PI/180)*r;
    if(Math.hypot(mx-nx,my-ny)<40)return d.id;
  }
  return null;
}
function pbMouseMove(e){
  if(!pbCanvas)return;
  pbHover=pbGetHit(e);
  pbCanvas.style.cursor=pbHover?'pointer':'default';
}
function pbClick(e){
  if(!pbCanvas)return;
  const hit=pbGetHit(e);
  if(!hit)return;
  pbActive=pbActive===hit?null:hit;
  const d=PB_DATA.find(x=>x.id===pbActive);
  const hint=document.getElementById('pb-hint');
  if(d){
    hint.style.opacity='0';
    document.getElementById('pb-bheda-name').textContent=d.name;
    document.getElementById('pb-bheda-skt').textContent=d.skt+' — '+d.label;
    document.getElementById('pb-bheda-body').textContent=d.body;
  } else {
    hint.style.opacity='1';
    document.getElementById('pb-bheda-name').textContent='';
    document.getElementById('pb-bheda-skt').textContent='';
    document.getElementById('pb-bheda-body').textContent='';
  }
}
window.openPancaBheda=openPancaBheda;
window.closePancaBheda=closePancaBheda;
})();

// ═══════════════════════════════════════════════════════
//  ABHINAVAGUPTA'S WEB — 36 TATTVAS
// ═══════════════════════════════════════════════════════
(function(){
const AG_TATTVAS=[
  // Śiva Tattvas (1–5) — pure consciousness
  {n:1,name:'Śiva',skt:'शिव',group:'shiva',body:'Pure undivided consciousness. No object, no subject, no space, no time. The ground from which everything emerges and into which everything dissolves. Not a God "out there" — the very nature of awareness itself before any distinction arises.'},
  {n:2,name:'Śakti',skt:'शक्ति',group:'shiva',body:'The dynamic power of Śiva. Consciousness becoming aware of its own power. If Śiva is the screen, Śakti is the light. They are inseparable — Śiva without Śakti is a corpse; Śakti without Śiva has no ground. This is the first "movement" within the absolute.'},
  {n:3,name:'Sadāśiva',skt:'सदाशिव',group:'shiva',body:'The first moment of "I am this." Consciousness begins to sense a universe but the I dominates: "I AM... (and somehow there is a world)." The universe is still almost entirely absorbed in the subject. This is the tattva of cosmic will — Icchā Śakti predominant.'},
  {n:4,name:'Īśvara',skt:'ईश्वर',group:'shiva',body:'The balance shifts: "This I am." Subject and object are equal. This is the tattva of cosmic knowledge — Jñāna Śakti predominant. God as the omniscient witness of the universe, equally identified with both self and world.'},
  {n:5,name:'Sadvidyā',skt:'सद्विद्या',group:'shiva',body:'Pure knowledge. "I am this AND this is I." Subject and object are simultaneously grasped as one. Also called Śuddhavidyā — pure wisdom. The last tattva where unity is still perceived. Below this, the veil thickens.'},
  // Māyā and its five Kañcukas (6–11)
  {n:6,name:'Māyā',skt:'माया',group:'maya',body:'The great veil. Not illusion but the power of limitation — the force that makes the infinite appear finite, the undivided appear divided, the eternal appear temporal. Māyā does not destroy reality; it contracts it. Below Māyā, consciousness forgets its own nature.'},
  {n:7,name:'Kalā',skt:'कला',group:'maya',body:'First Kañcuka (sheath). The limitation of omnipotence. Infinite creativity becomes limited authorship. You can do SOME things, not all things. The bound soul experiences itself as a partial agent in a world it did not create and cannot fully control.'},
  {n:8,name:'Vidyā',skt:'विद्या',group:'maya',body:'Second Kañcuka. The limitation of omniscience. All-knowing becomes partial knowing. You know some things. You do not know most things. The bound soul is surrounded by mystery, ignorance, and the need to learn — because infinite knowledge has been contracted to a point.'},
  {n:9,name:'Rāga',skt:'राग',group:'maya',body:'Third Kañcuka. The limitation of complete fullness. The bound soul feels incomplete, desires, longs. Where the absolute IS fullness itself, the contracted soul SEEKS fullness. This is the root of all desire — not a flaw but the natural consequence of forgetting one\'s infinite nature.'},
  {n:10,name:'Kāla',skt:'काल',group:'maya',body:'Fourth Kañcuka. The limitation of eternity. Time appears. Before, now, after. Sequence. Mortality. The anxiety of running out of time. The absolute has no before or after — but the contracted soul lives entirely within the prison of sequence.'},
  {n:11,name:'Niyati',skt:'नियति',group:'maya',body:'Fifth Kañcuka. The limitation of omnipresence. Space appears. Here, there, near, far. The bound soul is located — this body, this place, this life. Where the absolute is everywhere simultaneously, the contracted soul is irreducibly here and not there.'},
  // Puruṣa and Prakṛti (12–13)
  {n:12,name:'Puruṣa',skt:'पुरुष',group:'purusha',body:'The bound individual soul — Śiva wrapped in the five sheaths, no longer recognising itself as Śiva. The experiencer. The witness who has forgotten he is the whole stage, the whole play, and all the actors.'},
  {n:13,name:'Prakṛti',skt:'प्रकृति',group:'purusha',body:'Primordial matter — the unmanifest root of all physical existence. Contains the three guṇas (sattva, rajas, tamas) in perfect equilibrium. When that equilibrium breaks, the universe of experience begins to unfold.'},
  // Intellect and Mind (14–16)
  {n:14,name:'Buddhi',skt:'बुद्धि',group:'antah',body:'Cosmic intellect — the faculty of determination and discernment. The capacity to decide, to know, to distinguish real from unreal. At the individual level: the discriminating intelligence that, when purified, can recognise the self.'},
  {n:15,name:'Ahaṃkāra',skt:'अहंकार',group:'antah',body:'The ego-principle — the faculty of self-identification. "I am this body, this name, this history." The necessary intermediate step between universal intelligence and individual experience. In itself not a flaw — only a problem when its boundaries are taken as final.'},
  {n:16,name:'Manas',skt:'मनस्',group:'antah',body:'The processing mind — sensory input, coordination, imagination. Receives raw data from the senses and presents it to buddhi for evaluation. The monkey mind of meditation tradition. Not the enemy — an instrument that needs a master.'},
  // Five sense capacities (17–21)
  {n:17,name:'Śrotra',skt:'श्रोत्र',group:'jnanendriya',body:'Capacity of hearing. Not the ear (physical organ) but the power of auditory cognition — the ability to receive and process sound as meaningful information.'},
  {n:18,name:'Tvak',skt:'त्वक्',group:'jnanendriya',body:'Capacity of touch. The power of tactile cognition — pressure, temperature, texture. The largest sense organ in terms of physical extent, and the first to develop in the embryo.'},
  {n:19,name:'Cakṣus',skt:'चक्षुस्',group:'jnanendriya',body:'Capacity of sight. The power of visual cognition. The tradition regards sight as the most "sattvic" of the five senses — the closest to pure knowledge, the most capable of extended range and precision.'},
  {n:20,name:'Rasanā',skt:'रसना',group:'jnanendriya',body:'Capacity of taste. The power of gustatory cognition. Connected in Āyurveda to the water element, and to the emotional palette of experience — rasa means both taste and aesthetic emotion.'},
  {n:21,name:'Ghrāṇa',skt:'घ्राण',group:'jnanendriya',body:'Capacity of smell. The power of olfactory cognition. Connected to the earth element. The most direct pathway to memory and emotion — the olfactory nerve is the only sensory pathway that bypasses the thalamus and connects directly to the limbic system.'},
  // Five action capacities (22–26)
  {n:22,name:'Vāk',skt:'वाक्',group:'karmendriya',body:'Capacity of speech. The power of articulate expression. Not just language but all purposive sound-making. The tradition regards vāk as the most powerful of the five action capacities — speech creates worlds.'},
  {n:23,name:'Pāṇi',skt:'पाणि',group:'karmendriya',body:'Capacity of grasping. The power of manipulation with the hands. The capacity that most distinguishes human agency in the physical world — building, making, transforming.'},
  {n:24,name:'Pāda',skt:'पाद',group:'karmendriya',body:'Capacity of locomotion. The power of directed movement through space. The ability to approach and to leave — to choose one\'s position in the physical world.'},
  {n:25,name:'Pāyu',skt:'पायु',group:'karmendriya',body:'Capacity of elimination. The power of releasing, discarding, purging. Not merely biological — the philosophical principle of knowing what to release. Retention without elimination is stagnation.'},
  {n:26,name:'Upastha',skt:'उपस्थ',group:'karmendriya',body:'Capacity of procreation and pleasure. The power of creation at the biological level and the experience of pleasure. Connected to the water element and the principle that creation requires delight.'},
  // Five subtle elements (27–31)
  {n:27,name:'Śabda',skt:'शब्द',group:'tanmatra',body:'Subtle element of sound — the tanmātra from which space (ākāśa) condenses. Not physical sound but the potentiality of sound, the principle of vibration before it becomes audible.'},
  {n:28,name:'Sparśa',skt:'स्पर्श',group:'tanmatra',body:'Subtle element of touch — the tanmātra from which air (vāyu) condenses. The principle of contact and pressure before it becomes physical sensation.'},
  {n:29,name:'Rūpa',skt:'रूप',group:'tanmatra',body:'Subtle element of form — the tanmātra from which fire (tejas) condenses. The principle of visibility, colour, and light before it becomes perceptible.'},
  {n:30,name:'Rasa',skt:'रस',group:'tanmatra',body:'Subtle element of taste — the tanmātra from which water (jala) condenses. The principle of flavour and feeling before it becomes sensory experience.'},
  {n:31,name:'Gandha',skt:'गन्ध',group:'tanmatra',body:'Subtle element of smell — the tanmātra from which earth (pṛthivī) condenses. The principle of identity and distinctness — each thing has its own unique "smell" before it has physical form.'},
  // Five gross elements (32–36)
  {n:32,name:'Ākāśa',skt:'आकाश',group:'mahabhuta',body:'Space — the first gross element. The container of all other elements. Neither created nor destroyed, it is the precondition for all physical existence. In modern physics: spacetime itself. In Vedic cosmology: the element closest to pure consciousness.'},
  {n:33,name:'Vāyu',skt:'वायु',group:'mahabhuta',body:'Air — movement, breath, the principle of dynamic change. In the body: prāṇa. In the cosmos: wind, atmosphere, the mediating element between the invisible (space) and the visible (fire, water, earth).'},
  {n:34,name:'Tejas',skt:'तेजस्',group:'mahabhuta',body:'Fire — transformation, digestion, perception. The element that converts one thing into another. In the body: metabolism, digestion, the eyes. In the cosmos: the Sun, stars, all sources of light and heat.'},
  {n:35,name:'Jala',skt:'जल',group:'mahabhuta',body:'Water — cohesion, flow, the principle of binding. The element that holds things together without rigidity. In the body: plasma, fluids, the tongue. In the cosmos: all liquids, and the gravitational binding of matter.'},
  {n:36,name:'Pṛthivī',skt:'पृथ्वी',group:'mahabhuta',body:'Earth — solidity, form, the principle of density and structure. The densest expression of consciousness. In the body: bones, tissue, the nose. In the cosmos: all solid matter. The furthest point of the descent — and the beginning of the return.'}
];

const AG_GROUPS={
  shiva:{color:'#E8D0FF',label:'Śiva Tattvas'},
  maya:{color:'#FF9040',label:'Māyā & Kañcukas'},
  purusha:{color:'#B48CFF',label:'Puruṣa & Prakṛti'},
  antah:{color:'#8CC8DC',label:'Antaḥkaraṇa'},
  jnanendriya:{color:'#DCB450',label:'Jñānendriyas'},
  karmendriya:{color:'#90C890',label:'Karmendriyas'},
  tanmatra:{color:'#C89090',label:'Tanmātras'},
  mahabhuta:{color:'#A09070',label:'Mahābhūtas'}
};

let agCanvas=null,agCtx=null,agFrame=null,agHover=null,agT=0,agNodes=[];
let agScale=1,agOffY=0;

function openAbhinavagupta(){
  document.getElementById('ag-ov').classList.add('on');
  setTimeout(agInit,80);
}
function closeAbhinavagupta(){
  document.getElementById('ag-ov').classList.remove('on');
  if(agFrame){cancelAnimationFrame(agFrame);agFrame=null;}
}
function agInit(){
  agCanvas=document.getElementById('ag-canvas');
  if(!agCanvas)return;
  const dpr=window.devicePixelRatio||1;
  const W=agCanvas.offsetWidth,H=agCanvas.offsetHeight;
  agCanvas.width=W*dpr;agCanvas.height=H*dpr;
  agCtx=agCanvas.getContext('2d');agCtx.scale(dpr,dpr);
  // Build node positions — vertical cascade, left of panel
  const pw=window.innerWidth>768?320:0;
  const cw=W-pw,rowH=H/10,cx=cw/2;
  const groupOrder=['shiva','maya','purusha','antah','jnanendriya','karmendriya','tanmatra','mahabhuta'];
  let row=0;
  agNodes=[];
  groupOrder.forEach(g=>{
    const ts=AG_TATTVAS.filter(t=>t.group===g);
    ts.forEach((t,i)=>{
      const cols=ts.length;
      const x=cx+(i-(cols-1)/2)*(cw*0.85/cols);
      const y=80+row*rowH+(rowH*0.5);
      agNodes.push({t,x,y,r:20,hov:false});
    });
    row++;
  });
  agCanvas.onclick=agClick;
  agCanvas.onmousemove=agMouseMove;
  agCanvas.onmouseleave=()=>{agHover=null;};
  if(agFrame)cancelAnimationFrame(agFrame);
  agFrame=requestAnimationFrame(agLoop);
}
function agLoop(){
  if(!agCanvas||!agCtx)return;
  agT+=0.01;
  const dpr=window.devicePixelRatio||1;
  const W=agCanvas.width/dpr,H=agCanvas.height/dpr;
  agCtx.clearRect(0,0,W,H);
  // Draw connections between consecutive groups
  for(let i=1;i<agNodes.length;i++){
    const a=agNodes[i-1],b=agNodes[i];
    if(a.t.group===b.t.group||(i>0&&agNodes[i-1].t.group!==agNodes[i].t.group)){
      agCtx.beginPath();agCtx.moveTo(a.x,a.y);agCtx.lineTo(b.x,b.y);
      const c=AG_GROUPS[a.t.group].color;
      agCtx.strokeStyle=c+'18';agCtx.lineWidth=1;agCtx.stroke();
    }
  }
  agNodes.forEach(nd=>{
    const c=AG_GROUPS[nd.t.group].color;
    const isHov=agHover===nd.t.n;
    const nr=isHov?26:20;
    if(isHov){
      const gl=agCtx.createRadialGradient(nd.x,nd.y,nr*.4,nd.x,nd.y,nr*2.5);
      gl.addColorStop(0,c+'35');gl.addColorStop(1,'rgba(0,0,0,0)');
      agCtx.beginPath();agCtx.arc(nd.x,nd.y,nr*2.5,0,Math.PI*2);
      agCtx.fillStyle=gl;agCtx.fill();
    }
    agCtx.beginPath();agCtx.arc(nd.x,nd.y,nr,0,Math.PI*2);
    agCtx.fillStyle=isHov?c+'22':c+'0E';agCtx.fill();
    agCtx.strokeStyle=isHov?c:c+'55';agCtx.lineWidth=isHov?1.5:1;agCtx.stroke();
    // Number
    agCtx.fillStyle=isHov?c:'rgba(180,160,220,.4)';
    agCtx.font=`${isHov?'500 ':''}9px IBM Plex Mono,monospace`;
    agCtx.textAlign='center';agCtx.textBaseline='middle';
    agCtx.fillText(nd.t.n,nd.x,nd.y-4);
    agCtx.font='8px Cinzel,serif';
    agCtx.fillText(nd.t.name,nd.x,nd.y+6);
  });
  // Group labels on left
  const groupOrder=['shiva','maya','purusha','antah','jnanendriya','karmendriya','tanmatra','mahabhuta'];
  const pw=window.innerWidth>768?320:0;
  const cw=(agCanvas.width/(window.devicePixelRatio||1))-pw;
  groupOrder.forEach((g,i)=>{
    const rowH=(agCanvas.height/(window.devicePixelRatio||1))/10;
    const y=80+i*rowH+rowH*.5;
    agCtx.fillStyle=AG_GROUPS[g].color+'55';
    agCtx.font='6px IBM Plex Mono,monospace';
    agCtx.textAlign='left';agCtx.textBaseline='middle';
    agCtx.fillText(AG_GROUPS[g].label.toUpperCase(),8,y);
  });
  agFrame=requestAnimationFrame(agLoop);
}
function agMouseMove(e){
  if(!agCanvas)return;
  const rect=agCanvas.getBoundingClientRect();
  const mx=e.clientX-rect.left,my=e.clientY-rect.top;
  agHover=null;
  agNodes.forEach(nd=>{if(Math.hypot(mx-nd.x,my-nd.y)<nd.r+6)agHover=nd.t.n;});
  agCanvas.style.cursor=agHover?'pointer':'crosshair';
}
function agClick(e){
  if(!agCanvas)return;
  const rect=agCanvas.getBoundingClientRect();
  const mx=e.clientX-rect.left,my=e.clientY-rect.top;
  let hit=null;
  agNodes.forEach(nd=>{if(Math.hypot(mx-nd.x,my-nd.y)<nd.r+6)hit=nd.t;});
  if(!hit)return;
  const c=AG_GROUPS[hit.group].color;
  document.getElementById('ag-panel-num').textContent='Tattva '+hit.n+' · '+AG_GROUPS[hit.group].label;
  document.getElementById('ag-panel-num').style.color=c+'99';
  document.getElementById('ag-panel-title').textContent=hit.name;
  document.getElementById('ag-panel-title').style.color=c;
  document.getElementById('ag-panel-skt').textContent=hit.skt;
  document.getElementById('ag-panel-skt').style.color=c+'66';
  document.getElementById('ag-panel-body').textContent=hit.body;
}
window.openAbhinavagupta=openAbhinavagupta;
window.closeAbhinavagupta=closeAbhinavagupta;
})();

// ═══════════════════════════════════════════════════════
//  ŚĀSTRARTHA STAGE
// ═══════════════════════════════════════════════════════
(function(){
const SS_SCRIPT=[
  {speaker:'narrator',text:'788 CE. A small town in what is now Madhya Pradesh. Maṇḍana Miśra — the greatest living scholar of Mīmāṃsā — sits in his courtyard. He has never lost a debate. His wife, Ubhayabhāratī, is said to be more learned than he is. A young sannyāsi, barely sixteen years old, appears at his gate.'},
  {speaker:'narrator',text:'This young man is Śaṅkarācārya. He has already written commentaries on the Brahmasūtras, the Upanishads, and the Gita. He has walked the length of India. He is here for one reason: to challenge Maṇḍana Miśra to a formal philosophical debate — a śāstrartha — on the most fundamental question in Indian philosophy.'},
  {speaker:'shankara',text:'"Maṇḍana Miśra. The question before us is this: is liberation achieved through ritual action — karma — as your tradition holds? Or through the direct knowledge that Brahman alone is real — as mine does? I propose that we debate this until one of us is defeated. Ubhayabhāratī shall be the judge."'},
  {speaker:'mandana',text:'"I accept. But know this: I have heard your arguments before. The Advaita position is clever. It is not, however, true. The Vedas prescribe action. Every word of the karma-kāṇḍa is an injunction — a command to act. To dismiss ritual as secondary is to dismiss the Vedas themselves. And the Vedas are eternal."'},
  {speaker:'shankara',text:'"The Vedas are not dismissed — they are understood correctly. The karma-kāṇḍa addresses the bound soul, the soul that believes it is separate from Brahman. The jñāna-kāṇḍa — the Upanishads — addresses the same soul and says: your bondage is not real. You were never bound. No action can liberate you from a bondage that does not exist."'},
  {speaker:'mandana',text:'"Beautiful poetry. But consider: if you were never bound, why do you suffer? Why does the world appear? Why is ignorance so powerful and so persistent? Your position requires you to explain the appearance of bondage without giving it any reality. That is not philosophy — it is a word game."'},
  {speaker:'shankara',text:'"The dream-argument. You dream. In the dream, you suffer. The suffering is real within the dream. When you wake, you do not ask: but where is the dream-pain now? It is gone — not because it was annihilated, but because it was never real in the waking sense. Saṃsāra is exactly this. Vivid. Functional. Not ultimately real."'},
  {speaker:'mandana',text:'"But the waker is different from the dreamer. Who wakes from saṃsāra? If the jīva is Brahman, who is ignorant? Brahman cannot be ignorant — Brahman is pure awareness. The jīva cannot be ignorant of its own nature — that would make the ignorance real. Your position cannot identify who is ignorant without destroying itself."'},
  {speaker:'narrator',text:'The debate continues for seventeen days. Ubhayabhāratī listens without expression. The parrots in the courtyard, having heard the arguments repeated, begin to recite fragments of the Brahmasūtras.'},
  {speaker:'shankara',text:'"The question of who is ignorant is like asking: where is the darkness, exactly, when the lamp is lit? You cannot point to the darkness because it has no positive existence. It is only the absence of light. Ignorance similarly has no locus — it appears to belong to the jīva, but the jīva is Brahman, and when Brahman is recognised, the question of where ignorance resided dissolves with the ignorance itself."'},
  {speaker:'mandana',text:'"And yet you — this body, this monk, this voice — are here, arguing with me. If you know Brahman, why is there a you? Why is there a me? Why is there this argument? The appearance of duality is persistent and total. You cannot dismiss it with a lamp analogy."'},
  {speaker:'shankara',text:'"I do not dismiss the appearance. I explain its nature. The appearance of duality continues for the jīvanmukta — the one liberated while living — just as the phantom limb pain continues for the amputee. The appearance does not constitute reality. The liberated one acts in the world, speaks, debates — as I am doing now — while knowing that the actor, the speech, and the debate are all Brahman appearing as multiplicity."'},
  {speaker:'ubhaya',text:'"Maṇḍana. I have listened for seventeen days. The young sannyāsi\'s arguments are sound. Your strongest objection — the question of who is ignorant — he has answered, not completely, but sufficiently. I declare him the victor of this debate."'},
  {speaker:'mandana',text:'"Then I accept defeat. I will take sannyāsa. I will study under this boy who has defeated me." — He pauses. — "But my wife has not yet spoken on the question she wished to raise."'},
  {speaker:'ubhaya',text:'"Śaṅkara. You are a renunciate monk who left home as a child. You have never been a householder. There is an entire domain of knowledge — the science of love, the kāmaśāstra, the full knowledge of the householder life — that you cannot possess. And yet you claim to have understood all of reality. A map with a blank region is not a complete map."'},
  {speaker:'narrator',text:'Śaṅkara requests time. He finds a recently deceased king, temporarily enters his body using the yogic power of parakāya praveśa, and spends months as a householder learning what he could not otherwise know. He returns. The debate concludes. Maṇḍana Miśra becomes Sureśvara — one of Śaṅkara\'s four principal disciples. The tradition holds that this debate established Advaita Vedānta as the dominant school of Indian philosophy for the next twelve centuries.'},
  {speaker:'narrator',text:'What Ubhayabhāratī\'s challenge reveals: no single position, however logically complete, can claim to have understood all of reality from one vantage point. The debate is not merely a historical event. It is the permanent condition of human understanding.'}
];

let ssCanvas=null,ssCtx=null,ssFrame=null,ssT=0,ssLines=[],ssIdx=0,ssChosen=null,ssScore={s:50,m:50};

function openShastrArtha(){
  document.getElementById('ss-ov').classList.add('on');
  setTimeout(ssInit,80);
}
function closeShastrArtha(){
  document.getElementById('ss-ov').classList.remove('on');
  if(ssFrame){cancelAnimationFrame(ssFrame);ssFrame=null;}
}
function ssInit(){
  ssCanvas=document.getElementById('ss-stage-canvas');
  if(!ssCanvas)return;
  const dpr=window.devicePixelRatio||1;
  ssCanvas.width=ssCanvas.offsetWidth*dpr;
  ssCanvas.height=ssCanvas.offsetHeight*dpr;
  ssCtx=ssCanvas.getContext('2d');ssCtx.scale(dpr,dpr);
  ssLines=[];ssIdx=0;ssChosen=null;ssScore={s:50,m:50};
  document.getElementById('ss-debate-wrap').innerHTML='';
  document.getElementById('ss-bar-s').style.width='50%';
  document.getElementById('ss-bar-m').style.width='50%';
  document.getElementById('ss-choice-wrap').style.display='none';
  document.getElementById('ss-progress-lbl').textContent='';
  if(ssFrame)cancelAnimationFrame(ssFrame);
  ssFrame=requestAnimationFrame(ssLoop);
  ssAdvance();
}
function ssLoop(){
  if(!ssCanvas||!ssCtx)return;
  ssT+=0.012;
  const dpr=window.devicePixelRatio||1;
  const W=ssCanvas.width/dpr,H=ssCanvas.height/dpr;
  ssCtx.clearRect(0,0,W,H);
  // Background — flickering torchlight effect
  const flicker=0.03+Math.sin(ssT*7)*0.015+Math.sin(ssT*13)*0.01;
  const bg=ssCtx.createRadialGradient(W*.35,H*.4,0,W*.35,H*.4,W*.7);
  bg.addColorStop(0,`rgba(40,28,12,${flicker+0.06})`);
  bg.addColorStop(0.4,`rgba(20,14,6,${flicker+0.02})`);
  bg.addColorStop(1,'rgba(4,3,1,0)');
  ssCtx.fillStyle=bg;ssCtx.fillRect(0,0,W,H);
  // Two silhouettes
  ssSilhouette(ssCtx,W*.22,H*.72,H*.38,'#C9A84C',ssT,'shankara');
  ssSilhouette(ssCtx,W*.65,H*.72,H*.38,'#90C890',ssT+1.5,'mandana');
  // Ground line
  ssCtx.beginPath();ssCtx.moveTo(0,H*.72);ssCtx.lineTo(W,H*.72);
  ssCtx.strokeStyle='rgba(201,168,76,0.08)';ssCtx.lineWidth=1;ssCtx.stroke();
  ssFrame=requestAnimationFrame(ssLoop);
}
function ssSilhouette(ctx,x,y,h,col,t,role){
  const breathe=Math.sin(t*0.8)*0.008;
  ctx.save();ctx.translate(x,y);ctx.scale(1+breathe,1-breathe*.5);
  // Body
  const g=ctx.createLinearGradient(0,-h,0,0);
  g.addColorStop(0,col+'30');g.addColorStop(1,col+'08');
  ctx.fillStyle=g;
  ctx.beginPath();
  ctx.moveTo(-h*.12,0);ctx.lineTo(-h*.08,-h*.55);
  ctx.lineTo(-h*.05,-h*.7);ctx.lineTo(0,-h*.72);
  ctx.lineTo(h*.05,-h*.7);ctx.lineTo(h*.08,-h*.55);
  ctx.lineTo(h*.12,0);ctx.closePath();ctx.fill();
  // Head
  ctx.beginPath();ctx.arc(0,-h*.78,h*.09,0,Math.PI*2);
  ctx.fillStyle=col+'25';ctx.fill();
  ctx.restore();
}
function ssAdvance(){
  if(ssIdx>=SS_SCRIPT.length)return;
  const line=SS_SCRIPT[ssIdx];
  ssIdx++;
  const wrap=document.getElementById('ss-debate-wrap');
  const div=document.createElement('div');
  div.className='ss-line';
  div.innerHTML=`<div class="ss-speaker ${line.speaker}">${line.speaker.toUpperCase()}</div><div class="ss-text ${line.speaker}">${line.text}</div>`;
  wrap.appendChild(div);
  setTimeout(()=>{div.classList.add('vis');},50);
  // Scroll into view
  setTimeout(()=>{div.scrollIntoView({behavior:'smooth',block:'end'});},200);
  // Update score
  if(line.speaker==='shankara'){ssScore.s=Math.min(70,ssScore.s+3);ssScore.m=Math.max(30,ssScore.m-3);}
  if(line.speaker==='mandana'){ssScore.m=Math.min(70,ssScore.m+3);ssScore.s=Math.max(30,ssScore.s-3);}
  if(line.speaker==='ubhaya'){ssScore.s=68;ssScore.m=32;}
  document.getElementById('ss-bar-s').style.width=ssScore.s+'%';
  document.getElementById('ss-bar-m').style.width=ssScore.m+'%';
  document.getElementById('ss-progress-lbl').textContent=ssIdx+' / '+SS_SCRIPT.length;
  // Show choice prompts at philosophical turning points
  if(ssIdx===5||ssIdx===9||ssIdx===13){
    document.getElementById('ss-choice-wrap').style.display='';
  }
  // Auto-advance with delay
  if(ssIdx<SS_SCRIPT.length){
    const delay=line.speaker==='narrator'?4200:3200;
    setTimeout(ssAdvance,delay);
  }
}
function ssChoose(side){
  ssChosen=side;
  document.getElementById('ss-btn-s').classList.toggle('chosen',side==='shankara');
  document.getElementById('ss-btn-m').classList.toggle('chosen',side==='mandana');
}
window.openShastrArtha=openShastrArtha;
window.closeShastrArtha=closeShastrArtha;
window.ssChoose=ssChoose;
})();

