// ─── cosmos initialisation ─────────────────────────────────────────────
function tbInitCosmos(){
  tbStars.length=0; tbDust.length=0; tbNebulae.length=0; tbShooting.length=0;
  for(var i=0;i<140;i++){
    tbStars.push({
      x:Math.random(), y:Math.random(),
      r:0.3 + Math.random()*1.8,
      tw:Math.random()*Math.PI*2,
      twS: 0.4 + Math.random()*1.4,
      layer: Math.floor(Math.random()*4),
      hue: Math.random()<0.18 ? (200+Math.random()*60) : (40+Math.random()*30)
    });
  }
  for(var n=0;n<5;n++){
    tbNebulae.push({
      x:Math.random(), y:0.1 + Math.random()*0.8,
      r: 0.16 + Math.random()*0.20,
      hue: [260,280,200,30,330][n],
      drift: 0.02 + Math.random()*0.04,
      ph: Math.random()*Math.PI*2
    });
  }
  for(var d=0;d<60;d++){
    tbDust.push({
      x:Math.random(), y:Math.random(),
      r:0.4+Math.random()*0.8,
      vx:(-0.5+Math.random())*0.00012,
      vy:(-0.5+Math.random())*0.00012,
      a:0.05+Math.random()*0.18
    });
  }
}

// ─── torus particle init: 3 bands flowing in fountain pattern ──────────
function tbInitTorus(){
  tbTorusParticles.length=0;
  // Three rings (bands) of particles each at a different radius/elevation cycle
  for(var ring=0; ring<3; ring++){
    for(var i=0; i<70; i++){
      var phase = Math.random() * Math.PI*2;
      var theta = Math.random() * Math.PI*2; // around the vertical axis
      tbTorusParticles.push({
        phase: phase,
        theta: theta,
        ring: ring,
        speed: 0.55 + ring*0.20 + Math.random()*0.15,
        rPhase: Math.random()*Math.PI*2,
        size: 1.0 + Math.random()*1.4,
        hueShift: Math.random()*40 - 20
      });
    }
  }
  tbSushumnaParticles.length=0;
  for(var s=0;s<32;s++){
    tbSushumnaParticles.push({
      y: Math.random(),
      v: 0.0030 + Math.random()*0.0050,
      size: 1.2 + Math.random()*1.8,
      ph: Math.random()*Math.PI*2
    });
  }
}

// ─── canvas resize ────────────────────────────────────────────────────
function tbResize(){
  if(!tbCanvas || !tbCtx) return;
  var rect=tbCanvas.getBoundingClientRect();
  tbDPR=Math.min(window.devicePixelRatio||1, 1.5);   // cap at 1.5 — halves retina cost
  tbW=Math.max(320,Math.floor(rect.width));
  tbH=Math.max(480,Math.floor(rect.height));
  tbCanvas.width=Math.floor(tbW*tbDPR);
  tbCanvas.height=Math.floor(tbH*tbDPR);
  tbCanvas.style.width=tbW+'px';
  tbCanvas.style.height=tbH+'px';
  tbCtx.setTransform(tbDPR,0,0,tbDPR,0,0);
}
function tbResizeGuarded(){
  if(typeof guardedResize==='function'){ guardedResize(tbResize,200); }
  else{ clearTimeout(tbResizeTimer); tbResizeTimer=setTimeout(tbResize,200); }
}

// ─── helpers ─────────────────────────────────────────────────────────
function tbTau(){ return (performance.now()-tbT0)/1000; }
function tbBreathScale(){
  // breath-modulated radius scalar (1.0 ± amplitude)
  var t = tbTau();
  if(tbBreathOn){
    // 16s sama-vritti cycle: 4 inhale (expand), 4 hold (expanded), 4 exhale (contract), 4 hold (contracted)
    var bt = ((performance.now()-tbBreathT0)/1000) % 16;
    var s;
    if(bt < 4)       { s = bt/4; }
    else if(bt < 8)  { s = 1; }
    else if(bt < 12) { s = 1 - (bt-8)/4; }
    else             { s = 0; }
    return 0.86 + 0.16*s;
  }
  // gentle ambient breath at rest (~6 sec cycle)
  return 0.94 + 0.06 * Math.sin(t * 1.05);
}

function tbBreathPhaseLabel(){
  if(!tbBreathOn) return '';
  var bt = ((performance.now()-tbBreathT0)/1000) % 16;
  if(bt < 4)       return ['IN','PŪRAKA',bt,4];
  else if(bt < 8)  return ['HOLD','KUMBHAKA',bt-4,4];
  else if(bt < 12) return ['OUT','RECAKA',bt-8,4];
  else             return ['HOLD','BĀHYA',bt-12,4];
}
// ════════════════════════════════════════════════════════════════════════
// COSMOS — the rotating starfield, nebulae, dust, shooting stars
// ════════════════════════════════════════════════════════════════════════
function tbDrawCosmos(){
  if(!tbCtx) return;
  var t = tbTau();
  // base deep-indigo gradient
  var bg = tbCtx.createRadialGradient(tbW*0.5, tbH*0.42, tbW*0.05, tbW*0.5, tbH*0.50, tbW*0.95);
  bg.addColorStop(0, '#1a1530');
  bg.addColorStop(0.45,'#0c0a22');
  bg.addColorStop(1,   '#02010a');
  tbCtx.fillStyle = bg;
  tbCtx.fillRect(0,0,tbW,tbH);

  // ── slow-rotating Milky Way band
  tbCtx.save();
  tbCtx.translate(tbW*0.5, tbH*0.55);
  tbCtx.rotate(-0.32 + Math.sin(t*0.03)*0.04);
  var mw = tbCtx.createLinearGradient(-tbW*0.85, 0, tbW*0.85, 0);
  mw.addColorStop(0,   'rgba(120,90,200,0.0)');
  mw.addColorStop(0.30,'rgba(180,140,240,0.13)');
  mw.addColorStop(0.50,'rgba(220,200,255,0.18)');
  mw.addColorStop(0.70,'rgba(180,140,240,0.13)');
  mw.addColorStop(1,   'rgba(120,90,200,0.0)');
  tbCtx.fillStyle = mw;
  tbCtx.fillRect(-tbW*0.9, -tbH*0.08, tbW*1.8, tbH*0.16);
  tbCtx.restore();

  // ── nebulae (drifting glow clouds)
  tbCtx.globalCompositeOperation='lighter';
  for(var n=0; n<tbNebulae.length; n++){
    var nb = tbNebulae[n];
    var pulse = 0.7 + 0.3 * Math.sin(t*nb.drift*10 + nb.ph);
    var nx = (nb.x + Math.sin(t*nb.drift)*0.05) * tbW;
    var ny = (nb.y + Math.cos(t*nb.drift*0.7)*0.03) * tbH;
    var nr = nb.r * tbW * pulse;
    var ng = tbCtx.createRadialGradient(nx, ny, 0, nx, ny, nr);
    ng.addColorStop(0,   'hsla('+nb.hue+',70%,55%,0.18)');
    ng.addColorStop(0.4, 'hsla('+nb.hue+',60%,40%,0.07)');
    ng.addColorStop(1,   'hsla('+nb.hue+',60%,40%,0)');
    tbCtx.fillStyle = ng;
    tbCtx.beginPath(); tbCtx.arc(nx, ny, nr, 0, Math.PI*2); tbCtx.fill();
  }
  tbCtx.globalCompositeOperation='source-over';

  // ── stars (twinkling, parallax-drifting)
  for(var i=0; i<tbStars.length; i++){
    var s = tbStars[i];
    s.tw += 0.015 * s.twS;
    var alpha = 0.35 + 0.55 * (0.5 + 0.5*Math.sin(s.tw));
    var driftX = Math.sin(t*0.04 + s.layer)*0.005;
    var sx = ((s.x + driftX) % 1) * tbW;
    var sy = s.y * tbH;
    tbCtx.fillStyle = 'hsla('+s.hue+', 70%, 88%, '+alpha+')';
    tbCtx.beginPath();
    tbCtx.arc(sx, sy, s.r, 0, Math.PI*2);
    tbCtx.fill();
    if(s.r > 1.3 && alpha > 0.75){
      // star spike
      tbCtx.strokeStyle = 'hsla('+s.hue+',80%,90%,'+alpha*0.55+')';
      tbCtx.lineWidth = 0.5;
      tbCtx.beginPath();
      tbCtx.moveTo(sx-s.r*3, sy); tbCtx.lineTo(sx+s.r*3, sy);
      tbCtx.moveTo(sx, sy-s.r*3); tbCtx.lineTo(sx, sy+s.r*3);
      tbCtx.stroke();
    }
  }

  // ── dust (slow drift)
  for(var d=0; d<tbDust.length; d++){
    var du = tbDust[d];
    du.x += du.vx; du.y += du.vy;
    if(du.x<0) du.x=1; if(du.x>1) du.x=0;
    if(du.y<0) du.y=1; if(du.y>1) du.y=0;
    tbCtx.fillStyle = 'rgba(220,210,250,'+du.a+')';
    tbCtx.beginPath();
    tbCtx.arc(du.x*tbW, du.y*tbH, du.r, 0, Math.PI*2);
    tbCtx.fill();
  }

  // ── occasional shooting star
  if(Math.random() < 0.0028){
    tbShooting.push({
      x: Math.random()*0.9, y: 0.05 + Math.random()*0.4,
      vx: 0.008 + Math.random()*0.012,
      vy: 0.004 + Math.random()*0.006,
      life: 1.0
    });
  }
  for(var ss = tbShooting.length-1; ss>=0; ss--){
    var sh = tbShooting[ss];
    sh.x += sh.vx; sh.y += sh.vy; sh.life -= 0.018;
    if(sh.life <= 0){ tbShooting.splice(ss,1); continue; }
    var sx2 = sh.x*tbW, sy2 = sh.y*tbH;
    var tx = sx2 - sh.vx*tbW*16, ty = sy2 - sh.vy*tbH*16;
    var sg = tbCtx.createLinearGradient(tx,ty, sx2,sy2);
    sg.addColorStop(0,'rgba(255,240,200,0)');
    sg.addColorStop(1,'rgba(255,240,200,'+sh.life+')');
    tbCtx.strokeStyle = sg;
    tbCtx.lineWidth = 1.5;
    tbCtx.beginPath(); tbCtx.moveTo(tx,ty); tbCtx.lineTo(sx2,sy2); tbCtx.stroke();
    tbCtx.fillStyle='rgba(255,250,220,'+sh.life+')';
    tbCtx.beginPath(); tbCtx.arc(sx2,sy2,1.4,0,Math.PI*2); tbCtx.fill();
  }
}

// ════════════════════════════════════════════════════════════════════════
// SCALE HINT — the same torus pattern at every scale (atom→galaxy)
// ════════════════════════════════════════════════════════════════════════
function tbDrawScaleHint(cx, cy, R){
  if(!tbCtx) return;
  var t = tbTau();
  tbCtx.save();

  if(tbScale === 0){
    // ATOM — 3 electron orbits in 3D-ish ellipses around the body
    for(var o=0; o<3; o++){
      var phase = t*1.2 + o*Math.PI*2/3;
      var tilt = 0.42 + o*0.15;
      var orad = R*(1.05 + o*0.16);
      tbCtx.strokeStyle = 'rgba(120,200,255,'+(0.16 - o*0.03)+')';
      tbCtx.lineWidth = 1;
      tbCtx.beginPath();
      tbCtx.ellipse(cx, cy, orad, orad*tilt, o*0.6, 0, Math.PI*2);
      tbCtx.stroke();
      // electron-glow on the orbit
      var ex = cx + Math.cos(phase) * orad;
      var ey = cy + Math.sin(phase) * orad*tilt;
      var gg = tbCtx.createRadialGradient(ex,ey,0,ex,ey,16);
      gg.addColorStop(0,'rgba(160,220,255,0.85)');
      gg.addColorStop(1,'rgba(160,220,255,0)');
      tbCtx.fillStyle = gg;
      tbCtx.beginPath(); tbCtx.arc(ex,ey,16,0,Math.PI*2); tbCtx.fill();
    }
  }

  else if(tbScale === 1){
    // CELL — paired centrosomes + radial mitotic spindle
    var sp = R*1.15, dx = R*0.85;
    for(var s=0;s<2;s++){
      var x = cx + (s? dx : -dx), y = cy;
      var pulse = 0.7 + 0.3*Math.sin(t*1.8);
      var cg = tbCtx.createRadialGradient(x,y,0,x,y,28);
      cg.addColorStop(0,'rgba(180,240,200,'+(0.6*pulse)+')');
      cg.addColorStop(1,'rgba(180,240,200,0)');
      tbCtx.fillStyle = cg;
      tbCtx.beginPath(); tbCtx.arc(x,y,28,0,Math.PI*2); tbCtx.fill();
      // spindle fibres
      tbCtx.strokeStyle = 'rgba(180,240,200,0.10)';
      tbCtx.lineWidth = 0.7;
      for(var f=0;f<24;f++){
        var ang = (f/24)*Math.PI*2 + t*0.1;
        var ex = x + Math.cos(ang)*sp;
        var ey = y + Math.sin(ang)*sp*0.85;
        tbCtx.beginPath(); tbCtx.moveTo(x,y); tbCtx.lineTo(ex,ey); tbCtx.stroke();
      }
    }
  }

  else if(tbScale === 2){
    // ORGAN — heart electromagnetic field (oblate radiating from chest)
    var hx = cx, hy = cy - R*0.18;
    var pulse = 0.85 + 0.15*Math.abs(Math.sin(t*1.6));
    for(var f=4; f>=0; f--){
      var rr = R*(0.7 + f*0.18) * pulse;
      tbCtx.strokeStyle = 'rgba(255,90,130,'+(0.13 - f*0.022)+')';
      tbCtx.lineWidth = 1;
      tbCtx.beginPath();
      tbCtx.ellipse(hx, hy, rr*1.2, rr*0.85, 0, 0, Math.PI*2);
      tbCtx.stroke();
    }
    // ECG trace
    tbCtx.strokeStyle = 'rgba(255,140,170,0.45)';
    tbCtx.lineWidth = 1.2;
    tbCtx.beginPath();
    var ecgY = cy + R*0.95;
    for(var x=0; x<tbW; x+=4){
      var phase = (x*0.02 + t*2.4) % 6;
      var y = ecgY;
      if(phase < 0.25) y -= 4;
      else if(phase < 0.40) y -= 25 * Math.sin((phase-0.25)/0.15 * Math.PI);
      else if(phase < 0.55) y += 10 * Math.sin((phase-0.40)/0.15 * Math.PI);
      tbCtx.lineTo(x, y);
    }
    tbCtx.stroke();
  }

  else if(tbScale === 3){
    // BODY (default) — just the aura halo, the body itself takes over
    var ag = tbCtx.createRadialGradient(cx, cy, R*0.3, cx, cy, R*1.4);
    ag.addColorStop(0,'rgba(255,225,180,0.08)');
    ag.addColorStop(1,'rgba(255,225,180,0)');
    tbCtx.fillStyle = ag;
    tbCtx.beginPath(); tbCtx.arc(cx, cy, R*1.4, 0, Math.PI*2); tbCtx.fill();
  }

  else if(tbScale === 4){
    // EARTH — magnetosphere lines (8 nested teardrop ellipses) + earth disc
    for(var m=0;m<8;m++){
      var rr = R*(1 + m*0.12);
      var pulse2 = 0.92 + 0.08*Math.sin(t*0.8 + m*0.4);
      tbCtx.strokeStyle = 'rgba(120,180,255,'+(0.12 - m*0.012)+')';
      tbCtx.lineWidth = 1;
      tbCtx.beginPath();
      tbCtx.ellipse(cx + R*0.2*m*0.1, cy, rr*pulse2*1.05, rr*pulse2*0.92, 0, 0, Math.PI*2);
      tbCtx.stroke();
    }
    // a faint earth-disc behind the body
    var eg = tbCtx.createRadialGradient(cx, cy, 0, cx, cy, R*0.65);
    eg.addColorStop(0,'rgba(80,140,200,0.16)');
    eg.addColorStop(0.6,'rgba(60,100,150,0.08)');
    eg.addColorStop(1,'rgba(40,70,110,0)');
    tbCtx.fillStyle = eg;
    tbCtx.beginPath(); tbCtx.arc(cx,cy,R*0.65,0,Math.PI*2); tbCtx.fill();
  }

  else if(tbScale === 5){
    // SOLAR — corona blazes around the body
    for(var k=4;k>=0;k--){
      var rr2 = R*(1.0 + k*0.22);
      var pulse3 = 0.88 + 0.12*Math.sin(t*0.9 + k*0.3);
      var cg2 = tbCtx.createRadialGradient(cx,cy, rr2*0.5, cx,cy, rr2*pulse3);
      cg2.addColorStop(0,'rgba(255,180,80,0)');
      cg2.addColorStop(0.75,'rgba(255,180,80,'+(0.14 - k*0.025)+')');
      cg2.addColorStop(1,'rgba(255,140,40,0)');
      tbCtx.fillStyle = cg2;
      tbCtx.beginPath(); tbCtx.arc(cx,cy,rr2*pulse3,0,Math.PI*2); tbCtx.fill();
    }
    // sun flares
    for(var fl=0;fl<28;fl++){
      var ang = (fl/28)*Math.PI*2 + t*0.05;
      var len = R*(1.4 + 0.25*Math.sin(t*1.3 + fl));
      var x1 = cx + Math.cos(ang)*R*0.95, y1 = cy + Math.sin(ang)*R*0.95;
      var x2 = cx + Math.cos(ang)*len,    y2 = cy + Math.sin(ang)*len;
      tbCtx.strokeStyle = 'rgba(255,200,100,0.13)';
      tbCtx.lineWidth = 1;
      tbCtx.beginPath(); tbCtx.moveTo(x1,y1); tbCtx.lineTo(x2,y2); tbCtx.stroke();
    }
  }

  else if(tbScale === 6){
    // GALAXY — 4 spiral arms unwinding from body's centre
    tbCtx.save();
    tbCtx.translate(cx, cy);
    tbCtx.rotate(t*0.05);
    for(var arm=0; arm<4; arm++){
      tbCtx.rotate(Math.PI/2);
      tbCtx.beginPath();
      var pts = 60;
      for(var pt=0; pt<pts; pt++){
        var theta2 = pt * 0.16;
        var radius = R*0.3 + pt * R*0.05;
        var sx2 = Math.cos(theta2) * radius;
        var sy2 = Math.sin(theta2) * radius;
        if(pt===0) tbCtx.moveTo(sx2,sy2); else tbCtx.lineTo(sx2,sy2);
      }
      tbCtx.strokeStyle = 'rgba(200,180,255,0.20)';
      tbCtx.lineWidth = 2.4;
      tbCtx.stroke();
      // arm dust
      for(var pp=0; pp<70; pp++){
        var th3 = pp * 0.16 + Math.random()*0.04;
        var rr3 = R*0.3 + pp * R*0.05 + (Math.random()-0.5)*R*0.04;
        var px = Math.cos(th3)*rr3;
        var py = Math.sin(th3)*rr3;
        var hue = pp<25 ? 50 : (pp<45 ? 280 : 220);
        tbCtx.fillStyle = 'hsla('+hue+',70%,80%,'+(0.5 - pp*0.005)+')';
        tbCtx.beginPath(); tbCtx.arc(px,py, 0.8+Math.random()*0.6, 0, Math.PI*2); tbCtx.fill();
      }
    }
    // galactic core
    var corG = tbCtx.createRadialGradient(0,0,0,0,0,R*0.3);
    corG.addColorStop(0,'rgba(255,220,150,0.85)');
    corG.addColorStop(0.4,'rgba(255,180,100,0.35)');
    corG.addColorStop(1,'rgba(255,140,60,0)');
    tbCtx.fillStyle = corG;
    tbCtx.beginPath(); tbCtx.arc(0,0,R*0.3,0,Math.PI*2); tbCtx.fill();
    tbCtx.restore();
  }

  tbCtx.restore();
}

// ════════════════════════════════════════════════════════════════════════
// BODY — luminous human silhouette (the central figure)
// ════════════════════════════════════════════════════════════════════════
function tbDrawBody(cx, cy, H, breath){
  if(!tbCtx) return {spineTop:cy, spineBot:cy};
  var t = tbTau();
  // gentle sway
  var sway = Math.sin(t*0.4)*1.2;
  cx += sway;

  // proportions
  var bodyH = H * 0.84;
  var headR = bodyH * 0.085 * breath;
  var shoulderW = bodyH * 0.20 * breath;
  var hipW = bodyH * 0.13 * breath;
  var top = cy - bodyH*0.50;
  var headCy = top + headR*1.2;
  var neckY = headCy + headR*0.9;
  var shoulderY = neckY + bodyH*0.05;
  var navelY = shoulderY + bodyH*0.32;
  var hipY = shoulderY + bodyH*0.52;
  var feetY = cy + bodyH*0.50;

  // ── aura halo
  var aurR = bodyH*0.55 * breath;
  var ag = tbCtx.createRadialGradient(cx, cy - bodyH*0.05, aurR*0.25, cx, cy - bodyH*0.05, aurR);
  ag.addColorStop(0,   'rgba(255,225,180,0.18)');
  ag.addColorStop(0.6, 'rgba(255,225,180,0.06)');
  ag.addColorStop(1,   'rgba(255,225,180,0)');
  tbCtx.fillStyle = ag;
  tbCtx.beginPath(); tbCtx.ellipse(cx, cy - bodyH*0.05, aurR*0.85, aurR, 0, 0, Math.PI*2); tbCtx.fill();

  // ── body silhouette (bezier-curved torso, head, arms, legs)
  tbCtx.save();

  // head
  var hg = tbCtx.createRadialGradient(cx, headCy, 0, cx, headCy, headR*1.5);
  hg.addColorStop(0,   'rgba(255,235,200,0.95)');
  hg.addColorStop(0.6, 'rgba(255,210,170,0.55)');
  hg.addColorStop(1,   'rgba(255,210,170,0)');
  tbCtx.fillStyle = hg;
  tbCtx.beginPath(); tbCtx.arc(cx, headCy, headR*1.5, 0, Math.PI*2); tbCtx.fill();

  tbCtx.fillStyle = 'rgba(255,220,180,0.78)';
  tbCtx.beginPath();
  tbCtx.ellipse(cx, headCy, headR, headR*1.05, 0, 0, Math.PI*2);
  tbCtx.fill();

  // neck
  tbCtx.fillStyle = 'rgba(255,220,180,0.66)';
  tbCtx.beginPath();
  tbCtx.moveTo(cx-headR*0.4, headCy+headR*0.9);
  tbCtx.quadraticCurveTo(cx, headCy+headR*1.15, cx+headR*0.4, headCy+headR*0.9);
  tbCtx.lineTo(cx+headR*0.5, neckY);
  tbCtx.lineTo(cx-headR*0.5, neckY);
  tbCtx.closePath();
  tbCtx.fill();

  // torso (bezier-curved trapezoid: shoulders wider, waist narrower, hips slightly less wide)
  tbCtx.beginPath();
  tbCtx.moveTo(cx - shoulderW, shoulderY);
  tbCtx.quadraticCurveTo(cx - shoulderW*0.85, navelY, cx - hipW, hipY);
  tbCtx.lineTo(cx + hipW, hipY);
  tbCtx.quadraticCurveTo(cx + shoulderW*0.85, navelY, cx + shoulderW, shoulderY);
  tbCtx.closePath();
  var tg = tbCtx.createLinearGradient(cx-shoulderW, shoulderY, cx+shoulderW, shoulderY);
  tg.addColorStop(0,   'rgba(255,210,170,0.30)');
  tg.addColorStop(0.5, 'rgba(255,225,190,0.70)');
  tg.addColorStop(1,   'rgba(255,210,170,0.30)');
  tbCtx.fillStyle = tg;
  tbCtx.fill();

  // arms hanging down, thumbs forward (just two long curves)
  for(var arm=0; arm<2; arm++){
    var sign = arm? 1 : -1;
    var shx = cx + sign * shoulderW * 0.92;
    var shy = shoulderY + bodyH*0.02;
    var elx = cx + sign * shoulderW * 1.0;
    var ely = shoulderY + bodyH*0.30;
    var hx = cx + sign * shoulderW * 0.85;
    var hy = shoulderY + bodyH*0.58;
    tbCtx.beginPath();
    tbCtx.moveTo(shx, shy);
    tbCtx.quadraticCurveTo(elx, ely, hx, hy);
    tbCtx.lineWidth = bodyH*0.04;
    tbCtx.lineCap='round';
    tbCtx.strokeStyle='rgba(255,220,180,0.55)';
    tbCtx.stroke();
  }

  // legs
  for(var lg=0; lg<2; lg++){
    var s2 = lg? 1 : -1;
    var hipx = cx + s2 * hipW*0.55;
    var hipy = hipY;
    var kx = cx + s2 * hipW*0.45;
    var ky = hipY + bodyH*0.25;
    var fx = cx + s2 * hipW*0.65;
    var fy = feetY;
    tbCtx.beginPath();
    tbCtx.moveTo(hipx, hipy);
    tbCtx.quadraticCurveTo(kx, ky, fx, fy);
    tbCtx.lineWidth = bodyH*0.05;
    tbCtx.lineCap='round';
    tbCtx.strokeStyle = 'rgba(255,220,180,0.55)';
    tbCtx.stroke();
  }

  tbCtx.restore();

  // return spine anchors for nadi drawing
  return {
    spineTop: headCy + headR*0.5,   // crown anchor (top)
    spineBot: hipY + bodyH*0.04,    // root anchor (bottom of spine)
    bodyH: bodyH,
    headR: headR,
    cx: cx,
    cy: cy
  };
}
// ════════════════════════════════════════════════════════════════════════
// TORUS — the breathing toroidal field around the body
// ════════════════════════════════════════════════════════════════════════
function tbDrawTorus(cx, cy, H, breath){
  if(!tbCtx) return;
  if(!tbFieldsOn) return;          // hidden by user
  var t = tbTau();
  var R = H * 0.46 * breath;
  var rotY = tbRotY;

  // ── 14 field-line shells (the toroidal flow lines)
  tbCtx.save();
  tbCtx.globalCompositeOperation='lighter';
  for(var shell=0; shell<14; shell++){
    var s = shell/13;                          // 0..1
    var radius = R * (0.55 + s*0.95);
    var height = R * (1.5 - s*1.2);
    var alpha = 0.18 - shell*0.011;
    if(alpha<=0) continue;
    // The "field line" shape: a flowing curve from top to bottom on each side
    tbCtx.strokeStyle = 'rgba(180,210,255,'+alpha+')';
    tbCtx.lineWidth = 1.2;
    tbCtx.beginPath();
    // left side
    tbCtx.moveTo(cx, cy - height);
    tbCtx.bezierCurveTo(
      cx - radius*1.2, cy - height*0.7,
      cx - radius*1.2, cy + height*0.7,
      cx, cy + height
    );
    tbCtx.stroke();
    // right side
    tbCtx.beginPath();
    tbCtx.moveTo(cx, cy - height);
    tbCtx.bezierCurveTo(
      cx + radius*1.2, cy - height*0.7,
      cx + radius*1.2, cy + height*0.7,
      cx, cy + height
    );
    tbCtx.stroke();
  }

  // ── 3 oval encompassing rings (visible 'donut' outline)
  for(var or=0; or<3; or++){
    var orR = R*(1.0 + or*0.10);
    var orH = H*(0.60 + or*0.04) * breath;
    var alphaR = 0.18 - or*0.04;
    tbCtx.strokeStyle = 'rgba(255,210,180,'+alphaR+')';
    tbCtx.lineWidth = 1.4 - or*0.3;
    tbCtx.beginPath();
    tbCtx.ellipse(cx, cy, orR, orH, 0, 0, Math.PI*2);
    tbCtx.stroke();
  }

  // ── polarity sigils (X-shapes top and bottom)
  var topY = cy - H*0.55*breath, botY = cy + H*0.55*breath;
  var flashA = 0.4 + 0.5*tbPolarityFlip;
  var sig = R*0.06;
  tbCtx.strokeStyle = 'rgba(255,220,160,'+flashA+')';
  tbCtx.lineWidth = 1.5;
  tbCtx.beginPath();
  tbCtx.moveTo(cx-sig, topY-sig); tbCtx.lineTo(cx+sig, topY+sig);
  tbCtx.moveTo(cx+sig, topY-sig); tbCtx.lineTo(cx-sig, topY+sig);
  tbCtx.moveTo(cx-sig, botY-sig); tbCtx.lineTo(cx+sig, botY+sig);
  tbCtx.moveTo(cx+sig, botY-sig); tbCtx.lineTo(cx-sig, botY+sig);
  tbCtx.stroke();

  // glow at the polarity points
  var pg1 = tbCtx.createRadialGradient(cx, topY, 0, cx, topY, R*0.20);
  pg1.addColorStop(0,'rgba(255,230,170,'+(0.55+0.4*tbPolarityFlip)+')');
  pg1.addColorStop(1,'rgba(255,230,170,0)');
  tbCtx.fillStyle = pg1;
  tbCtx.beginPath(); tbCtx.arc(cx, topY, R*0.20, 0, Math.PI*2); tbCtx.fill();
  var pg2 = tbCtx.createRadialGradient(cx, botY, 0, cx, botY, R*0.20);
  pg2.addColorStop(0,'rgba(180,220,255,'+(0.55+0.4*tbPolarityFlip)+')');
  pg2.addColorStop(1,'rgba(180,220,255,0)');
  tbCtx.fillStyle = pg2;
  tbCtx.beginPath(); tbCtx.arc(cx, botY, R*0.20, 0, Math.PI*2); tbCtx.fill();

  // ── particle fountain
  // particles flow: UP the central column, OUT through the top, DOWN around the outside, IN through the bottom
  // each particle has a `phase` in [0..1) which describes where in the cycle it is.
  for(var i=0; i<tbTorusParticles.length; i++){
    var p = tbTorusParticles[i];
    p.phase += 0.0042 * p.speed * tbPolarityDir;
    if(p.phase >= 1) p.phase -= 1;
    if(p.phase < 0)  p.phase += 1;

    // Determine 3D position on the torus
    // Phase 0..0.35: rising up the centre (column)
    // Phase 0.35..0.50: arcing out through the top
    // Phase 0.50..0.85: falling down on the outside
    // Phase 0.85..1.0: arcing in through the bottom
    var ph = p.phase;
    var ring = p.ring;
    var ringR = R * (0.95 + ring*0.06);
    var ringH = H * (0.55 + ring*0.04) * breath;
    var py, pr, px, opacity;
    var theta = p.theta + tbRotY;
    var depth = Math.cos(theta);                 // -1..1 (front=+1)

    if(ph < 0.35){
      // up the centre column
      var lv = ph/0.35;
      px = cx + Math.cos(theta) * R*0.12;
      py = cy + ringH - lv*ringH*2;
      pr = p.size;
      opacity = 0.9;
    } else if(ph < 0.50){
      // arcing out over the top
      var lv2 = (ph-0.35)/0.15;
      var ang = -Math.PI/2 + lv2*Math.PI;       // -90° → +90°
      px = cx + Math.cos(theta) * (ringR*Math.sin(lv2*Math.PI*0.5)) * 0.8;
      // sweep up over the dome
      py = cy - ringH - Math.cos(lv2*Math.PI*0.5)*ringH*0.2 + (1-Math.cos(lv2*Math.PI*0.5))*ringH*0.18;
      pr = p.size * 0.95;
      opacity = 0.7;
    } else if(ph < 0.85){
      // descending on the outside
      var lv3 = (ph-0.50)/0.35;
      var radSwell = Math.sin(lv3*Math.PI);     // 0→1→0 (max width at middle)
      px = cx + Math.cos(theta) * (ringR*(0.7 + radSwell*0.30));
      py = cy - ringH + lv3*ringH*2;
      pr = p.size * (0.9 + 0.2*radSwell);
      opacity = 0.8;
    } else {
      // arcing under the bottom
      var lv4 = (ph-0.85)/0.15;
      px = cx + Math.cos(theta) * (ringR * Math.cos(lv4*Math.PI*0.5)) * 0.8;
      py = cy + ringH + Math.cos(lv4*Math.PI*0.5)*ringH*0.2 - (1-Math.cos(lv4*Math.PI*0.5))*ringH*0.18;
      pr = p.size * 0.9;
      opacity = 0.7;
    }

    // adjust opacity for front/back
    opacity *= (0.45 + 0.55 * (depth*0.5 + 0.5));
    if(depth < -0.2) opacity *= 0.55;     // dimmer behind body

    // colour shifts with ring + polarity flip
    var hue;
    if(tbPolarityFlip > 0.3){
      hue = 200 + p.hueShift;            // blue when flipped
    } else {
      hue = 35 + ring*8 + p.hueShift;    // warm gold-amber default
    }
    var lit = 75 - ring*5;

    // soft glow — plain fill (much cheaper than per-frame radial gradients)
    tbCtx.fillStyle = 'hsla('+hue+',85%,'+lit+'%,'+(opacity*0.35)+')';
    tbCtx.beginPath(); tbCtx.arc(px, py, pr*2.6, 0, Math.PI*2); tbCtx.fill();

    // bright core
    tbCtx.fillStyle = 'hsla('+hue+',90%,90%,'+opacity+')';
    tbCtx.beginPath(); tbCtx.arc(px, py, pr*0.6, 0, Math.PI*2); tbCtx.fill();
  }

  tbCtx.restore();
  tbCtx.globalCompositeOperation='source-over';

  // decay polarity flip
  if(tbPolarityFlip > 0){
    tbPolarityFlip -= 0.005;
    if(tbPolarityFlip < 0){ tbPolarityFlip = 0; tbPolarityDir = 1; }
  }
}

// ════════════════════════════════════════════════════════════════════════
// NADIS — iḍā · piṅgalā · suṣumnā
// ════════════════════════════════════════════════════════════════════════
function tbDrawNadis(cx, cy, H, breath, spineTop, spineBot){
  if(!tbCtx) return;
  var t = tbTau();
  var spineH = spineBot - spineTop;
  var spineMid = (spineTop + spineBot)*0.5;
  var amp = H * 0.045 * breath;            // horizontal amplitude of the serpentines

  // ── SUṢUMNĀ — straight pillar with rising particles
  if(tbShowNadis.sushumna){
    // pillar glow
    var sg = tbCtx.createLinearGradient(cx, spineTop, cx, spineBot);
    sg.addColorStop(0,   'rgba(255,240,200,0.05)');
    sg.addColorStop(0.5, 'rgba(255,240,200,0.20)');
    sg.addColorStop(1,   'rgba(255,240,200,0.05)');
    tbCtx.strokeStyle = sg;
    tbCtx.lineWidth = 9;
    tbCtx.lineCap='round';
    tbCtx.beginPath();
    tbCtx.moveTo(cx, spineTop);
    tbCtx.lineTo(cx, spineBot);
    tbCtx.stroke();
    // pillar core
    tbCtx.strokeStyle = 'rgba(255,235,180,0.7)';
    tbCtx.lineWidth = 1.6;
    tbCtx.beginPath();
    tbCtx.moveTo(cx, spineTop);
    tbCtx.lineTo(cx, spineBot);
    tbCtx.stroke();
    // rising particles
    for(var sp=0; sp<tbSushumnaParticles.length; sp++){
      var pt = tbSushumnaParticles[sp];
      pt.y -= pt.v * tbPolarityDir;
      if(pt.y < 0) pt.y = 1;
      if(pt.y > 1) pt.y = 0;
      var px = cx + Math.sin(t*2 + pt.ph)*1.2;
      var py = spineTop + pt.y * spineH;
      var a = 0.55 + 0.4*Math.sin(t*3 + pt.ph);
      // soft glow halo — plain fill
      tbCtx.fillStyle = 'rgba(255,245,210,'+(a*0.30)+')';
      tbCtx.beginPath(); tbCtx.arc(px,py,pt.size*3,0,Math.PI*2); tbCtx.fill();
      // bright core
      tbCtx.fillStyle = 'rgba(255,250,230,'+a+')';
      tbCtx.beginPath(); tbCtx.arc(px,py,pt.size*0.7,0,Math.PI*2); tbCtx.fill();
    }
  }

  // ── IḌĀ (lunar, left) and PIṄGALĀ (solar, right)
  // 7 crossings = 8 segments. The two serpents weave around suṣumnā in opposite phase.
  var crossings = 7;
  var segs = crossings + 1;

  // wave offset depends on breath and rotation
  var waveOffset = Math.sin(t * (tbBreathOn ? Math.PI/8 : 0.6)) * 0.25;

  function drawNadi(side, color, glowColor){
    // side: -1 for ida (starts left), +1 for pingala
    tbCtx.save();
    // outer glow line (no shadow blur — far cheaper than canvas shadows)
    tbCtx.strokeStyle = glowColor;
    tbCtx.lineWidth = 6;
    tbCtx.lineCap='round';
    tbCtx.beginPath();
    for(var i=0; i<=40; i++){
      var f = i/40;
      // crossings: sin wave, 7 crossings = 3.5 full waves
      var wave = Math.sin(f * Math.PI * crossings + waveOffset) * side;
      var x = cx + wave * amp;
      var y = spineTop + f * spineH;
      if(i===0) tbCtx.moveTo(x,y); else tbCtx.lineTo(x,y);
    }
    tbCtx.stroke();
    // inner line
    tbCtx.strokeStyle = color;
    tbCtx.lineWidth = 1.7;
    tbCtx.beginPath();
    for(var i2=0; i2<=40; i2++){
      var f2 = i2/40;
      var wave2 = Math.sin(f2 * Math.PI * crossings + waveOffset) * side;
      var x2 = cx + wave2 * amp;
      var y2 = spineTop + f2 * spineH;
      if(i2===0) tbCtx.moveTo(x2,y2); else tbCtx.lineTo(x2,y2);
    }
    tbCtx.stroke();
    // flowing pulse-particles along the nadi
    var nPulses = 4;
    for(var pl=0; pl<nPulses; pl++){
      var fph = ((t*0.18 + pl/nPulses) * tbPolarityDir * (side>0?1:-1)) % 1;
      if(fph<0) fph+=1;
      // pingala goes down (solar=outflow), ida goes up (lunar=inflow) — by convention
      var fp = side>0 ? fph : (1-fph);
      var wave3 = Math.sin(fp * Math.PI * crossings + waveOffset) * side;
      var px = cx + wave3 * amp;
      var py = spineTop + fp * spineH;
      var pgFill = color;
      tbCtx.fillStyle = pgFill;
      tbCtx.beginPath(); tbCtx.arc(px,py,3.2,0,Math.PI*2); tbCtx.fill();
    }
    tbCtx.restore();
  }

  if(tbShowNadis.ida){
    drawNadi(-1, 'rgba(160,200,255,0.95)', 'rgba(120,170,255,0.20)');
  }
  if(tbShowNadis.pingala){
    drawNadi(+1, 'rgba(255,160,90,0.95)', 'rgba(255,140,60,0.22)');
  }

  // ── 7 chakras at the crossings + hit-test coords
  for(var c=0; c<7; c++){
    var ch = TB_CHAKRAS[c];
    var fc = 1 - ch.y;                         // ch.y is 0=top in our data (oops), but let's match: 0.04=crown, 0.94=root. So position from top: 1 - ch.y maps wrong. Use ch.y directly with 0=base ⇢ NO we want 0.04 to be at top. So fc = 1 - ch.y? Actually ch.y=0.04 means crown which should be at TOP, fc=0. So fc = 1 - ch.y when 0=root.
    // Let me re-read: y:0.94 = root (TOP of array's order is base); y:0.04 = crown.
    // Where on the spine? Crown is at spineTop, root is at spineBot.
    // fc = (1 - ch.y) gives:  crown 1-0.04=0.96 (bottom?) — that's wrong.
    // fc = ch.y gives: crown 0.04, root 0.94 — root at spineBot would be ch.y=0.94 * spineH ⇒ fraction 0.94 along (top→bot) — YES correct.
    fc = ch.y;
    var cx2 = cx;
    var cy2 = spineTop + fc * spineH;
    ch._x = cx2; ch._y = cy2;

    var pulse = 0.85 + 0.15 * Math.sin(t*1.6 + c*0.7);
    var isActive = (tbActiveChakra === c);
    var rOuter = (isActive ? 22 : 14) * pulse;
    var rInner = (isActive ? 8 : 5);

    // halo
    var cg = tbCtx.createRadialGradient(cx2, cy2, 0, cx2, cy2, rOuter*1.8);
    cg.addColorStop(0,   ch.col);
    cg.addColorStop(0.4, ch.col.replace(')', ',0.5)').replace('#','rgba(').slice());
    cg.addColorStop(1, 'rgba(0,0,0,0)');
    // simpler: use hex→rgba via canvas, just layer two glows
    var hexR = parseInt(ch.col.slice(1,3),16);
    var hexG = parseInt(ch.col.slice(3,5),16);
    var hexB = parseInt(ch.col.slice(5,7),16);
    var rgbaBase = 'rgba('+hexR+','+hexG+','+hexB+',';
    var cg2 = tbCtx.createRadialGradient(cx2, cy2, 0, cx2, cy2, rOuter*2);
    cg2.addColorStop(0,   rgbaBase+(isActive?0.95:0.75)+')');
    cg2.addColorStop(0.45,rgbaBase+(isActive?0.35:0.20)+')');
    cg2.addColorStop(1,   rgbaBase+'0)');
    tbCtx.fillStyle = cg2;
    tbCtx.beginPath(); tbCtx.arc(cx2, cy2, rOuter*2, 0, Math.PI*2); tbCtx.fill();

    // outer ring
    tbCtx.strokeStyle = rgbaBase+(isActive?0.95:0.75)+')';
    tbCtx.lineWidth = isActive ? 2 : 1.2;
    tbCtx.beginPath(); tbCtx.arc(cx2, cy2, rOuter*0.6, 0, Math.PI*2); tbCtx.stroke();

    // core
    tbCtx.fillStyle = isActive ? '#fff' : rgbaBase+'0.95)';
    tbCtx.beginPath(); tbCtx.arc(cx2, cy2, rInner, 0, Math.PI*2); tbCtx.fill();

    // bija glyph above when active
    if(isActive){
      tbCtx.font = '600 16px "Noto Sans Devanagari", serif';
      tbCtx.textAlign = 'center';
      tbCtx.fillStyle = rgbaBase+'0.95)';
      tbCtx.fillText(ch.sa, cx2, cy2 - rOuter - 8);
    }
  }
}

// ════════════════════════════════════════════════════════════════════════
// CROWN RAYS — sahasrara-ray shimmer when crown chakra (idx 6) is active
// ════════════════════════════════════════════════════════════════════════
function tbDrawCrownRays(cx, cy, H, breath){
  if(!tbCtx) return;
  if(tbActiveChakra !== 6) return;
  var ch = TB_CHAKRAS[6];
  if(!ch || ch._x===undefined) return;
  var t = tbTau();
  tbCtx.save();
  tbCtx.translate(ch._x, ch._y);
  tbCtx.rotate(t*0.15);
  for(var r=0; r<24; r++){
    var ang = (r/24) * Math.PI*2;
    var len = 50 + 25*Math.sin(t*2 + r*0.4);
    tbCtx.strokeStyle = 'rgba(255,240,220,'+(0.16 + 0.16*Math.sin(t*2 + r))+')';
    tbCtx.lineWidth = 1;
    tbCtx.beginPath();
    tbCtx.moveTo(Math.cos(ang)*8, Math.sin(ang)*8);
    tbCtx.lineTo(Math.cos(ang)*len, Math.sin(ang)*len);
    tbCtx.stroke();
  }
  tbCtx.restore();
}

// ════════════════════════════════════════════════════════════════════════
// BREATH HUD — count-down ring + label when breath practice is active
// ════════════════════════════════════════════════════════════════════════
function tbDrawBreathHUD(){
  if(!tbCtx) return;
  if(!tbBreathOn) return;
  var phase = tbBreathPhaseLabel();
  if(!phase) return;
  var label = phase[0], sk = phase[1], elapsed = phase[2], duration = phase[3];
  var pct = elapsed/duration;

  var x = tbW*0.5, y = 50;
  var r = 22;
  // back ring
  tbCtx.strokeStyle = 'rgba(255,230,200,0.18)';
  tbCtx.lineWidth = 3;
  tbCtx.beginPath(); tbCtx.arc(x,y,r,0,Math.PI*2); tbCtx.stroke();
  // progress arc
  tbCtx.strokeStyle = 'rgba(255,230,180,0.95)';
  tbCtx.lineWidth = 3;
  tbCtx.lineCap='round';
  tbCtx.beginPath();
  tbCtx.arc(x,y,r,-Math.PI/2, -Math.PI/2 + pct*Math.PI*2);
  tbCtx.stroke();
  // label
  tbCtx.fillStyle = 'rgba(255,240,210,0.95)';
  tbCtx.font = '600 11px "IBM Plex Mono", monospace';
  tbCtx.textAlign='center';
  tbCtx.fillText(label, x, y+4);
  tbCtx.font = '400 9px "IBM Plex Mono", monospace';
  tbCtx.fillStyle = 'rgba(255,225,180,0.55)';
  tbCtx.fillText(sk, x, y+r+14);
  // countdown number
  tbCtx.fillStyle = 'rgba(255,240,210,0.85)';
  tbCtx.font = '500 14px "Cinzel", serif';
  tbCtx.fillText(Math.ceil(duration-elapsed), x, y-r-6);
}

// ════════════════════════════════════════════════════════════════════════
// MAIN DRAW LOOP — wraps in try/catch so a bad frame doesn't kill us
// Also: STOPS when overlay is closed or tab is hidden (saves CPU/heat).
// ════════════════════════════════════════════════════════════════════════
function tbDraw(){
  try {
    if(!tbCtx || !tbCanvas){
      // canvas vanished; abort loop
      tbRAF = null;
      return;
    }
    // pause if tab is hidden (saves significant CPU on macOS)
    if(document.hidden){
      tbRAF = requestAnimationFrame(tbDraw);
      return;
    }
    // pause if overlay is no longer open
    var ov = $tb('torus-exp');
    if(!ov || !ov.classList.contains('on')){
      tbRAF = null;
      return;
    }

    // 1. cosmos background
    tbDrawCosmos();

    // rotation inertia (parikrama)
    if(tbDragX === null){
      tbRotY += tbRotV;
      tbRotV *= 0.94;
      if(Math.abs(tbRotV) < 0.0001) tbRotV = 0;
    }
    // a tiny continuous rotation so it always feels alive
    tbRotY += 0.0015;

    // figure centre
    var cx = tbW*0.5, cy = tbH*0.52;
    var H = Math.min(tbW*0.78, tbH*0.78);

    var breath = tbBreathScale();

    // 2. scale-hint background
    tbDrawScaleHint(cx, cy, H*0.42);

    // 3. body silhouette
    var anchors = tbDrawBody(cx, cy, H, breath);

    // 4. torus field (in front of body, additive)
    tbDrawTorus(cx, cy, H, breath);

    // 5. nadis + chakras
    tbDrawNadis(cx, cy, H, breath, anchors.spineTop, anchors.spineBot);

    // 6. crown rays
    tbDrawCrownRays(cx, cy, H, breath);

    // 7. HUD
    tbDrawBreathHUD();

  } catch(e){
    // don't kill the loop; just log silently
    if(window.console && console.error) console.error('tbDraw frame error:', e);
  }
  tbRAF = requestAnimationFrame(tbDraw);
}

// ════════════════════════════════════════════════════════════════════════
// CANVAS INTERACTION — chakra tap-detection, parikrama drag
// ════════════════════════════════════════════════════════════════════════
function tbCanvasPos(evt){
  if(!tbCanvas) return null;
  var rect = tbCanvas.getBoundingClientRect();
  var x, y;
  if(evt.touches && evt.touches.length){
    x = evt.touches[0].clientX - rect.left;
    y = evt.touches[0].clientY - rect.top;
  } else {
    x = evt.clientX - rect.left;
    y = evt.clientY - rect.top;
  }
  return {x:x, y:y};
}

function tbCanvasClick(evt){
  var pos = tbCanvasPos(evt);
  if(!pos) return;
  // hit-test chakras
  for(var c=0; c<7; c++){
    var ch = TB_CHAKRAS[c];
    if(ch._x === undefined) continue;
    var dx = pos.x - ch._x, dy = pos.y - ch._y;
    if(dx*dx + dy*dy < 26*26){
      tbActiveChakra = c;
      tbUpdateChakraReadout();
      return;
    }
  }
  // tap on empty area: deselect
  if(tbActiveChakra >= 0){
    tbActiveChakra = -1;
    tbUpdateChakraReadout();
  }
}

function tbDragStart(evt){
  var pos = tbCanvasPos(evt);
  if(!pos) return;
  // ignore drag if it's a chakra tap
  for(var c=0; c<7; c++){
    var ch = TB_CHAKRAS[c];
    if(ch._x === undefined) continue;
    var dx = pos.x - ch._x, dy = pos.y - ch._y;
    if(dx*dx + dy*dy < 26*26) return;
  }
  tbDragX = pos.x;
  tbDragLast = pos.x;
  if(evt.preventDefault) evt.preventDefault();
}
function tbDragMove(evt){
  if(tbDragX === null) return;
  var pos = tbCanvasPos(evt);
  if(!pos) return;
  var dx = pos.x - tbDragLast;
  tbRotY += dx * 0.005;
  tbRotV = dx * 0.005;
  tbDragLast = pos.x;
  if(evt.preventDefault) evt.preventDefault();
}
function tbDragEnd(){
  tbDragX = null;
  tbDragLast = null;
}
// ════════════════════════════════════════════════════════════════════════
// CHAKRA READOUT — slides in from bottom-left when a chakra is tapped
// ════════════════════════════════════════════════════════════════════════
function tbUpdateChakraReadout(){
  var box = $tb('tb-chakra-readout');
  if(!box) return;
  if(tbActiveChakra < 0){
    box.classList.remove('on');
    box.innerHTML='';
    return;
  }
  var c = TB_CHAKRAS[tbActiveChakra];
  if(!c) return;
  var hexR = parseInt(c.col.slice(1,3),16);
  var hexG = parseInt(c.col.slice(3,5),16);
  var hexB = parseInt(c.col.slice(5,7),16);
  var rgba = function(a){ return 'rgba('+hexR+','+hexG+','+hexB+','+a+')'; };

  box.innerHTML =
    '<div class="tb-cr-hdr" style="border-left:3px solid '+c.col+';padding-left:10px;">'+
      '<div class="tb-cr-row1">'+
        '<span class="tb-cr-glyph" style="background:'+rgba(0.18)+';color:'+c.col+';">'+(c.tr.charAt(0))+'</span>'+
        '<div class="tb-cr-titles">'+
          '<div class="tb-cr-sa">'+c.sa+'</div>'+
          '<div class="tb-cr-tr">'+c.tr+' · '+c.en+'</div>'+
        '</div>'+
        '<button class="tb-cr-x" onclick="tbCloseChakra()" title="Close">✕</button>'+
      '</div>'+
    '</div>'+
    '<div class="tb-cr-body">'+
      '<div class="tb-cr-row"><span class="tb-cr-lbl">Element</span><span class="tb-cr-val">'+c.element+'</span></div>'+
      '<div class="tb-cr-row"><span class="tb-cr-lbl">Bīja</span><span class="tb-cr-val" style="font-family:\'Noto Sans Devanagari\',serif;">'+c.bija+'</span></div>'+
      '<div class="tb-cr-row"><span class="tb-cr-lbl">Location</span><span class="tb-cr-val">'+c.loc+'</span></div>'+
      '<div class="tb-cr-row"><span class="tb-cr-lbl">Gland · plexus</span><span class="tb-cr-val">'+c.gland+'</span></div>'+
      '<div class="tb-cr-row"><span class="tb-cr-lbl">Petals</span><span class="tb-cr-val">'+c.petals+'</span></div>'+
      '<div class="tb-cr-row"><span class="tb-cr-lbl">Frequency</span><span class="tb-cr-val">'+c.freq.toFixed(2)+' Hz</span></div>'+
      '<div class="tb-cr-lived">'+c.lived+'</div>'+
    '</div>';
  box.classList.add('on');
}

window.tbCloseChakra = function(){
  tbActiveChakra = -1;
  tbUpdateChakraReadout();
};

// ════════════════════════════════════════════════════════════════════════
// DARSHAN PANEL — sliding teaching panel
// ════════════════════════════════════════════════════════════════════════
window.tbShowChapter = function(key){
  tbCurrentChapter = key;
  // update pill states
  var pills = document.querySelectorAll('#tb-darshan-pills .tb-chap-pill');
  for(var p=0; p<pills.length; p++){
    pills[p].classList.toggle('active', pills[p].getAttribute('data-chap')===key);
  }
  // update title
  var titleEl = $tb('tb-darshan-title');
  if(titleEl){
    for(var k=0; k<TB_CHAPTERS.length; k++){
      if(TB_CHAPTERS[k].key === key){
        titleEl.textContent = TB_CHAPTERS[k].label;
        break;
      }
    }
  }
  // inject body
  var body = $tb('tb-darshan-body');
  if(!body) return;
  // cancel any subpage RAFs from the previous chapter before swapping content
  if(tbCymaticRAF){ cancelAnimationFrame(tbCymaticRAF); tbCymaticRAF=null; }
  if(tbBreathChamberRAF){ cancelAnimationFrame(tbBreathChamberRAF); tbBreathChamberRAF=null; }
  body.innerHTML = TB_CONTENT[key] || '<p class="tb-source">Chapter loading…</p>';
  body.scrollTop = 0;

  // special chapter behaviour
  if(key === 'cymatics'){
    // start cymatic timer
    tbCymaticT0 = performance.now();
    tbWireCymaticChamber();
  } else if(key === 'breath'){
    tbWireBreathChamber();
  }
};

window.tbOpenDarshan = function(chap){
  var p = $tb('tb-darshan');
  if(!p) return;
  p.classList.add('on');
  tbDarshanOpen = true;
  window.tbShowChapter(chap || tbCurrentChapter || 'torus');
};

window.tbCloseDarshan = function(){
  var p = $tb('tb-darshan');
  if(!p) return;
  p.classList.remove('on');
  tbDarshanOpen = false;
};

// ════════════════════════════════════════════════════════════════════════
// SCALE SLIDER — switch backdrop
// ════════════════════════════════════════════════════════════════════════
window.tbSetScale = function(n){
  n = Math.max(0, Math.min(6, n|0));
  tbScale = n;
  var dots = document.querySelectorAll('.tb-scale-dot');
  for(var i=0;i<dots.length;i++){
    dots[i].classList.toggle('active', i===n);
  }
  var lbl = $tb('tb-scale-lbl');
  if(lbl) lbl.textContent = tbScaleNames[n];
};

