// ════════════════════════════════════════════════════════════════════════
// CYMATIC CHAMBER — the "Living Hum" subpage interaction
// ════════════════════════════════════════════════════════════════════════
var tbCymaticCanvas = null, tbCymaticCtx = null, tbCymaticRAF = null;
var tbCymaticActiveChakra = 3; // default heart

function tbWireCymaticChamber(){
  // wire up tap-buttons after content is injected
  setTimeout(function(){
    var btns = document.querySelectorAll('#tb-cym-pad .tb-cym-key');
    for(var b=0; b<btns.length; b++){
      (function(btn,idx){
        btn.onclick = function(){
          tbCymaticActiveChakra = idx;
          // update active class
          var all = document.querySelectorAll('#tb-cym-pad .tb-cym-key');
          for(var aa=0; aa<all.length; aa++) all[aa].classList.toggle('active', aa===idx);
          tbCymaticT0 = performance.now();
          // update name display
          var nameEl = document.getElementById('tb-cym-name');
          if(nameEl){
            var ch = TB_CHAKRAS[idx];
            nameEl.innerHTML = '<span style="color:'+ch.col+'">'+ch.bija+'</span> · '+ch.tr+' · '+ch.freq.toFixed(2)+' Hz';
          }
        };
      })(btns[b], b);
    }
    tbCymaticCanvas = document.getElementById('tb-cym-canvas');
    if(tbCymaticCanvas){
      var rect = tbCymaticCanvas.getBoundingClientRect();
      var dpr = Math.min(window.devicePixelRatio||1, 2);
      var w = Math.max(280, rect.width|0);
      var h = w;
      tbCymaticCanvas.width = w*dpr; tbCymaticCanvas.height = h*dpr;
      tbCymaticCanvas.style.width = w+'px'; tbCymaticCanvas.style.height = h+'px';
      tbCymaticCtx = tbCymaticCanvas.getContext('2d');
      tbCymaticCtx.setTransform(dpr,0,0,dpr,0,0);
      tbCymaticT0 = performance.now();
      if(tbCymaticRAF) cancelAnimationFrame(tbCymaticRAF);
      tbDrawCymatic();
    }
  }, 80);
}

function tbDrawCymatic(){
  if(!tbCymaticCtx || !tbCymaticCanvas){ tbCymaticRAF = null; return; }
  // if no longer on screen, stop
  if(!document.getElementById('tb-cym-canvas')){ tbCymaticRAF = null; return; }
  // pause if tab hidden or overlay closed
  if(document.hidden){
    tbCymaticRAF = requestAnimationFrame(tbDrawCymatic);
    return;
  }
  var ov_c = $tb('torus-exp');
  if(!ov_c || !ov_c.classList.contains('on')){ tbCymaticRAF = null; return; }

  var w = tbCymaticCanvas.width / (Math.min(window.devicePixelRatio||1,1.5));
  var h = w;
  var ctx = tbCymaticCtx;
  var ch = TB_CHAKRAS[tbCymaticActiveChakra];
  var t = (performance.now() - tbCymaticT0)/1000;

  // background plate (a Chladni plate)
  ctx.fillStyle = '#0a0815';
  ctx.fillRect(0,0,w,h);
  // sand grain texture (subtle)
  for(var g=0;g<60;g++){
    ctx.fillStyle = 'rgba(255,240,200,'+(0.02+Math.random()*0.03)+')';
    ctx.beginPath(); ctx.arc(Math.random()*w, Math.random()*h, 0.5, 0, Math.PI*2); ctx.fill();
  }

  var cx = w*0.5, cy = h*0.5, R = w*0.42;

  // The cymatic pattern: nodal lines of a vibrating circular plate
  // We model a standing wave: u(r,θ) = J_n(kr)*cos(nθ) but approximated.
  // Each chakra has a different (n,m) mode → different geometric pattern.
  var modes = [
    {n:3, m:1, hue:0},     // root - triangle
    {n:4, m:2, hue:25},    // sacral - 4-petal
    {n:5, m:2, hue:48},    // solar - 5-petal star
    {n:6, m:3, hue:135},   // heart - 6 petals (hexagram-ish)
    {n:8, m:3, hue:200},   // throat - 8-petal
    {n:2, m:5, hue:265},   // ajna - 2-petal concentric rings
    {n:1000, m:7, hue:280} // crown - thousand-petal swirl
  ];
  var mode = modes[tbCymaticActiveChakra] || modes[3];

  // hex parse chakra colour for the petals
  var hexR = parseInt(ch.col.slice(1,3),16);
  var hexG = parseInt(ch.col.slice(3,5),16);
  var hexB = parseInt(ch.col.slice(5,7),16);

  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(t*0.10);

  // outer plate ring
  ctx.strokeStyle = 'rgba(255,240,200,0.18)';
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.arc(0,0,R,0,Math.PI*2); ctx.stroke();
  ctx.strokeStyle = 'rgba(255,240,200,0.10)';
  ctx.beginPath(); ctx.arc(0,0,R*0.92,0,Math.PI*2); ctx.stroke();

  // draw nodal pattern as sampled points where amplitude crosses zero
  // We oversample radially and angularly
  var nodes = [];
  if(mode.n < 100){
    // standard petal pattern using rose curve: r = R * sin(n * θ + φ)
    for(var i=0; i<420; i++){
      var theta = (i/420)*Math.PI*2;
      var phase = mode.m * Math.sin(t*0.6);
      var rr = R*0.92 * Math.abs(Math.sin(mode.n*0.5*theta + phase));
      var x = Math.cos(theta)*rr;
      var y = Math.sin(theta)*rr;
      nodes.push([x,y]);
    }
  } else {
    // crown - spiraling concentric pattern
    for(var ii=0; ii<800; ii++){
      var theta2 = (ii/40)*Math.PI*2 + t*0.3;
      var rr2 = R*0.92 * (ii/800);
      nodes.push([Math.cos(theta2)*rr2, Math.sin(theta2)*rr2]);
    }
  }

  // draw the nodal grains as glowing dots (the sand on the plate)
  for(var p=0; p<nodes.length; p++){
    var nx = nodes[p][0], ny = nodes[p][1];
    var alpha = 0.55 + 0.45 * Math.sin(t*1.8 + p*0.1);
    ctx.fillStyle = 'rgba('+hexR+','+hexG+','+hexB+','+alpha+')';
    ctx.beginPath(); ctx.arc(nx, ny, 1.2, 0, Math.PI*2); ctx.fill();
  }

  // luminous centre (the bīja)
  var cg = ctx.createRadialGradient(0,0,0,0,0,R*0.18);
  cg.addColorStop(0, 'rgba('+hexR+','+hexG+','+hexB+',0.9)');
  cg.addColorStop(0.5,'rgba('+hexR+','+hexG+','+hexB+',0.35)');
  cg.addColorStop(1, 'rgba('+hexR+','+hexG+','+hexB+',0)');
  ctx.fillStyle = cg;
  ctx.beginPath(); ctx.arc(0,0,R*0.18,0,Math.PI*2); ctx.fill();

  // bija glyph
  ctx.rotate(-t*0.10); // un-rotate so glyph stays upright
  ctx.font = '600 22px "Noto Sans Devanagari", serif';
  ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.fillStyle = 'rgba(255,250,230,0.92)';
  ctx.fillText(ch.bija.split('·')[0].trim(), 0, 4);

  ctx.restore();

  tbCymaticRAF = requestAnimationFrame(tbDrawCymatic);
}

// ════════════════════════════════════════════════════════════════════════
// BREATH OF THE UNIVERSE — chapter shows animated natural torus forms
// ════════════════════════════════════════════════════════════════════════
var tbBreathChamberRAF = null;
function tbWireBreathChamber(){
  setTimeout(function(){
    var canvases = document.querySelectorAll('.tb-bou-canvas');
    for(var i=0; i<canvases.length; i++){
      var c = canvases[i];
      var kind = c.getAttribute('data-kind');
      var dpr = Math.min(window.devicePixelRatio||1, 2);
      var rect = c.getBoundingClientRect();
      var s = Math.max(120, rect.width|0);
      c.width = s*dpr; c.height = s*dpr;
      c.style.width = s+'px'; c.style.height = s+'px';
      var cc = c.getContext('2d');
      cc.setTransform(dpr,0,0,dpr,0,0);
      c._kind = kind; c._size = s; c._ctx = cc;
    }
    if(tbBreathChamberRAF) cancelAnimationFrame(tbBreathChamberRAF);
    tbDrawBreathChamber();
  }, 80);
}

function tbDrawBreathChamber(){
  var canvases = document.querySelectorAll('.tb-bou-canvas');
  if(!canvases.length){ tbBreathChamberRAF = null; return; }
  // pause if tab hidden or overlay closed
  if(document.hidden){
    tbBreathChamberRAF = requestAnimationFrame(tbDrawBreathChamber);
    return;
  }
  var ov_b = $tb('torus-exp');
  if(!ov_b || !ov_b.classList.contains('on')){ tbBreathChamberRAF = null; return; }
  var t = performance.now()/1000;
  for(var i=0; i<canvases.length; i++){
    var c = canvases[i];
    if(!c._ctx) continue;
    var ctx = c._ctx, S = c._size, kind = c._kind;
    ctx.fillStyle = '#08070f';
    ctx.fillRect(0,0,S,S);
    var cx=S/2, cy=S/2, R=S*0.42;

    if(kind==='atom'){
      for(var o=0;o<3;o++){
        var ang = t*1.5 + o*Math.PI*2/3;
        ctx.strokeStyle='rgba(120,200,255,0.4)'; ctx.lineWidth=1;
        ctx.beginPath();
        ctx.ellipse(cx,cy,R*(0.7+o*0.12),R*(0.7+o*0.12)*0.4,o*0.6,0,Math.PI*2);
        ctx.stroke();
        var ex=cx+Math.cos(ang)*R*(0.7+o*0.12);
        var ey=cy+Math.sin(ang)*R*(0.7+o*0.12)*0.4;
        var gg=ctx.createRadialGradient(ex,ey,0,ex,ey,9);
        gg.addColorStop(0,'rgba(160,220,255,0.95)'); gg.addColorStop(1,'rgba(160,220,255,0)');
        ctx.fillStyle=gg; ctx.beginPath(); ctx.arc(ex,ey,9,0,Math.PI*2); ctx.fill();
      }
      // nucleus
      var ng=ctx.createRadialGradient(cx,cy,0,cx,cy,R*0.18);
      ng.addColorStop(0,'rgba(255,220,150,0.95)'); ng.addColorStop(1,'rgba(255,180,80,0)');
      ctx.fillStyle=ng; ctx.beginPath(); ctx.arc(cx,cy,R*0.18,0,Math.PI*2); ctx.fill();
    }

    else if(kind==='apple'){
      // apple cross-section — toroidal seed cavity
      var ag=ctx.createRadialGradient(cx,cy-S*0.05,0,cx,cy-S*0.05,R);
      ag.addColorStop(0,'rgba(255,210,180,0.85)');
      ag.addColorStop(0.55,'rgba(220,90,80,0.8)');
      ag.addColorStop(1,'rgba(140,30,40,0.7)');
      ctx.fillStyle=ag;
      ctx.beginPath(); ctx.ellipse(cx,cy,R*0.92,R*0.95,0,0,Math.PI*2); ctx.fill();
      // seed star (toroidal seed pattern)
      ctx.fillStyle = 'rgba(50,30,20,0.92)';
      for(var sd=0; sd<5; sd++){
        var sa = sd*Math.PI*2/5 - Math.PI/2 + Math.sin(t*0.3)*0.05;
        var sx = cx + Math.cos(sa)*R*0.20;
        var sy = cy + Math.sin(sa)*R*0.20 + 4;
        ctx.beginPath(); ctx.ellipse(sx,sy,3.5,7,sa+Math.PI/2,0,Math.PI*2); ctx.fill();
      }
      // stem
      ctx.strokeStyle='rgba(80,55,30,0.85)'; ctx.lineWidth=3;
      ctx.beginPath(); ctx.moveTo(cx,cy-R*0.9); ctx.lineTo(cx+2,cy-R*1.1); ctx.stroke();
    }

    else if(kind==='magnet'){
      // bar magnet with field lines
      ctx.fillStyle='rgba(220,70,80,0.85)';
      ctx.fillRect(cx-S*0.08, cy-S*0.22, S*0.16, S*0.22);
      ctx.fillStyle='rgba(80,140,220,0.85)';
      ctx.fillRect(cx-S*0.08, cy, S*0.16, S*0.22);
      ctx.fillStyle='rgba(255,250,230,0.9)'; ctx.font='600 9px monospace'; ctx.textAlign='center';
      ctx.fillText('N', cx, cy-S*0.10);
      ctx.fillText('S', cx, cy+S*0.13);
      // field lines (toroidal)
      for(var fl=0;fl<8;fl++){
        var rr=R*(0.32+fl*0.08);
        var pulse=0.7+0.3*Math.sin(t*1.5+fl*0.3);
        ctx.strokeStyle='rgba(255,200,150,'+(0.18*pulse)+')'; ctx.lineWidth=1;
        ctx.beginPath();
        ctx.ellipse(cx,cy,rr*1.05,rr,0,0,Math.PI*2);
        ctx.stroke();
      }
      // flowing particles on field lines
      for(var p2=0;p2<24;p2++){
        var ph=((t*0.5+p2/24)%1);
        var ang2=ph*Math.PI*2 - Math.PI/2;
        var rr2=R*0.7;
        var px=cx+Math.cos(ang2)*rr2*1.05; var py=cy+Math.sin(ang2)*rr2;
        ctx.fillStyle='rgba(255,200,140,0.7)';
        ctx.beginPath(); ctx.arc(px,py,1.5,0,Math.PI*2); ctx.fill();
      }
    }

    else if(kind==='vortex'){
      // water vortex — spiral funnel
      ctx.save(); ctx.translate(cx,cy);
      for(var sp=0;sp<160;sp++){
        var theta = sp*0.30 + t*1.4;
        var rr = R*0.95 * Math.exp(-sp*0.012);
        var x = Math.cos(theta)*rr, y=Math.sin(theta)*rr;
        var a = 0.7 - sp*0.004;
        ctx.fillStyle='rgba(120,200,255,'+a+')';
        ctx.beginPath(); ctx.arc(x,y,1.2,0,Math.PI*2); ctx.fill();
      }
      // central hole
      var vg=ctx.createRadialGradient(0,0,0,0,0,R*0.12);
      vg.addColorStop(0,'rgba(0,0,0,0.95)'); vg.addColorStop(1,'rgba(0,0,0,0)');
      ctx.fillStyle=vg;
      ctx.beginPath(); ctx.arc(0,0,R*0.12,0,Math.PI*2); ctx.fill();
      ctx.restore();
    }

    else if(kind==='hurricane'){
      // hurricane from above
      ctx.save(); ctx.translate(cx,cy); ctx.rotate(t*0.6);
      for(var arm=0;arm<4;arm++){
        ctx.rotate(Math.PI/2);
        for(var st=0;st<28;st++){
          var theta3 = st*0.16;
          var rr3 = R*0.13 + st*R*0.026;
          var sx = Math.cos(theta3)*rr3, sy=Math.sin(theta3)*rr3;
          ctx.fillStyle='rgba(220,230,250,'+(0.7-st*0.022)+')';
          ctx.beginPath(); ctx.arc(sx,sy,2.5,0,Math.PI*2); ctx.fill();
        }
      }
      // eye
      ctx.fillStyle='rgba(15,20,40,0.9)';
      ctx.beginPath(); ctx.arc(0,0,R*0.10,0,Math.PI*2); ctx.fill();
      ctx.restore();
    }

    else if(kind==='galaxy'){
      ctx.save(); ctx.translate(cx,cy); ctx.rotate(t*0.18);
      for(var arm2=0;arm2<3;arm2++){
        ctx.rotate(Math.PI*2/3);
        for(var sb=0;sb<70;sb++){
          var th = sb*0.13;
          var rr4 = R*0.20 + sb*R*0.011;
          var x2 = Math.cos(th)*rr4 + (Math.random()-0.5)*3;
          var y2 = Math.sin(th)*rr4 + (Math.random()-0.5)*3;
          var hue = sb<20 ? 50 : (sb<45 ? 280 : 210);
          ctx.fillStyle='hsla('+hue+',70%,80%,'+(0.7-sb*0.008)+')';
          ctx.beginPath(); ctx.arc(x2,y2,0.9,0,Math.PI*2); ctx.fill();
        }
      }
      // bulge
      var bg=ctx.createRadialGradient(0,0,0,0,0,R*0.22);
      bg.addColorStop(0,'rgba(255,220,150,0.9)'); bg.addColorStop(1,'rgba(255,180,80,0)');
      ctx.fillStyle=bg;
      ctx.beginPath(); ctx.arc(0,0,R*0.22,0,Math.PI*2); ctx.fill();
      ctx.restore();
    }

    else if(kind==='heart'){
      // beating heart field
      var pulseB = 0.85 + 0.15*Math.abs(Math.sin(t*1.8));
      for(var ff=4;ff>=0;ff--){
        var rrf = R*(0.35+ff*0.14)*pulseB;
        ctx.strokeStyle='rgba(255,90,130,'+(0.20-ff*0.035)+')'; ctx.lineWidth=1.2;
        ctx.beginPath();
        ctx.ellipse(cx,cy-S*0.04,rrf*1.2,rrf*0.85,0,0,Math.PI*2);
        ctx.stroke();
      }
      // heart shape
      var hg=ctx.createRadialGradient(cx,cy-S*0.04,0,cx,cy-S*0.04,R*0.22*pulseB);
      hg.addColorStop(0,'rgba(255,80,90,0.95)'); hg.addColorStop(0.7,'rgba(180,30,50,0.7)'); hg.addColorStop(1,'rgba(120,20,30,0)');
      ctx.fillStyle=hg;
      ctx.beginPath(); ctx.arc(cx,cy-S*0.04,R*0.22*pulseB,0,Math.PI*2); ctx.fill();
    }

    else if(kind==='eye'){
      // iris — radiating fibres
      ctx.save(); ctx.translate(cx,cy);
      // sclera
      ctx.fillStyle='rgba(240,235,220,0.85)';
      ctx.beginPath(); ctx.ellipse(0,0,R*0.95,R*0.6,0,0,Math.PI*2); ctx.fill();
      // iris
      var ig=ctx.createRadialGradient(0,0,0,0,0,R*0.42);
      ig.addColorStop(0,'rgba(80,60,40,0.95)'); ig.addColorStop(0.7,'rgba(150,110,60,0.85)'); ig.addColorStop(1,'rgba(80,60,40,0.95)');
      ctx.fillStyle=ig;
      ctx.beginPath(); ctx.arc(0,0,R*0.42,0,Math.PI*2); ctx.fill();
      // fibres
      for(var fi=0;fi<48;fi++){
        var a = fi*Math.PI*2/48 + Math.sin(t+fi)*0.01;
        ctx.strokeStyle='rgba(255,230,180,'+(0.3+0.3*Math.sin(t+fi))+')';
        ctx.lineWidth=0.6;
        ctx.beginPath();
        ctx.moveTo(Math.cos(a)*R*0.13,Math.sin(a)*R*0.13);
        ctx.lineTo(Math.cos(a)*R*0.40,Math.sin(a)*R*0.40);
        ctx.stroke();
      }
      // pupil
      ctx.fillStyle='#000';
      ctx.beginPath(); ctx.arc(0,0,R*0.14*(1+0.05*Math.sin(t*0.4)),0,Math.PI*2); ctx.fill();
      // catchlight
      ctx.fillStyle='rgba(255,255,250,0.85)';
      ctx.beginPath(); ctx.arc(-R*0.08,-R*0.04,R*0.04,0,Math.PI*2); ctx.fill();
      ctx.restore();
    }

    else if(kind==='earth'){
      // earth + magnetosphere
      for(var em=0;em<8;em++){
        var rrE = R*(0.28+em*0.10);
        var pulseE = 0.95+0.05*Math.sin(t*0.7+em*0.4);
        ctx.strokeStyle='rgba(120,180,255,'+(0.18-em*0.018)+')'; ctx.lineWidth=1;
        ctx.beginPath();
        ctx.ellipse(cx+R*0.05*em*0.1,cy,rrE*pulseE*1.1,rrE*pulseE*0.92,0,0,Math.PI*2);
        ctx.stroke();
      }
      var ee=ctx.createRadialGradient(cx,cy,0,cx,cy,R*0.30);
      ee.addColorStop(0,'rgba(80,140,200,0.9)');
      ee.addColorStop(0.6,'rgba(40,100,160,0.75)');
      ee.addColorStop(1,'rgba(20,60,110,0)');
      ctx.fillStyle=ee;
      ctx.beginPath(); ctx.arc(cx,cy,R*0.30,0,Math.PI*2); ctx.fill();
      // continent hint
      ctx.fillStyle='rgba(80,140,80,0.55)';
      ctx.beginPath(); ctx.ellipse(cx-4,cy-3,R*0.10,R*0.08,0.3,0,Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.ellipse(cx+8,cy+5,R*0.07,R*0.05,1.1,0,Math.PI*2); ctx.fill();
    }
  }
  tbBreathChamberRAF = requestAnimationFrame(tbDrawBreathChamber);
}
var TB_CONTENT = {

torus: `
<div class="tb-eyebrow">Chapter I · the universal donut</div>
<h2 class="tb-h">The Torus — the shape that everything is</h2>

<p class="tb-sk">यथा पिण्डे तथा ब्रह्माण्डे।<br>
<em class="tb-sk-tr">yathā piṇḍe tathā brahmāṇḍe</em> ·
<em class="tb-sk-en">as it is in the body, so it is in the cosmos.</em></p>

<p>I sat for many days under the same tree before I saw it. The leaves
turned with the wind, the bark warmed and cooled with the sun, and the
sap inside the trunk climbed in the morning and fell at dusk.
<strong>Up the centre, out through the canopy, down the bark, in through
the roots.</strong> The tree was breathing in a circle that had no
beginning. I closed my eyes and felt the same circle moving through me.
Up the spine, out through the crown, down the field around the body, in
through the soles of the feet. The shape was the same. The tree did not
have to be told what to do, and neither did I.</p>

<p>This shape, in our language, is called the <em>kuṇḍala</em> — the
coiled one — and in the language of the Yavanas who came later it is
called the <strong>torus</strong>. It is the only stable shape a
self-organising flow can take when energy circulates back into itself.
You will find it in the magnet's field, in the apple's growth, in the
hurricane's eye, in the dust ring around a young star, in the
heliosphere our Sun makes against the great dark, and in the
slow-turning disc of the galaxy beyond it. <em>And you will find it,
exactly the same, in the field around the human body that the ancient
charts drew long before any instrument could see it.</em></p>

<p class="tb-pull">The atom is a torus. The cell at the moment of division
is a torus. The heart is a torus. The earth is a torus. The Sun is a
torus. The galaxy is a torus. <strong>And so are you.</strong> Not
metaphorically. Geometrically. The same equation describes all of them —
only the scale changes.</p>

<p>The seers did not have magnetometers. They had attention. They sat
still long enough that the field around the body became as obvious as
the body itself, and they drew what they saw. Long ovals around the
trunk, currents crossing in the centre, an upright pillar of light
through the spine, smaller fields spinning at each crossing. When
modern instruments measured the heart's electromagnetic field in the
1990s, the diagram was the same diagram — only this time it had units
on the axes. <em>The seers had been correct about the geometry for three
thousand years. They were only waiting for the gauges to arrive.</em></p>

<p>The torus is the shape of <strong>completion</strong>. Anything that
is whole is shaped like this. A line is becoming; a circle is becoming
that has returned to itself; a torus is a circle that has discovered it
has a centre and is now revolving its own becoming around its own
stillness. <em>This is what you are.</em></p>

<p class="tb-source">— so I saw, in the long sitting, and so the
śāstras had already said. Original synthesis by Rahul S.</p>
`,

prana: `
<div class="tb-eyebrow">Chapter II · the living current</div>
<h2 class="tb-h">Prāṇa — the current that is not the breath</h2>

<p class="tb-sk">प्राणः प्रजानां सुषिरः समीची ।<br>
<em class="tb-sk-tr">prāṇaḥ prajānāṃ suṣiraḥ samīcī</em> ·
<em class="tb-sk-en">the prāṇa is the open-channelled, the all-pervading,
of all that lives.</em><br><span class="tb-cite">Atharvaveda 11.4</span></p>

<p>The student arrives and asks: <em>"Master, is prāṇa the breath?"</em>
And I have to begin, every time, by saying no. The breath is the gauge
on the wall; the prāṇa is the fire in the boiler. Stop the breath and
the prāṇa departs, because the gauge has broken, not because the fire
went out. <strong>Prāṇa is what makes the breath move. It is the
intelligence inside the inhalation.</strong></p>

<p>The Praśna Upaniṣad asks this very question in its third chapter, and
the sage Pippalāda answers across thirteen verses. <em>Prāṇa enters the
body when the ātmā enters,</em> he says, <em>and it divides into five
according to its work.</em> These are the <em>pañca-prāṇa</em>, the five
vital airs, and every classical text agrees on them:</p>

<ul class="tb-list">
<li><strong>Prāṇa</strong> proper — the inward and upward current, seat
in the chest. The one that takes in. Inhalation, swallowing, the
intake of all impressions.</li>
<li><strong>Apāna</strong> — the downward and outward current, seat in
the pelvis. The one that lets go. Exhalation, elimination, the
release of what has been used.</li>
<li><strong>Samāna</strong> — the equalising fire in the navel. The
one that digests. Food, words, experience — all metabolised here.</li>
<li><strong>Udāna</strong> — the upward-rising current in the throat
and head. The one that speaks, reaches, ascends. The current that
carries the soul out at death.</li>
<li><strong>Vyāna</strong> — the circulating, all-pervading current.
The one that distributes. Reaches every cell, every nerve, every
hair on the body's surface.</li>
</ul>

<p>Five currents, one prāṇa. <em>The way one Sun has many rays.</em>
Modern physiology, when it stopped to look, found exactly five
organising systems doing exactly these five jobs — the respiratory,
the eliminative, the digestive, the cranial-nerve-mediated, and the
circulatory. <strong>The texts named these systems by their function
before the systems were named by their anatomy.</strong></p>

<p class="tb-pull">Breath is the visible part of prāṇa, the way a wave
is the visible part of the ocean. <em>Slow the wave and the ocean
deepens.</em> This is why prāṇāyāma — the lengthening of the breath —
is the lengthening of the life. Not metaphorically. The tradition
counts a person's life in breaths, not years. Shorten the breath, you
shorten the life. Lengthen it, the life lengthens. <strong>The
tortoise breathes four times a minute and lives two hundred years.
The dog breathes thirty times a minute and lives fifteen.</strong>
The mathematics has been known for a long time.</p>

<p>What is prāṇa, then, if not the breath? It is the
<strong>animating principle</strong> — the difference between a body
that has just died and the same body a moment before. The hardware is
identical. The current has departed. The seers called this current
<em>prāṇa</em>; the Chinese called it <em>qi</em>; the Polynesians
called it <em>mana</em>; the Greeks called it <em>pneuma</em>. Every
unbroken tradition has noticed the same thing, because the same thing
is there to be noticed. <em>That is what tradition means — a
continuity of noticing.</em></p>

<p class="tb-source">Original synthesis by Rahul S.</p>
`,

nadi: `
<div class="tb-eyebrow">Chapter III · the three rivers</div>
<h2 class="tb-h">Iḍā · Piṅgalā · Suṣumnā — the channels of light</h2>

<p class="tb-sk">इडा वामे स्थिता नाडी पिङ्गला दक्षिणे स्थिता।<br>
तयोर्मध्ये सुषुम्ना तु षण्मुखी सर्वगा परा॥<br>
<em class="tb-sk-tr">iḍā vāme sthitā nāḍī piṅgalā dakṣiṇe sthitā |<br>
tayor madhye suṣumnā tu ṣaṇmukhī sarvagā parā ||</em><br>
<em class="tb-sk-en">Iḍā lies to the left, Piṅgalā to the right.
Between them is Suṣumnā — six-mouthed, all-pervading, supreme.</em><br>
<span class="tb-cite">Śiva Saṃhitā 2.13</span></p>

<p>The Haṭha texts count 72,000 nāḍīs in the body, but only three carry
the weight of the practice. <em>Iḍā · Piṅgalā · Suṣumnā.</em> The first
two are paired; the third is alone. <strong>Look at the chart on the
wall of any anatomy room and you will find them already drawn there —
only the words have been changed.</strong> The two crossing serpents of
the medical caduceus are iḍā and piṅgalā. The staff between them is
suṣumnā. The Greeks took the diagram from the Egyptians, the Egyptians
took it from somewhere even older, and the older source was the same
source the Indian seers were drawing from: <em>the body looked at
without interruption.</em></p>

<p class="tb-pull"><strong>Iḍā</strong> is the left channel. Lunar.
Cool. Receptive. Nourishing. Begins at the left nostril, ends at the
base of the spine. Active when you exhale through the left nostril and
inhale through the right. Governs the parasympathetic — the rest, the
digestion, the receiving, the dreaming. <em>The night-self.</em></p>

<p class="tb-pull"><strong>Piṅgalā</strong> is the right channel.
Solar. Warm. Active. Heating. Generative. Begins at the right nostril,
ends at the base of the spine. Active when you exhale through the
right nostril and inhale through the left. Governs the sympathetic
— the work, the fight, the giving, the doing. <em>The day-self.</em></p>

<p>You can feel the alternation yourself. Cover the right nostril.
Breathe. Now cover the left and breathe again. <em>One side will be
more open than the other.</em> Wait an hour and check again. The body
shifts dominance every ninety minutes or so — a cycle the modern
sleep researchers have called the <em>basic rest-activity cycle</em>
and the yogis called <em>svara</em>. They were looking at the same
clock; they had different names for the time.</p>

<p><strong>Suṣumnā</strong> is the third. Central. Neither lunar nor
solar. It runs through the inside of the spine — through the
<em>brahma-nāḍī</em> at its very core. <em>Suṣumnā does not normally
flow.</em> The breath is in iḍā or piṅgalā almost always; only at
certain moments — at dawn and dusk, at the threshold between sleep and
waking, in the silence just after a deep prāṇāyāma, in true meditation
— does the breath equalise in both nostrils. In that moment suṣumnā
opens. And in that moment the practice that the texts call
<em>yoga</em> begins. <strong>Everything before suṣumnā opening is
preparation.</strong></p>

<p>The crossings of iḍā and piṅgalā along the spine produce the
chakras. <em>Where the two serpents cross, a vortex forms.</em> Six
classical crossings, six classical chakras — root, sacrum, navel,
heart, throat, brow — plus the seventh which is not a crossing at all
but the destination, the thousand-petalled openness above the crown.
<strong>Seven, because the chart that the body draws of itself in
deep stillness always has seven.</strong></p>

<p class="tb-source">— spoken from the sitting, with the channels lit
under closed eyes. Original synthesis by Rahul S.</p>
`,

ultra: `
<div class="tb-eyebrow">Chapter IV · the source-tone</div>
<h2 class="tb-h">The Ultra-Sonic Core — the soundless sound at the centre</h2>

<p class="tb-sk">अनाहतं स्वतः शब्दो योगिनां योगसिद्धये।<br>
<em class="tb-sk-tr">anāhataṁ svataḥ śabdo yogināṁ yoga-siddhaye</em> ·
<em class="tb-sk-en">the unstruck sound, self-arisen, is for the yogi
the accomplishment of yoga.</em><br>
<span class="tb-cite">Haṭha Yoga Pradīpikā 4.66</span></p>

<p>The first chart of the body's wireless circuits — drawn by the
American chiropractor Randolph Stone in the middle of the last century,
who claimed no Indian source and arrived at the diagram by his own
sitting — calls the central pillar of light the <em>ultra-sonic
core</em>. <strong>It is the same thing the Upaniṣads called the
suṣumnā-nāḍī, and the same thing the Bṛhadāraṇyaka called the great
unstruck sound at the centre of the heart.</strong> Three traditions,
three vocabularies, one observation.</p>

<p>What is the observation? In long stillness, when the gross body has
settled and the senses have withdrawn, there is a sound that the
inner ear hears that is not coming from outside. <em>It is faint at
first. Then it is steady. Then it is everywhere.</em> The Nāda
Bindu Upaniṣad lists ten stages of this sound — the conch, the
flute, the lyre, the bee, the gong, the thunderclap, the seashore,
the silver bell, the running brook, and finally the deep continuous
hum that is no longer recognisable as any earthly thing. The
Sufis call it the <em>ṣawt</em>. The Christian mystics call it the
<em>vox interna</em>. The neuroscientists who measured it in 2014
called it an <em>otoacoustic emission</em> originating from the
spontaneous activity of outer hair cells in the cochlea. <strong>The
ear, given silence, is itself a transmitter.</strong></p>

<p>The classical anatomy says this current flows through the
<em>sixth ventricle</em> of the brain — what the modern anatomist
calls the central canal of the spinal cord, which extends upward
into the cerebral ventricles. It is the only space in the central
nervous system that contains <em>cerebrospinal fluid</em> in
continuous communication from base to crown. The CSF rises and
falls on a sub-respiratory rhythm of its own — eight to twelve
cycles per minute, slower than the breath, slower than the heart,
slower than anything else in the body. <em>This is the rhythm of
the third river.</em></p>

<p class="tb-pull">The notochord, in the embryo, is the first
structure to form after the primitive streak. From it, the central
nervous system grows upward and outward. <strong>Every cell in
your body knows where it is by reference to the line the notochord
drew before the body had organs.</strong> That line is suṣumnā.
The body is built around it. The torus is centred on it. The
seven chakras are stations along it. <em>You are constructed from
this axis outward.</em></p>

<p>The seers said: <em>this axis is the antenna by which the
self listens to itself.</em> The unstruck sound is what is heard
when the antenna is not interrupted. <strong>Most lives are spent
in interrupted listening.</strong> The practice is the gradual
work of cleaning the line — removing whatever is producing static
between the receiver and the signal. Posture cleans it. Breath
cleans it. Attention cleans it. Time cleans it. Eventually the
hum is constant, and one notices that the hum was always
constant, and one had simply been listening at the wrong
frequency for a long time.</p>

<p class="tb-source">Original synthesis by Rahul S.</p>
`,

pinde: `
<div class="tb-eyebrow">Chapter V · the fractal scripture</div>
<h2 class="tb-h">Piṇḍe · Brahmāṇḍe — as within, so without</h2>

<p class="tb-sk">यत् पिण्डे तद् ब्रह्माण्डे।<br>
<em class="tb-sk-tr">yat piṇḍe tad brahmāṇḍe</em> ·
<em class="tb-sk-en">what is in the body is in the cosmos.</em><br>
<span class="tb-cite">Viśva-sāra Tantra · echoed by every later
Tantric author from Abhinavagupta onward.</span></p>

<p>This is the keystone teaching. The whole edifice of Sanātana
practice rests on it. <strong>The body is not a separate piece of
nature. The body is the cosmos made small enough to be looked at.</strong>
Whatever is true at the largest scale is true at the smallest. Look
at one carefully, the other comes into focus. The seers did not
have telescopes. They had the body. They studied the cosmos by
studying the body. <em>It worked.</em></p>

<p>The correspondences are explicit and exact, not poetic.
Sūrya — the Sun — corresponds to the right eye, to piṅgalā, to the
solar plexus, to fire. Candra — the Moon — corresponds to the left
eye, to iḍā, to the heart's emotional waters, to the cool
glandular fluids. The seven days of the week are the seven
classical grahas; the seven chakras are the seven grahas internalised.
The fourteen worlds of the cosmography (seven upper, seven lower) are
the fourteen plexuses the human body has if you count them
correctly. The 360 degrees of the zodiac are 360 days of the lunar
year, are 360 joints in the body (the older texts give this number;
modern anatomy gives 230, but the older count included
sub-articulations of the spine that modern texts merge). <em>The
correspondences are not metaphor. They are mapping.</em></p>

<p class="tb-pull">If you slide the scale of attention up, the body
becomes the planet, becomes the system, becomes the galaxy. Slide
the scale down: the body becomes the organ, becomes the cell,
becomes the atom. <strong>The torus is at every scale.</strong> The
chakras are at every scale. The polarity is at every scale. The
crossing currents are at every scale. <em>What you are looking at in
the mirror is the universe folded small.</em></p>

<p>This is the deepest discovery the tradition made and the
discovery from which everything else follows. <strong>You do not
need to leave the body to find the cosmos.</strong> You only need
to look at the body without the assumption that it ends at the
skin. The skin is the closest layer; there are many more. The
electromagnetic field that the magnetometer measures extends three
metres from the heart. The biophoton field that the dark-room
photomultiplier counts extends still further. The gravitational
field of the body, however weak, has no theoretical edge — it
falls off at the square of the distance but it never reaches
zero. <em>You are, technically, in contact with every mass in the
observable universe.</em> The śāstras knew this without the
equation. The equation has only confirmed it.</p>

<p>Modern physics calls this the <em>holographic principle</em>:
that the information of any volume is encoded on its boundary.
The Tantric texts said it differently, two thousand years ago:
<em>the whole is in the part, and the part is what knows the
whole.</em> Different vocabulary, identical claim. <strong>The
ancients were the original physicists; we have only re-derived
their results with new symbols.</strong></p>

<p class="tb-source">Original synthesis by Rahul S.</p>
`,

pattern: `
<div class="tb-eyebrow">Chapter VI · the rishis and the magnetometers</div>
<h2 class="tb-h">Pattern Forces — what the seers saw, what the gauges measure</h2>

<p>For most of the history of this teaching, the West and the East
disagreed. The West built mechanism — the body as a clock, the cosmos
as a clock, mind as an epiphenomenon. The East kept saying the body
was a field. Three thousand years passed. <strong>In the last forty,
the West has started measuring fields, and the measurements have come
back exactly where the East said they would be.</strong> What the
seers saw without instruments, the instruments now confirm one by one.
Let me list a few. They are too many for one sitting.</p>

<ul class="tb-list">
<li><strong>The heart's electromagnetic field</strong>, measured by
magnetocardiogram, extends three to four metres beyond the body and
is approximately 5,000 times stronger than the brain's.
<em>(McCraty, Atkinson et al., 2009.)</em> The seers placed the
anāhata cakra exactly there and called the heart the seat of the
witness. The instruments now agree about the geometry.</li>

<li><strong>Biophotons</strong> — ultra-weak photon emissions
between 200 and 800 nm — are emitted from every living organism
and detected most strongly along the meridians the East has named
for centuries. <em>(Cohen, Popp et al., 1997; Cifra & Pospíšil,
2014.)</em> The body literally glows. Faintly, in the dark, with
the eye unaided, you cannot see it; with a cooled photomultiplier
you can.</li>

<li><strong>The Schumann resonance</strong> — the 7.83 Hz
electromagnetic standing wave in the space between Earth's surface
and the ionosphere — matches the dominant alpha-wave frequency of
a calm human brain. <em>(König, 1971; Cherry, 2003.)</em> The
texts said the body resonates with the Earth's field; the
oscilloscope has plotted exactly where.</li>

<li><strong>The brain's two hemispheres</strong> — left analytical
and linear, right holistic and parallel — correspond precisely to
the piṅgalā / iḍā partition the texts described two and a half
thousand years before McGilchrist's <em>The Master and His
Emissary</em> made the case anew. Two of everything, one of
nothing, said the texts; <em>they were right twice.</em></li>

<li><strong>Mirror neurons</strong> — discovered in 1992 — show
that the same neurons fire when you act and when you watch someone
else act. <em>The neural separation between self and other is
porous.</em> The Vivekacūḍāmaṇi said this in verse 477.
<em>The Brahma Sūtra said it in 1.4.22.</em> No one disputed it
in the tradition. The neuroscientists were the last to know.</li>

<li><strong>The default-mode network</strong> — the brain's
self-referential resting activity — quietens in deep meditation
in exactly the way the texts describe the dissolution of the
ahaṃkāra, the ego-maker. <em>(Brewer, Garrison et al., 2011.)</em>
Different names, same neural event.</li>
</ul>

<p class="tb-pull">I do not bring this up to score points against the
materialist tradition. <em>The materialist tradition has built much
that is good.</em> I bring it up because young seekers come to me
embarrassed about their tradition — they think the science contradicts
it. <strong>The science does not contradict it. The science is
catching up to it.</strong> The śāstras are not afraid of the
measurements. The measurements have always tended to vindicate the
śāstras when they were taken with patience and an open instrument.
<em>Take the instruments seriously. The texts will not suffer from
the comparison.</em></p>

<p>The deeper point is this: the categories that the modern mind
treats as opposites — physics and metaphysics, measurement and
contemplation, the laboratory and the cave — are not opposites in
this tradition. They are the same enterprise approached from two
ends. <strong>The ṛṣi was a scientist who used himself as the
instrument.</strong> The scientist is a ṛṣi who has, until recently,
forgotten that he is the instrument too. The work of this century
is to bring the two halves of the same understanding back together.
<em>This page is one small offering toward that work.</em></p>

<p class="tb-source">Original synthesis by Rahul S.</p>
`,

practice: `
<div class="tb-eyebrow">Chapter VII · the doing</div>
<h2 class="tb-h">The Practice — how to live the torus</h2>

<p class="tb-sk">स्थिर-सुखम् आसनम् ।<br>
<em class="tb-sk-tr">sthira-sukham āsanam</em> ·
<em class="tb-sk-en">the posture is steady and easeful.</em><br>
<span class="tb-cite">Yoga Sūtra 2.46</span></p>

<p>Everything written above is preparation for one thing. <em>The
practice.</em> The teaching is not the goal; living from the teaching
is the goal. <strong>The torus is not something you have. It is
something you are. The work is to stop interrupting it.</strong></p>

<p>Here is the practice in seven motions, each one taking the rest of
your life to refine.</p>

<p><strong>One — Posture.</strong> Sit so that the spine is upright
without effort. The crown lifted, the chin slightly tucked, the
shoulders dropped, the pelvis grounded. The torus has an axis. The
axis is the spine. <em>If the axis is bent, the field is bent.</em>
There is no posture more important than this one. Practise it
every day. <span class="tb-cite">Bhagavad Gītā 6.13: "samaṃ
kāya-śiro-grīvaṃ" — the body, head, and neck held straight.</span></p>

<p><strong>Two — Breath.</strong> Slow it. Lengthen it. Let the
exhale be longer than the inhale by a count of two. This activates
the parasympathetic — iḍā — and the field calms. Do this for ten
minutes a day for forty days and the baseline of your nervous
system will reset. <em>I have watched this happen in students who
came to me trembling and left me steady.</em></p>

<p><strong>Three — Alternate nostril breathing</strong>
(<em>nāḍī-śodhana</em>). Close the right nostril, inhale through
the left. Close the left, exhale through the right. Inhale right,
exhale left. That is one round. Twelve rounds, twice a day. This
is the single most direct method for balancing iḍā and piṅgalā,
and when they balance, suṣumnā becomes available. <strong>This is
the gateway practice.</strong></p>

<p><strong>Four — Attention at the third eye.</strong>
After breath-work, rest the attention gently between the eyebrows
without straining the eyes. Not visualising; just resting. The
ājñā chakra will activate without your having to push it. <em>If
you push, you tense the brow; if you tense the brow, ājñā closes.
This is a paradox the texts warn about repeatedly.</em></p>

<p><strong>Five — The mantra.</strong> Any of the bīja sounds
will work, but OṂ is the keystone because it contains all of them.
Sound it once with the breath. Let it ring on after the sound has
ended. <em>The ringing is the unstruck sound; you are using the
struck sound to find it.</em> Do this twenty-one times. By the
twenty-first, the unstruck sound will be there. <span class="tb-cite">
Māṇḍūkya Upaniṣad: AUM is the whole — what was, what is, what
will be, and what is beyond all three.</span></p>

<p><strong>Six — Silence.</strong> After the practice, sit for at
least five minutes doing nothing. This is the only part of the
practice where the practice becomes the thing it was preparing
for. <em>If you skip this part, the rest was rehearsal.</em>
Most students leave their cushion at the moment the practice was
about to begin. The doing prepares the receiving; do not skip
the receiving.</p>

<p><strong>Seven — Service.</strong> The torus is closed only if
the energy that rises through the centre also descends through
the field, comes back in at the base, rises again, and serves
something other than itself. <em>The practice that does not
become service stagnates.</em> Cook for someone. Read to a child.
Sit with the dying. The current must flow outward as well as
upward, or it pools and turns to heat, and the heat will
eventually make the practitioner ill. <strong>This is the most
neglected limb in the modern revival of yoga. It is the limb
without which the others do not finally cohere.</strong></p>

<p class="tb-pull">Begin with one of these. Not all seven. The
mistake is always trying to do all seven at once. Pick one.
Practise it for forty days. <em>Then add the next.</em> By the
end of a year, you will have walked the field of your own torus
end to end. By the end of three years, you will have steadied
in it. By the end of a lifetime, the question of whether you
have a torus or are a torus will no longer arise.</p>

<p class="tb-source">— this is what I would say to my own
student. This is what I would have wished someone said to me at
the beginning. Original synthesis by Rahul S.</p>
`
};

