function tbInit(){
  tbCanvas = $tb('tb-canvas');
  if(!tbCanvas){
    // overlay may have been removed; abort
    return;
  }
  tbCtx = tbCanvas.getContext('2d');
  tbT0 = performance.now();
  tbResize();
  tbInitCosmos();
  tbInitTorus();

  if(!tbInitialized){
    // canvas events
    tbCanvas.addEventListener('click', tbCanvasClick);
    tbCanvas.addEventListener('mousedown', tbDragStart);
    tbCanvas.addEventListener('mousemove', tbDragMove);
    tbCanvas.addEventListener('mouseup', tbDragEnd);
    tbCanvas.addEventListener('mouseleave', tbDragEnd);
    tbCanvas.addEventListener('touchstart', function(e){
      // tap detection: store touch start
      tbCanvas._touchT0 = Date.now();
      tbCanvas._touchX0 = e.touches[0].clientX;
      tbCanvas._touchY0 = e.touches[0].clientY;
      tbDragStart(e);
    }, {passive:false});
    tbCanvas.addEventListener('touchmove', tbDragMove, {passive:false});
    tbCanvas.addEventListener('touchend', function(e){
      tbDragEnd();
      // if it was a quick tap (no big drag), treat as click on last position
      var t0 = tbCanvas._touchT0;
      if(t0 && Date.now() - t0 < 250){
        // build a synthetic click using changedTouches
        if(e.changedTouches && e.changedTouches.length){
          var ct = e.changedTouches[0];
          var rect = tbCanvas.getBoundingClientRect();
          var x = ct.clientX - rect.left;
          var y = ct.clientY - rect.top;
          var dx = Math.abs(ct.clientX - tbCanvas._touchX0);
          var dy = Math.abs(ct.clientY - tbCanvas._touchY0);
          if(dx < 14 && dy < 14){
            // hit-test
            for(var c=0; c<7; c++){
              var ch = TB_CHAKRAS[c];
              if(ch._x === undefined) continue;
              var ddx = x - ch._x, ddy = y - ch._y;
              if(ddx*ddx + ddy*ddy < 32*32){
                tbActiveChakra = c;
                tbUpdateChakraReadout();
                return;
              }
            }
            if(tbActiveChakra >= 0){
              tbActiveChakra = -1;
              tbUpdateChakraReadout();
            }
          }
        }
      }
    });
    window.addEventListener('resize', tbResizeGuarded);
    tbInitialized = true;
  }

  if(tbRAF) cancelAnimationFrame(tbRAF);
  tbDraw();
}

window.openPindeBrahmande = function(){
  var ov = $tb('torus-exp');
  if(!ov) return;
  // close any other open modals first (avoid stacking)
  ov.classList.add('on');
  // reset some state on open
  tbBreathOn = false;
  tbActiveChakra = -1;
  tbFieldsOn = true;
  tbShowNadis.ida = true;
  tbShowNadis.pingala = true;
  tbShowNadis.sushumna = true;
  tbScale = 2;
  tbRotY = 0; tbRotV = 0;
  tbPolarityFlip = 0; tbPolarityDir = 1;
  // ensure UI states reflect reset
  setTimeout(function(){
    var dots = document.querySelectorAll('.tb-scale-dot');
    for(var i=0;i<dots.length;i++) dots[i].classList.toggle('active', i===2);
    var lbl = $tb('tb-scale-lbl'); if(lbl) lbl.textContent='Organ';
    var bbtn = $tb('tb-breath-btn'); if(bbtn){ bbtn.classList.remove('active'); bbtn.textContent='◉ Breathe With Me'; }
    var fbtn = $tb('tb-fields-btn'); if(fbtn){ fbtn.classList.remove('active'); fbtn.textContent='⊚ Hide Torus'; }
    var nb = document.querySelectorAll('.tb-nadi-btn');
    for(var n=0;n<nb.length;n++) nb[n].classList.add('active');
    var cr = $tb('tb-chakra-readout'); if(cr){ cr.classList.remove('on'); cr.innerHTML=''; }
    var dp = $tb('tb-darshan'); if(dp) dp.classList.remove('on');
    tbDarshanOpen = false;
  }, 50);
  setTimeout(tbInit, 320);
};

window.closePindeBrahmande = function(){
  var ov = $tb('torus-exp');
  if(!ov) return;
  ov.classList.remove('on');
  if(tbRAF){ cancelAnimationFrame(tbRAF); tbRAF=null; }
  if(tbCymaticRAF){ cancelAnimationFrame(tbCymaticRAF); tbCymaticRAF=null; }
  if(tbBreathChamberRAF){ cancelAnimationFrame(tbBreathChamberRAF); tbBreathChamberRAF=null; }
  tbDarshanOpen = false;
  tbBreathOn = false;
  tbActiveChakra = -1;
  var p = $tb('tb-darshan'); if(p) p.classList.remove('on');
  var btn = $tb('tb-breath-btn'); if(btn){ btn.classList.remove('active'); btn.textContent='◉ Breathe With Me'; }
  tbUpdateChakraReadout();
};

// ESC handler — chakra → darshan → overlay
document.addEventListener('keydown', function(e){
  if(e.key !== 'Escape') return;
  var ov = $tb('torus-exp');
  if(!ov || !ov.classList.contains('on')) return;
  if(tbActiveChakra >= 0){ window.tbCloseChakra(); return; }
  if(tbDarshanOpen){ window.tbCloseDarshan(); return; }
  window.closePindeBrahmande();
});

// Visibility — resume the main loop when tab becomes visible again
// (the loop self-pauses when document.hidden via tbDraw's guard)
document.addEventListener('visibilitychange', function(){
  if(document.hidden) return;
  var ov = $tb('torus-exp');
  if(!ov || !ov.classList.contains('on')) return;
  // restart main loop if it had stopped
  if(!tbRAF){ tbDraw(); }
  // restart cymatic loop if the canvas is in DOM
  if(!tbCymaticRAF && document.getElementById('tb-cym-canvas')){ tbDrawCymatic(); }
  // restart breath-chamber loop if its canvases are in DOM
  if(!tbBreathChamberRAF && document.querySelector('.tb-bou-canvas')){ tbDrawBreathChamber(); }
});

