// ─── build node index map + adjacency ──────────────────────────────────
var IJ_IDX = {};                          // id → index
var IJ_ADJ = {};                          // id → array of {to, type}
function ijBuildIndex(){
  IJ_IDX = {}; IJ_ADJ = {};
  for(var i=0; i<IJ_NODES.length; i++){
    IJ_IDX[IJ_NODES[i].id] = i;
    IJ_ADJ[IJ_NODES[i].id] = [];
  }
  for(var e=0; e<IJ_EDGES.length; e++){
    var ed = IJ_EDGES[e];
    if(IJ_IDX[ed[0]]===undefined || IJ_IDX[ed[1]]===undefined) continue;
    IJ_ADJ[ed[0]].push({to:ed[1], type:ed[2]});
    IJ_ADJ[ed[1]].push({to:ed[0], type:ed[2]});  // undirected for visualisation
  }
}

// ─── canvas resize ─────────────────────────────────────────────────────
function ijResize(){
  if(!ijCanvas || !ijCtx) return;
  var rect=ijCanvas.getBoundingClientRect();
  ijDPR=Math.min(window.devicePixelRatio||1, 1.5);
  ijW=Math.max(320,Math.floor(rect.width));
  ijH=Math.max(480,Math.floor(rect.height));
  ijCanvas.width=Math.floor(ijW*ijDPR);
  ijCanvas.height=Math.floor(ijH*ijDPR);
  ijCanvas.style.width=ijW+'px';
  ijCanvas.style.height=ijH+'px';
  ijCtx.setTransform(ijDPR,0,0,ijDPR,0,0);
}
function ijResizeGuarded(){
  if(typeof guardedResize==='function'){ guardedResize(ijResize,200); }
  else{ clearTimeout(ijResizeTimer); ijResizeTimer=setTimeout(ijResize,200); }
}

// ─── stars ─────────────────────────────────────────────────────────────
function ijInitStars(){
  ijStars.length=0;
  for(var i=0;i<110;i++){
    ijStars.push({
      x:Math.random(), y:Math.random(),
      r:0.3 + Math.random()*1.4,
      tw:Math.random()*Math.PI*2,
      twS: 0.4 + Math.random()*1.2,
      hue: Math.random()<0.18 ? (200+Math.random()*60) : (40+Math.random()*30)
    });
  }
}

// ─── INITIAL POSITIONS — layout nodes by layer in concentric rings ─────
// This gives the force simulation a meaningful starting state.
function ijLayoutNodes(){
  // Group nodes by layer
  var byLayer = {1:[],2:[],3:[],4:[],5:[],6:[],7:[]};
  for(var i=0; i<IJ_NODES.length; i++){
    var n = IJ_NODES[i];
    if(!byLayer[n.layer]) byLayer[n.layer]=[];
    byLayer[n.layer].push(n);
  }
  // Layer 7 (meta) is centre; 1 (physical) is outermost.
  // For each layer, distribute nodes around a circle whose radius depends on layer.
  // Layer→radius: 7=80, 5=210, 6=320, 2=450, 3=560, 4=380, 1=620
  // We want concept-clusters near each other, so we slightly perturb angles by category.
  var layerR = {7:80, 5:210, 4:340, 6:440, 3:540, 2:640, 1:740};
  for(var L=1; L<=7; L++){
    var arr = byLayer[L] || [];
    var R = layerR[L] || 400;
    for(var j=0; j<arr.length; j++){
      var theta = (j / Math.max(arr.length,1)) * Math.PI*2;
      var jitter = (Math.random()-0.5)*60;
      arr[j].x = Math.cos(theta) * (R + jitter);
      arr[j].y = Math.sin(theta) * (R + jitter);
      arr[j].vx = 0; arr[j].vy = 0;
    }
  }
}

// ─── FORCE SIMULATION — Verlet-style ────────────────────────────────────
// Repulsion between all pairs (Coulomb-style, O(N²) but N=110 is fine).
// Attraction along edges (spring).
// Centering gravity toward (0,0).
// Damping each step.
function ijSimStep(){
  if(IJ_NODES.length===0) return;
  var N = IJ_NODES.length;
  var REPEL = 18000;           // strength of node-node repulsion
  var SPRING = 0.013;          // spring constant for edges
  var REST = 165;              // target edge length
  var GRAVITY = 0.0012;        // pull toward centre
  var DAMP = 0.78;             // velocity damping per step

  // 1) reset force accumulators on each node
  for(var i=0; i<N; i++){ IJ_NODES[i].fx=0; IJ_NODES[i].fy=0; }

  // 2) pairwise repulsion
  for(var a=0; a<N; a++){
    var na = IJ_NODES[a];
    for(var b=a+1; b<N; b++){
      var nb = IJ_NODES[b];
      var dx = na.x - nb.x, dy = na.y - nb.y;
      var d2 = dx*dx + dy*dy + 0.1;
      var d = Math.sqrt(d2);
      var f = REPEL / d2;
      if(f > 12) f = 12;
      var fxv = (dx/d) * f, fyv = (dy/d) * f;
      na.fx += fxv; na.fy += fyv;
      nb.fx -= fxv; nb.fy -= fyv;
    }
  }

  // 3) edge springs
  for(var e=0; e<IJ_EDGES.length; e++){
    var ed = IJ_EDGES[e];
    var ai = IJ_IDX[ed[0]], bi = IJ_IDX[ed[1]];
    if(ai===undefined || bi===undefined) continue;
    var na2 = IJ_NODES[ai], nb2 = IJ_NODES[bi];
    var dx2 = nb2.x - na2.x, dy2 = nb2.y - na2.y;
    var d22 = Math.sqrt(dx2*dx2 + dy2*dy2) + 0.001;
    var disp = d22 - REST;
    var fmag = SPRING * disp;
    var fxe = (dx2/d22) * fmag, fye = (dy2/d22) * fmag;
    na2.fx += fxe; na2.fy += fye;
    nb2.fx -= fxe; nb2.fy -= fye;
  }

  // 4) centering gravity
  for(var c=0; c<N; c++){
    var nc = IJ_NODES[c];
    nc.fx -= nc.x * GRAVITY;
    nc.fy -= nc.y * GRAVITY;
  }

  // 5) integrate — but skip the actively dragged node
  var totalKE = 0;
  for(var k=0; k<N; k++){
    var nk = IJ_NODES[k];
    if(ijDraggingNode === nk.id){ nk.vx = 0; nk.vy = 0; continue; }
    nk.vx = (nk.vx + nk.fx) * DAMP;
    nk.vy = (nk.vy + nk.fy) * DAMP;
    // velocity cap
    var vmag = Math.sqrt(nk.vx*nk.vx + nk.vy*nk.vy);
    if(vmag > 8){ nk.vx *= 8/vmag; nk.vy *= 8/vmag; }
    nk.x += nk.vx;
    nk.y += nk.vy;
    totalKE += nk.vx*nk.vx + nk.vy*nk.vy;
  }
  ijSimEnergy = totalKE;
}

// Should we keep iterating? Run hot first ~600 steps, then only when energy is high enough
// or when a user just touched something.
function ijShouldSim(){
  if(ijSimSteps < 600) return true;
  if(ijSimEnergy > 0.08) return true;
  return false;
}

// ─── helpers ───────────────────────────────────────────────────────────
function ijWorldToScreen(wx, wy){
  return {
    x: ijW*0.5 + ijOffsetX + wx * ijScale,
    y: ijH*0.5 + ijOffsetY + wy * ijScale
  };
}
function ijScreenToWorld(sx, sy){
  return {
    x: (sx - ijW*0.5 - ijOffsetX) / ijScale,
    y: (sy - ijH*0.5 - ijOffsetY) / ijScale
  };
}

function ijNodeMatchesSearch(n){
  if(!ijSearchTerm) return true;
  var q = ijSearchTerm.toLowerCase();
  return ((''+n.id).toLowerCase().indexOf(q)>=0) ||
         ((''+n.tr).toLowerCase().indexOf(q)>=0) ||
         ((''+n.en).toLowerCase().indexOf(q)>=0) ||
         ((''+n.sa).indexOf(q)>=0);
}

function ijNodeVisible(n){
  // filter by category
  if(ijCatFilter[n.cat]===false) return false;
  // filter by layer
  if(ijLayerFilter[n.layer]===false) return false;
  return true;
}

function ijIsConnected(a_id, b_id){
  var lst = IJ_ADJ[a_id]; if(!lst) return null;
  for(var i=0; i<lst.length; i++) if(lst[i].to === b_id) return lst[i].type;
  return null;
}

// ─── DRAW background ───────────────────────────────────────────────────
function ijDrawBackground(){
  var t = (performance.now()-ijT0)/1000;
  // deep base
  var bg = ijCtx.createRadialGradient(ijW*0.5, ijH*0.5, ijW*0.05, ijW*0.5, ijH*0.5, ijW*0.85);
  bg.addColorStop(0, '#0c0820');
  bg.addColorStop(0.5,'#070518');
  bg.addColorStop(1, '#02010a');
  ijCtx.fillStyle = bg; ijCtx.fillRect(0,0,ijW,ijH);
  // stars (cheap, plain fills)
  for(var i=0; i<ijStars.length; i++){
    var s = ijStars[i];
    s.tw += 0.015 * s.twS;
    var alpha = 0.30 + 0.45 * (0.5 + 0.5*Math.sin(s.tw));
    var sx = (s.x % 1) * ijW;
    var sy = s.y * ijH;
    ijCtx.fillStyle = 'hsla('+s.hue+', 70%, 88%, '+alpha+')';
    ijCtx.beginPath(); ijCtx.arc(sx, sy, s.r, 0, Math.PI*2); ijCtx.fill();
  }
}

// ─── DRAW edges ────────────────────────────────────────────────────────
function ijDrawEdges(){
  // Only render edges where both endpoints are visible-by-filter.
  for(var e=0; e<IJ_EDGES.length; e++){
    var ed = IJ_EDGES[e];
    var ai = IJ_IDX[ed[0]], bi = IJ_IDX[ed[1]];
    if(ai===undefined || bi===undefined) continue;
    var na = IJ_NODES[ai], nb = IJ_NODES[bi];
    if(!ijNodeVisible(na) || !ijNodeVisible(nb)) continue;
    var rel = IJ_RELS[ed[2]] || IJ_RELS.ASSOCIATED;
    var pa = ijWorldToScreen(na.x, na.y);
    var pb = ijWorldToScreen(nb.x, nb.y);
    // skip if both offscreen
    if((pa.x<-20 && pb.x<-20) || (pa.x>ijW+20 && pb.x>ijW+20) ||
       (pa.y<-20 && pb.y<-20) || (pa.y>ijH+20 && pb.y>ijH+20)) continue;
    // emphasis: if active node is one endpoint, brighter; if neither, dimmer
    var alpha = 1;
    if(ijActive){
      if(na.id===ijActive || nb.id===ijActive){ alpha = 1.25; }
      else { alpha = 0.20; }
    }
    if(ijSearchTerm){
      // dim edges not touching a matching node
      if(!ijNodeMatchesSearch(na) && !ijNodeMatchesSearch(nb)) alpha *= 0.35;
    }
    // colour
    var col = rel.col;
    // multiply alpha into rgba
    var rgbaMatch = col.match(/rgba\((\d+),(\d+),(\d+),([\d.]+)\)/);
    var drawCol = col;
    if(rgbaMatch){
      var newA = Math.min(1, parseFloat(rgbaMatch[4]) * alpha);
      drawCol = 'rgba('+rgbaMatch[1]+','+rgbaMatch[2]+','+rgbaMatch[3]+','+newA+')';
    }
    ijCtx.strokeStyle = drawCol;
    ijCtx.lineWidth = (ijActive && (na.id===ijActive || nb.id===ijActive)) ? 1.6 : 0.9;
    ijCtx.beginPath();
    ijCtx.moveTo(pa.x, pa.y); ijCtx.lineTo(pb.x, pb.y);
    ijCtx.stroke();
  }
}

// ─── DRAW nodes ────────────────────────────────────────────────────────
function ijDrawNodes(){
  var t = (performance.now()-ijT0)/1000;
  for(var i=0; i<IJ_NODES.length; i++){
    var n = IJ_NODES[i];
    if(!ijNodeVisible(n)) continue;
    var p = ijWorldToScreen(n.x, n.y);
    // skip if offscreen
    if(p.x < -30 || p.x > ijW+30 || p.y < -30 || p.y > ijH+30) continue;
    var cat = IJ_CATS[n.cat] || IJ_CATS.concept;
    var col = cat.col;
    var hexR = parseInt(col.slice(1,3),16);
    var hexG = parseInt(col.slice(3,5),16);
    var hexB = parseInt(col.slice(5,7),16);
    var rgba = function(a){ return 'rgba('+hexR+','+hexG+','+hexB+','+a+')'; };

    var isActive = (n.id === ijActive);
    var isHover = (n.id === ijHover);
    var connected = ijActive ? (ijIsConnected(ijActive, n.id) !== null || n.id===ijActive) : false;
    var matchSearch = ijNodeMatchesSearch(n);

    var r = 8;
    if(isActive) r = 16;
    else if(isHover) r = 12;
    else if(connected) r = 11;
    // gentle breathing pulse
    r += Math.sin(t*1.5 + i*0.3) * 0.6;

    // emphasis alpha
    var coreAlpha = 0.95;
    var glowAlpha = 0.42;
    if(ijActive && !connected){ coreAlpha = 0.25; glowAlpha = 0.10; }
    if(ijSearchTerm && !matchSearch){ coreAlpha *= 0.35; glowAlpha *= 0.35; }

    // glow halo (plain fill, no gradients per node — cheap)
    ijCtx.fillStyle = rgba(glowAlpha);
    ijCtx.beginPath(); ijCtx.arc(p.x, p.y, r*2.4, 0, Math.PI*2); ijCtx.fill();
    // outer ring for active
    if(isActive){
      ijCtx.strokeStyle = rgba(0.95);
      ijCtx.lineWidth = 2;
      ijCtx.beginPath(); ijCtx.arc(p.x, p.y, r*1.7, 0, Math.PI*2); ijCtx.stroke();
    }
    // core
    ijCtx.fillStyle = rgba(coreAlpha);
    ijCtx.beginPath(); ijCtx.arc(p.x, p.y, r, 0, Math.PI*2); ijCtx.fill();
    // dot at very centre
    if(isActive || isHover || connected){
      ijCtx.fillStyle = 'rgba(255,250,230,'+coreAlpha+')';
      ijCtx.beginPath(); ijCtx.arc(p.x, p.y, Math.min(r*0.45, 4), 0, Math.PI*2); ijCtx.fill();
    }
    // label
    var showLabel = isActive || isHover || (ijScale > 0.8 && (connected || matchSearch));
    if(showLabel){
      ijCtx.font = '500 11px "Cinzel", serif';
      ijCtx.textAlign = 'center';
      ijCtx.textBaseline = 'top';
      var label = n.tr;
      // shadow / outline for legibility
      ijCtx.fillStyle = 'rgba(8,5,15,0.85)';
      ijCtx.fillText(label, p.x+1, p.y + r + 5);
      ijCtx.fillStyle = isActive ? '#FFE9B0' : 'rgba(255,235,200,0.92)';
      ijCtx.fillText(label, p.x, p.y + r + 4);
    }
  }
}

// ─── HUD overlay (top-left layer key) ──────────────────────────────────
function ijDrawHUD(){
  // simulation settling indicator
  if(ijSimSteps < 600){
    ijCtx.fillStyle = 'rgba(255,230,180,0.55)';
    ijCtx.font = '400 9px "IBM Plex Mono", monospace';
    ijCtx.textAlign = 'left'; ijCtx.textBaseline = 'top';
    ijCtx.fillText('settling… '+Math.floor((ijSimSteps/600)*100)+'%', 16, ijH - 22);
  }
}

// ─── MAIN DRAW LOOP ─────────────────────────────────────────────────────
function ijDraw(){
  try {
    if(!ijCtx || !ijCanvas){ ijRAF=null; return; }
    if(document.hidden){
      ijRAF = requestAnimationFrame(ijDraw);
      return;
    }
    var ov = $ij('indrajala-exp');
    if(!ov || !ov.classList.contains('on')){ ijRAF=null; return; }

    // smooth zoom interpolation
    ijScale += (ijTargetScale - ijScale) * 0.18;

    // run physics steps (multiple per frame while hot)
    var stepsThisFrame = ijSimSteps < 200 ? 3 : (ijSimSteps < 600 ? 2 : 1);
    for(var s=0; s<stepsThisFrame; s++){
      if(ijShouldSim()){ ijSimStep(); ijSimSteps++; }
    }

    ijDrawBackground();
    ijDrawEdges();
    ijDrawNodes();
    ijDrawHUD();

  } catch(e){
    if(window.console && console.error) console.error('ijDraw frame error:', e);
  }
  ijRAF = requestAnimationFrame(ijDraw);
}

// ─── HIT TEST ──────────────────────────────────────────────────────────
function ijHitTest(sx, sy){
  // returns node id at screen coordinates, or null
  // iterate in reverse so later (visually-on-top) nodes win ties
  for(var i=IJ_NODES.length-1; i>=0; i--){
    var n = IJ_NODES[i];
    if(!ijNodeVisible(n)) continue;
    var p = ijWorldToScreen(n.x, n.y);
    var dx = sx - p.x, dy = sy - p.y;
    var r = (n.id===ijActive) ? 22 : 16;
    if(dx*dx + dy*dy < r*r) return n.id;
  }
  return null;
}

// ─── CANVAS EVENT HANDLERS ─────────────────────────────────────────────
function ijCanvasPos(evt){
  if(!ijCanvas) return null;
  var rect = ijCanvas.getBoundingClientRect();
  var x, y;
  if(evt.touches && evt.touches.length){
    x = evt.touches[0].clientX - rect.left;
    y = evt.touches[0].clientY - rect.top;
  } else {
    x = evt.clientX - rect.left;
    y = evt.clientY - rect.top;
  }
  return {x:x, y:y};
}

var ijMouseDownPos = null;
var ijMouseDownTime = 0;
function ijMouseDown(evt){
  var p = ijCanvasPos(evt); if(!p) return;
  ijMouseDownPos = p;
  ijMouseDownTime = Date.now();
  var hit = ijHitTest(p.x, p.y);
  if(hit){
    ijDraggingNode = hit;
  } else {
    ijPanning = true;
    ijPanStart = {x:p.x, y:p.y};
    ijOffsetStart = {x:ijOffsetX, y:ijOffsetY};
  }
  if(evt.preventDefault) evt.preventDefault();
}
function ijMouseMove(evt){
  var p = ijCanvasPos(evt); if(!p) return;
  if(ijDraggingNode){
    // convert screen movement to world coords
    var w = ijScreenToWorld(p.x, p.y);
    var idx = IJ_IDX[ijDraggingNode];
    if(idx!==undefined){
      IJ_NODES[idx].x = w.x;
      IJ_NODES[idx].y = w.y;
      IJ_NODES[idx].vx = 0; IJ_NODES[idx].vy = 0;
      ijSimSteps = Math.min(ijSimSteps, 580);   // kick simulation back on
    }
  } else if(ijPanning){
    ijOffsetX = ijOffsetStart.x + (p.x - ijPanStart.x);
    ijOffsetY = ijOffsetStart.y + (p.y - ijPanStart.y);
  } else {
    // hover detection (cheap)
    var hit = ijHitTest(p.x, p.y);
    ijHover = hit;
    if(ijCanvas) ijCanvas.style.cursor = hit ? 'pointer' : (ijPanning?'grabbing':'grab');
  }
  if(evt.preventDefault) evt.preventDefault();
}
function ijMouseUp(evt){
  var wasShortTap = ijMouseDownPos &&
    Date.now() - ijMouseDownTime < 280 &&
    Math.abs((ijCanvasPos(evt)||{x:ijMouseDownPos.x}).x - ijMouseDownPos.x) < 8;
  if(wasShortTap){
    var p = ijCanvasPos(evt) || ijMouseDownPos;
    var hit = ijHitTest(p.x, p.y);
    if(hit){
      ijActive = hit;
      ijUpdateReadout();
    } else {
      // tap on empty area deselects
      if(ijActive){ ijActive = null; ijUpdateReadout(); }
    }
  }
  ijDraggingNode = null;
  ijPanning = false;
  ijMouseDownPos = null;
  if(ijCanvas) ijCanvas.style.cursor = 'grab';
}

function ijWheel(evt){
  if(!ijCanvas) return;
  evt.preventDefault();
  var p = ijCanvasPos(evt); if(!p) return;
  // world point under cursor before zoom
  var wBefore = ijScreenToWorld(p.x, p.y);
  // zoom step
  var dy = evt.deltaY || 0;
  var factor = dy > 0 ? 0.90 : 1.10;
  var newScale = ijTargetScale * factor;
  newScale = Math.max(0.30, Math.min(3.0, newScale));
  // adjust offset so world point under cursor stays put
  // We need ijTargetScale to reach newScale; but offset uses ijScale (animated).
  // Simpler approach: directly snap scale and re-anchor offset around the cursor.
  ijTargetScale = newScale;
  ijScale = newScale;
  var wAfter = ijScreenToWorld(p.x, p.y);
  ijOffsetX += (wAfter.x - wBefore.x) * ijScale;
  ijOffsetY += (wAfter.y - wBefore.y) * ijScale;
}

// pinch zoom for touch
var ijPinchStartDist = 0;
var ijPinchStartScale = 1;
function ijTouchStart(evt){
  if(evt.touches.length === 2){
    var dx = evt.touches[0].clientX - evt.touches[1].clientX;
    var dy = evt.touches[0].clientY - evt.touches[1].clientY;
    ijPinchStartDist = Math.sqrt(dx*dx + dy*dy);
    ijPinchStartScale = ijTargetScale;
    ijDraggingNode = null; ijPanning = false;
  } else {
    ijMouseDown(evt);
  }
}
function ijTouchMove(evt){
  if(evt.touches.length === 2){
    var dx = evt.touches[0].clientX - evt.touches[1].clientX;
    var dy = evt.touches[0].clientY - evt.touches[1].clientY;
    var d = Math.sqrt(dx*dx + dy*dy);
    if(ijPinchStartDist > 0){
      var ratio = d / ijPinchStartDist;
      var ns = Math.max(0.30, Math.min(3.0, ijPinchStartScale * ratio));
      ijTargetScale = ns;
      ijScale = ns;
    }
    if(evt.preventDefault) evt.preventDefault();
  } else {
    ijMouseMove(evt);
  }
}
function ijTouchEnd(evt){
  if(evt.touches.length < 2){
    ijPinchStartDist = 0;
  }
  ijMouseUp(evt);
}

// ─── READOUT panel (slides in on tap) ──────────────────────────────────
function ijUpdateReadout(){
  var box = $ij('ij-readout');
  if(!box) return;
  if(!ijActive){
    box.classList.remove('on');
    box.innerHTML = '';
    return;
  }
  var idx = IJ_IDX[ijActive];
  if(idx===undefined){ box.classList.remove('on'); return; }
  var n = IJ_NODES[idx];
  var cat = IJ_CATS[n.cat] || IJ_CATS.concept;
  var layer = IJ_LAYERS[n.layer-1] || {lbl:''};

  // list of connections grouped by relation type
  var byRel = {};
  var adj = IJ_ADJ[n.id] || [];
  for(var j=0; j<adj.length; j++){
    var a = adj[j];
    if(!byRel[a.type]) byRel[a.type] = [];
    var target = IJ_NODES[IJ_IDX[a.to]];
    if(target) byRel[a.type].push(target);
  }
  var connHtml = '';
  // Order of relation types in display
  var relOrder = ['UNION_WITH','AVATAR_OF','MANIFESTS_AS','EMANATES_FROM','EVOLVES_INTO','IS_PART_OF','HIGHER_OCTAVE','LOWER_OCTAVE','GOVERNS','SYMBOLIZES','BALANCES','OPPOSITE_OF','CONNECTS_TO','PARALLEL_TO','ASSOCIATED'];
  for(var r=0; r<relOrder.length; r++){
    var rk = relOrder[r];
    if(!byRel[rk] || !byRel[rk].length) continue;
    var rel = IJ_RELS[rk] || IJ_RELS.ASSOCIATED;
    var items = byRel[rk].map(function(t){
      return '<button class="ij-conn-pill" onclick="ijSelectNode(\''+t.id+'\')">'+t.tr+'</button>';
    }).join(' ');
    connHtml += '<div class="ij-rel-grp"><div class="ij-rel-lbl">'+rel.lbl+'</div><div class="ij-rel-pills">'+items+'</div></div>';
  }
  if(!connHtml) connHtml = '<div class="ij-rel-grp"><div class="ij-rel-lbl" style="color:rgba(255,225,180,0.45);">no connections in current graph</div></div>';

  box.innerHTML =
    '<div class="ij-r-hdr" style="border-left:3px solid '+cat.col+';">'+
      '<div class="ij-r-row1">'+
        '<span class="ij-r-glyph" style="background:'+cat.col+'33;color:'+cat.col+';">'+(n.glyph||cat.glyph)+'</span>'+
        '<div class="ij-r-titles">'+
          '<div class="ij-r-sa">'+n.sa+'</div>'+
          '<div class="ij-r-tr">'+n.tr+' · <span class="ij-r-en">'+n.en+'</span></div>'+
        '</div>'+
        '<button class="ij-r-x" onclick="ijCloseNode()" title="Close">✕</button>'+
      '</div>'+
    '</div>'+
    '<div class="ij-r-meta">'+
      '<span class="ij-r-mtag" style="color:'+cat.col+';">'+cat.lbl+'</span>'+
      '<span class="ij-r-mtag">Layer '+n.layer+' · '+layer.lbl+'</span>'+
    '</div>'+
    '<div class="ij-r-desc">'+n.desc+'</div>'+
    '<div class="ij-r-conns">'+connHtml+'</div>';
  box.classList.add('on');
}

// expose for in-html onclicks
window.ijSelectNode = function(id){
  if(IJ_IDX[id]===undefined) return;
  ijActive = id;
  ijUpdateReadout();
  // gently pan to it
  var n = IJ_NODES[IJ_IDX[id]];
  // animate offset to centre this node on screen
  var startX = ijOffsetX, startY = ijOffsetY;
  var targetX = -n.x*ijScale, targetY = -n.y*ijScale;
  var t0 = performance.now();
  function step(){
    var t = Math.min(1, (performance.now()-t0)/480);
    var ease = 1 - Math.pow(1-t, 3);
    ijOffsetX = startX + (targetX-startX)*ease;
    ijOffsetY = startY + (targetY-startY)*ease;
    if(t < 1) requestAnimationFrame(step);
  }
  step();
};

window.ijCloseNode = function(){
  ijActive = null;
  ijUpdateReadout();
};

// ─── FILTER UI ─────────────────────────────────────────────────────────
window.ijToggleCat = function(cat){
  ijCatFilter[cat] = ijCatFilter[cat] === false ? true : false;
  var btn = document.querySelector('.ij-cat-btn[data-cat="'+cat+'"]');
  if(btn) btn.classList.toggle('off', ijCatFilter[cat]===false);
};
window.ijToggleLayer = function(L){
  ijLayerFilter[L] = ijLayerFilter[L] === false ? true : false;
  var btn = document.querySelector('.ij-layer-btn[data-layer="'+L+'"]');
  if(btn) btn.classList.toggle('off', ijLayerFilter[L]===false);
};
window.ijResetFilters = function(){
  ijCatFilter = {};
  ijLayerFilter = {};
  var btns = document.querySelectorAll('.ij-cat-btn, .ij-layer-btn');
  for(var i=0; i<btns.length; i++) btns[i].classList.remove('off');
};

// ─── SEARCH ────────────────────────────────────────────────────────────
window.ijSearch = function(q){
  ijSearchTerm = (q||'').trim();
  // populate suggestion list
  var list = $ij('ij-search-list');
  if(!list) return;
  if(!ijSearchTerm){ list.innerHTML=''; list.style.display='none'; return; }
  var matches = [];
  var qq = ijSearchTerm.toLowerCase();
  for(var i=0; i<IJ_NODES.length; i++){
    var n = IJ_NODES[i];
    if(n.tr.toLowerCase().indexOf(qq)>=0 ||
       n.en.toLowerCase().indexOf(qq)>=0 ||
       n.id.indexOf(qq)>=0 ||
       n.sa.indexOf(ijSearchTerm)>=0){
      matches.push(n);
      if(matches.length>=10) break;
    }
  }
  if(!matches.length){
    list.innerHTML = '<div class="ij-no-match">no concept matches</div>';
    list.style.display = 'block';
    return;
  }
  list.innerHTML = matches.map(function(m){
    var c = IJ_CATS[m.cat] || IJ_CATS.concept;
    return '<button class="ij-search-item" onclick="ijSelectFromSearch(\''+m.id+'\')">'+
      '<span class="ij-si-dot" style="background:'+c.col+';"></span>'+
      '<span class="ij-si-name">'+m.tr+' <em>'+m.en+'</em></span>'+
    '</button>';
  }).join('');
  list.style.display = 'block';
};
window.ijSelectFromSearch = function(id){
  var inp = $ij('ij-search-input');
  if(inp) inp.value = '';
  ijSearchTerm = '';
  var list = $ij('ij-search-list');
  if(list){ list.innerHTML=''; list.style.display='none'; }
  ijSelectNode(id);
};

// ═══════════════════════════════════════════════════════════════════════
// INIT / OPEN / CLOSE
// ═══════════════════════════════════════════════════════════════════════
function ijInit(){
  ijCanvas = $ij('ij-canvas');
  if(!ijCanvas) return;
  ijCtx = ijCanvas.getContext('2d');
  ijT0 = performance.now();
  ijResize();
  ijInitStars();
  ijBuildIndex();
  ijLayoutNodes();
  ijSimSteps = 0;
  ijSimEnergy = 999;

  if(!ijInitialized){
    ijCanvas.addEventListener('mousedown', ijMouseDown);
    window.addEventListener('mousemove', ijMouseMoveWindow);
    window.addEventListener('mouseup', ijMouseUp);
    ijCanvas.addEventListener('wheel', ijWheel, {passive:false});
    ijCanvas.addEventListener('touchstart', ijTouchStart, {passive:false});
    ijCanvas.addEventListener('touchmove', ijTouchMove, {passive:false});
    ijCanvas.addEventListener('touchend', ijTouchEnd, {passive:false});
    window.addEventListener('resize', ijResizeGuarded);
    ijInitialized = true;
  }

  if(ijRAF) cancelAnimationFrame(ijRAF);
  ijDraw();
}

// window-level move so panning doesn't stutter when cursor briefly exits canvas
function ijMouseMoveWindow(evt){
  if(!ijPanning && !ijDraggingNode) return;
  // synthesize relative pos from canvas
  if(!ijCanvas) return;
  var rect = ijCanvas.getBoundingClientRect();
  ijMouseMove({
    clientX: evt.clientX, clientY: evt.clientY,
    preventDefault: function(){},
    touches: null
  });
}

window.openIndrajala = function(){
  var ov = $ij('indrajala-exp');
  if(!ov) return;
  ov.classList.add('on');
  // reset state
  ijActive = null; ijHover = null;
  ijOffsetX = 0; ijOffsetY = 0;
  ijScale = 1.0; ijTargetScale = 1.0;
  ijSearchTerm = '';
  ijCatFilter = {}; ijLayerFilter = {};
  setTimeout(function(){
    var inp = $ij('ij-search-input'); if(inp) inp.value='';
    var list = $ij('ij-search-list'); if(list){ list.innerHTML=''; list.style.display='none'; }
    var r = $ij('ij-readout'); if(r){ r.classList.remove('on'); r.innerHTML=''; }
    var fbtns = document.querySelectorAll('.ij-cat-btn, .ij-layer-btn');
    for(var b=0; b<fbtns.length; b++) fbtns[b].classList.remove('off');
  }, 50);
  setTimeout(ijInit, 320);
};

window.closeIndrajala = function(){
  var ov = $ij('indrajala-exp');
  if(!ov) return;
  ov.classList.remove('on');
  if(ijRAF){ cancelAnimationFrame(ijRAF); ijRAF=null; }
  ijActive = null; ijHover = null;
  ijUpdateReadout();
};

// resume loop when tab becomes visible
document.addEventListener('visibilitychange', function(){
  if(document.hidden) return;
  var ov = $ij('indrajala-exp');
  if(!ov || !ov.classList.contains('on')) return;
  if(!ijRAF) ijDraw();
});

// ESC closes node, then overlay
document.addEventListener('keydown', function(e){
  if(e.key !== 'Escape') return;
  var ov = $ij('indrajala-exp');
  if(!ov || !ov.classList.contains('on')) return;
  if(ijActive){ window.ijCloseNode(); return; }
  window.closeIndrajala();
});

