var HG_TOTAL_STAGES=HG_STAGES.length;

// ── Helpers ───────────────────────────────────────────
function $hg(id){return document.getElementById(id);}

function hgResetAll(){
  hgStage=0;
  hgStageT=0;
  hgDidAdvance=false;
  hgSilenceDust=[];
  hgReflectors=[];
  hgIgnitionRays=[];
  hgWombParticles=[];
  hgInfoBits=[];
  hgHumRings=[];
  hgWebNodes=[];
  hgWebEdges=[];
  hgMandalaReady=false;
  // UI
  var rec=$hg('hg-recognition'); if(rec)rec.classList.remove('visible');
  var adv=$hg('hg-advance'); if(adv){adv.classList.remove('visible');adv.textContent='Begin';/* first click starts Act I */}
  var rw=$hg('hg-rewind'); if(rw)rw.classList.remove('visible');
  var hum=$hg('hg-hum-label'); if(hum)hum.classList.remove('visible');
  var tat=$hg('hg-tattva-names'); if(tat){tat.classList.remove('visible');tat.innerHTML='';}
  var hint=$hg('hg-hint'); if(hint)hint.style.opacity='';
  hgRenderStageDots();
  hgSetStageLabel();
  hgRenderNarrative();
  // Show advance button after entrance delay so user can start
  setTimeout(function(){
    var a=$hg('hg-advance');
    if(a&&$hg('hg-exp').classList.contains('on')){
      a.classList.add('visible');
    }
  },2600);
}

function hgRenderStageDots(){
  var dots=document.querySelectorAll('#hg-stages .hg-stage-dot');
  dots.forEach(function(d,i){
    d.classList.remove('current','done');
    if(i<hgStage)d.classList.add('done');
    else if(i===hgStage)d.classList.add('current');
  });
}

function hgSetStageLabel(){
  var el=$hg('hg-stage-label');
  if(!el)return;
  if(hgStage>=HG_TOTAL_STAGES){el.textContent='Recognition';el.style.color='rgba(255,220,140,.65)';return;}
  el.textContent=HG_STAGES[hgStage].label;
  // Color shifts as we progress (cool amber → warm gold)
  var hueMix=hgStage/HG_TOTAL_STAGES;
  el.style.color='rgba('+(201+Math.round(hueMix*40))+','+(168+Math.round(hueMix*40))+','+(76+Math.round(hueMix*40))+',.5)';
}

function hgRenderNarrative(){
  var wrap=$hg('hg-narrative');
  if(!wrap)return;
  wrap.innerHTML='';
  if(hgStage>=HG_TOTAL_STAGES)return;
  var lines=HG_STAGES[hgStage].narr();
  lines.forEach(function(l,i){
    var div=document.createElement('div');
    div.className='hg-narr-line '+l.cls;
    div.innerHTML=l.text;
    wrap.appendChild(div);
    setTimeout(function(){
      // Only reveal if still on this stage (user may have advanced fast)
      if(div.parentElement===wrap) div.classList.add('visible');
    },l.delay);
  });
}

// ── Advance to next act ───────────────────────────────
window.hgAdvance=function(){
  if(hgStage===0 && !hgDidAdvance){
    // First press — just start the journey
    hgDidAdvance=true;
    var hint=$hg('hg-hint');if(hint)hint.style.opacity='0';
    var adv=$hg('hg-advance');if(adv)adv.textContent='Continue';
    var rw=$hg('hg-rewind');if(rw)rw.classList.add('visible');
    // Restart narrative so the timed fades fire cleanly from t=0
    hgRenderNarrative();
    hgStageT=0;
    return;
  }
  if(hgStage<HG_TOTAL_STAGES-1){
    hgStage++;
    hgStageT=0;
    hgOnStageEnter();
  } else if(hgStage===HG_TOTAL_STAGES-1){
    // Jump to recognition
    hgStage=HG_TOTAL_STAGES;
    hgStageT=0;
    hgShowRecognition();
  }
};

window.hgRewind=function(){
  hgResetAll();
};

function hgShowRecognition(){
  hgRenderStageDots();
  var el=$hg('hg-stage-label');if(el){el.textContent='Recognition';el.style.color='rgba(255,220,140,.7)';}
  $hg('hg-narrative').innerHTML='';
  $hg('hg-advance').classList.remove('visible');
  $hg('hg-hum-label').classList.remove('visible');
  setTimeout(function(){
    $hg('hg-recognition').classList.add('visible');
  },700);
}

function hgOnStageEnter(){
  hgRenderStageDots();
  hgSetStageLabel();
  hgRenderNarrative();

  // Act-specific setup
  if(hgStage===1){
    // Reflection — spawn a handful of rotating "reflector" arcs
    hgReflectors=[];
    for(var r=0;r<3;r++){
      hgReflectors.push({
        radius:40+r*28,
        angle:Math.random()*Math.PI*2,
        speed:0.003+r*0.0008,
        alpha:0
      });
    }
  }
  else if(hgStage===2){
    // Ignition — rays bursting outward
    hgIgnitionRays=[];
    var N=36;
    for(var i=0;i<N;i++){
      hgIgnitionRays.push({
        angle:(i/N)*Math.PI*2,
        length:0,
        maxLen:80+Math.random()*60,
        alpha:0,
        speed:1.5+Math.random()*1.5
      });
    }
  }
  else if(hgStage===3){
    // Womb breathing — spawn orbiting ember particles
    hgWombParticles=[];
    for(var j=0;j<90;j++){
      hgWombParticles.push({
        orbitR:60+Math.random()*80,
        angle:Math.random()*Math.PI*2,
        speed:(Math.random()-0.5)*0.01,
        r:Math.random()*1.4+0.3,
        alpha:0,
        targetAlpha:Math.random()*0.5+0.15,
        phase:Math.random()*Math.PI*2
      });
    }
  }
  else if(hgStage===4){
    // Information bits — digital particles that flicker
    hgInfoBits=[];
    for(var k=0;k<140;k++){
      hgInfoBits.push({
        x:Math.random()*hgW,
        y:Math.random()*hgH,
        tx:0,ty:0,
        vx:0,vy:0,
        r:Math.random()*1.1+0.4,
        alpha:0,
        targetAlpha:Math.random()*0.6+0.2,
        flickerPhase:Math.random()*Math.PI*2,
        flickerSpeed:0.04+Math.random()*0.08,
        bit:Math.random()<0.5?0:1
      });
    }
    // Assign target positions arranged in rough grid pattern
    hgAssignBitTargets();
  }
  else if(hgStage===5){
    // Hum rings
    hgHumRings=[];
    var hum=$hg('hg-hum-label');if(hum)hum.classList.add('visible');
  }
  else if(hgStage===6){
    // Cosmic web — sample nodes & build edges
    hgBuildCosmicWeb();
    var hum=$hg('hg-hum-label');if(hum)hum.classList.remove('visible');
  }
  else if(hgStage===7){
    // Mandala + tattva labels will render procedurally
    hgMandalaReady=true;
    hgWombParticles=[]; // clear any stale orbiters from Act 3
    hgRenderTattvaLabels();
  }
}

function hgAssignBitTargets(){
  // Arrange bits on a circular ring of "information shell" around center
  var cx=hgW/2, cy=hgH/2;
  hgInfoBits.forEach(function(b,i){
    var ang=(i/hgInfoBits.length)*Math.PI*2 + Math.random()*0.4;
    var rad=Math.min(hgW,hgH)*0.28 + (Math.random()-0.5)*80;
    b.tx=cx+Math.cos(ang)*rad;
    b.ty=cy+Math.sin(ang)*rad;
  });
}

function hgBuildCosmicWeb(){
  hgWebNodes=[];
  hgWebEdges=[];
  var cx=hgW/2, cy=hgH/2;
  // Central bright node
  hgWebNodes.push({x:cx,y:cy,r:5,alpha:0,target:0.95,pulsePhase:0});
  // Surrounding nodes on 2 rings
  var rings=[{r:Math.min(hgW,hgH)*0.2,n:8},{r:Math.min(hgW,hgH)*0.34,n:12}];
  rings.forEach(function(ring){
    for(var i=0;i<ring.n;i++){
      var a=(i/ring.n)*Math.PI*2 + (Math.random()-0.5)*0.2;
      var rr=ring.r + (Math.random()-0.5)*30;
      hgWebNodes.push({
        x:cx+Math.cos(a)*rr,
        y:cy+Math.sin(a)*rr,
        r:1.8+Math.random()*1.8,
        alpha:0,
        target:0.4+Math.random()*0.35,
        pulsePhase:Math.random()*Math.PI*2
      });
    }
  });
  // Outer scattered nodes
  for(var s=0;s<14;s++){
    var aa=Math.random()*Math.PI*2;
    var rrr=Math.min(hgW,hgH)*(0.42+Math.random()*0.1);
    hgWebNodes.push({
      x:cx+Math.cos(aa)*rrr,
      y:cy+Math.sin(aa)*rrr,
      r:1+Math.random()*1.2,
      alpha:0,
      target:0.25+Math.random()*0.25,
      pulsePhase:Math.random()*Math.PI*2
    });
  }
  // Build edges: each node connects to 2-3 nearest neighbors
  for(var p=0;p<hgWebNodes.length;p++){
    var neighbors=[];
    for(var q=0;q<hgWebNodes.length;q++){
      if(p===q)continue;
      var dx=hgWebNodes[p].x-hgWebNodes[q].x;
      var dy=hgWebNodes[p].y-hgWebNodes[q].y;
      var d=Math.sqrt(dx*dx+dy*dy);
      neighbors.push({idx:q,d:d});
    }
    neighbors.sort(function(a,b){return a.d-b.d;});
    var edgeCount=2+Math.floor(Math.random()*2);
    for(var e=0;e<Math.min(edgeCount,neighbors.length);e++){
      // Avoid duplicate edges
      var a2=p, b2=neighbors[e].idx;
      var key=Math.min(a2,b2)+'-'+Math.max(a2,b2);
      if(!hgWebEdges.some(function(x){return x.key===key;})){
        hgWebEdges.push({a:a2,b:b2,key:key,alpha:0,target:0.12+Math.random()*0.12,delay:Math.random()*40});
      }
    }
  }
}

var HG_TATTVAS=[
  {skt:'महत्',en:'Mahat',sub:'Cosmic Intelligence',r:0.00},
  {skt:'अहंकार',en:'Ahaṃkāra',sub:'I-Maker',r:0.42},
  {skt:'बुद्धि',en:'Buddhi',sub:'Discriminative Intellect',r:0.58},
  {skt:'मनस्',en:'Manas',sub:'Thinking Mind',r:0.74},
  {skt:'तन्मात्र',en:'Tanmātra',sub:'Subtle Elements',r:0.90}
];

function hgRenderTattvaLabels(){
  var wrap=$hg('hg-tattva-names');
  if(!wrap)return;
  wrap.innerHTML='';
  var cx=hgW/2, cy=hgH/2;
  var baseR=Math.min(hgW,hgH)*0.33;
  HG_TATTVAS.forEach(function(t,i){
    if(i===0){
      // Center label
      var el=document.createElement('div');
      el.className='hg-tattva-label';
      el.style.left=cx+'px';
      el.style.top=cy+'px';
      el.innerHTML=t.skt;
      wrap.appendChild(el);
      var e2=document.createElement('div');
      e2.className='hg-tattva-label-en';
      e2.style.left=cx+'px';
      e2.style.top=(cy+20)+'px';
      e2.textContent=t.en+' · '+t.sub;
      wrap.appendChild(e2);
      return;
    }
    // Ring labels — place at an angle around the ring
    var angle=-Math.PI/2 + (i-1)*0.35; // fan upper-right-ish
    var rr=baseR*t.r;
    var lx=cx+Math.cos(angle)*rr;
    var ly=cy+Math.sin(angle)*rr;
    var el=document.createElement('div');
    el.className='hg-tattva-label';
    el.style.left=lx+'px';
    el.style.top=ly+'px';
    el.textContent=t.skt;
    wrap.appendChild(el);
    var e3=document.createElement('div');
    e3.className='hg-tattva-label-en';
    e3.style.left=lx+'px';
    e3.style.top=(ly+14)+'px';
    e3.textContent=t.en;
    wrap.appendChild(e3);
  });
  setTimeout(function(){wrap.classList.add('visible');},400);
}

// ── Open / Close ──────────────────────────────────────
window.openHiranyagarbhaExp=function(){
  var ov=$hg('hg-exp');
  if(!ov)return;
  ov.classList.add('on');
  // Reset tabs
  document.querySelectorAll('#hg-exp .era-exp-tab').forEach(function(t,i){t.classList.toggle('active',i===0);});
  var cnt=$hg('hg-content'); if(cnt)cnt.classList.remove('open');
  hgResetAll();
  setTimeout(initHiranyagarbhaCanvas,300);
};

window.closeHiranyagarbhaExp=function(){
  var ov=$hg('hg-exp');
  if(!ov)return;
  ov.classList.remove('on');
  if(hgFrame){cancelAnimationFrame(hgFrame);hgFrame=null;}
};

// ── Tabs ──────────────────────────────────────────────
window.hgTab=function(tab){
  document.querySelectorAll('#hg-exp .era-exp-tab').forEach(function(t){t.classList.remove('active');});
  if(typeof event!=='undefined'&&event&&event.target&&event.target.classList)event.target.classList.add('active');
  if(tab==='experience'){$hg('hg-content').classList.remove('open');return;}
  var ct=$hg('hg-ct'), cb=$hg('hg-cb');

  if(tab==='upanishad'){
    ct.textContent='The Aitareya Upaniṣad';ct.style.color='rgba(255,220,140,.7)';
    cb.innerHTML=
      makeInsight('Before the gods, before the worlds, before even the question of "before" — there was this: a single, self-aware point of golden light.','Aitareya Upaniṣad · interpreted')+
      makeSection('ॐ','Hiraṇyagarbha Sūkta','Ṛgveda 10.121','Ten verses that changed philosophy forever.',
        'The Hiraṇyagarbha Sūkta is one of the oldest cosmological texts ever composed — a hymn of ten verses, each asking the same devastating question: <em>"Kasmai devāya haviṣā vidhema?"</em> — "To which god shall we offer our oblation?" The genius of the hymn is that the answer is not given. The hymn points at something that existed <strong>before any god</strong> — before any name or form to which one could offer. Hiraṇyagarbha was the first principle: golden (hiraṇya — luminous, precious) womb (garbha — the enclosing vessel of possibility). The Ṛṣis understood that creation required a seed — not material, but informational — containing everything that would unfold. <em>The universe did not explode outward from nothing. It unfolded from a structured potential.</em>',
        ['Brahman','Prakriti','Chit','Tattva'])+
      makeSection('✧','Prajñānam Brahma','Consciousness Is Brahman','The Aitareya Upaniṣad\'s supreme declaration.',
        'The Aitareya Upaniṣad belongs to the Ṛgveda. Its central Mahāvākya — <em>Prajñānam Brahma</em> ("Consciousness is Brahman") — is perhaps the single most radical statement in world philosophy. The text does not say consciousness is <em>a property of</em> Brahman, or <em>contained in</em> Brahman. It says consciousness <strong>is</strong> Brahman. Identity. No gap. <em>What you call your awareness — the simple fact that anything is being experienced at all — that is the absolute itself.</em> The Upaniṣad was teaching, 3,000 years before neuroscience, what Chalmers would name the "hard problem": consciousness cannot be explained by anything else, because it is the ground in which all explanations arise.',
        ['Brahman','Chit','Pratyabhijñā','Atman'])+
      makeSection('◎','The Three Births of the Self','Aitareya 2.1-2.4','The Upaniṣad\'s map of incarnation.',
        'The second chapter of the Aitareya describes three births of the Self: the first when a father places the seed in the mother; the second when the child is born into the world; the third when the embodied being recognizes itself as Ātman, as Brahman — the spiritual birth. <strong>Hiraṇyagarbha parallels this at the cosmic scale:</strong> the first stirring within Brahman, the emergence into manifest cosmos, and finally — in the enlightened one — the recognition that these three were always one. The cosmological and the personal are not two scales. They are the same event, viewed from different distances.',
        ['Atman','Brahman','Jiva','Moksha'])+
      makeSection('⊛','Hiraṇyagarbha and the Other Upaniṣads','A Living Thread','The same principle, described by many names.',
        'The Śvetāśvatara Upaniṣad (3.4) calls Hiraṇyagarbha the One who <em>"encompasses all births and is the origin of all."</em> The Muṇḍaka Upaniṣad (2.1.2) describes it as <em>"the divine person, without form, both within and without, unborn, without breath, without mind, pure, higher than the highest imperishable."</em> The Bṛhadāraṇyaka identifies it with Prajāpati, "Lord of Creatures" — not a distant creator god, but the self-aware intelligence inherent in the act of creation. <em>Hiraṇyagarbha is not one doctrine in one text. It is the name the tradition gives to the structural necessity of a self-aware first principle.</em>',
        ['Brahman','Prana','Spanda (doctrine)','Mahat']);
  }
  else if(tab==='samkhya'){
    ct.textContent='Mahat — The Sāṃkhya Cosmos';ct.style.color='rgba(220,190,130,.75)';
    cb.innerHTML=
      makeInsight('Sāṃkhya gave the tradition its most precise map: 25 tattvas descending from Puruṣa and Prakṛti through Mahat — the cosmic intelligence — all the way to a grain of sand.','Sāṃkhya Kārikā synthesis')+
      makeSection('◈','What Mahat Is','The First Evolute','Before individual mind, universal mind.',
        'In Sāṃkhya\'s cosmology, when Puruṣa (pure consciousness) witnesses Prakṛti (primordial matter), Prakṛti\'s equilibrium of the three guṇas (Sattva, Rajas, Tamas) is disturbed. The first thing that emerges from this disturbance is <strong>Mahat</strong> — literally "the Great" — also called Buddhi at the cosmic scale. Mahat is the universal field of discriminating intelligence. <em>Before there is any individual mind, there is a cosmic mind that contains the potential for all individual minds.</em> This is not poetic. It is a precise technical claim: intelligence is not produced by brains — brains are local precipitations of a pre-existing intelligence field.',
        ['Mahat','Prakriti','Buddhi','Sattva'])+
      makeSection('◉','The Descent Through the Tattvas','How Intelligence Becomes World','One becomes five becomes fifty.',
        'From Mahat comes <strong>Ahaṃkāra</strong> (the I-maker) — the principle that creates the felt sense of being a separate experiencer. From Ahaṃkāra in its Sattvic aspect come the five organs of knowledge (eyes, ears, nose, tongue, skin) and the five organs of action (speech, hands, feet, generative, excretory) and Manas (mind). From Ahaṃkāra in its Tāmasic aspect come the five Tanmātras (subtle elements — sound, touch, form, taste, smell) and from those the five Mahābhūtas (gross elements — space, air, fire, water, earth). <em>The entire apparatus of embodied experience unfolds from Mahat.</em> You are not a body that happens to contain mind. You are mind that took this particular form.',
        ['Tattva','Ahamkara','Manas','Tanmātra','Pañcabhūta'])+
      makeSection('◊','Mahat and Hiraṇyagarbha','Two Names, One Reality','The Vedic poetic name and the Sāṃkhyan analytical name.',
        'The Vedic tradition named the first cosmic intelligence <em>Hiraṇyagarbha</em> — the Golden Womb. The analytical Sāṃkhya school named the same principle <em>Mahat</em> — the Great. The Upaniṣads also call it <em>Īśvara</em> — the Lord — in its functional aspect as the intelligent organizer of the cosmos. <strong>These are not three separate gods. They are three names for the same structural reality:</strong> a field of self-aware intelligence that mediates between the unmanifest absolute (Brahman) and the fully manifest universe (Virāt). Hiraṇyagarbha is how it appears poetically. Mahat is how it appears analytically. Īśvara is how it appears functionally. <em>Same reality, three lenses.</em>',
        ['Brahman','Mahat','Atman','Jiva'])+
      makeSection('⚬','Modern Analog — The Field Hypothesis','What Sheldrake and Jung Glimpsed','A field of intelligence more fundamental than minds.',
        'Carl Jung\'s "collective unconscious" — a shared substrate of psychic material from which individual consciousness draws — is a partial rediscovery of Mahat. Rupert Sheldrake\'s "morphic fields" — non-physical patterns that organize biological and psychological development — is another. More recently, integrated information theory (Tononi) and panpsychist approaches (Goff, Strawson) are beginning to entertain seriously what Sāṃkhya asserted: <strong>consciousness is not emergent. It is fundamental.</strong> The interesting question is not "how does matter produce mind?" but "how does mind localize itself into a particular body?" Sāṃkhya had the answer 2,500 years ago: through Mahat, Ahaṃkāra, and the tattvic descent.',
        ['Mahat','Buddhi','Prakriti','Chit']);
  }
  else if(tab==='cosmology'){
    ct.textContent='Modern Cosmology';ct.style.color='rgba(160,200,230,.75)';
    cb.innerHTML=
      makeInsight('The universe is not expanding into pre-existing space. Space is being created as it expands. This is precisely what Hiraṇyagarbha means — a womb that contains the container it is unfolding into.','Cosmological parallel')+
      makeSection('∞','The Planck Epoch','10⁻⁴³ Seconds','Before space and time had separated.',
        'In the first ~10⁻⁴³ seconds after the Big Bang — the Planck epoch — all four fundamental forces (gravity, electromagnetism, strong nuclear, weak nuclear) were unified in a single force. Space and time were not yet distinguishable. The universe was a state of pure potential, infinitely dense and infinitely hot, containing every law and every particle that would unfold over the next 13.8 billion years. <strong>This is a remarkably exact description of Hiraṇyagarbha.</strong> The Ṛgveda did not have telescopes. It had something else: Ṛṣis whose introspective instruments were sensitive enough to sense the structural requirements of a self-aware cosmos. They reported what they sensed. Cosmology now confirms it.',
        ['Brahman','Mahat','Prakriti'])+
      makeSection('◎','It from Bit — Wheeler\'s Insight','Information as the Ground of Reality','What the universe is, at bottom.',
        'John Archibald Wheeler — one of the greatest physicists of the 20th century, who worked with both Einstein and Bohr — coined the phrase <em>"It from Bit."</em> His claim: <strong>every physical entity, every particle and field, derives its existence from observer-participancy, from asked-and-answered yes-or-no questions.</strong> The universe at bottom is not made of matter. It is made of information. Matter is what information feels like from the inside. This is the Hiraṇyagarbha claim translated into physics: before matter, information; before particles, distinctions; before reality, intelligence organizing itself into the possibility of being observed. <em>Wheeler spent the last decades of his life on this hypothesis.</em> He was not mystical. He was following the equations wherever they led.',
        ['Mahat','Chit','Brahman','Pratyabhijñā'])+
      makeSection('✦','The Cosmic Web','Largest Known Structure','Galaxy filaments that look like neurons.',
        'In 2014, astronomers released the largest map ever made of the universe\'s structure. What it revealed astonished even the astronomers: <strong>the universe is not randomly distributed. Galaxies cluster along vast filaments of dark matter, with empty voids between them.</strong> Zoom in on a scan of neural tissue — axons connecting neural clusters with empty space between — and the patterns are structurally identical. Same geometry at the scale of 10⁻⁶ meters (neurons) and 10²² meters (cosmic filaments). <em>Twenty-eight orders of magnitude apart, the same pattern.</em> The tradition said it 3,000 years ago: <em>Yathā piṇḍe tathā brahmāṇḍe</em> — As within, so without. The universe is a neural network that grew a species of neural networks inside itself, and through them, recognized the pattern it was.',
        ['Mahat','Tattva','Spanda (doctrine)'])+
      makeSection('∿','Acoustic Oscillations','The Universe Sang Itself into Structure','Modern cosmology\'s "baryonic acoustic oscillations."',
        'About 380,000 years after the Big Bang, the universe became transparent to light — the cosmic microwave background was released. Before this moment, the universe was a dense plasma in which <strong>pressure waves</strong> propagated at half the speed of light. These waves — baryonic acoustic oscillations — imprinted a characteristic pattern on matter: today, galaxies cluster at a preferred distance of about 500 million light-years, the "fossilized" wavelength of that primordial sound. <em>Literally: the universe sang, and the pattern of its song is now the cosmic structure we see.</em> The Ṛgveda called this <em>Nāda</em> — primordial sound — and Nāda Brahma — the cosmos is sound. Not metaphor. Measurable imprint.',
        ['Spanda (doctrine)','Sphoṭa','Mahat'])+
      makeSection('◐','The Observer Universe','Why Anything Is Experienced','The claim physics is being forced toward.',
        'Werner Heisenberg: <em>"What we observe is not nature itself, but nature exposed to our method of questioning."</em> John Wheeler: <em>"No elementary phenomenon is a phenomenon until it is an observed phenomenon."</em> Schrödinger: <em>"The total number of minds in the universe is one."</em> These are not fringe views. These are the dominant interpretations among those who shaped the modern physics of matter, energy, and information. They were driven — by the equations themselves — to positions that the Upaniṣads had articulated before Socrates was born. <strong>Hiraṇyagarbha is not an ancient myth awaiting falsification. It is the map of the cosmos that physics keeps re-drawing.</strong>',
        ['Chit','Brahman','Atman','Mahat']);
  }
  $hg('hg-content').classList.add('open');
  $hg('hg-content').scrollTop=0;
};

window.hgCloseContent=function(){
  $hg('hg-content').classList.remove('open');
  document.querySelectorAll('#hg-exp .era-exp-tab').forEach(function(t){t.classList.remove('active');});
  var first=document.querySelector('#hg-exp .era-exp-tab');
  if(first)first.classList.add('active');
};

// ══════════════════════════════════════════════════════════
//  CANVAS ENGINE
// ══════════════════════════════════════════════════════════
function initHiranyagarbhaCanvas(){
  var c=$hg('hg-canvas');
  if(!c)return;
  hgCanvas=c;
  hgCtx=c.getContext('2d');
  hgDpr=window.devicePixelRatio||1;

  function resize(){
    var ov=$hg('hg-exp');
    if(!ov)return;
    hgW=ov.clientWidth||window.innerWidth;
    hgH=ov.clientHeight||window.innerHeight;
    c.width=hgW*hgDpr; c.height=hgH*hgDpr;
    c.style.width=hgW+'px'; c.style.height=hgH+'px';
    hgCtx.setTransform(hgDpr,0,0,hgDpr,0,0);
    // Re-seed silence dust
    hgSilenceDust=[];
    for(var i=0;i<55;i++){
      hgSilenceDust.push({
        x:Math.random()*hgW, y:Math.random()*hgH,
        vx:(Math.random()-0.5)*0.04, vy:(Math.random()-0.5)*0.04,
        r:Math.random()*0.8+0.2,
        a:Math.random()*0.14+0.03,
        phase:Math.random()*Math.PI*2,
        speed:Math.random()*0.001+0.0005
      });
    }
    // Recalculate positional targets for stage-specific collections
    if(hgStage===4)hgAssignBitTargets();
    if(hgStage===6){hgBuildCosmicWeb();}
    if(hgStage===7)hgRenderTattvaLabels();
  }
  resize();
  window.addEventListener('resize',function(){guardedResize(resize,200);});

  // Tap canvas to advance (only if tapping outside advance button / tabs)
  c.addEventListener('click',function(ev){
    if(!hgDidAdvance){hgAdvance();return;}
    // If on final stage already, don't re-advance on canvas tap
    if(hgStage>=HG_TOTAL_STAGES)return;
    // Require min dwell time so narrative can finish its fade
    if(hgStageT<HG_STAGES[hgStage].minFramesBeforeAdvance)return;
    hgAdvance();
  });

  if(hgFrame)cancelAnimationFrame(hgFrame);
  hgFrame=requestAnimationFrame(hgDraw);
}

function hgDraw(){
  if(!hgCtx){hgFrame=null;return;}
  hgT++;
  hgStageT++;

  var cx=hgW/2, cy=hgH/2;

  // Clear
  hgCtx.clearRect(0,0,hgW,hgH);

  // ── Stage-layered rendering — each stage builds on previous ──
  // We render in dependency order: background → dust → stage-specific → foreground

  // ── Background radial wash — color warms as we progress through acts ──
  var warmth=Math.min(1,(hgStage+hgStageT*0.002)/HG_TOTAL_STAGES);
  var bgPulse=Math.sin(hgT*0.008)*0.5+0.5;
  var bgG=hgCtx.createRadialGradient(cx,cy,0,cx,cy,Math.max(hgW,hgH)*0.7);
  bgG.addColorStop(0,'rgba('+Math.round(30+warmth*40)+','+Math.round(20+warmth*30)+','+Math.round(10+warmth*5)+','+(0.04+0.02*bgPulse+0.02*warmth)+')');
  bgG.addColorStop(0.55,'rgba('+Math.round(16+warmth*20)+','+Math.round(10+warmth*15)+','+Math.round(5+warmth*3)+','+(0.025+0.01*bgPulse)+')');
  bgG.addColorStop(1,'rgba(0,0,0,0)');
  hgCtx.fillStyle=bgG;
  hgCtx.fillRect(0,0,hgW,hgH);

  // ── Silence dust — always drifts, faintly, beneath everything ──
  hgSilenceDust.forEach(function(p){
    p.phase+=p.speed;
    p.x+=p.vx; p.y+=p.vy;
    if(p.x<-10)p.x=hgW+10; if(p.x>hgW+10)p.x=-10;
    if(p.y<-10)p.y=hgH+10; if(p.y>hgH+10)p.y=-10;
    var a=p.a*(0.4+0.6*Math.sin(p.phase));
    var pg=hgCtx.createRadialGradient(p.x,p.y,0,p.x,p.y,p.r*4);
    pg.addColorStop(0,'rgba(240,210,160,'+a+')');
    pg.addColorStop(1,'rgba(240,210,160,0)');
    hgCtx.fillStyle=pg;
    hgCtx.beginPath(); hgCtx.arc(p.x,p.y,p.r*4,0,Math.PI*2); hgCtx.fill();
  });

  // ── Stage-specific rendering ──

  // Persistent core — once ignition has happened (stage>=2), the golden bindu exists
  var corePresent = hgStage>=2 || (hgStage===1 && hgStageT>80);

  // ACT I: The Silence — just dust; a very faint pulsing echo at center
  if(hgStage===0){
    // Subtle "breathing potential" at center — very faint
    var sil=(Math.sin(hgT*0.012)*0.5+0.5)*0.05 + 0.03;
    var silG=hgCtx.createRadialGradient(cx,cy,0,cx,cy,Math.min(hgW,hgH)*0.15);
    silG.addColorStop(0,'rgba(240,210,160,'+sil+')');
    silG.addColorStop(1,'rgba(240,210,160,0)');
    hgCtx.fillStyle=silG;
    hgCtx.beginPath(); hgCtx.arc(cx,cy,Math.min(hgW,hgH)*0.15,0,Math.PI*2); hgCtx.fill();
  }

  // ACT II: The First Turning — inward-rotating arcs tightening toward center
  if(hgStage===1){
    hgReflectors.forEach(function(r){
      r.angle+=r.speed;
      r.radius=Math.max(6,r.radius-0.08);
      r.alpha=Math.min(0.35,r.alpha+0.005);
      hgCtx.strokeStyle='rgba(240,210,160,'+r.alpha+')';
      hgCtx.lineWidth=0.8;
      hgCtx.beginPath();
      hgCtx.arc(cx,cy,r.radius,r.angle,r.angle+Math.PI*1.2);
      hgCtx.stroke();
    });
    // Nascent bindu at center
    var bR=Math.min(1.5+hgStageT*0.02,5);
    var bg=hgCtx.createRadialGradient(cx,cy,0,cx,cy,bR*8);
    bg.addColorStop(0,'rgba(255,230,170,'+Math.min(0.4,hgStageT*0.004)+')');
    bg.addColorStop(1,'rgba(255,230,170,0)');
    hgCtx.fillStyle=bg;
    hgCtx.beginPath(); hgCtx.arc(cx,cy,bR*8,0,Math.PI*2); hgCtx.fill();
  }

  // ACT III: The Ignition — radial rays bursting outward
  if(hgStage===2){
    hgIgnitionRays.forEach(function(r,i){
      if(r.length<r.maxLen)r.length+=r.speed;
      r.alpha=Math.min(0.55,r.alpha+0.013);
      var ex=cx+Math.cos(r.angle)*r.length;
      var ey=cy+Math.sin(r.angle)*r.length;
      var grad=hgCtx.createLinearGradient(cx,cy,ex,ey);
      grad.addColorStop(0,'rgba(255,230,170,'+r.alpha+')');
      grad.addColorStop(1,'rgba(255,200,110,0)');
      hgCtx.strokeStyle=grad;
      hgCtx.lineWidth=0.9;
      hgCtx.beginPath();
      hgCtx.moveTo(cx,cy);
      hgCtx.lineTo(ex,ey);
      hgCtx.stroke();
    });
    // Core that is the source of the rays
    drawGoldenCore(cx,cy, 5+Math.min(hgStageT*0.04,3), 0.85);
  }

  // ACT IV: The Womb Breathes — pulsing sphere with orbiting particles
  if(hgStage===3){
    // Spheric halo that inhales and exhales
    var breath=Math.sin(hgT*0.02)*0.5+0.5;
    var wombR=65 + breath*22;
    // Big glow
    var wg=hgCtx.createRadialGradient(cx,cy,0,cx,cy,wombR*2);
    wg.addColorStop(0,'rgba(255,230,170,'+(0.35+0.15*breath)+')');
    wg.addColorStop(0.4,'rgba(255,200,110,'+(0.12+0.08*breath)+')');
    wg.addColorStop(1,'rgba(255,200,110,0)');
    hgCtx.fillStyle=wg;
    hgCtx.beginPath(); hgCtx.arc(cx,cy,wombR*2,0,Math.PI*2); hgCtx.fill();
    // Inner solid
    hgCtx.fillStyle='rgba(255,240,200,'+(0.5+0.2*breath)+')';
    hgCtx.beginPath(); hgCtx.arc(cx,cy,wombR*0.25,0,Math.PI*2); hgCtx.fill();
    // Orbiting embers
    hgWombParticles.forEach(function(w){
      w.angle+=w.speed;
      w.phase+=0.025;
      w.alpha += (w.targetAlpha-w.alpha)*0.02;
      var wx=cx+Math.cos(w.angle)*w.orbitR;
      var wy=cy+Math.sin(w.angle)*w.orbitR;
      var a=w.alpha*(0.5+0.5*Math.sin(w.phase));
      var pg=hgCtx.createRadialGradient(wx,wy,0,wx,wy,w.r*5);
      pg.addColorStop(0,'rgba(255,220,140,'+a+')');
      pg.addColorStop(1,'rgba(255,220,140,0)');
      hgCtx.fillStyle=pg;
      hgCtx.beginPath(); hgCtx.arc(wx,wy,w.r*5,0,Math.PI*2); hgCtx.fill();
    });
  }

  // ACT V: The Information Field — bits converging to a circular shell
  if(hgStage===4){
    hgInfoBits.forEach(function(b){
      // Move toward target
      var dx=b.tx-b.x, dy=b.ty-b.y;
      b.vx += dx*0.008 - b.vx*0.12;
      b.vy += dy*0.008 - b.vy*0.12;
      b.x+=b.vx; b.y+=b.vy;
      b.flickerPhase+=b.flickerSpeed;
      b.alpha += (b.targetAlpha-b.alpha)*0.03;
      var flicker=Math.abs(Math.sin(b.flickerPhase));
      var a=b.alpha*flicker;
      // Bits shimmer gold or pale
      var col = b.bit===1 ? '255,230,170' : '220,200,160';
      var pg=hgCtx.createRadialGradient(b.x,b.y,0,b.x,b.y,b.r*4);
      pg.addColorStop(0,'rgba('+col+','+a+')');
      pg.addColorStop(1,'rgba('+col+',0)');
      hgCtx.fillStyle=pg;
      hgCtx.beginPath(); hgCtx.arc(b.x,b.y,b.r*4,0,Math.PI*2); hgCtx.fill();
      // Occasionally draw a tiny "1" or "0" near it for the "It from Bit" effect
      if(Math.random()<0.003 && b.alpha>0.3){
        hgCtx.fillStyle='rgba(255,230,170,'+(b.alpha*0.55)+')';
        hgCtx.font='6px "IBM Plex Mono",monospace';
        hgCtx.textAlign='center';
        hgCtx.fillText(b.bit, b.x, b.y-4);
      }
    });
    // Central core still there
    drawGoldenCore(cx,cy,5,0.8);
  }

  // ACT VI: The Hum — concentric vibration rings emanating from core
  if(hgStage===5){
    // Spawn new rings periodically
    if(hgT%24===0 && hgHumRings.length<18){
      hgHumRings.push({r:0,alpha:0.35,speed:1.1+Math.random()*0.4});
    }
    for(var hi=hgHumRings.length-1;hi>=0;hi--){
      var hr=hgHumRings[hi];
      hr.r+=hr.speed;
      hr.alpha*=0.992;
      if(hr.alpha<0.01){hgHumRings.splice(hi,1);continue;}
      hgCtx.strokeStyle='rgba(255,220,140,'+hr.alpha+')';
      hgCtx.lineWidth=0.9;
      hgCtx.beginPath(); hgCtx.arc(cx,cy,hr.r,0,Math.PI*2); hgCtx.stroke();
      // Secondary inner ring
      if(hr.r>25){
        hgCtx.strokeStyle='rgba(255,220,140,'+hr.alpha*0.5+')';
        hgCtx.beginPath(); hgCtx.arc(cx,cy,hr.r*0.72,0,Math.PI*2); hgCtx.stroke();
      }
    }
    // Info bits still lingering, slowly dissolving
    hgInfoBits.forEach(function(b){
      b.alpha*=0.992;
      if(b.alpha<0.02)return;
      var a=b.alpha*Math.abs(Math.sin(b.flickerPhase+=b.flickerSpeed*0.3));
      var pg=hgCtx.createRadialGradient(b.x,b.y,0,b.x,b.y,b.r*3);
      pg.addColorStop(0,'rgba(240,210,160,'+a+')');
      pg.addColorStop(1,'rgba(240,210,160,0)');
      hgCtx.fillStyle=pg;
      hgCtx.beginPath(); hgCtx.arc(b.x,b.y,b.r*3,0,Math.PI*2); hgCtx.fill();
    });
    drawGoldenCore(cx,cy,6+Math.sin(hgT*0.04)*1.5,0.85);
  }

  // ACT VII: The Cosmic Web — nodes ignite and edges crystallize
  if(hgStage===6){
    // Edges first (they appear behind nodes)
    hgWebEdges.forEach(function(e){
      if(hgStageT<e.delay)return;
      e.alpha += (e.target-e.alpha)*0.04;
      var na=hgWebNodes[e.a], nb=hgWebNodes[e.b];
      hgCtx.strokeStyle='rgba(255,220,140,'+e.alpha+')';
      hgCtx.lineWidth=0.6;
      hgCtx.beginPath();
      hgCtx.moveTo(na.x,na.y); hgCtx.lineTo(nb.x,nb.y);
      hgCtx.stroke();
    });
    // Nodes
    hgWebNodes.forEach(function(n,i){
      var delay=i*1.5;
      if(hgStageT<delay)return;
      n.alpha += (n.target-n.alpha)*0.05;
      n.pulsePhase+=0.025;
      var pulse=0.6+0.4*Math.sin(n.pulsePhase);
      var na=n.alpha*pulse;
      var ng=hgCtx.createRadialGradient(n.x,n.y,0,n.x,n.y,n.r*6);
      ng.addColorStop(0,'rgba(255,230,170,'+na+')');
      ng.addColorStop(0.45,'rgba(255,200,110,'+(na*0.4)+')');
      ng.addColorStop(1,'rgba(255,200,110,0)');
      hgCtx.fillStyle=ng;
      hgCtx.beginPath(); hgCtx.arc(n.x,n.y,n.r*6,0,Math.PI*2); hgCtx.fill();
      // Core
      hgCtx.fillStyle='rgba(255,240,200,'+Math.min(1,na*1.4)+')';
      hgCtx.beginPath(); hgCtx.arc(n.x,n.y,n.r,0,Math.PI*2); hgCtx.fill();
    });
    // Central node is most radiant
    if(hgWebNodes.length>0){
      var cn=hgWebNodes[0];
      drawGoldenCore(cn.x,cn.y, 7+Math.sin(hgT*0.04)*1.2, 0.92);
    }
  }

  // ACT VIII: Mahat Descends — golden mandala with concentric tattva rings
  if(hgStage===7){
    var baseR=Math.min(hgW,hgH)*0.33;
    // Background mandala glow
    var mandG=hgCtx.createRadialGradient(cx,cy,0,cx,cy,baseR*1.4);
    mandG.addColorStop(0,'rgba(255,220,140,'+(0.1+0.03*Math.sin(hgT*0.02))+')');
    mandG.addColorStop(0.5,'rgba(255,200,110,0.04)');
    mandG.addColorStop(1,'rgba(255,200,110,0)');
    hgCtx.fillStyle=mandG;
    hgCtx.beginPath(); hgCtx.arc(cx,cy,baseR*1.4,0,Math.PI*2); hgCtx.fill();

    // 5 concentric rings — the tattva ladder
    HG_TATTVAS.forEach(function(t,i){
      if(i===0)return; // skip center
      var rr=baseR*t.r;
      var ringPulse=Math.sin(hgT*0.02+i*0.9)*0.5+0.5;
      var alpha=0.12+0.1*ringPulse;
      hgCtx.strokeStyle='rgba(255,220,140,'+alpha+')';
      hgCtx.lineWidth=0.8;
      hgCtx.beginPath(); hgCtx.arc(cx,cy,rr,0,Math.PI*2); hgCtx.stroke();
      // Tick marks at equi-angle to suggest sub-divisions
      var ticks=6+i*2;
      for(var tk=0;tk<ticks;tk++){
        var ta=(tk/ticks)*Math.PI*2 + hgT*0.0006*(i%2?1:-1);
        var tx1=cx+Math.cos(ta)*(rr-3);
        var ty1=cy+Math.sin(ta)*(rr-3);
        var tx2=cx+Math.cos(ta)*(rr+3);
        var ty2=cy+Math.sin(ta)*(rr+3);
        hgCtx.strokeStyle='rgba(255,230,170,'+(alpha*1.4)+')';
        hgCtx.lineWidth=0.6;
        hgCtx.beginPath(); hgCtx.moveTo(tx1,ty1); hgCtx.lineTo(tx2,ty2); hgCtx.stroke();
      }
    });

    // Radial lines (geometry)
    for(var rl=0;rl<12;rl++){
      var ra=(rl/12)*Math.PI*2 + hgT*0.0004;
      var ox=cx+Math.cos(ra)*6;
      var oy=cy+Math.sin(ra)*6;
      var ex2=cx+Math.cos(ra)*baseR*0.9;
      var ey2=cy+Math.sin(ra)*baseR*0.9;
      var gradR=hgCtx.createLinearGradient(ox,oy,ex2,ey2);
      gradR.addColorStop(0,'rgba(255,230,170,0.3)');
      gradR.addColorStop(1,'rgba(255,200,110,0.04)');
      hgCtx.strokeStyle=gradR;
      hgCtx.lineWidth=0.6;
      hgCtx.beginPath(); hgCtx.moveTo(ox,oy); hgCtx.lineTo(ex2,ey2); hgCtx.stroke();
    }

    // Eight-petal lotus as the innermost structure
    var petalR=baseR*0.3;
    for(var pt=0;pt<8;pt++){
      var pa=(pt/8)*Math.PI*2 + hgT*0.0008;
      var px=cx+Math.cos(pa)*petalR;
      var py=cy+Math.sin(pa)*petalR;
      hgCtx.strokeStyle='rgba(255,220,140,'+(0.25+0.1*Math.sin(hgT*0.02+pt))+')';
      hgCtx.lineWidth=0.8;
      hgCtx.beginPath();
      var ox=cx+Math.cos(pa)*3, oy=cy+Math.sin(pa)*3;
      var pex=cx+Math.cos(pa+0.35)*petalR*0.82;
      var pey=cy+Math.sin(pa+0.35)*petalR*0.82;
      var pex2=cx+Math.cos(pa-0.35)*petalR*0.82;
      var pey2=cy+Math.sin(pa-0.35)*petalR*0.82;
      hgCtx.moveTo(ox,oy);
      hgCtx.quadraticCurveTo(pex,pey,px,py);
      hgCtx.quadraticCurveTo(pex2,pey2,ox,oy);
      hgCtx.stroke();
    }

    // Central Mahat glow — the source from which all tattvas descend
    drawGoldenCore(cx,cy, 10+Math.sin(hgT*0.03)*2, 0.95);

    // Particles descending through the rings (showing the descent of intelligence into form)
    if(hgT%5===0){
      hgWombParticles.push({
        orbitR:baseR*1.05, angle:Math.random()*Math.PI*2,
        speed:0, r:Math.random()*1.2+0.4, alpha:0.5,
        targetAlpha:0.5, phase:0,
        fallMode:true,
        fallV:0.5+Math.random()*0.8
      });
    }
    hgWombParticles.forEach(function(w){
      if(w.fallMode){
        w.orbitR-=w.fallV;
        w.alpha*=0.992;
        var wx=cx+Math.cos(w.angle)*Math.max(0,w.orbitR);
        var wy=cy+Math.sin(w.angle)*Math.max(0,w.orbitR);
        var pg=hgCtx.createRadialGradient(wx,wy,0,wx,wy,w.r*4);
        pg.addColorStop(0,'rgba(255,220,140,'+w.alpha+')');
        pg.addColorStop(1,'rgba(255,220,140,0)');
        hgCtx.fillStyle=pg;
        hgCtx.beginPath(); hgCtx.arc(wx,wy,w.r*4,0,Math.PI*2); hgCtx.fill();
      }
    });
    // Cull old fallen particles
    hgWombParticles=hgWombParticles.filter(function(w){return !w.fallMode || (w.orbitR>0 && w.alpha>0.02);});
  }

  // ── Final recognition stage — silent, solitary bindu breathing ──
  if(hgStage>=HG_TOTAL_STAGES){
    var recPulse=Math.sin(hgT*0.018)*0.5+0.5;
    var recR=10+recPulse*4;
    var recG=hgCtx.createRadialGradient(cx,cy-20,0,cx,cy-20,recR*14);
    recG.addColorStop(0,'rgba(255,235,170,'+(0.5+0.15*recPulse)+')');
    recG.addColorStop(0.4,'rgba(255,200,110,0.1)');
    recG.addColorStop(1,'rgba(255,200,110,0)');
    hgCtx.fillStyle=recG;
    hgCtx.beginPath(); hgCtx.arc(cx,cy-20,recR*14,0,Math.PI*2); hgCtx.fill();
  }

  hgFrame=requestAnimationFrame(hgDraw);
}

// ── Golden core drawing helper ────────────────────────
function drawGoldenCore(x,y,r,alphaScale){
  alphaScale=alphaScale||1;
  // Outer halo
  var hR=r*8;
  var hG=hgCtx.createRadialGradient(x,y,0,x,y,hR);
  hG.addColorStop(0,'rgba(255,220,140,'+(0.28*alphaScale)+')');
  hG.addColorStop(0.4,'rgba(255,200,110,'+(0.1*alphaScale)+')');
  hG.addColorStop(1,'rgba(255,200,110,0)');
  hgCtx.fillStyle=hG;
  hgCtx.beginPath(); hgCtx.arc(x,y,hR,0,Math.PI*2); hgCtx.fill();
  // Mid glow
  var mR=r*3;
  var mG=hgCtx.createRadialGradient(x,y,0,x,y,mR);
  mG.addColorStop(0,'rgba(255,240,200,'+(0.85*alphaScale)+')');
  mG.addColorStop(0.6,'rgba(255,220,140,'+(0.25*alphaScale)+')');
  mG.addColorStop(1,'rgba(255,220,140,0)');
  hgCtx.fillStyle=mG;
  hgCtx.beginPath(); hgCtx.arc(x,y,mR,0,Math.PI*2); hgCtx.fill();
  // Core dot
  hgCtx.fillStyle='rgba(255,250,220,'+(0.95*alphaScale)+')';
  hgCtx.beginPath(); hgCtx.arc(x,y,r*0.7,0,Math.PI*2); hgCtx.fill();
}

