// ═══════════════════════════════════════════════════════════════════
//  CONTENT-ACTIVE OBSERVER · 20260427
//  Watches every .era-exp-content panel. When the panel gets the
//  .open class, mirror it as .content-active onto the nearest
//  .modal-base ancestor so CSS can hide the animation panels behind.
//  Works for every present and future big-build overlay automatically.
//
//  Also (20260428): toggles body.ov-active when #ov opens and
//  body.modal-active whenever any .modal-base.on is active, so
//  CSS can hide the timeline-chrome that bleeds through overlays.
// ═══════════════════════════════════════════════════════════════════
(function(){
  function syncContentActive(){
    document.querySelectorAll('.modal-base').forEach(function(ov){
      var content = ov.querySelector(':scope > .era-exp-content');
      if (!content) {
        // fallback: search descendants
        content = ov.querySelector('.era-exp-content');
      }
      if (content && content.classList.contains('open')){
        ov.classList.add('content-active');
      } else {
        ov.classList.remove('content-active');
      }
    });
  }
  function syncBodyOverlayState(){
    var ovEl = document.getElementById('ov');
    var ovOn = !!(ovEl && ovEl.classList.contains('on'));
    document.body.classList.toggle('ov-active', ovOn);
    var anyModalOn = false;
    document.querySelectorAll('.modal-base').forEach(function(m){
      if (m.classList.contains('on') || m.classList.contains('open')) anyModalOn = true;
    });
    // Also count Om guide / WhoFor / Yuga clock / etc — anything z-400+
    ['om-guide','whofor-ov','yugaclock-ov','turiya-ov','intro','kosha-deep','manthan-ov'].forEach(function(id){
      var el = document.getElementById(id);
      if (el && (el.classList.contains('on') || el.classList.contains('open'))) anyModalOn = true;
    });
    document.body.classList.toggle('modal-active', anyModalOn || ovOn);
  }
  function startObserver(){
    var observer = new MutationObserver(function(mutations){
      var needsContentSync = false;
      var needsBodySync = false;
      for (var i=0;i<mutations.length;i++){
        var t = mutations[i].target;
        if (!t || !t.classList) continue;
        if (t.classList.contains('era-exp-content')) needsContentSync = true;
        if (t.classList.contains('modal-base') || t.id === 'ov' ||
            t.id === 'om-guide' || t.id === 'whofor-ov' ||
            t.id === 'yugaclock-ov' || t.id === 'turiya-ov' ||
            t.id === 'intro' || t.id === 'kosha-deep' ||
            t.id === 'manthan-ov') needsBodySync = true;
      }
      if (needsContentSync) syncContentActive();
      if (needsBodySync) syncBodyOverlayState();
    });
    document.querySelectorAll('.era-exp-content').forEach(function(el){
      observer.observe(el, {attributes:true, attributeFilter:['class']});
    });
    document.querySelectorAll('.modal-base').forEach(function(el){
      observer.observe(el, {attributes:true, attributeFilter:['class']});
    });
    ['ov','om-guide','whofor-ov','yugaclock-ov','turiya-ov','intro','kosha-deep','manthan-ov'].forEach(function(id){
      var el = document.getElementById(id);
      if (el) observer.observe(el, {attributes:true, attributeFilter:['class']});
    });
    syncContentActive();
    syncBodyOverlayState();
  }
  if (document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', startObserver);
  } else {
    startObserver();
  }
})();

