// ══════════════════════════════════════════════════════════════════════
// GATEWAY EXPERIENCE — Cosmic OS Entry System
// 3-stage perception interface: VOID → ORIENTATION → SYSTEM ENTRY
// Replaces the old "Enter the Yuga" intro page
// ══════════════════════════════════════════════════════════════════════
(function(){
  'use strict';

  var _gw={
    stage:0,
    canvas:null, ctx:null,
    w:0, h:0,
    particles:[],
    animId:null,
    resizeTimer:null,
    initiated:false
  };

  function $g(id){return document.getElementById(id);}

  // ── Particle field ──
  function gwInitParticles(){
    _gw.particles=[];
    var count=Math.min(80,Math.floor(_gw.w*_gw.h/14000));
    for(var i=0;i<count;i++){
      _gw.particles.push({
        x:Math.random()*_gw.w,
        y:Math.random()*_gw.h,
        r:Math.random()*1.2+0.2,
        vx:(Math.random()-.5)*0.18,
        vy:(Math.random()-.5)*0.18,
        alpha:Math.random()*0.35+0.05,
        pulse:Math.random()*Math.PI*2,
        pspeed:Math.random()*0.008+0.004
      });
    }
  }

  function gwDrawFrame(){
    if(!_gw.ctx)return;
    var c=_gw.ctx, w=_gw.w, h=_gw.h;
    c.clearRect(0,0,w,h);

    // Faint center glow
    var grd=c.createRadialGradient(w*.5,h*.5,0,w*.5,h*.5,w*.6);
    grd.addColorStop(0,'rgba(40,30,10,0.07)');
    grd.addColorStop(1,'rgba(0,0,0,0)');
    c.fillStyle=grd;
    c.fillRect(0,0,w,h);

    // Particles
    for(var i=0;i<_gw.particles.length;i++){
      var p=_gw.particles[i];
      p.x+=p.vx; p.y+=p.vy;
      p.pulse+=p.pspeed;
      if(p.x<-4)p.x=w+4;
      if(p.x>w+4)p.x=-4;
      if(p.y<-4)p.y=h+4;
      if(p.y>h+4)p.y=-4;
      var a=p.alpha*(0.6+0.4*Math.sin(p.pulse));
      c.beginPath();
      c.arc(p.x,p.y,p.r,0,Math.PI*2);
      c.fillStyle='rgba(200,175,110,'+a+')';
      c.fill();
    }
    _gw.animId=requestAnimationFrame(gwDrawFrame);
  }

  function gwResize(){
    var c=_gw.canvas;
    if(!c)return;
    _gw.w=c.width=c.offsetWidth||window.innerWidth;
    _gw.h=c.height=c.offsetHeight||window.innerHeight;
    gwInitParticles();
  }

  function gwResizeGuarded(){
    if(typeof guardedResize==='function'){guardedResize(gwResize,200);}
    else{clearTimeout(_gw.resizeTimer);_gw.resizeTimer=setTimeout(gwResize,200);}
  }

  // ── Stage transitions ──
  function gwShowStage(n){
    for(var i=1;i<=3;i++){
      var s=$g('gw-s'+i);
      if(s){s.classList.remove('gw-active','gw-leaving');}
    }
    var target=$g('gw-s'+n);
    if(!target)return;
    _gw.stage=n;

    if(n===1) gwAnimateStage1();
    else if(n===2) gwAnimateStage2();
    else if(n===3) gwAnimateStage3();

    setTimeout(function(){
      if(target) target.classList.add('gw-active');
    },n===1?0:80);
  }

  function gwAnimateStage1(){
    var line=$g('gw-void-line');
    var btn=$g('gw-enter-btn');
    var skip=$g('gw-skip');
    // Faster: line by 300ms, button by 1100ms, skip by 2200ms
    if(line){setTimeout(function(){line.classList.add('gw-lit');},300);}
    if(btn){setTimeout(function(){btn.classList.add('gw-lit');},1100);}
    if(skip){setTimeout(function(){skip.classList.add('gw-lit');},2200);}
  }

  function gwAnimateStage2(){
    // Faster cascade: 200, 800, 1500, 2200, 3000
    var delays=[200,800,1500,2200,3000];
    var ids=['gw-ol1','gw-ol2','gw-ol3','gw-ol4','gw-begin-btn'];
    ids.forEach(function(id,i){
      setTimeout(function(){
        var el=$g(id);
        if(el)el.classList.add('gw-lit');
      },delays[i]);
    });
  }

  // Force-show all elements in current stage (used on user tap)
  function gwForceShowCurrent(){
    var stage=_gw.stage;
    if(stage===1){
      ['gw-void-line','gw-enter-btn','gw-skip'].forEach(function(id){
        var el=$g(id); if(el) el.classList.add('gw-lit');
      });
    } else if(stage===2){
      ['gw-ol1','gw-ol2','gw-ol3','gw-ol4','gw-begin-btn'].forEach(function(id){
        var el=$g(id); if(el) el.classList.add('gw-lit');
      });
    }
  }

  function gwAnimateStage3(){
    var layers=['gwl-source','gwl-field','gwl-system','gwl-experience','gwl-self'];
    layers.forEach(function(id,i){
      setTimeout(function(){
        var el=$g(id);
        if(el)el.classList.add('gw-lit');
      },200+i*160);
    });
    setTimeout(function(){
      var btn=$g('gw-timeline-btn');
      var note=document.querySelector('.gw-system-note');
      if(btn)btn.classList.add('gw-lit');
      if(note)note.classList.add('gw-lit');
    },1400);
  }

  window.gwNext=function(toStage){
    var current=$g('gw-s'+_gw.stage);
    if(current){
      current.classList.add('gw-leaving');
      setTimeout(function(){
        current.classList.remove('gw-active','gw-leaving');
        gwShowStage(toStage);
      },350);
    } else {
      gwShowStage(toStage);
    }
  };

  window.gwEnterLayer=function(layer){
    // Visual feedback: highlight selected layer
    var all=document.querySelectorAll('.gw-layer');
    all.forEach(function(l){l.style.opacity='0.4';});
    var sel=$g('gwl-'+layer);
    if(sel){
      sel.style.opacity='1';
      sel.style.background='rgba(200,168,80,.07)';
    }
    setTimeout(function(){gwDismiss(layer);},400);
  };

  window.gwEnterTimeline=function(){gwDismiss('source');};
  window.gwSkip=function(){gwDismiss('source');};

  function gwDismiss(layer){
    var ov=$g('gw-ov');
    if(!ov)return;
    if(_gw.animId)cancelAnimationFrame(_gw.animId);

    ov.classList.add('gw-exiting');
    setTimeout(function(){
      ov.style.display='none';
      if(typeof startTimeline==='function'){
        startTimeline();
      }
    },650);
  }

  function gwInit(){
    if(_gw.initiated)return;
    _gw.initiated=true;

    _gw.canvas=$g('gw-canvas');
    if(_gw.canvas){
      _gw.ctx=_gw.canvas.getContext('2d');
      gwResize();
      gwDrawFrame();
      window.addEventListener('resize',gwResizeGuarded);
    }

    // Start at Stage 1
    gwShowStage(1);

    // ── TAP-ANYWHERE-TO-ADVANCE ────────────────────────────────
    // Single tap on Stage 1 → reveal all Stage 1 elements instantly
    //                       (so user can press Enter without waiting)
    // Double tap or tap on already-revealed Stage 1 → advance to Stage 2
    // Same logic for Stage 2 → enters timeline
    var ov=$g('gw-ov');
    if(ov){
      ov.addEventListener('click', function(e){
        // Don't intercept clicks on the buttons themselves — they have their own handlers
        if(e.target.closest('button')) return;
        if(e.target.id==='gw-skip') return;

        var stage=_gw.stage;
        if(stage===1){
          var btn=$g('gw-enter-btn');
          // If button isn't lit yet, just reveal everything immediately
          if(btn && !btn.classList.contains('gw-lit')){
            gwForceShowCurrent();
          } else {
            // Already revealed — advance to stage 2
            window.gwNext(2);
          }
        } else if(stage===2){
          var bbtn=$g('gw-begin-btn');
          if(bbtn && !bbtn.classList.contains('gw-lit')){
            gwForceShowCurrent();
          } else {
            // Already revealed — enter timeline
            window.gwEnterTimeline();
          }
        }
      });
    }

    // Enter key support
    document.addEventListener('keydown',function(e){
      var ov=$g('gw-ov');
      if(!ov || ov.style.display==='none' || ov.classList.contains('gw-exiting'))return;
      if(e.key==='Escape'){
        gwDismiss('source');
        return;
      }
      if(e.key==='Enter' || e.key===' '){
        e.preventDefault();
        var stage=_gw.stage;
        if(stage===1){
          gwForceShowCurrent();
          setTimeout(function(){window.gwNext(2);},80);
        } else if(stage===2){
          gwForceShowCurrent();
          setTimeout(function(){window.gwEnterTimeline();},80);
        }
      }
    });
  }

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',gwInit);
  } else {
    setTimeout(gwInit,0);
  }

})();

