// ── Init / Open / Close ────────────────────────────────────────────────────
window.openDharm=function(){
  var ov=$dh('dharm-exp'); if(!ov) return;
  ov.classList.add('on');
  document.querySelectorAll('#dharm-exp .era-exp-tab').forEach(function(t,i){t.classList.toggle('active',i===0);});
  var content=$dh('dharm-content'); if(content) content.classList.remove('open');
  ov.classList.remove('content-active');
  setTimeout(dhInit,300);
};
window.closeDharm=function(){
  var ov=$dh('dharm-exp'); if(!ov) return;
  ov.classList.remove('on');
  if(dhFrame){cancelAnimationFrame(dhFrame); dhFrame=null;}
  window.removeEventListener('resize',dhResizeGuarded);
  var content=$dh('dharm-content'); if(content) content.classList.remove('open');
  ov.classList.remove('content-active');
};

function dhInit(){
  dhCanvas=$dh('dharm-canvas'); if(!dhCanvas) return;
  dhCtx=dhCanvas.getContext('2d');
  dhResize();
  window.addEventListener('resize',dhResizeGuarded);
  dhT=0; dhCategory=0; dhCategoryT=0; dhSelected=-1; dhSelectionT=0;
  dhAutoCycle=true; dhAutoCycleI=0; dhAutoCycleT=0;
  dhPrevCategory=-1; dhTransitionT=1;
  // seed background
  dhStars=[];
  for(var s=0;s<180;s++){
    dhStars.push({
      x:Math.random(), y:Math.random(),
      r:Math.random()*1.0+.25,
      a:Math.random()*.55+.15,
      ph:Math.random()*Math.PI*2,
      sp:Math.random()*.0035+.0008
    });
  }
  dhDust=[];
  for(var d=0;d<60;d++){
    dhDust.push({
      x:Math.random(), y:Math.random(),
      r:Math.random()*1.4+.4,
      a:Math.random()*.18+.05,
      vx:(Math.random()-.5)*.0006,
      vy:(Math.random()-.5)*.0006,
      hue:Math.random()
    });
  }
  dhRipples=[]; dhPulses=[];
  dhUpdateCategoryUI();
  dhUpdateSelectionUI();
  dhAttachInput();
  dhLoop();
}

function dhResize(){
  if(!dhCanvas) return;
  var rect=dhCanvas.getBoundingClientRect();
  dhW=rect.width; dhH=rect.height;
  if(dhW<10||dhH<10){
    var ov=$dh('dharm-exp');
    if(ov){dhW=ov.clientWidth; dhH=ov.clientHeight;}
  }
  dhDpr=window.devicePixelRatio||1;
  dhCanvas.width=Math.floor(dhW*dhDpr);
  dhCanvas.height=Math.floor(dhH*dhDpr);
  dhCanvas.style.width=dhW+'px';
  dhCanvas.style.height=dhH+'px';
  if(dhCtx) dhCtx.setTransform(dhDpr,0,0,dhDpr,0,0);
}

// ── Input ──────────────────────────────────────────────────────────────────
function dhAttachInput(){
  if(!dhCanvas) return;
  dhCanvas.removeEventListener('click',dhClickH);
  dhCanvas.removeEventListener('mousemove',dhMoveH);
  dhCanvas.removeEventListener('mouseleave',dhLeaveH);
  dhCanvas.removeEventListener('touchend',dhTouchH);
  dhCanvas.addEventListener('click',dhClickH);
  dhCanvas.addEventListener('mousemove',dhMoveH);
  dhCanvas.addEventListener('mouseleave',dhLeaveH);
  dhCanvas.addEventListener('touchend',dhTouchH,{passive:false});
}
function dhLocalXY(cx,cy){
  var r=dhCanvas.getBoundingClientRect();
  return {x:cx-r.left, y:cy-r.top};
}
function dhMoveH(e){
  var p=dhLocalXY(e.clientX,e.clientY);
  dhMouseX=p.x; dhMouseY=p.y;
}
function dhLeaveH(){dhMouseX=-1; dhMouseY=-1;}
function dhClickH(e){
  var p=dhLocalXY(e.clientX,e.clientY);
  dhProcessTap(p.x, p.y);
}
function dhTouchH(e){
  if(e.changedTouches && e.changedTouches.length){
    var t=e.changedTouches[0];
    var p=dhLocalXY(t.clientX, t.clientY);
    dhProcessTap(p.x, p.y);
    e.preventDefault();
  }
}
function dhProcessTap(px, py){
  var idx=dhPickThing(px,py);
  if(idx>=0){
    dhSelected=idx;
    dhSelectionT=0;
    dhAutoCycle=false;
    dhUpdateSelectionUI();
    // emit ripple at the thing
    var pos=dhThingPosition(idx,1);
    dhRipples.push({x:pos.x,y:pos.y,t:0,life:90,r0:8});
    dhPulses.push({t:0,life:80,r:0});
    return;
  }
  // tap empty space -> deselect & resume auto cycle
  if(dhSelected!==-1){
    dhSelected=-1;
    dhSelectionT=0;
    dhUpdateSelectionUI();
  } else {
    // toggle auto cycle off if user tapped centre area, else nothing
    var cx=dhW/2, cy=dhH*.52;
    var dx=px-cx, dy=py-cy;
    if(dx*dx+dy*dy < (dhMinDim()*0.10)*(dhMinDim()*0.10)){
      dhAutoCycle=!dhAutoCycle;
      dhAutoCycleT=0;
    }
  }
  dhRipples.push({x:px,y:py,t:0,life:60,r0:4});
}
function dhMinDim(){return Math.min(dhW,dhH);}

// ── Geometry helpers ───────────────────────────────────────────────────────
function dhThingPosition(idx, fade){
  // 24 things in a single ring around centre; ring radius depends on viewport.
  var things=DHARM_CATEGORIES[dhCategory].things;
  var n=things.length;
  var cx=dhW/2, cy=dhH*.52;
  var R=dhMinDim()*0.36;
  // slow rotation
  var omega=dhT*0.0017;
  var ang=(idx/n)*Math.PI*2 + omega;
  // breath / wobble
  var br=R + Math.sin(dhT*0.012 + idx*0.4)*4;
  var x=cx+Math.cos(ang)*br;
  var y=cy+Math.sin(ang)*br*0.86;
  // selected thing drifts slightly toward upper-centre
  if(idx===dhSelected){
    var st=Math.min(1, dhSelectionT/45);
    var sm=0.5-0.5*Math.cos(st*Math.PI);
    var tx=cx, ty=cy-dhMinDim()*0.18;
    x=x*(1-sm*0.55)+tx*sm*0.55;
    y=y*(1-sm*0.55)+ty*sm*0.55;
  }
  return {x:x,y:y,ang:ang};
}
function dhPickThing(px,py){
  var things=DHARM_CATEGORIES[dhCategory].things;
  var pickR=dhMinDim()*0.05;
  for(var i=0;i<things.length;i++){
    var p=dhThingPosition(i,1);
    var dx=px-p.x, dy=py-p.y;
    if(dx*dx+dy*dy <= pickR*pickR){return i;}
  }
  return -1;
}

// ── Category swap ──────────────────────────────────────────────────────────
window.dhSelectCategory=function(idx){
  if(idx===dhCategory) return;
  dhPrevCategory=dhCategory;
  dhCategory=idx;
  dhCategoryT=0;
  dhTransitionT=0;
  dhSelected=-1;
  dhAutoCycle=true; dhAutoCycleI=0; dhAutoCycleT=0;
  dhPulses.push({t:0,life:120,r:0});
  dhUpdateCategoryUI();
  dhUpdateSelectionUI();
};
function dhUpdateCategoryUI(){
  var btns=document.querySelectorAll('#dharm-cats .dh-cat-btn');
  btns.forEach(function(b,i){b.classList.toggle('active', i===dhCategory);});
  var lbl=$dh('dharm-cat-label');
  if(lbl){
    var c=DHARM_CATEGORIES[dhCategory];
    lbl.innerHTML='<span style="opacity:.55;letter-spacing:5px;">— '+c.label.toUpperCase()+' —</span><br><span style="font-size:7px;letter-spacing:6px;opacity:.4;">'+c.sub.toUpperCase()+'</span>';
  }
}
function dhUpdateSelectionUI(){
  var disp=$dh('dharm-display');
  var things=DHARM_CATEGORIES[dhCategory].things;
  if(!disp) return;
  if(dhSelected<0){
    if(dhAutoCycle && things[dhAutoCycleI]){
      var t=things[dhAutoCycleI];
      disp.innerHTML='<div class="dh-disp-skt">'+t.skt+'</div>'+
                    '<div class="dh-disp-name">'+t.n+'</div>'+
                    '<div class="dh-disp-d">— its dharm is <em>'+t.d+'</em></div>'+
                    '<div class="dh-disp-hint">tap any orb to hold its dharm · tap centre to pause</div>';
      disp.classList.add('on');
    } else {
      disp.innerHTML='<div class="dh-disp-name" style="font-size:14px;letter-spacing:5px;opacity:.6;">paused</div>'+
                    '<div class="dh-disp-hint">tap any orb to read its dharm · tap centre again to resume</div>';
      disp.classList.add('on');
    }
    return;
  }
  var thing=things[dhSelected];
  disp.innerHTML='<div class="dh-disp-skt">'+thing.skt+'</div>'+
                '<div class="dh-disp-name">'+thing.n+'</div>'+
                '<div class="dh-disp-d">— its dharm is <em>'+thing.d+'</em></div>'+
                '<div class="dh-disp-hint">tap empty space to release · tap another orb to hold it</div>';
  disp.classList.add('on');
}

// ── Background helpers ─────────────────────────────────────────────────────
function dhBgColors(){
  // optionally interpolate during transition
  var c=DHARM_CATEGORIES[dhCategory];
  if(dhPrevCategory>=0 && dhTransitionT<1){
    var p=DHARM_CATEGORIES[dhPrevCategory];
    var t=dhTransitionT;
    return {a:dhMixRgba(p.bgA,c.bgA,t), b:dhMixRgba(p.bgB,c.bgB,t)};
  }
  return {a:c.bgA, b:c.bgB};
}
function dhMixRgba(a,b,t){
  var pa=dhParseRgba(a), pb=dhParseRgba(b);
  if(!pa||!pb) return a;
  var r=Math.round(pa[0]*(1-t)+pb[0]*t);
  var g=Math.round(pa[1]*(1-t)+pb[1]*t);
  var bl=Math.round(pa[2]*(1-t)+pb[2]*t);
  var al=pa[3]*(1-t)+pb[3]*t;
  return 'rgba('+r+','+g+','+bl+','+al+')';
}
function dhParseRgba(s){
  var m=s.match(/rgba?\(([^)]+)\)/);
  if(!m) return null;
  var p=m[1].split(',').map(function(x){return parseFloat(x);});
  return [p[0]||0,p[1]||0,p[2]||0,p[3]==null?1:p[3]];
}

// ── The animation loop ─────────────────────────────────────────────────────
function dhLoop(){
  if(!dhCtx||!dhCanvas){dhFrame=null; return;}
  dhT++; dhCategoryT++; dhSelectionT++; dhAutoCycleT++;
  if(dhTransitionT<1) dhTransitionT=Math.min(1, dhTransitionT+0.022);

  // Auto cycle: advance every ~5s
  if(dhAutoCycle && dhSelected===-1 && dhAutoCycleT>290){
    dhAutoCycleI=(dhAutoCycleI+1)%DHARM_CATEGORIES[dhCategory].things.length;
    dhAutoCycleT=0;
    dhUpdateSelectionUI();
    dhPulses.push({t:0,life:60,r:0,faint:true});
  }

  var cx=dhW/2, cy=dhH*.52;
  var minD=dhMinDim();

  // ── Background gradient ──
  var cols=dhBgColors();
  var bg=dhCtx.createRadialGradient(cx, cy, 0, cx, cy, Math.max(dhW,dhH)*0.85);
  bg.addColorStop(0, cols.a);
  bg.addColorStop(1, cols.b);
  dhCtx.fillStyle=bg;
  dhCtx.fillRect(0,0,dhW,dhH);

  // ── Mandala lines ──
  dhCtx.save();
  dhCtx.translate(cx,cy);
  dhCtx.rotate(dhT*0.0008);
  for(var ml=0; ml<24; ml++){
    var a=(ml/24)*Math.PI*2;
    var alphaL=0.05+0.04*Math.sin(dhT*0.01+ml);
    dhCtx.strokeStyle='rgba(220,200,160,'+alphaL+')';
    dhCtx.lineWidth=0.4;
    dhCtx.beginPath();
    dhCtx.moveTo(Math.cos(a)*minD*0.08, Math.sin(a)*minD*0.08);
    dhCtx.lineTo(Math.cos(a)*minD*0.46, Math.sin(a)*minD*0.46);
    dhCtx.stroke();
  }
  dhCtx.restore();

  // mandala rings (faint)
  for(var rng=0; rng<3; rng++){
    var rrad=minD*(0.18+rng*0.12);
    dhCtx.strokeStyle='rgba(220,200,160,'+(0.06-rng*0.012)+')';
    dhCtx.lineWidth=0.5;
    dhCtx.beginPath();
    dhCtx.arc(cx,cy,rrad,0,Math.PI*2);
    dhCtx.stroke();
  }

  // ── Stars ──
  dhStars.forEach(function(s){
    s.ph += s.sp;
    var alpha=s.a * (0.45+0.55*Math.abs(Math.sin(s.ph)));
    dhCtx.fillStyle='rgba(220,210,235,'+alpha+')';
    dhCtx.beginPath();
    dhCtx.arc(s.x*dhW, s.y*dhH, s.r, 0, Math.PI*2);
    dhCtx.fill();
  });

  // ── Cosmic dust ──
  dhDust.forEach(function(p){
    p.x += p.vx; p.y += p.vy;
    if(p.x<0)p.x+=1; else if(p.x>1)p.x-=1;
    if(p.y<0)p.y+=1; else if(p.y>1)p.y-=1;
    var hue=DHARM_CATEGORIES[dhCategory].col;  // e.g. 'rgba(180,200,255,'
    dhCtx.fillStyle=hue+(p.a*0.7)+')';
    dhCtx.beginPath();
    dhCtx.arc(p.x*dhW, p.y*dhH, p.r, 0, Math.PI*2);
    dhCtx.fill();
  });

  // ── Pulses (radial waves emanating from centre) ──
  for(var pi=dhPulses.length-1; pi>=0; pi--){
    var pu=dhPulses[pi]; pu.t++;
    if(pu.t>=pu.life){dhPulses.splice(pi,1); continue;}
    var pp=pu.t/pu.life;
    var pr=pp * minD*0.55;
    var pa=(1-pp)*(pu.faint?0.18:0.42);
    dhCtx.strokeStyle='rgba(255,225,170,'+pa+')';
    dhCtx.lineWidth=1.4;
    dhCtx.beginPath();
    dhCtx.arc(cx,cy,pr,0,Math.PI*2);
    dhCtx.stroke();
  }

  // ── Centre glyph ──
  dhDrawCentre(cx, cy, minD);

  // ── Things (orbiting orbs) ──
  var things=DHARM_CATEGORIES[dhCategory].things;
  for(var ti=0; ti<things.length; ti++){
    dhDrawThing(ti, things[ti], minD);
  }

  // Connecting glow line from centre to selected thing
  if(dhSelected>=0){
    var ts=Math.min(1, dhSelectionT/35);
    var pos=dhThingPosition(dhSelected,1);
    var grd=dhCtx.createLinearGradient(cx,cy,pos.x,pos.y);
    grd.addColorStop(0,'rgba(255,225,170,'+(0.6*ts)+')');
    grd.addColorStop(1,'rgba(255,225,170,0)');
    dhCtx.strokeStyle=grd;
    dhCtx.lineWidth=1.2;
    dhCtx.beginPath();
    dhCtx.moveTo(cx,cy);
    dhCtx.lineTo(pos.x,pos.y);
    dhCtx.stroke();
  }

  // Connecting line from centre to auto-cycle highlighted (faint)
  if(dhAutoCycle && dhSelected===-1 && things[dhAutoCycleI]){
    var posa=dhThingPosition(dhAutoCycleI,1);
    var grd2=dhCtx.createLinearGradient(cx,cy,posa.x,posa.y);
    var alp=0.32 * (0.6+0.4*Math.sin(dhT*0.05));
    grd2.addColorStop(0,'rgba(255,225,170,'+alp+')');
    grd2.addColorStop(1,'rgba(255,225,170,0)');
    dhCtx.strokeStyle=grd2;
    dhCtx.lineWidth=0.8;
    dhCtx.beginPath();
    dhCtx.moveTo(cx,cy);
    dhCtx.lineTo(posa.x,posa.y);
    dhCtx.stroke();
  }

  // ── Ripples ──
  for(var ri=dhRipples.length-1; ri>=0; ri--){
    var rp=dhRipples[ri]; rp.t++;
    if(rp.t>=rp.life){dhRipples.splice(ri,1); continue;}
    var rpp=rp.t/rp.life;
    var rrr=rp.r0+rpp*44;
    var ra=(1-rpp)*0.7;
    dhCtx.strokeStyle='rgba(255,225,170,'+ra+')';
    dhCtx.lineWidth=1.2;
    dhCtx.beginPath();
    dhCtx.arc(rp.x,rp.y,rrr,0,Math.PI*2);
    dhCtx.stroke();
  }

  dhFrame=requestAnimationFrame(dhLoop);
}

function dhDrawCentre(cx, cy, minD){
  // Big glowing aura
  var pulse=0.5+0.5*Math.sin(dhT*0.02);
  var aura=dhCtx.createRadialGradient(cx,cy,0,cx,cy,minD*0.18);
  aura.addColorStop(0,'rgba(255,225,170,'+(0.45+0.18*pulse)+')');
  aura.addColorStop(0.55,'rgba(255,200,140,'+(0.10+0.04*pulse)+')');
  aura.addColorStop(1,'rgba(0,0,0,0)');
  dhCtx.fillStyle=aura;
  dhCtx.beginPath();
  dhCtx.arc(cx,cy,minD*0.18,0,Math.PI*2);
  dhCtx.fill();

  // inner core
  var core=dhCtx.createRadialGradient(cx,cy,0,cx,cy,minD*0.05);
  core.addColorStop(0,'rgba(255,240,200,0.95)');
  core.addColorStop(1,'rgba(255,180,80,0)');
  dhCtx.fillStyle=core;
  dhCtx.beginPath();
  dhCtx.arc(cx,cy,minD*0.05,0,Math.PI*2);
  dhCtx.fill();

  // Devanagari "धर्म" (using canvas font)
  dhCtx.save();
  dhCtx.textAlign='center';
  dhCtx.textBaseline='middle';
  var fSize=Math.max(20, minD*0.075);
  dhCtx.font='500 '+fSize+'px "Noto Sans Devanagari", "Cinzel", serif';
  // shadow halo
  dhCtx.fillStyle='rgba(255,200,120,'+(0.12+0.06*pulse)+')';
  for(var k=0;k<3;k++){
    dhCtx.fillText('धर्म', cx, cy-fSize*0.04);
  }
  // main glyph
  dhCtx.fillStyle='rgba(255,235,195,'+(0.92+0.06*pulse)+')';
  dhCtx.fillText('धर्म', cx, cy-fSize*0.04);

  // English label
  dhCtx.font='500 '+(fSize*0.22)+'px "Cinzel", serif';
  dhCtx.fillStyle='rgba(255,230,200,0.62)';
  dhCtx.fillText('DHARMA', cx, cy+fSize*0.55);
  dhCtx.font='400 '+(fSize*0.13)+'px "IBM Plex Mono", monospace';
  dhCtx.fillStyle='rgba(255,220,180,0.30)';
  dhCtx.fillText('— THE FOUNDATION —', cx, cy+fSize*0.78);
  dhCtx.restore();
}

function dhDrawThing(idx, thing, minD){
  var pos=dhThingPosition(idx,1);
  var c=DHARM_CATEGORIES[dhCategory];
  var isSel=(idx===dhSelected);
  var isAuto=(dhAutoCycle && dhSelected===-1 && idx===dhAutoCycleI);
  // hover detection
  var hover=false;
  if(dhMouseX>=0){
    var dx=dhMouseX-pos.x, dy=dhMouseY-pos.y;
    var pickR=minD*0.05;
    hover = (dx*dx+dy*dy <= pickR*pickR);
  }
  var emph= isSel?1 : (isAuto?0.7 : (hover?0.5:0));
  var pulse=0.5+0.5*Math.sin(dhT*0.04 + idx*0.55);
  var orbR=minD*0.018 + emph*minD*0.014 + pulse*1.1;

  // glow
  var gR=orbR*4.5;
  var glow=dhCtx.createRadialGradient(pos.x,pos.y,0,pos.x,pos.y,gR);
  glow.addColorStop(0, c.cBright+(0.55+emph*0.4)+')');
  glow.addColorStop(0.4, c.col+(0.18+emph*0.25)+')');
  glow.addColorStop(1, c.col+'0)');
  dhCtx.fillStyle=glow;
  dhCtx.beginPath();
  dhCtx.arc(pos.x,pos.y,gR,0,Math.PI*2);
  dhCtx.fill();

  // core
  dhCtx.fillStyle=c.cBright+(0.85+emph*0.15)+')';
  dhCtx.beginPath();
  dhCtx.arc(pos.x,pos.y,orbR*0.55,0,Math.PI*2);
  dhCtx.fill();

  // label
  dhCtx.save();
  dhCtx.textAlign='center';
  dhCtx.textBaseline='middle';
  var labelDist=orbR*2.7+5;
  // place outside the circle (away from centre)
  var cx=dhW/2, cy=dhH*.52;
  var nx=pos.x-cx, ny=pos.y-cy;
  var nl=Math.sqrt(nx*nx+ny*ny)||1;
  nx/=nl; ny/=nl;
  var lx=pos.x+nx*labelDist;
  var ly=pos.y+ny*labelDist;
  var fSize=Math.max(8.5, minD*0.014) + emph*1.4;
  dhCtx.font='500 '+fSize+'px "Cinzel", serif';
  dhCtx.fillStyle='rgba(255,235,200,'+(0.55+emph*0.4)+')';
  dhCtx.fillText(thing.n, lx, ly);
  dhCtx.font='400 '+(fSize*0.78)+'px "Noto Sans Devanagari", serif';
  dhCtx.fillStyle='rgba(255,220,180,'+(0.32+emph*0.4)+')';
  dhCtx.fillText(thing.skt, lx, ly+fSize*0.95);
  dhCtx.restore();
}

// ═══════════════════════════════════════════════════════════════════════════
// TABS
// ═══════════════════════════════════════════════════════════════════════════
window.dhTab=function(which, btn){
  document.querySelectorAll('#dharm-exp .era-exp-tab').forEach(function(t){t.classList.remove('active');});
  if(btn) btn.classList.add('active');
  var ov=$dh('dharm-exp');
  var c=$dh('dharm-content');
  if(!c) return;
  if(which==='experience'){
    c.classList.remove('open');
    if(ov) ov.classList.remove('content-active');
    return;
  }
  c.classList.add('open');
  if(ov) ov.classList.add('content-active');
  var t=$dh('dharm-ct'), b=$dh('dharm-cb');
  if(!t||!b) return;
  var content=DHARM_TAB_CONTENT[which];
  if(!content) return;
  t.textContent=content.title;
  b.innerHTML=content.body;
  // scroll to top of content
  if(c) c.scrollTop=0;
};
window.dhCloseContent=function(){
  var c=$dh('dharm-content'); if(c) c.classList.remove('open');
  var ov=$dh('dharm-exp'); if(ov) ov.classList.remove('content-active');
  document.querySelectorAll('#dharm-exp .era-exp-tab').forEach(function(t){t.classList.remove('active');});
  var first=document.querySelector('#dharm-exp .era-exp-tab');
  if(first) first.classList.add('active');
};

