document.addEventListener('keydown',function(e){
  if(e.key!=='Escape') return;
  var ov=$dh('dharm-exp');
  if(ov && ov.classList.contains('on')){
    var content=$dh('dharm-content');
    if(content && content.classList.contains('open')){
      window.dhCloseContent();
      return;
    }
    window.closeDharm();
  }
});

