// ═══════════════════════════════════════════════════════════════════════════
// DARSHAN PANEL LOGIC
// ═══════════════════════════════════════════════════════════════════════════

window.dvOpenDarshan = function(chapter){
  var panel = $dv('dv-darshan');
  if(!panel) return;
  dvDarshanOpen = true;
  panel.classList.add('on');
  if(chapter) dvShowChapter(chapter);
  else dvShowChapter(dvCurrentChapter);
};

window.dvCloseDarshan = function(){
  var panel = $dv('dv-darshan');
  if(panel) panel.classList.remove('on');
  dvDarshanOpen = false;
  dvMode = 'cosmos';
};

window.dvShowChapter = function(key){
  dvCurrentChapter = key;
  document.querySelectorAll('#dv-chapter-pills .dv-chap-pill').forEach(function(p){
    p.classList.toggle('active', p.getAttribute('data-chap') === key);
  });
  var titleEl = $dv('dv-darshan-title');
  var bodyEl = $dv('dv-darshan-body');
  if(!titleEl || !bodyEl) return;

  if(key === 'battles'){
    titleEl.textContent = 'The 20 Greatest Battles';
    dvShowBattleList();
    return;
  }
  var chap = DV_CHAPTERS[key];
  if(!chap) return;
  titleEl.textContent = chap.title;
  bodyEl.innerHTML = chap.body;
  bodyEl.scrollTop = 0;
};

window.dvShowBattleList = function(){
  var bodyEl = $dv('dv-darshan-body');
  if(!bodyEl) return;
  // Switch canvas back to cosmos
  dvMode = 'cosmos';

  var html = '<p style="font-family:\'Cormorant Garamond\',serif;font-size:15px;line-height:1.7;color:rgba(220,200,160,.75);font-style:italic;margin-bottom:18px;">Tap any battle to see its story, hidden meaning, and watch the animated canvas.</p>';
  html += '<div style="display:grid;grid-template-columns:1fr;gap:8px;" id="dv-battle-list">';
  for(var i=0; i<DV_BATTLES.length; i++){
    var b = DV_BATTLES[i];
    var sideColor = b.side==='devas' ? 'rgba(160,200,255,.7)' :
                    b.side==='asuraSide' ? 'rgba(255,160,100,.7)' :
                    b.side==='collab' ? 'rgba(200,220,180,.7)' :
                    b.side==='devi' ? 'rgba(255,160,200,.7)' :
                    b.side==='shiva' ? 'rgba(200,180,255,.7)' :
                    b.side==='mixed' ? 'rgba(220,200,160,.7)' :
                    'rgba(255,220,160,.7)';
    html += '<button class="dv-battle-item" data-id="'+b.id+'" onclick="dvSelectBattle(\''+b.id+'\')" style="text-align:left;padding:12px 15px;background:rgba(20,15,35,.65);border:1px solid rgba(255,210,150,.15);border-left:3px solid '+sideColor+';border-radius:3px;cursor:pointer;transition:all .25s ease;touch-action:manipulation;-webkit-tap-highlight-color:transparent;">';
    html += '<div style="display:flex;align-items:baseline;gap:10px;margin-bottom:4px;">';
    html += '<span style="font-family:\'Cinzel\',serif;font-size:10px;letter-spacing:1.5px;color:rgba(220,200,160,.6);">'+String(b.n).padStart(2,'0')+'</span>';
    html += '<span style="font-family:\'Cinzel\',serif;font-size:13.5px;letter-spacing:1.5px;color:rgba(255,235,200,.95);">'+b.name+'</span>';
    html += '<span style="font-family:\'Noto Sans Devanagari\',serif;font-size:12px;color:rgba(255,200,140,.65);">'+b.skt+'</span>';
    html += '</div>';
    html += '<div style="font-family:\'Cormorant Garamond\',serif;font-size:13.5px;line-height:1.55;color:rgba(220,210,190,.75);font-style:italic;">'+b.short+'</div>';
    html += '</button>';
  }
  html += '</div>';
  bodyEl.innerHTML = html;
  bodyEl.scrollTop = 0;
};

// ═══════════════════════════════════════════════════════════════════════════
// INIT / OPEN / CLOSE
// ═══════════════════════════════════════════════════════════════════════════
function dvInit(){
  dvCanvas = $dv('dv-canvas');
  if(!dvCanvas) return;
  dvCtx = dvCanvas.getContext('2d');
  dvResize();
  dvSeedParticles();
  dvStartT = performance.now();
  dvLastT = 0;

  if(!dvInitialized){
    dvCanvas.addEventListener('click', dvCanvasTap);
    dvCanvas.addEventListener('touchend', dvCanvasTap);
    window.addEventListener('resize', dvResizeGuarded);
    dvInitialized = true;
  }
  if(dvRAF) cancelAnimationFrame(dvRAF);
  dvLoop();
}

window.openDevAsura = function(){
  var ov = $dv('devasura-exp');
  if(!ov) return;
  ov.classList.add('on');
  setTimeout(dvInit, 300);
};

window.closeDevAsura = function(){
  var ov = $dv('devasura-exp');
  if(!ov) return;
  ov.classList.remove('on');
  if(dvRAF){ cancelAnimationFrame(dvRAF); dvRAF = null; }
  dvDarshanOpen = false;
  dvMode = 'cosmos';
  var panel = $dv('dv-darshan');
  if(panel) panel.classList.remove('on');
};

// ESC key handler
document.addEventListener('keydown', function(e){
  if(e.key !== 'Escape') return;
  var ov = $dv('devasura-exp');
  if(!ov || !ov.classList.contains('on')) return;
  if(dvDarshanOpen){ window.dvCloseDarshan(); return; }
  if(dvMode !== 'cosmos'){ dvMode = 'cosmos'; return; }
  window.closeDevAsura();
});

