document.addEventListener('keydown',function(e){
  if(e.key!=='Escape')return;
  var ov=$vd('vidya-exp');
  if(ov && ov.classList.contains('on')){
    var panel=$vd('vd-darshan');
    if(panel && panel.classList.contains('on')){
      window.vdCloseDarshan();
      return;
    }
    var sr=$vd('vd-search-results');
    if(sr && sr.classList.contains('on')){
      window.vdSearchClear();
      return;
    }
    window.closeVidya();
  }
});

