// ══════════════════════════════════════════════════════════════════════════
// OPEN / CLOSE / INIT
// ══════════════════════════════════════════════════════════════════════════

window.openVishvarupa=function(){
  var ov=$vp('vp-exp'); if(!ov) return;
  ov.classList.add('on');
  vpAct=0; vpActT=0; vpT=0; vpFadeIn=0;
  vpFormScale=0; vpFormTargetScale=0;
  vpHeadCount=1; vpArmCount=2;
  vpTimeMouthOpen=0; vpEyeBlaze=0;
  vpCameraY=0; vpCameraTargetY=0;
  vpShockwaveT=-99; vpKaloFlash=0;
  vpDarshanOpen=false;
  var panel=$vp('vp-darshan'); if(panel) panel.classList.remove('on');
  setTimeout(vpInit,300);
};

window.closeVishvarupa=function(){
  var ov=$vp('vp-exp'); if(!ov) return;
  ov.classList.remove('on');
  if(vpFrame){cancelAnimationFrame(vpFrame); vpFrame=null;}
  window.removeEventListener('resize',vpResizeGuarded);
  var panel=$vp('vp-darshan'); if(panel) panel.classList.remove('on');
  vpDarshanOpen=false;
};

function vpInit(){
  vpCanvas=$vp('vp-canvas'); if(!vpCanvas) return;
  vpCtx=vpCanvas.getContext('2d');
  vpResize();
  window.addEventListener('resize',vpResizeGuarded);
  vpSeedDust();
  vpSeedStars();
  vpSeedArmies();
  vpSeedBeings();
  vpSeedFireSparks();
  vpRenderStageStrip();
  vpRenderAct(0, true);
  vpShowChapter('overview');
  if(vpFrame) cancelAnimationFrame(vpFrame);
  vpLoop();
}

function vpResize(){
  if(!vpCanvas) return;
  var rect=vpCanvas.getBoundingClientRect();
  if(rect.width<=0||rect.height<=0){
    setTimeout(vpResize,200); return;
  }
  vpW=rect.width; vpH=rect.height;
  vpDpr=Math.min(window.devicePixelRatio||1, 2);
  vpCanvas.width=Math.floor(vpW*vpDpr);
  vpCanvas.height=Math.floor(vpH*vpDpr);
  vpCanvas.style.width=vpW+'px';
  vpCanvas.style.height=vpH+'px';
  vpCtx.setTransform(vpDpr,0,0,vpDpr,0,0);
}

// ── SEEDS ─────────────────────────────────────────────────────────────────
function vpSeedDust(){
  vpDust=[];
  var count=Math.max(20, Math.floor((vpW*vpH)/24000));
  for(var i=0;i<count;i++){
    vpDust.push({
      x:Math.random(),
      y:Math.random(),
      r:30+Math.random()*60,
      a:0.025+Math.random()*0.045,
      vx:(Math.random()-0.5)*0.0005,
      vy:-(0.0001+Math.random()*0.0006),
      phase:Math.random()*Math.PI*2
    });
  }
}
function vpSeedStars(){
  vpStars=[];
  var c1=Math.max(80, Math.floor((vpW*vpH)/12000));
  for(var i=0;i<c1;i++){
    vpStars.push({
      x:Math.random(),
      y:Math.random()*0.7,
      s:Math.random()*1.4+0.3,
      p:Math.random()*Math.PI*2,
      sp:0.005+Math.random()*0.022,
      layer:i%3
    });
  }
}
function vpSeedArmies(){
  vpLeftArmy=[]; vpRightArmy=[];
  for(var i=0;i<160;i++){
    vpLeftArmy.push({
      x:0.04+Math.random()*0.38, y:0.62+Math.random()*0.30,
      r:Math.random()*1.4+0.6,
      a:Math.random()*0.6+0.3,
      phase:Math.random()*Math.PI*2
    });
    vpRightArmy.push({
      x:0.58+Math.random()*0.38, y:0.62+Math.random()*0.30,
      r:Math.random()*1.4+0.6,
      a:Math.random()*0.6+0.3,
      phase:Math.random()*Math.PI*2
    });
  }
}
function vpSeedBeings(){
  vpBeingsIn=[];
  for(var i=0;i<40;i++){
    vpBeingsIn.push({
      ang:Math.random()*Math.PI*2,
      r:0.55+Math.random()*0.5,
      sp:0.0035+Math.random()*0.005,
      size:1+Math.random()*1.6,
      kind:Math.floor(Math.random()*4), // 0 king 1 warrior 2 priest 3 sage
      hue:[
        200+Math.floor(Math.random()*55),
        140+Math.floor(Math.random()*80),
        80+Math.floor(Math.random()*100)
      ]
    });
  }
}
function vpSeedFireSparks(){
  vpFireSparks=[];
  for(var i=0;i<60;i++){
    vpFireSparks.push({
      ang:Math.random()*Math.PI*2,
      r:Math.random()*0.4,
      sp:0.003+Math.random()*0.006,
      size:Math.random()*1.4+0.5,
      life:Math.random()*240
    });
  }
}

// ── INPUT ─────────────────────────────────────────────────────────────────
function vpAttachInput(){
  if(!vpCanvas) return;
}

// ── ADVANCE / REWIND ──────────────────────────────────────────────────────
window.vpAdvance=function(){
  if(vpAct >= VP_ACTS.length-1){
    // wrap-around to first act
    vpRenderAct(0, false);
    return;
  }
  vpRenderAct(vpAct+1, false);
};
window.vpRewind=function(){
  if(vpAct<=0) return;
  vpRenderAct(vpAct-1, false);
};
window.vpJumpToAct=function(n){
  if(n<0||n>=VP_ACTS.length) return;
  vpRenderAct(n, false);
};

function vpRenderAct(n, isInit){
  vpAct=n; vpActT=0;
  // act-specific camera & form targets
  switch(n){
    case 0: vpFormTargetScale=0;   vpHeadCount=1; vpArmCount=2; vpCameraTargetY=0;    vpTimeMouthOpen=0; vpEyeBlaze=0; break;
    case 1: vpFormTargetScale=0;   vpHeadCount=1; vpArmCount=2; vpCameraTargetY=-30;  vpTimeMouthOpen=0; vpEyeBlaze=0; break;
    case 2: vpFormTargetScale=0.05;vpHeadCount=1; vpArmCount=2; vpCameraTargetY=-20;  vpTimeMouthOpen=0; vpEyeBlaze=0.05; break;
    case 3: vpFormTargetScale=0.2; vpHeadCount=1; vpArmCount=2; vpCameraTargetY=-10;  vpTimeMouthOpen=0; vpEyeBlaze=0.2; break;
    case 4: vpFormTargetScale=0.5; vpHeadCount=3; vpArmCount=4; vpCameraTargetY=0;    vpTimeMouthOpen=0; vpEyeBlaze=0.45; break;
    case 5: vpFormTargetScale=0.85;vpHeadCount=5; vpArmCount=8; vpCameraTargetY=0;    vpTimeMouthOpen=0; vpEyeBlaze=0.6; vpShockwaveT=0; break;
    case 6: vpFormTargetScale=1;   vpHeadCount=7; vpArmCount=10;vpCameraTargetY=0;    vpTimeMouthOpen=0.1; vpEyeBlaze=0.8; break;
    case 7: vpFormTargetScale=1;   vpHeadCount=9; vpArmCount=12;vpCameraTargetY=0;    vpTimeMouthOpen=0.6; vpEyeBlaze=1; vpShockwaveT=0; break;
    case 8: vpFormTargetScale=1;   vpHeadCount=11;vpArmCount=12;vpCameraTargetY=0;    vpTimeMouthOpen=1; vpEyeBlaze=1; break;
    case 9: vpFormTargetScale=1;   vpHeadCount=11;vpArmCount=12;vpCameraTargetY=0;    vpTimeMouthOpen=1; vpEyeBlaze=1; vpKaloFlash=1; break;
    case 10:vpFormTargetScale=0.35;vpHeadCount=1; vpArmCount=4; vpCameraTargetY=10;   vpTimeMouthOpen=0; vpEyeBlaze=0.3; break;
  }
  // update visible UI
  vpUpdateStageStrip(n);
  vpUpdateNarrative(VP_ACTS[n]);
  vpUpdateVerse(VP_ACTS[n]);
  if(vpDarshanOpen){
    // if darshan is in 'act' mode, refresh
    var pill=document.querySelector('#vp-darshan .vp-chap-pill.active');
    if(pill && pill.getAttribute('data-chap')==='current-act'){
      vpShowChapter('current-act');
    }
  }
}

function vpRenderStageStrip(){
  var strip=$vp('vp-stages-inner');
  if(!strip) return;
  var html='';
  for(var i=0;i<VP_ACTS.length;i++){
    var label=(i===0?'i':i===1?'ii':i===2?'iii':i===3?'iv':i===4?'v':i===5?'vi':i===6?'vii':i===7?'viii':i===8?'ix':i===9?'x':'xi');
    html+='<button class="vp-stage-dot'+(i===0?' current':'')+'" data-act="'+i+'" '+
          'onclick="vpJumpToAct('+i+')" title="'+VP_ACTS[i].title.replace(/"/g,'&quot;')+'">'+
          '<span class="vp-stage-num">'+label+'</span>'+
          '</button>';
  }
  strip.innerHTML=html;
}

function vpUpdateStageStrip(n){
  var dots=document.querySelectorAll('#vp-stages-inner .vp-stage-dot');
  for(var i=0;i<dots.length;i++){
    dots[i].classList.remove('current','done');
    if(i<n) dots[i].classList.add('done');
    else if(i===n) dots[i].classList.add('current');
  }
  var label=$vp('vp-stage-label');
  if(label) label.textContent=VP_ACTS[n].title;
}

function vpUpdateNarrative(act){
  var el=$vp('vp-narrative');
  if(!el) return;
  el.classList.remove('visible');
  // build inner with eyebrow + text
  setTimeout(function(){
    el.innerHTML=
      '<div class="vp-narr-eyebrow">'+act.eyebrow+'</div>'+
      '<div class="vp-narr-text">'+act.narrative+'</div>';
    el.classList.add('visible');
  }, 220);
}
function vpUpdateVerse(act){
  var el=$vp('vp-verse');
  if(!el) return;
  el.classList.remove('visible');
  setTimeout(function(){
    el.innerHTML=
      '<div class="vp-verse-sa">'+act.verseSa+'</div>'+
      '<div class="vp-verse-iast"><em>'+act.verseIast+'</em></div>'+
      '<div class="vp-verse-tr">'+act.verseTr+'</div>'+
      '<div class="vp-verse-src">'+act.verseSrc+'</div>';
    el.classList.add('visible');
  }, 360);
}


// ══════════════════════════════════════════════════════════════════════════
// MAIN LOOP + DRAW
// ══════════════════════════════════════════════════════════════════════════

function vpLoop(){
  if(!vpCtx||!vpCanvas){vpFrame=null; return;}
  vpT++;
  vpActT++;
  vpFadeIn=Math.min(1, vpFadeIn+0.012);
  // smooth scale lerp
  vpFormScale += (vpFormTargetScale - vpFormScale)*0.04;
  vpCameraY += (vpCameraTargetY - vpCameraY)*0.04;

  vpDrawBackground();
  vpDrawStars();
  vpDrawDust();
  vpDrawArmies();      // armies frozen below — visible always
  if(vpFormScale > 0.01) vpDrawCosmicForm();
  vpDrawArjuna();
  if(vpAct >= 8) vpDrawTimeMouthBeings();
  vpDrawKaloFlash();
  vpFrame=requestAnimationFrame(vpLoop);
}

// ── BACKGROUND ────────────────────────────────────────────────────────────
function vpDrawBackground(){
  var ctx=vpCtx;
  // base gradient — deep cosmic indigo with warm cosmic glow at center
  var g=ctx.createLinearGradient(0,0,0,vpH);
  g.addColorStop(0,'rgb(4,3,12)');
  g.addColorStop(0.45,'rgb(14,8,28)');
  g.addColorStop(0.75,'rgb(18,10,18)');
  g.addColorStop(1,'rgb(6,4,8)');
  ctx.fillStyle=g; ctx.fillRect(0,0,vpW,vpH);
  // central glow that intensifies as form opens
  var gx=vpW/2, gy=vpH*0.45+vpCameraY;
  var gr=Math.max(vpW,vpH)*0.7;
  var glow=ctx.createRadialGradient(gx,gy,0,gx,gy,gr);
  var pulse=0.18+vpFormScale*0.35;
  glow.addColorStop(0,'rgba(255,210,120,'+(pulse*0.5)+')');
  glow.addColorStop(0.25,'rgba(220,150,80,'+(pulse*0.35)+')');
  glow.addColorStop(0.6,'rgba(120,80,180,'+(pulse*0.18)+')');
  glow.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=glow; ctx.fillRect(0,0,vpW,vpH);
}

// ── STARS ─────────────────────────────────────────────────────────────────
function vpDrawStars(){
  var ctx=vpCtx;
  ctx.save();
  for(var i=0;i<vpStars.length;i++){
    var s=vpStars[i];
    var tw=0.4+0.6*Math.abs(Math.sin(vpT*s.sp + s.p));
    var x=s.x*vpW, y=s.y*vpH;
    var alpha=(s.layer===0?0.32:s.layer===1?0.5:0.78)*tw;
    ctx.fillStyle='rgba(245,235,255,'+alpha+')';
    ctx.beginPath(); ctx.arc(x, y, s.s, 0, Math.PI*2); ctx.fill();
    if(s.s>1.0){
      ctx.fillStyle='rgba(255,230,200,'+(alpha*0.32)+')';
      ctx.beginPath(); ctx.arc(x, y, s.s*2.4, 0, Math.PI*2); ctx.fill();
    }
  }
  ctx.restore();
}

// ── DUST / NEBULAE ───────────────────────────────────────────────────────
function vpDrawDust(){
  var ctx=vpCtx;
  ctx.save();
  ctx.globalCompositeOperation='lighter';
  for(var i=0;i<vpDust.length;i++){
    var d=vpDust[i];
    d.x+=d.vx; d.y+=d.vy;
    if(d.y<-0.1) d.y=1.1;
    if(d.x<-0.1) d.x=1.1; if(d.x>1.1) d.x=-0.1;
    var x=d.x*vpW, y=d.y*vpH;
    var grad=ctx.createRadialGradient(x,y,0,x,y,d.r);
    grad.addColorStop(0,'rgba(180,120,220,'+(d.a*1.2)+')');
    grad.addColorStop(0.5,'rgba(255,180,120,'+(d.a*0.6)+')');
    grad.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=grad;
    ctx.fillRect(x-d.r, y-d.r, d.r*2, d.r*2);
  }
  ctx.restore();
}

// ── ARMIES ────────────────────────────────────────────────────────────────
function vpDrawArmies(){
  var ctx=vpCtx;
  // Soft horizon line under armies (kurukṣetra field)
  var horizonY=vpH*0.92;
  ctx.fillStyle='rgba(10,8,20,0.85)';
  ctx.fillRect(0, horizonY, vpW, vpH-horizonY);
  // Field gradient leading up
  var fg=ctx.createLinearGradient(0, vpH*0.78, 0, vpH);
  fg.addColorStop(0,'rgba(0,0,0,0)');
  fg.addColorStop(1,'rgba(40,20,10,0.65)');
  ctx.fillStyle=fg; ctx.fillRect(0, vpH*0.78, vpW, vpH-vpH*0.78);
  // Chariot trail mid-field — between armies (only visible early acts and act 11)
  if(vpAct<=2 || vpAct===10){
    var cx=vpW*0.5, cy=vpH*0.83;
    // wheel tracks
    ctx.strokeStyle='rgba(255,200,140,0.18)';
    ctx.lineWidth=1;
    ctx.beginPath();
    ctx.moveTo(cx-8, cy+8); ctx.lineTo(cx-8, cy-12);
    ctx.moveTo(cx+8, cy+8); ctx.lineTo(cx+8, cy-12);
    ctx.stroke();
  }
  // Left army (Pāṇḍava — cool indigo-gold)
  ctx.save();
  for(var i=0;i<vpLeftArmy.length;i++){
    var s=vpLeftArmy[i];
    var x=s.x*vpW, y=s.y*vpH;
    var tw=0.5+0.5*Math.sin(vpT*0.025 + s.phase);
    ctx.fillStyle='rgba(200,180,240,'+(s.a*tw*0.7)+')';
    ctx.beginPath(); ctx.arc(x,y, s.r, 0, Math.PI*2); ctx.fill();
  }
  // Right army (Kaurava — warm crimson-gold)
  for(var j=0;j<vpRightArmy.length;j++){
    var s2=vpRightArmy[j];
    var x2=s2.x*vpW, y2=s2.y*vpH;
    var tw2=0.5+0.5*Math.sin(vpT*0.025 + s2.phase);
    ctx.fillStyle='rgba(255,170,130,'+(s2.a*tw2*0.75)+')';
    ctx.beginPath(); ctx.arc(x2,y2, s2.r, 0, Math.PI*2); ctx.fill();
  }
  // Banners
  if(vpAct===0 || vpAct===10){
    ctx.font='400 9px "Cinzel", serif';
    ctx.fillStyle='rgba(220,200,240,0.65)';
    ctx.textAlign='center';
    ctx.fillText('PĀṆḌAVA · 7 akṣauhiṇīs', vpW*0.22, vpH*0.78);
    ctx.fillStyle='rgba(255,180,140,0.65)';
    ctx.fillText('KAURAVA · 11 akṣauhiṇīs', vpW*0.78, vpH*0.78);
    ctx.textAlign='start';
  }
  ctx.restore();
}

// ══════════════════════════════════════════════════════════════════════════
// COSMIC FORM — the centerpiece
// ══════════════════════════════════════════════════════════════════════════
function vpDrawCosmicForm(){
  var ctx=vpCtx;
  var cx=vpW*0.5;
  var cy=vpH*0.42 + vpCameraY;
  var scale=vpFormScale;
  // Overall body radius
  var R=Math.min(vpW,vpH)*0.27*scale;
  if(R<2) return;

  ctx.save();

  // ─ OUTER COSMIC HALO ─────────────────────────────────────
  var haloR=Math.max(vpW,vpH)*0.95*scale;
  var halo=ctx.createRadialGradient(cx,cy,0,cx,cy,haloR);
  halo.addColorStop(0,'rgba(255,230,140,'+(0.55*scale)+')');
  halo.addColorStop(0.18,'rgba(255,180,80,'+(0.32*scale)+')');
  halo.addColorStop(0.42,'rgba(180,90,200,'+(0.22*scale)+')');
  halo.addColorStop(0.7,'rgba(60,40,120,'+(0.14*scale)+')');
  halo.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=halo;
  ctx.fillRect(0,0,vpW,vpH);

  // ─ ROTATING RING OF FIRE ─────────────────────────────────
  if(scale>0.5){
    var ringR=R*1.55;
    var ringRot=vpT*0.004;
    for(var rf=0;rf<60;rf++){
      var a=(rf/60)*Math.PI*2 + ringRot;
      var px=cx+Math.cos(a)*ringR;
      var py=cy+Math.sin(a)*ringR;
      var sz=2+Math.sin(vpT*0.05+rf)*1.2;
      var rg=ctx.createRadialGradient(px,py,0,px,py,sz*8);
      rg.addColorStop(0,'rgba(255,230,150,'+(0.85*scale)+')');
      rg.addColorStop(0.4,'rgba(255,140,60,'+(0.45*scale)+')');
      rg.addColorStop(1,'rgba(255,80,40,0)');
      ctx.fillStyle=rg;
      ctx.fillRect(px-sz*8,py-sz*8,sz*16,sz*16);
    }
  }

  // ─ FIRE SPARKS streaming inward ──────────────────────────
  if(vpAct>=6 && scale>0.5){
    ctx.save();
    ctx.globalCompositeOperation='lighter';
    for(var sp=0;sp<vpFireSparks.length;sp++){
      var spk=vpFireSparks[sp];
      spk.life-=1;
      if(spk.life<=0){
        spk.ang=Math.random()*Math.PI*2;
        spk.r=0.6+Math.random()*0.4;
        spk.life=80+Math.random()*200;
      }
      spk.r -= spk.sp;
      if(spk.r<0.05) spk.r=0.6+Math.random()*0.4;
      var radius=spk.r*Math.max(vpW,vpH)*0.5;
      var sx=cx+Math.cos(spk.ang)*radius;
      var sy=cy+Math.sin(spk.ang)*radius*0.85;
      var lifeR=spk.life/240;
      var pg=ctx.createRadialGradient(sx,sy,0,sx,sy,spk.size*6);
      pg.addColorStop(0,'rgba(255,210,130,'+(0.9*lifeR)+')');
      pg.addColorStop(0.5,'rgba(255,120,60,'+(0.4*lifeR)+')');
      pg.addColorStop(1,'rgba(0,0,0,0)');
      ctx.fillStyle=pg;
      ctx.fillRect(sx-spk.size*6, sy-spk.size*6, spk.size*12, spk.size*12);
    }
    ctx.restore();
  }

  // ─ BODY ──────────────────────────────────────────────────
  var bodyG=ctx.createRadialGradient(cx, cy-R*0.18, 0, cx, cy+R*0.3, R*1.4);
  bodyG.addColorStop(0,'rgba(255,255,230,0.92)');
  bodyG.addColorStop(0.16,'rgba(255,220,150,0.85)');
  bodyG.addColorStop(0.5,'rgba(180,120,200,0.55)');
  bodyG.addColorStop(0.85,'rgba(60,40,120,0.3)');
  bodyG.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=bodyG;
  ctx.beginPath();
  ctx.ellipse(cx, cy+R*0.4, R*0.78, R*1.3, 0, 0, Math.PI*2);
  ctx.fill();

  // ─ MULTIPLE ARMS ─────────────────────────────────────────
  ctx.save();
  ctx.translate(cx, cy-R*0.05);
  var arms=vpArmCount;
  for(var a=0;a<arms;a++){
    var armA=(a/arms)*Math.PI*2 - Math.PI/2 + Math.sin(vpT*0.012+a)*0.04;
    var armLen=R*1.05;
    var ax=Math.cos(armA)*armLen;
    var ay=Math.sin(armA)*armLen*0.88;
    // arm line
    ctx.strokeStyle='rgba(255,220,160,'+(0.78*scale)+')';
    ctx.lineWidth=3.5;
    ctx.lineCap='round';
    ctx.beginPath();
    ctx.moveTo(0, R*0.25);
    ctx.quadraticCurveTo(ax*0.45, ay*0.55-R*0.05, ax, ay);
    ctx.stroke();
    // hand glow
    var wg=ctx.createRadialGradient(ax,ay,0,ax,ay,16);
    wg.addColorStop(0,'rgba(255,240,180,'+(0.95*scale)+')');
    wg.addColorStop(0.5,'rgba(255,180,100,'+(0.5*scale)+')');
    wg.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=wg;
    ctx.fillRect(ax-16,ay-16,32,32);
    // weapon glyph (only if arms >= 4)
    if(arms>=4) vpDrawWeaponGlyph(ctx, ax, ay, a, armA);
  }
  ctx.restore();

  // ─ HEADS ─────────────────────────────────────────────────
  var heads=vpHeadCount;
  if(heads===1){
    vpDrawHead(cx, cy-R*0.55, R*0.24, 0, 1.0, true, scale, false);
  } else if(heads===3){
    vpDrawHead(cx, cy-R*0.58, R*0.22, 0, 1.0, true, scale, false);
    vpDrawHead(cx-R*0.36, cy-R*0.42, R*0.18, -0.22, 0.85, true, scale, false);
    vpDrawHead(cx+R*0.36, cy-R*0.42, R*0.18, 0.22, 0.85, true, scale, false);
  } else if(heads===5){
    vpDrawHead(cx, cy-R*0.6, R*0.22, 0, 1.0, true, scale, false);
    vpDrawHead(cx-R*0.32, cy-R*0.45, R*0.18, -0.18, 0.9, true, scale, false);
    vpDrawHead(cx+R*0.32, cy-R*0.45, R*0.18, 0.18, 0.9, true, scale, false);
    vpDrawHead(cx-R*0.58, cy-R*0.24, R*0.14, -0.36, 0.72, false, scale, false);
    vpDrawHead(cx+R*0.58, cy-R*0.24, R*0.14, 0.36, 0.72, false, scale, false);
  } else if(heads===7){
    vpDrawHead(cx, cy-R*0.6, R*0.22, 0, 1.0, true, scale, false);
    vpDrawHead(cx-R*0.3, cy-R*0.48, R*0.17, -0.18, 0.9, true, scale, false);
    vpDrawHead(cx+R*0.3, cy-R*0.48, R*0.17, 0.18, 0.9, true, scale, false);
    vpDrawHead(cx-R*0.55, cy-R*0.30, R*0.14, -0.32, 0.78, false, scale, false);
    vpDrawHead(cx+R*0.55, cy-R*0.30, R*0.14, 0.32, 0.78, false, scale, false);
    vpDrawHead(cx-R*0.72, cy-R*0.08, R*0.11, -0.46, 0.65, false, scale, vpAct>=7);
    vpDrawHead(cx+R*0.72, cy-R*0.08, R*0.11, 0.46, 0.65, false, scale, vpAct>=7);
  } else if(heads===9){
    vpDrawHead(cx, cy-R*0.62, R*0.22, 0, 1.0, true, scale, vpAct>=7);
    vpDrawHead(cx-R*0.28, cy-R*0.5, R*0.17, -0.18, 0.92, true, scale, vpAct>=7);
    vpDrawHead(cx+R*0.28, cy-R*0.5, R*0.17, 0.18, 0.92, true, scale, vpAct>=7);
    vpDrawHead(cx-R*0.52, cy-R*0.34, R*0.14, -0.30, 0.82, false, scale, vpAct>=7);
    vpDrawHead(cx+R*0.52, cy-R*0.34, R*0.14, 0.30, 0.82, false, scale, vpAct>=7);
    vpDrawHead(cx-R*0.72, cy-R*0.14, R*0.12, -0.46, 0.7, false, scale, vpAct>=7);
    vpDrawHead(cx+R*0.72, cy-R*0.14, R*0.12, 0.46, 0.7, false, scale, vpAct>=7);
    vpDrawHead(cx-R*0.86, cy+R*0.10, R*0.10, -0.6, 0.58, false, scale, vpAct>=7);
    vpDrawHead(cx+R*0.86, cy+R*0.10, R*0.10, 0.6, 0.58, false, scale, vpAct>=7);
  } else { // 11
    vpDrawHead(cx, cy-R*0.64, R*0.22, 0, 1.0, true, scale, true);
    vpDrawHead(cx-R*0.26, cy-R*0.52, R*0.17, -0.16, 0.92, true, scale, true);
    vpDrawHead(cx+R*0.26, cy-R*0.52, R*0.17, 0.16, 0.92, true, scale, true);
    vpDrawHead(cx-R*0.48, cy-R*0.38, R*0.14, -0.28, 0.84, false, scale, true);
    vpDrawHead(cx+R*0.48, cy-R*0.38, R*0.14, 0.28, 0.84, false, scale, true);
    vpDrawHead(cx-R*0.68, cy-R*0.20, R*0.12, -0.42, 0.74, false, scale, true);
    vpDrawHead(cx+R*0.68, cy-R*0.20, R*0.12, 0.42, 0.74, false, scale, true);
    vpDrawHead(cx-R*0.84, cy+R*0.02, R*0.105, -0.56, 0.65, false, scale, true);
    vpDrawHead(cx+R*0.84, cy+R*0.02, R*0.105, 0.56, 0.65, false, scale, true);
    vpDrawHead(cx-R*0.95, cy+R*0.25, R*0.09, -0.7, 0.55, false, scale, true);
    vpDrawHead(cx+R*0.95, cy+R*0.25, R*0.09, 0.7, 0.55, false, scale, true);
  }

  // ─ AUREOLE BEHIND CENTRAL HEAD ──────────────────────────
  if(scale>0.3){
    var aurR=R*0.55;
    var aur=ctx.createRadialGradient(cx, cy-R*0.6, 0, cx, cy-R*0.6, aurR);
    aur.addColorStop(0,'rgba(255,250,200,0)');
    aur.addColorStop(0.5,'rgba(255,230,140,'+(0.25*scale)+')');
    aur.addColorStop(0.8,'rgba(255,180,80,'+(0.4*scale)+')');
    aur.addColorStop(1,'rgba(255,140,60,0)');
    ctx.fillStyle=aur;
    ctx.beginPath(); ctx.arc(cx, cy-R*0.6, aurR, 0, Math.PI*2); ctx.fill();
  }

  // ─ "SUN AND MOON IN THE EYES" — only when form is fully open ─
  if(vpAct>=5 && scale>0.7){
    var sunX=cx-R*0.06, sunY=cy-R*0.65;
    var moonX=cx+R*0.06, moonY=cy-R*0.65;
    var sg=ctx.createRadialGradient(sunX,sunY,0,sunX,sunY,R*0.04);
    sg.addColorStop(0,'rgba(255,255,210,1)');
    sg.addColorStop(1,'rgba(255,180,40,0)');
    ctx.fillStyle=sg;
    ctx.beginPath(); ctx.arc(sunX, sunY, R*0.04, 0, Math.PI*2); ctx.fill();
    var mg=ctx.createRadialGradient(moonX,moonY,0,moonX,moonY,R*0.04);
    mg.addColorStop(0,'rgba(220,230,255,1)');
    mg.addColorStop(1,'rgba(100,140,200,0)');
    ctx.fillStyle=mg;
    ctx.beginPath(); ctx.arc(moonX, moonY, R*0.04, 0, Math.PI*2); ctx.fill();
  }

  // ─ SHOCKWAVE on big reveals ──────────────────────────────
  if(vpShockwaveT>=0 && vpShockwaveT<120){
    var swPh=vpShockwaveT/120;
    var swR=R*(0.5+swPh*3.2);
    ctx.strokeStyle='rgba(255,220,140,'+(0.5*(1-swPh))+')';
    ctx.lineWidth=2.5*(1-swPh);
    ctx.beginPath();
    ctx.arc(cx, cy, swR, 0, Math.PI*2);
    ctx.stroke();
    vpShockwaveT++;
  } else if(vpShockwaveT>=120){
    vpShockwaveT=-99;
  }

  ctx.restore();
}

function vpDrawHead(x,y,r,tilt,bright,crown,scale,mouthOpen){
  var ctx=vpCtx;
  ctx.save();
  ctx.translate(x,y);
  ctx.rotate(tilt);
  // Aura
  var auraG=ctx.createRadialGradient(0,0,0,0,0,r*1.8);
  auraG.addColorStop(0,'rgba(255,230,150,'+(0.5*bright*scale)+')');
  auraG.addColorStop(0.5,'rgba(255,180,100,'+(0.25*bright*scale)+')');
  auraG.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=auraG;
  ctx.beginPath(); ctx.arc(0,0, r*1.8, 0, Math.PI*2); ctx.fill();
  // Face
  var faceG=ctx.createLinearGradient(0,-r,0,r);
  faceG.addColorStop(0,'rgba(255,230,180,'+(0.95*bright)+')');
  faceG.addColorStop(0.5,'rgba(255,200,140,'+(0.85*bright)+')');
  faceG.addColorStop(1,'rgba(180,120,120,'+(0.7*bright)+')');
  ctx.fillStyle=faceG;
  ctx.beginPath();
  ctx.ellipse(0, 0, r*0.85, r, 0, 0, Math.PI*2);
  ctx.fill();
  // Eyes — radiant
  var eyeBright=0.85+vpEyeBlaze*0.15;
  ctx.fillStyle='rgba(255,255,220,'+(eyeBright*bright)+')';
  ctx.beginPath(); ctx.arc(-r*0.32, -r*0.1, r*0.075, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc( r*0.32, -r*0.1, r*0.075, 0, Math.PI*2); ctx.fill();
  // Eye glow when blazing
  if(vpEyeBlaze>0.4){
    var egL=ctx.createRadialGradient(-r*0.32, -r*0.1, 0, -r*0.32, -r*0.1, r*0.22);
    egL.addColorStop(0,'rgba(255,240,180,'+(vpEyeBlaze*0.5)+')');
    egL.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=egL;
    ctx.fillRect(-r*0.55, -r*0.32, r*0.45, r*0.45);
    var egR=ctx.createRadialGradient(r*0.32, -r*0.1, 0, r*0.32, -r*0.1, r*0.22);
    egR.addColorStop(0,'rgba(255,240,180,'+(vpEyeBlaze*0.5)+')');
    egR.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=egR;
    ctx.fillRect(r*0.10, -r*0.32, r*0.45, r*0.45);
  }
  // Mouth
  if(mouthOpen || vpTimeMouthOpen>0.3){
    // open mouth — terrible, fire inside
    var mouthH=r*0.22*(0.5+vpTimeMouthOpen*0.6);
    ctx.fillStyle='rgba(40,8,8,0.95)';
    ctx.beginPath();
    ctx.ellipse(0, r*0.42, r*0.28, mouthH, 0, 0, Math.PI*2);
    ctx.fill();
    // Teeth — visible white
    ctx.fillStyle='rgba(255,250,230,0.92)';
    for(var t=0;t<6;t++){
      var tx=-r*0.20+t*r*0.08;
      ctx.beginPath();
      ctx.moveTo(tx, r*0.42-mouthH*0.3);
      ctx.lineTo(tx+r*0.03, r*0.42-mouthH*0.05);
      ctx.lineTo(tx+r*0.06, r*0.42-mouthH*0.3);
      ctx.closePath();
      ctx.fill();
    }
    // Fire inside mouth
    var fireG=ctx.createRadialGradient(0, r*0.42, 0, 0, r*0.42, r*0.30);
    fireG.addColorStop(0,'rgba(255,210,120,'+(0.85*vpTimeMouthOpen)+')');
    fireG.addColorStop(0.5,'rgba(255,120,60,'+(0.5*vpTimeMouthOpen)+')');
    fireG.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=fireG;
    ctx.fillRect(-r*0.30, r*0.42-mouthH, r*0.6, mouthH*2);
  } else {
    // gentle mouth — closed lip
    ctx.fillStyle='rgba(120,40,40,0.6)';
    ctx.beginPath();
    ctx.ellipse(0, r*0.42, r*0.18, r*0.05, 0, 0, Math.PI*2);
    ctx.fill();
  }
  // Crown
  if(crown){
    ctx.fillStyle='rgba(255,210,120,'+(0.92*bright)+')';
    ctx.beginPath();
    ctx.moveTo(-r*0.7, -r*0.85);
    ctx.lineTo(-r*0.42, -r*1.42);
    ctx.lineTo(-r*0.16, -r*0.85);
    ctx.lineTo(0, -r*1.55);
    ctx.lineTo(r*0.16, -r*0.85);
    ctx.lineTo(r*0.42, -r*1.42);
    ctx.lineTo(r*0.7, -r*0.85);
    ctx.closePath();
    ctx.fill();
    // jewel
    ctx.fillStyle='rgba(255,255,210,'+(0.95*bright)+')';
    ctx.beginPath(); ctx.arc(0, -r*1.15, r*0.08, 0, Math.PI*2); ctx.fill();
  }
  ctx.restore();
}

function vpDrawWeaponGlyph(ctx, ax, ay, idx, armA){
  ctx.save();
  ctx.translate(ax, ay);
  ctx.rotate(armA);
  ctx.strokeStyle='rgba(255,240,180,0.95)';
  ctx.lineWidth=1.5;
  ctx.fillStyle='rgba(255,220,140,0.85)';
  switch(idx % 8){
    case 0: // discus
      ctx.beginPath(); ctx.arc(0,0,7,0,Math.PI*2); ctx.stroke();
      ctx.beginPath(); ctx.arc(0,0,3,0,Math.PI*2); ctx.fill();
      for(var s=0;s<8;s++){var sa=s*Math.PI/4; ctx.beginPath(); ctx.moveTo(Math.cos(sa)*3,Math.sin(sa)*3); ctx.lineTo(Math.cos(sa)*7,Math.sin(sa)*7); ctx.stroke();}
      break;
    case 1: // conch
      ctx.beginPath(); ctx.ellipse(0,0,7,4,0,0,Math.PI*2); ctx.fill();
      break;
    case 2: // mace
      ctx.fillRect(-1,-8,2,16);
      ctx.beginPath(); ctx.arc(0,-9,4,0,Math.PI*2); ctx.fill();
      break;
    case 3: // lotus
      for(var p=0;p<5;p++){var pa=p*Math.PI*2/5; ctx.beginPath(); ctx.ellipse(Math.cos(pa)*4,Math.sin(pa)*4,2,4,pa,0,Math.PI*2); ctx.fill();}
      break;
    case 4: // sword
      ctx.fillRect(-1,-8,2,12);
      ctx.fillRect(-3,3,6,2);
      break;
    case 5: // bow
      ctx.beginPath(); ctx.arc(0,0,7,-Math.PI/3,Math.PI/3); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0,-7); ctx.lineTo(0,7); ctx.stroke();
      break;
    case 6: // fire
      ctx.beginPath();
      ctx.moveTo(0,-7); ctx.quadraticCurveTo(4,-2,2,4); ctx.quadraticCurveTo(0,0,-2,4); ctx.quadraticCurveTo(-4,-2,0,-7); ctx.fill();
      break;
    case 7: // arrow
      ctx.beginPath(); ctx.moveTo(-7,0); ctx.lineTo(7,0); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(7,0); ctx.lineTo(3,-3); ctx.lineTo(3,3); ctx.closePath(); ctx.fill();
      break;
  }
  ctx.restore();
}

// ── ARJUNA at the feet ────────────────────────────────────────────────────
function vpDrawArjuna(){
  var ctx=vpCtx;
  var cx=vpW*0.5;
  // Arjuna position changes based on act
  var ax, ay, prostrate;
  if(vpAct<=1){
    // sitting on chariot
    ax=cx; ay=vpH*0.78; prostrate=false;
  } else if(vpAct<=2){
    ax=cx; ay=vpH*0.80; prostrate=false;
  } else if(vpAct<=4){
    ax=cx; ay=vpH*0.82; prostrate=false;
  } else if(vpAct<=7){
    ax=cx; ay=vpH*0.84; prostrate=true;
  } else if(vpAct<=9){
    ax=cx; ay=vpH*0.86; prostrate=true;
  } else {
    ax=cx; ay=vpH*0.80; prostrate=false;
  }
  ctx.save();
  if(prostrate){
    // prostrate — body lying down with hands joined forward
    ctx.fillStyle='rgba(200,180,220,0.85)';
    ctx.beginPath();
    ctx.ellipse(ax, ay+5, 12, 5, 0, 0, Math.PI*2); ctx.fill();
    ctx.beginPath();
    ctx.arc(ax-9, ay, 3.5, 0, Math.PI*2); ctx.fill();
    // joined hands at head
    var hg=ctx.createRadialGradient(ax-15, ay-1, 0, ax-15, ay-1, 7);
    hg.addColorStop(0,'rgba(255,230,180,0.95)');
    hg.addColorStop(1,'rgba(255,180,80,0)');
    ctx.fillStyle=hg;
    ctx.fillRect(ax-22, ay-8, 14, 14);
  } else {
    // standing/sitting
    ctx.fillStyle='rgba(200,180,220,0.88)';
    ctx.beginPath();
    ctx.ellipse(ax, ay+8, 6, 12, 0, 0, Math.PI*2); ctx.fill();
    ctx.beginPath();
    ctx.arc(ax, ay-5, 4.5, 0, Math.PI*2); ctx.fill();
    // joined hands
    var hg2=ctx.createRadialGradient(ax, ay+1, 0, ax, ay+1, 6);
    hg2.addColorStop(0,'rgba(255,230,180,0.95)');
    hg2.addColorStop(1,'rgba(255,180,80,0)');
    ctx.fillStyle=hg2;
    ctx.fillRect(ax-6, ay-4, 12, 12);
    // bow at side (acts 0-1 only)
    if(vpAct<=1){
      ctx.strokeStyle='rgba(180,140,90,0.8)';
      ctx.lineWidth=1.5;
      ctx.beginPath();
      ctx.moveTo(ax-12, ay-2);
      ctx.quadraticCurveTo(ax-22, ay+8, ax-18, ay+20);
      ctx.stroke();
    }
    // Chariot wheel hints
    if(vpAct<=2 || vpAct===10){
      ctx.strokeStyle='rgba(140,100,80,0.55)';
      ctx.lineWidth=1.5;
      ctx.beginPath(); ctx.arc(ax-14, ay+22, 8, 0, Math.PI*2); ctx.stroke();
      ctx.beginPath(); ctx.arc(ax+14, ay+22, 8, 0, Math.PI*2); ctx.stroke();
    }
  }
  // Label (small)
  ctx.font='400 8px "IBM Plex Mono", monospace';
  ctx.fillStyle='rgba(200,180,220,0.55)';
  ctx.textAlign='center';
  ctx.fillText('ARJUNA', ax, ay+38);
  ctx.textAlign='start';
  ctx.restore();
}

// ── BEINGS FLOWING INTO MOUTH (acts 8-10) ────────────────────────────────
function vpDrawTimeMouthBeings(){
  var ctx=vpCtx;
  var cx=vpW*0.5, cy=vpH*0.42+vpCameraY;
  var R=Math.min(vpW,vpH)*0.27*vpFormScale;
  if(R<10) return;
  ctx.save();
  ctx.globalCompositeOperation='lighter';
  for(var i=0;i<vpBeingsIn.length;i++){
    var b=vpBeingsIn[i];
    b.r -= b.sp;
    if(b.r<0.04){
      b.r = 0.6+Math.random()*0.35;
      b.ang = Math.random()*Math.PI*2;
    }
    var radius=b.r*Math.max(vpW,vpH)*0.4;
    var x=cx+Math.cos(b.ang)*radius;
    var y=cy+Math.sin(b.ang)*radius*0.88;
    // Trail
    var trailLen=20;
    ctx.strokeStyle='rgba('+b.hue[0]+','+b.hue[1]+','+b.hue[2]+',0.3)';
    ctx.lineWidth=1;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x+Math.cos(b.ang)*trailLen, y+Math.sin(b.ang)*trailLen*0.88);
    ctx.stroke();
    // figure
    var fg=ctx.createRadialGradient(x,y,0,x,y,b.size*5);
    fg.addColorStop(0,'rgba('+b.hue[0]+','+b.hue[1]+','+b.hue[2]+',0.95)');
    fg.addColorStop(0.5,'rgba('+b.hue[0]+','+b.hue[1]+','+b.hue[2]+',0.45)');
    fg.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=fg;
    ctx.fillRect(x-b.size*5, y-b.size*5, b.size*10, b.size*10);
  }
  ctx.restore();
}

// ── kālo'smi FLASH (act 10) ──────────────────────────────────────────────
function vpDrawKaloFlash(){
  if(vpKaloFlash<=0) return;
  var ctx=vpCtx;
  var flashPhase=Math.min(1, vpActT/100);
  // intense gold flare across whole canvas, briefly
  if(flashPhase<1){
    var pulseAlpha=Math.sin(flashPhase*Math.PI)*0.35;
    ctx.fillStyle='rgba(255,210,140,'+pulseAlpha+')';
    ctx.fillRect(0,0,vpW,vpH);
  }
  // verse fragment as superimposed text
  if(vpAct===9){
    ctx.save();
    ctx.font='italic 600 16px "Cormorant Garamond", serif';
    ctx.textAlign='center';
    ctx.fillStyle='rgba(255,230,180,0.85)';
    ctx.shadowColor='rgba(255,140,80,0.6)';
    ctx.shadowBlur=18;
    ctx.fillText('कालो\'स्मि लोकक्षयकृत्प्रवृद्धो', vpW*0.5, vpH*0.18);
    ctx.shadowBlur=0;
    ctx.restore();
  }
}


// ══════════════════════════════════════════════════════════════════════════
// DARSHAN PANEL · reading
// ══════════════════════════════════════════════════════════════════════════

window.vpOpenDarshan=function(chapId){
  var panel=$vp('vp-darshan');
  if(!panel) return;
  panel.classList.add('on');
  vpDarshanOpen=true;
  vpShowChapter(chapId||'overview');
};
window.vpCloseDarshan=function(){
  var panel=$vp('vp-darshan');
  if(panel) panel.classList.remove('on');
  vpDarshanOpen=false;
};
window.vpShowChapter=function(chapId){
  var pills=document.querySelectorAll('#vp-darshan .vp-chap-pill');
  for(var i=0;i<pills.length;i++){
    if(pills[i].getAttribute('data-chap')===chapId){
      pills[i].classList.add('active');
    } else {
      pills[i].classList.remove('active');
    }
  }
  var body=$vp('vp-darshan-body');
  if(!body) return;
  if(chapId==='current-act'){
    body.innerHTML=vpRenderActDetail(VP_ACTS[vpAct]);
    body.scrollTop=0;
    return;
  }
  var c=VP_CHAPTERS[chapId];
  if(!c){
    body.innerHTML='<p>Chapter not found.</p>';
    return;
  }
  body.innerHTML='<h2 class="vp-darshan-title">'+c.title+'</h2>'+c.body;
  body.scrollTop=0;
};

function vpShowChapter(id){ window.vpShowChapter(id); }

function vpRenderActDetail(act){
  var prevIdx=(vpAct-1+VP_ACTS.length)%VP_ACTS.length;
  var nextIdx=(vpAct+1)%VP_ACTS.length;
  var html=
    '<div class="vp-detail">'+
      '<div class="vp-d-num-tag">'+act.eyebrow+'</div>'+
      '<h2 class="vp-d-title">'+act.title+'</h2>'+
      '<div class="vp-d-mantra">'+
        '<div class="vp-d-m-eyebrow">verse · Gītā 11</div>'+
        '<div class="vp-d-m-sa">'+act.verseSa+'</div>'+
        '<div class="vp-d-m-iast"><em>'+act.verseIast+'</em></div>'+
        '<div class="vp-d-m-tr">'+act.verseTr+'</div>'+
        '<div class="vp-d-m-src">'+act.verseSrc+'</div>'+
      '</div>'+
      '<div class="vp-d-narrative">'+act.narrative+'</div>'+
      '<div class="vp-d-walk">'+
        '<button class="vp-d-walk-btn vp-d-walk-prev" onclick="vpJumpToAct('+prevIdx+');vpShowChapter(\'current-act\')">'+
          '<span class="vp-d-walk-arr">←</span>'+
          '<span class="vp-d-walk-lbl">'+VP_ACTS[prevIdx].title+'</span>'+
        '</button>'+
        '<button class="vp-d-walk-btn vp-d-walk-next" onclick="vpJumpToAct('+nextIdx+');vpShowChapter(\'current-act\')">'+
          '<span class="vp-d-walk-lbl">'+VP_ACTS[nextIdx].title+'</span>'+
          '<span class="vp-d-walk-arr">→</span>'+
        '</button>'+
      '</div>'+
      '<div class="vp-d-foot"><div class="vp-d-foot-attr">Original synthesis by Rahul S.</div></div>'+
    '</div>';
  return html;
}

